    g_kfiles('apvndhrb.pls').area := 'Suppliers';
    g_kfiles('apvndhrb.pls').subarea := 'Supplier/Site/Contact Creation & Update';
    g_kfiles('apvndhrb.pls').type := 'Package Body';
    g_kfiles('apvndhrb.pls').name := 'apvndhrb.pls';
    g_kfiles('apvndhrb.pls').version := '';
    g_kfiles('apvndhrb.pls').pkg_details := 'AP_VENDORS_PKG';
    g_kfiles('apvndhrb.pls').category := 'SUPPLIER';
    get_file_details(g_kfiles('apvndhrb.pls'));
  END IF;

  -- Return the proper g_kfiles value
  IF p_dtl = 'area' THEN
    RETURN(g_kfiles(l_file).area);
  ELSIF p_dtl = 'subarea' THEN
    RETURN(g_kfiles(l_file).subarea);
  ELSIF p_dtl = 'type' THEN
    RETURN(g_kfiles(l_file).type);
  ELSIF p_dtl = 'name' THEN
    RETURN(l_file);
  ELSIF p_dtl = 'version' THEN
    RETURN(g_kfiles(l_file).version);
  ELSIF p_dtl = 'pkg_details' THEN
    RETURN(g_kfiles(l_file).pkg_details);
  ELSIF p_dtl = 'category' THEN
    RETURN(g_kfiles(l_file).category);
  ELSE
    RETURN(null);
  END IF;
EXCEPTION WHEN OTHERS THEN
  RETURN(sqlerrm);
END get_kfile_dtl;



