PROCEDURE validate_parameters(
            p_analysis_mode                IN VARCHAR2    DEFAULT NULL
           ,p_invoice_id                   IN NUMBER      DEFAULT NULL
           ,p_check_id                     IN NUMBER      DEFAULT NULL
           ,p_vendor_id                    IN NUMBER      DEFAULT NULL
           ,p_trx_type                     IN VARCHAR2    DEFAULT 'ALL'
           ,p_start_date                   IN DATE        DEFAULT NULL
           ,p_end_date                     IN DATE        DEFAULT NULL
           ,p_org_ids                      IN NUMBER      DEFAULT NULL
           ,p_org_ids_sql                  IN NUMBER      DEFAULT NULL
           ,p_validations                  IN VARCHAR2    DEFAULT 'ALL'
           ,p_skip_general                 IN VARCHAR2    DEFAULT 'N'
           ,p_max_output_rows              IN NUMBER      DEFAULT 20
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

IS

  l_revision                  VARCHAR2(25);
  l_date_char                 VARCHAR2(30);
  l_instance                  VARCHAR2(255);
  l_apps_version              VARCHAR2(255);
  l_host                      VARCHAR2(255);
  l_full_hostname             VARCHAR2(255);
  l_key                       VARCHAR2(255);
  l_system_function_var       VARCHAR2(2000);
  l_exists_val                VARCHAR2(2000);
  l_index                     NUMBER:=1;
  l_dbversion                 VARCHAR2(255);
  l_db_name                   VARCHAR2(255);
  l_step                      VARCHAR2(10);
  invalid_parameters EXCEPTION;
  invalid_escape EXCEPTION;

----------------------------------------------------------------
-- Analyzer-specific code: Validation Declarations            --
----------------------------------------------------------------
  l_dummy         NUMBER;
  l_org_list      VARCHAR2(500);
  l_org           VARCHAR2(10);
  l_org_num       NUMBER;
  l_ledger_id     NUMBER;
  l_ledger_name   GL_LEDGERS.NAME%TYPE;
  l_is_concurrent VARCHAR2(1) := 'N';

  FUNCTION chk_dates (p_ledger_id IN NUMBER, p_start IN DATE, p_end IN DATE)
  RETURN boolean IS
    counter NUMBER := 0;
  BEGIN
    SELECT count(*) INTO counter
    FROM gl_period_statuses ps
    WHERE ps.ledger_id = p_ledger_id
    AND   ps.application_id = 200
    AND   nvl(p_start,ps.start_date) BETWEEN ps.start_date AND ps.end_date
    AND   ps.closing_status IN ('O','F');
    IF counter = 0 THEN
      return FALSE;
    END IF;

    SELECT count(*) INTO counter
    FROM gl_period_statuses ps
    WHERE ps.ledger_id = p_ledger_id
    AND   ps.application_id = 200
    AND   nvl(p_end,ps.end_date) BETWEEN ps.start_date AND ps.end_date
    AND   ps.closing_status IN ('O','F');
    IF counter = 0 THEN
      return FALSE;
    ELSE
      return TRUE;
    END IF;

  EXCEPTION WHEN OTHERS THEN
    print_log('Error in validate_parameters.chk_dates for ledger '||
      p_ledger_id||' and dates '||to_char(p_start,'DD-MON-YYYY')||
      ' to '||to_char(p_end,'DD-MON-YYYY')||': '||sqlerrm);
    raise;
  END chk_dates;





BEGIN

  l_step := '1';

  print_log(analyzer_title || ' Log File');
  print_log('***************************************************************');

  -- Create global hash for parameters. Numbers required for the output order
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Analysis Mode';
   g_parameters(g_parameters.LAST).pvalue := p_analysis_mode;
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Invoice ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_invoice_id,'NO_MASK');
   END IF;
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Check ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_check_id,'NO_MASK');
   END IF;
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Vendor ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_vendor_id,'NO_MASK');
   END IF;
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Transaction Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_trx_type,'NO_MASK');
   END IF;
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Start Date';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_start_date,'NO_MASK');
   END IF;
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'End Date';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_end_date,'NO_MASK');
   END IF;
   IF g_is_concurrent THEN 
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Unit';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_ids,'NO_MASK');
   END IF;
   END IF;
   IF NOT g_is_concurrent THEN 
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Units';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_ids_sql,'NO_MASK');
   END IF;
   END IF;
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Validations to Perform';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_validations,'NO_MASK');
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Skip General Section';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_skip_general,'NO_MASK');
   END IF;
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  print_log(chr(10)||'Parameter Values before validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  BEGIN

    SELECT max(release_name) INTO l_apps_version
    FROM fnd_product_groups;

    begin
        -- Try to get version using new 19c method
        execute immediate 'select instance_name, host_name, version_full, sys_context(''USERENV'',''DB_NAME'') FROM v$instance'
            into l_instance, l_host, l_dbversion, l_db_name;
    exception when others then
        -- Get version using old method
        SELECT instance_name, host_name, version, sys_context('USERENV','DB_NAME')
        INTO l_instance, l_host, l_dbversion, l_db_name
        FROM v$instance;
    end;
    l_host := nvl(l_host, sys_context('USERENV','SERVER_HOST'));
    l_instance := nvl(l_instance, sys_context('USERENV','INSTANCE_NAME'));

  EXCEPTION WHEN OTHERS THEN
    print_log('Error in validate_parameters gathering instance information: '
      ||sqlerrm);
    raise;
  END;

  l_step := '2';
  BEGIN
    SELECT distinct domain
    INTO l_full_hostname
    FROM (SELECT db_domain AS domain
            FROM fnd_databases
          UNION ALL
          SELECT domain AS domain
          FROM fnd_nodes) domains WHERE domains.domain IS NOT NULL and rownum = 1;
    EXCEPTION
        WHEN NO_DATA_FOUND THEN
          l_full_hostname := NULL;
        WHEN OTHERS    THEN
          print_log('Error in validate_parameters gathering instance information: '
          ||sqlerrm);
    END;

  l_step := '3';
-- Revision and date values can be populated by RCS
  l_revision := rtrim(replace('$Revision: 200.498  $','$',''));
  l_revision := ltrim(replace(l_revision,'Revision:',''));
  l_date_char := rtrim(replace('$Date: 2026/02/25 11:39:10 $','$',''));
  l_date_char := ltrim(replace(l_date_char,'Date:',''));
  l_date_char := to_char(to_date(l_date_char,'YYYY/MM/DD HH24:MI:SS'),'DD-MON-YYYY');

  l_step := '4';
-- Create global hash for mapping internal result codes (E, W, S, I) to user friendly result codes (error, warning, successful, information)
  g_result('E') := 'error';
  g_result('W') := 'warning';
  g_result('S') := 'success';
  g_result('I') := 'info';

  l_step := '5';
-- Create global hash for report information
-- Do not report host details (EBSAF-274); reverted by EBSAF-293
  g_rep_info('Host') := regexp_substr(l_host, '^[^.]+');
  -- the host name might already be fully qualified, need to check if it includes the domain before appending it
  IF (l_host LIKE '%.%') THEN
       g_rep_info('FullHost') := l_host;
  ELSE
       g_rep_info('FullHost') := l_host || '.' || l_full_hostname;
  END IF;
  l_step := '6';
  g_rep_info('Instance') := l_instance;
  g_rep_info('DB Name') := l_db_name;
  g_rep_info('DB Version') := l_dbversion;
  g_rep_info('Apps Version') := l_apps_version;
  g_rep_info('File Name') := 'ap_gdf_detect_analyzer.sql';
  g_rep_info('File Version') := l_revision;
  g_rep_info('Framework Version') := RTRIM(g_framework_version, ' ');
  g_rep_info('Execution Date') := to_char(sysdate,'DD-MON-YYYY HH24:MI:SS');
  g_rep_info('Description') := ('The ' || analyzer_title || ' <a href="' || g_cmos_km_url || g_analyzer_doc_id||'" target="_blank">(Note '||g_analyzer_doc_id||')</a> is a self-service health-check script that reviews the overall footprint, analyzes current configurations and settings for the environment and provides feedback and recommendations on best practices. Your application data is not altered in any way when you run this analyzer.');

  l_step := '7';
  IF (g_is_concurrent) THEN
     populate_user_details();
  END IF;

  ------------------------------------------------------------------------------
  -- NOTE: Add code here for validation to the parameters of your diagnostic
  ------------------------------------------------------------------------------
  l_step := '8';


  g_max_output_rows := nvl(p_max_output_rows,20);
  g_debug_mode := nvl(p_debug_mode, 'Y');

debug('begin parameter validation: p_invoice_id');
IF p_analysis_mode='SINGLE' THEN
IF p_invoice_id IS NOT NULL THEN
BEGIN
SELECT INVOICE_ID
INTO l_exists_val
FROM AP_INVOICES_ALL
WHERE INVOICE_ID = p_invoice_id
 AND (mo_global.is_mo_init_done = 'N' OR mo_global.check_access(org_id) = 'Y')
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: The INVOICE_ID value supplied is invalid.  Please provide a valid INVOICE_ID.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_invoice_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
END IF;
debug('end parameter validation: p_invoice_id');

debug('begin parameter validation: p_check_id');
IF p_analysis_mode='SINGLE' THEN
IF p_check_id IS NOT NULL THEN
BEGIN
SELECT CHECK_ID
INTO l_exists_val
FROM AP_CHECKS_ALL
WHERE CHECK_ID = p_check_id
 AND (mo_global.is_mo_init_done = 'N' OR mo_global.check_access(org_id) = 'Y')
 and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: The CHECK_ID value supplied is invalid.  Please provide a valid CHECK_ID.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_check_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
END IF;
debug('end parameter validation: p_check_id');

debug('begin parameter validation: p_vendor_id');
IF p_analysis_mode='SINGLE' THEN
IF p_vendor_id IS NOT NULL THEN
BEGIN
SELECT VENDOR_ID
INTO l_exists_val
FROM AP_SUPPLIERS
WHERE VENDOR_ID = p_vendor_id and rownum < 2;
EXCEPTION
   WHEN NO_DATA_FOUND THEN
   print_error('INVALID ARGUMENT: The VENDOR_ID value supplied is invalid.  Please provide a valid VENDOR_ID.');
   raise invalid_parameters;
   WHEN OTHERS THEN
   print_error('INVALID ARGUMENT: Validation query for p_vendor_id failed with '||sqlerrm||'.');
   raise invalid_parameters;
END;
END IF;
END IF;
debug('end parameter validation: p_vendor_id');

debug('begin parameter validation: p_trx_type');
IF p_analysis_mode='ALL' THEN
IF p_trx_type IS NOT NULL AND p_trx_type NOT IN ( 'ALL','INVOICE','PAYMENT','SUPPLIER') THEN
   print_error('INVALID ARGUMENT: The transaction type value supplied is invalid.  Please provide a valid transaction type.');
   raise invalid_parameters;
END IF;
END IF;
debug('end parameter validation: p_trx_type');




debug('begin parameter validation: p_validations');
IF p_validations IS NOT NULL AND p_validations NOT IN ( 'ALL','GDF','NON-GDF') THEN
   print_error('INVALID ARGUMENT: The Validations to Perform value provided is invalid.  Please provide a valid value (GDF, NON-GDF, ALL).');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_validations');

debug('begin parameter validation: p_skip_general');
IF p_analysis_mode='SINGLE' THEN
IF p_skip_general IS NOT NULL AND p_skip_general NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Invalid value for Skip General Section.  Please select Y or N.');
   raise invalid_parameters;
END IF;
END IF;
debug('end parameter validation: p_skip_general');


debug('begin parameter validation: p_debug_mode');
IF p_debug_mode IS NOT NULL AND p_debug_mode NOT IN ( 'N','Y') THEN
   print_error('INVALID ARGUMENT: Debug Mode is invalid.  Valid values are Y or N');
   raise invalid_parameters;
END IF;
debug('end parameter validation: p_debug_mode');



-- Validation to verify analyzer is run on proper e-Business application version
-- In case validation at the beginning is updated/removed, adding validation here also so execution fails

  IF substr(l_apps_version,1,4) NOT IN ('12.0','12.1','12.2') THEN
    print_log('eBusiness Suite version = '||l_apps_version);
    print_log('ERROR: This Analyzer script is compatible for following version(s): 12.0,12.1,12.2');
    raise invalid_parameters;
  END IF;

-- .log enhancements (ER # 140)
  print_log(chr(10)||'Instance Information:');
  print_log('---------------------------');
  -- Do not report host details (EBSAF-274); reverted by EBSAF-293
  print_log('Host: '||g_rep_info('Host'));
  print_log('FullHost: '||g_rep_info('FullHost'));
  print_log('Instance: '||g_rep_info('Instance'));
  print_log('Database name: '||g_rep_info('DB Name'));
  print_log('Database version: '||g_rep_info('DB Version'));
  print_log('Applications version: '||g_rep_info('Apps Version'));
  print_log('Analyzer version: '||g_rep_info('File Version'));
  -- Report call details for troubleshooting (EBSAF-265)
  print_log('Calling method: '||g_rep_info('Calling From') );
  print_log('Calling module: '||g_rep_info('Calling Module') );
  print_log('---------------------------');

  -- Log session details (EBSAF-308)
  l_step := '8.5';
  print_log(chr(10)||'Session Information:');
  print_log('---------------------------');
  print_log('Language Code: '||sys_context('USERENV', 'LANG'));
  print_log('Region: '||sys_context('USERENV', 'NLS_TERRITORY'));
  print_log('Locale: '||sys_context('USERENV', 'LANGUAGE'));
  print_log('Date Format: '||sys_context('USERENV', 'NLS_DATE_FORMAT'));
  -- Get number characters
  select max(value) into l_system_function_var from v$parameter where name = 'nls_numeric_characters';
  print_log('Number Characters: '||l_system_function_var);
  -- Check for language installation
  begin
    execute immediate 'select max(installed_flag) from FND_LANGUAGES where language_code = sys_context(''USERENV'', ''LANG'')' into l_system_function_var;
    if (l_system_function_var is null or l_system_function_var not in ('B', 'I')) then
      print_log('WARNING: FND_LANGUAGES shows the session language is not installed.');
      print_log('Signatures relying on translation information may have incorrect results.');
    end if;
  exception when others then
    print_log('WARNING: Failed to check FND_LANGUAGES if session language is installed.');
  end;
  print_log('---------------------------');

  -- Verify escape character is set properly (EBSAF-265)
  l_step := '9';
  IF regexp_replace('Replace Test', '\s', '*') <>
     regexp_replace('Replace Test', chr(92) || 's', '*') THEN
    print_log('Invalid Escape:  Expected "' || chr(92) || 's' ||'" Received "\s"');
    print_log('Backslash character was not escaped properly during installation or execution.');
    raise invalid_escape;
  END IF;

  l_step := '10';
----------------------------------------------------------------
-- Analyzer-specific code: Additional Validation              --
----------------------------------------------------------------
debug('begin Additional Code: Additional Validation');
  -- Adding date format change as per email from Don Howard
  execute immediate 'alter session set nls_date_format = ''YYYY-MM-DD HH24:MI:SS''';

  debug('Entered validate parameters');
  g_validations     := upper(nvl(p_validations,'GDF'));
  g_invoice_id      := p_invoice_id;
  g_check_id        := p_check_id;
  g_vendor_id       := p_vendor_id;
  g_skip_general    := substr(nvl(p_skip_general,'N'),1,1);

  IF g_is_concurrent THEN
    l_is_concurrent := 'Y';
  END IF;

  -- Set apply undo patch global text for latest undo patch
  g_undo_applied := check_patch('14082924');
  IF g_undo_applied THEN
    g_apply_undo := '';
  ELSE
    g_apply_undo := '<strong>You should apply the consolidated UNDO Accounting '||
      'Patch {14082924} before applying the GDF patch for this issue.</strong> '||
      'Without this patch undo accounting failures may not be properly reported '||
      'and the GDF may appear to fail to fix the data when in fact an undo error '||
      'has occurred.<br><br/>';
  END IF;

  IF (p_invoice_id is not null OR
      p_check_id is not null OR
      p_vendor_id is not null) THEN

    g_mode := 'SINGLE';
    g_start_date := null;
    g_end_date := null;
    g_trx_type := null;
    IF p_invoice_id is not null THEN
      BEGIN
        SELECT to_char(org_id) INTO l_org_list
        FROM   ap_invoices_all
        WHERE  invoice_id = p_invoice_id;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          print_log('Error: '||sqlerrm||' Invoice id ('||
            to_char(p_invoice_id)||') does not exist.  '||
            'Please provide a valid invoice id parameter value.');
          print_error('Error: '||sqlerrm||' Invoice id ('||
            to_char(p_invoice_id)||') does not exist.  '||
            'Please provide a valid invoice id parameter value.');
          raise invalid_parameters;
        WHEN OTHERS THEN
          print_log('Error: '||sqlerrm||' validating invoice id: '||
            to_char(p_invoice_id));
          raise invalid_parameters;
      END;
    END IF;

    IF p_check_id is not null THEN
      BEGIN
        SELECT decode(l_org_list,
                 null,to_char(org_id),
                 to_char(org_id), l_org_list,
                 l_org_list||','||to_char(org_id))
        INTO   l_org_list
        FROM   ap_checks_all
        WHERE  check_id = p_check_id;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          BEGIN
            SELECT decode(l_org_list,
                 null,to_char(org_id),
                 to_char(org_id), l_org_list,
                 l_org_list||','||to_char(org_id))
            INTO   l_org_list
            FROM   ap_invoice_payments_all
            WHERE  check_id = p_check_id;
          EXCEPTION
            WHEN NO_DATA_FOUND THEN
              print_log('Error: '||sqlerrm||' Check id ('||
                to_char(p_check_id)||') does not exist.  '||
                'Please provide a valid check id parameter value.');
              print_error('Error: '||sqlerrm||' Check id ('||
                to_char(p_check_id)||') does not exist.  '||
                'Please provide a valid check id parameter value.');
              raise invalid_parameters;
            WHEN OTHERS THEN
              raise;
          END;
        WHEN OTHERS THEN
          print_log('Error: '||sqlerrm||' validating check id: '||
            to_char(p_check_id));
          raise invalid_parameters;
      END;
    END IF;

    IF (g_is_concurrent) THEN
      l_org_list := nvl(l_org_list, 'SELECT org_id FROM ap_system_parameters_all '||
        'WHERE mo_global.check_access(org_id) = ''Y''');
    ELSE
      l_org_list := nvl(l_org_list, 'SELECT org_id FROM ap_system_parameters_all');
    END IF;

    g_org_ids := l_org_list;

    IF p_vendor_id is not null THEN
      BEGIN
        SELECT 1 INTO l_dummy
        FROM   ap_suppliers
        WHERE  vendor_id = p_vendor_id;
      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          print_log('Error: '||sqlerrm||' Vendor id ('||
            to_char(p_vendor_id)||') does not exist.  '||
            'Please provide a valid vendor id parameter value.');
          print_error('Error: '||sqlerrm||' Vendor id ('||
            to_char(p_vendor_id)||') does not exist.  '||
            'Please provide a valid vendor id parameter value.');
          raise invalid_parameters;
        WHEN OTHERS THEN
          print_log('Error: '||sqlerrm||' validating vendor id: '||
            to_char(p_vendor_id));
          raise invalid_parameters;
      END;
    END IF;
    -- Set the view values for single trx mode
    g_iview :=
      'SELECT /*+ qb_name(iview) */ '||to_char(p_invoice_id) ||
      ' invoice_id FROM dual';
    g_miview :=
      'SELECT /*+ materialize */ '||to_char(p_invoice_id) ||
      ' invoice_id FROM dual';
    g_cview :=
      'SELECT /*+ qb_name(cview) */ '||to_char(g_check_id)||
      ' check_id FROM dual';
    g_mcvieW :=
      'SELECT /*+ materialize */ '||to_char(g_check_id)||
      ' check_id FROM dual';
    g_pp_iview :=
      'SELECT /*+ qb_name(iview) */ DISTINCT ail.prepay_invoice_id invoice_id '||
      'FROM ap_invoice_lines_all ail '||
      'WHERE ail.prepay_invoice_id IS NOT NULL '||
      'AND   ail.invoice_id = '||to_char(g_invoice_id);
    g_pp_miview :=
      'SELECT /*+ materialize */ DISTINCT ail.prepay_invoice_id invoice_id '||
      'FROM ap_invoice_lines_all ail '||
      'WHERE ail.prepay_invoice_id IS NOT NULL '||
      'AND   ail.invoice_id = '||to_char(g_invoice_id);
    g_pd_iview :=
      'SELECT /*+ qb_name(iview) */ DISTINCT aip.invoice_id invoice_id '||
      'FROM ap_invoice_payments_all aip '||
      'WHERE aip.check_id = '||to_char(g_check_id);
    g_pd_miview :=
      'SELECT /*+ materialize */ DISTINCT aip.invoice_id invoice_id '||
      'FROM ap_invoice_payments_all aip '||
      'WHERE aip.check_id = '||to_char(g_check_id);

  ELSE
    debug('Using date range parameters');
    g_mode       := 'DATERANGE';
    g_start_date := p_start_date;
    g_end_date   := p_end_date;
    g_org_ids    := rtrim(ltrim(replace(p_org_ids,' ',''),','),',');
  --   g_validations := 'GDF'; -- per dev only GDF validations for date range.
 g_validations := upper(nvl(p_validations,'GDF')); -- Replacing so we get Non-GDF for date range
    g_trx_type   := upper(nvl(p_trx_type,'ALL'));


    -- Date range not relevant if type is SUPPLIER
    -- Checks not relevent if we are only looking at SUPPLIER DATA
    IF nvl(g_trx_type,'ALL') = 'SUPPLIER' THEN
      g_start_date := null;
      g_end_date := null;
    ELSE
  -- Validate date range
      -- Not NULL
      IF (g_start_date is null OR g_end_date is null) THEN
        print_log('Error: When running for a date range both the range '||
          'start date and end date must be specified.');
        print_error('Error: When running for a date range both the range '||
          'start date and end date must be specified.');
        raise invalid_parameters;
      END IF;
      --  Start <= End
      BEGIN
        SELECT 1 INTO l_dummy
        FROM DUAL
        WHERE g_start_date <= g_end_date;
      EXCEPTION WHEN NO_DATA_FOUND THEN
        print_log('Error: The date range start date ('||
          to_char(g_start_date,'DD-MON-YYYY HH24:MI:SS')||
          ') must be prior to the end date ('||
          to_char(g_end_date,'DD-MON-YYYY HH24:MI:SS')||')' );
        print_error('Error: The date range start date ('||
          to_char(g_start_date,'DD-MON-YYYY HH24:MI:SS')||
          ') must be prior to the end date ('||
          to_char(g_end_date,'DD-MON-YYYY HH24:MI:SS')||')' );
        raise invalid_parameters;
      WHEN OTHERS THEN
        print_log('Error: when validating the start date is prior to the end date '||
          'in validate_parameters: '||sqlerrm);
        raise invalid_parameters;
      END;
    END IF;

    -- Validate org_ids
    IF g_org_ids is not null THEN
      BEGIN
        l_org_list := g_org_ids;
        WHILE length(l_org_list) > 0 LOOP
          IF l_org_list like '%,%' THEN
            l_org := substr(l_org_list,1,instr(l_org_list,',')-1);
            l_org_list := substr(l_org_list,instr(l_org_list,',')+1);
          ELSE
            l_org := l_org_list;
            l_org_list := '';
          END IF;
          l_org_num := to_number(l_org);
          SELECT set_of_books_id INTO l_ledger_id
          FROM   AP_SYSTEM_PARAMETERS_ALL
          WHERE  org_id = l_org_num;
          IF chk_dates(l_ledger_id, g_start_date, g_end_date) THEN
            IF ((NOT g_is_concurrent) OR mo_global.check_access(l_org_num) = 'Y') THEN
              IF l_org_num NOT MEMBER OF g_ous THEN
                g_ous.extend();
                g_ous(g_ous.last) := l_org_num;
              END IF;
            ELSE
              IF l_org_num NOT MEMBER OF g_skipped_ous THEN
                g_skipped_ous.extend();
                g_skipped_ous(g_skipped_ous.last) := l_org_num;
              END IF;
            END IF;
          ELSE
            IF l_org_num NOT MEMBER OF g_skipped_ous THEN
              g_skipped_ous.extend();
              g_skipped_ous(g_skipped_ous.last) := l_org_num;
            END IF;
          END IF;
        END LOOP;
        -- Rebuild the org id list from the validated table
        g_org_ids := '';
        FOR i IN 1..g_ous.count LOOP
          g_org_ids := g_org_ids||to_char(g_ous(i))||',';
        END LOOP;
        g_org_ids := rtrim(g_org_ids,',');

      EXCEPTION
        WHEN NO_DATA_FOUND THEN
          print_log('Error in validating the operating unit list: '||g_org_ids);
          print_log('Invalid operating unit value supplied: '||to_char(l_org_num));
          print_log('Insure that the operating unit provided is valid and has Oracle '||
            'Payables implemented.');
          print_error('Error validating the operating unit list: '||g_org_ids||
            '<br/>Invalid operating unit value supplied: '||to_char(l_org_num)||
            '<br/>Insure that the operating unit provided is valid and has '||
            'Oracle Payables implemented.');
          raise invalid_parameters;
        WHEN OTHERS THEN
          print_log('Error in validating the operating unit list: '||g_org_ids);
          print_log('Please insure that this is a single org_id or a comma '||
            'separated list of org_ids.');
          print_log('Error on: '||l_org);
          raise;
      END;
      IF g_org_ids is null THEN -- No valid orgs to process due to dates or MOAC
        IF p_org_ids is not null THEN
          print_log('Error in validating the operating unit list: '||p_org_ids);
        ELSE
          print_log('Error in validating the operating unit list');
        END IF;
        print_log('No operating unit selected for which dates ('||
          to_char(g_start_date)||' and '||to_char(g_end_date)||') '||
          'fall in open periods');
        IF (g_is_concurrent) THEN
          print_log('And to which the current application user has access.');
        END IF;
        g_org_ids := 'null';
        raise invalid_parameters;
      END IF;
  ELSE
 /* Switching this as per email from Don
     g_org_ids :=
        'SELECT DISTINCT org_id '||
        'FROM ap_system_parameters_all sp '||
        'WHERE EXISTS ('||
           'SELECT 1 FROM gl_period_statuses ps '||
           'WHERE ps.ledger_id = sp.set_of_books_id '||
           'AND ps.application_id = 200 '||
           'AND to_date('''||to_char(g_start_date, 'DD-MON-YYYY')||''') BETWEEN '||
              'ps.start_date AND ps.end_date '||
           'AND ps.closing_status IN (''O'',''F'')) '||
        'AND EXISTS ('||
           'SELECT 1 FROM gl_period_statuses ps '||
           'WHERE ps.ledger_id = sp.set_of_books_id '||
           'AND ps.application_id = 200 '||
           'AND to_date('''||to_char(g_end_date, 'DD-MON-YYYY')||''') BETWEEN '||
              'ps.start_date AND ps.end_date '||
           'AND ps.closing_status IN (''O'',''F''))';
*/
     g_org_ids :=
'SELECT DISTINCT org_id '||
        'FROM ap_system_parameters_all sp '||
        'WHERE EXISTS ('||
           'SELECT 1 FROM gl_period_statuses ps '||
           'WHERE ps.ledger_id = sp.set_of_books_id '||
           'AND ps.application_id = 200 '||
           'AND to_date('''||to_char(g_start_date, 'DD-MON-YYYY')||''',''DD-MON-YYYY'') BETWEEN '||
              'ps.start_date AND ps.end_date '||
           'AND ps.closing_status IN (''O'',''F'')) '||
        'AND EXISTS ('||
           'SELECT 1 FROM gl_period_statuses ps '||
           'WHERE ps.ledger_id = sp.set_of_books_id '||
           'AND ps.application_id = 200 '||
           'AND to_date('''||to_char(g_end_date, 'DD-MON-YYYY')||''',''DD-MON-YYYY'') BETWEEN '||
              'ps.start_date AND ps.end_date '||
           'AND ps.closing_status IN (''O'',''F''))';


      IF (g_is_concurrent) THEN
        g_org_ids := g_org_ids||' AND mo_global.check_access(org_id) = ''Y''';
      END IF;

      SELECT DISTINCT sp.org_id BULK COLLECT INTO g_skipped_ous
      FROM  ap_system_parameters_all sp
      WHERE (NOT EXISTS (
               SELECT 1 FROM gl_period_statuses ps
               WHERE ps.ledger_id = sp.set_of_books_id
               AND ps.application_id = 200
               AND g_start_date BETWEEN ps.start_date AND ps.end_date
               AND ps.closing_status IN ('O','F')) OR
             NOT EXISTS (
               SELECT 1 FROM gl_period_statuses ps
               WHERE ps.ledger_id = sp.set_of_books_id
               AND ps.application_id = 200
               AND g_end_date BETWEEN ps.start_date AND ps.end_date
               AND ps.closing_status IN ('O','F')) OR
             (l_is_concurrent  = 'Y' AND
              nvl(mo_global.check_access(sp.org_id),'N') != 'Y'))
       ORDER by sp.org_id;
    END IF;

    -- If any OU's are skipped print a message to the log
    IF g_skipped_ous.count > 0 THEN
      print_log('The following operating units were not processed because '||
        'the dates '||to_char(g_start_date,'DD-MON-YYYY')||' and '||
        to_char(g_end_date,'DD-MON-YYYY')||' do not fall into open periods '||
        'for the corresponding ledger OR because the applications user does '||
        'not have access to the operating unit:');
      FOR i in 1..g_skipped_ous.count LOOP
        print_log('     '||to_char(g_skipped_ous(i)));
      END LOOP;
    END IF;

      -- Validate the type
    IF g_trx_type NOT IN ('ALL','INVOICE','PAYMENT','SUPPLIER') THEN
      print_log('Invalid value provided for parameter p_type: '||g_trx_type);
      print_log('Valid values are ALL, INVOICE, PAYMENT, or SUPPLIER');
      print_error('Invalid value provided for parameter p_type: '||g_trx_type||'<br/>'||
       'Valid values are ALL, INVOICE, PAYMENT, or SUPPLIER');
      raise invalid_parameters;
    END IF;

    -- Validate include non-gdf parameter
    IF g_validations NOT IN ('ALL','GDF','NON-GDF') THEN
      print_log('Invalid value provided for parameter p_validations: '||
        g_validations);
      print_log('Valid values are ALL, GDF, or NON-GDF');
      print_error('Invalid value provided for parameter p_validations: '||
        g_validations||'<br/>Valid values are ALL, GDF, or NON-GDF');
      raise invalid_parameters;
    END IF;

    -- Validate debug mode  parameter
    IF g_debug_mode NOT IN ('Y','N') THEN
      print_log('Invalid value provided for parameter p_debug_mode: '||
        g_debug_mode);
      print_log('Valid values are Y and N. Using default value: N');
      g_debug_mode := 'N';
    END IF;

    -- Validate the skip general section  parameter
    IF g_skip_general NOT IN ('Y','N') THEN
      print_log('Invalid value provided for parameter p_skip_general: '||
        g_skip_general);
      print_log('Valid values are Y and N. Using default value: N');
      g_skip_general := 'N';
    END IF;

    -- Set the view values for daterange
    g_iview := 
      'SELECT /*+ qb_name(iview) */ DISTINCT d.invoice_id '||
      'FROM ap_invoice_distributions_all d '||
      'WHERE d.org_id in ('||g_org_ids||') '||
      'AND   d.accounting_date BETWEEN '||
      '        to_date('''||to_char(g_start_date,'DD-MON-YYYY')||
                 ''',''DD-MON-YYYY'') AND '||
      '        to_date('''||to_char(g_end_date,'DD-MON-YYYY')||
                 ''',''DD-MON-YYYY'')';
    g_miview := 
      'SELECT /*+ materialize */ DISTINCT d.invoice_id '||
      'FROM ap_invoice_distributions_all d '||
      'WHERE d.org_id in ('||g_org_ids||') '||
      'AND   d.accounting_date BETWEEN '||
      '        to_date('''||to_char(g_start_date,'DD-MON-YYYY')||
                 ''',''DD-MON-YYYY'') AND '||
      '        to_date('''||to_char(g_end_date,'DD-MON-YYYY')||
                 ''',''DD-MON-YYYY'')';
    g_cview := 
      'SELECT /*+ qb_name(cview) */ DISTINCT ph.check_id '||
      'FROM ap_payment_history_all ph '||
      'WHERE ph.org_id in ('||g_org_ids||') '||
      'AND   ph.accounting_date BETWEEN '||
      '        to_date('''||to_char(g_start_date,'DD-MON-YYYY')||
                 ''',''DD-MON-YYYY'') AND '||
      '        to_date('''||to_char(g_end_date,'DD-MON-YYYY')||
                 ''',''DD-MON-YYYY'')';
    g_mcview := 
      'SELECT /*+ materialize */ DISTINCT ph.check_id '||
      'FROM ap_payment_history_all ph '||
      'WHERE ph.org_id in ('||g_org_ids||') '||
      'AND   ph.accounting_date BETWEEN '||
      '        to_date('''||to_char(g_start_date,'DD-MON-YYYY')||
                 ''',''DD-MON-YYYY'') AND '||
      '        to_date('''||to_char(g_end_date,'DD-MON-YYYY')||
                 ''',''DD-MON-YYYY'')';

  END IF;

  debug('g_mode:            '||g_mode);
  debug('g_invoice_id:      '||to_char(g_invoice_id));
  debug('g_check_id:        '||to_char(g_check_id));
  debug('g_vendor_id:       '||to_char(g_vendor_id));
  debug('g_start_date:      '||to_char(g_start_date,'DD-MON-YYYY'));
  debug('g_end_date:        '||to_char(g_end_date,'DD-MON-YYYY'));
  debug('g_org_ids:         '||g_org_ids);
  debug('g_trx_type:        '||g_trx_type);
  debug('g_validations:     '||g_validations);
  debug('g_max_output_rows: '||to_char(g_max_output_rows));
  debug('g_debug_mode:      '||g_debug_mode);
  debug('g_skip_general:    '||g_skip_general);
  debug('Leaving validate parameters');





    /* SEEDED EBS BANNER BEGIN */

    -- Premier Support Checks by priority
    select min(error_type) into l_system_function_var from (
        -- Database in Sustaining Support
        select 1 error_type from V$VERSION WHERE banner like '%11.2%' or banner like '%11.1%' or banner like '%10.%'
        union
        -- Application Version 11.5
        select 2 error_type from fnd_product_groups where release_name like '11.5%'
        union
        -- Application Version 12.1
        select 3 error_type from fnd_product_groups where release_name like '12.1%'
        union
        -- Database in Extended Support
        select 4 error_type from V$VERSION WHERE banner like '%12.1%'
        union
        -- Application Version 12.0
        select 5 error_type from fnd_product_groups where release_name like '12.0%'
        union
        -- Application Version 12.2.x outdated
        select 6 error_type from fnd_product_groups where release_name in ('12.2.0' , '12.2.1' , '12.2.2' , '12.2.3' , '12.2.4' , '12.2.5' , '12.2.6')
    );

    -- Set banner message by error type
    case l_system_function_var
        when 1 then
            -- Database in Sustaining Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Sustaining Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 2 then
            -- Application Version 11.5
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on November 2010. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br> Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 3 then
            -- Application Version 12.1
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support End for the application version on this instance is on December 2021. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp]. <br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 4 then
            -- Database in Extended Support
            g_banner_severity := 'W';
            g_banner_message := 'The database version running on this instance is in Extended Support. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 5 then
            -- Application Version 12.0
            g_banner_severity := 'W';
            g_banner_message := 'Premier Support for the application version on this instance ended on January 2012. Please refer to Oracle''s Lifetime Support Policy in [2655839.2#supportp].<br>Ignore this warning if you have upgraded since this analyzer output was generated.';
        when 6 then
           -- Application Version 12.2.7
           g_banner_severity := 'W';
           g_banner_message := '<b>Effective July 1, 2024, the E-Business Suite 12.2 Error Correction Baseline will be 12.2.7.</b><br>
<br>
<div><div style="display:inline-block; text-align:left; max-width:800px;">Updating the application version to release 12.2.7 or higher will ensure you have access to major product releases.<br>
Refer to:<ul>
<li>[1195034/KB696368] Oracle E-Business Suite Error Correction Support Policy</li>
<li><a href="https://blogs.oracle.com/ebstech/post/update-error-correction-baseline-for-ebs-122" target="_blank">Oracle E-Business Suite Technology Blog</a> Update: Error Correction Baseline for EBS 12.2</li>
</ul>
Customers running E-Business Suite products on the 12.2.3 - 12.2.6 release levels are encouraged to update to current code levels of those products before July 2024 so they can benefit from the simpler and smaller patches that will be available starting in July 2024.<br>
In the event a new issue is reported on a product at a code level below the baseline, Oracle Support will attempt to resolve the issue and engage Development if necessary. Development may determine that the issue can be resolved at the customer code level, or may determine that the only practical way to provide the fix is for the customer to apply the baseline (or later) code in the affected area, and provide the fix at that level.
</div></div>';
        else
            -- No banner required
            g_banner_message := null;
    end case;
    /* SEEDED EBS BANNER END */
debug('end Additional Code: Additional Validation');



  g_parameters.DELETE;

  -- Recreate global hash for parameters after validation (includes the modifiers)
debug('begin populate parameters hash table');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Analysis Mode';
   g_parameters(g_parameters.LAST).pvalue := p_analysis_mode;
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Invoice ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_invoice_id,'NO_MASK');
   END IF;
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Check ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_check_id,'NO_MASK');
   END IF;
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Vendor ID';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_vendor_id,'NO_MASK');
   END IF;
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Transaction Type';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_trx_type,'NO_MASK');
   END IF;
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Start Date';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_start_date,'NO_MASK');
   END IF;
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'End Date';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_end_date,'NO_MASK');
   END IF;
   IF g_is_concurrent THEN 
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Unit';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_ids,'NO_MASK');
   END IF;
   END IF;
   IF NOT g_is_concurrent THEN 
   IF p_analysis_mode='ALL' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Operating Units';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_org_ids_sql,'NO_MASK');
   END IF;
   END IF;
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Validations to Perform';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_validations,'NO_MASK');
   IF p_analysis_mode='SINGLE' THEN 
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Skip General Section';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_skip_general,'NO_MASK');
   END IF;
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Maximum Rows to Display';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_max_output_rows,'NO_MASK');
   g_parameters.extend();
   g_parameters(g_parameters.LAST).pname := 'Debug Mode';
   g_parameters(g_parameters.LAST).pvalue := mask_text(p_debug_mode,'NO_MASK');
debug('end populate parameters hash table');



  l_key := g_parameters.first;
  -- Print parameters to the log
  l_step := '11';
  print_log(chr(10)||'Parameter Values after validation:');
  print_log('---------------------------');

  FOR i IN 1..g_parameters.COUNT LOOP
    print_log(to_char(i) || '. ' || g_parameters(i).pname || ': ' || g_parameters(i).pvalue);
  END LOOP;
  print_log('---------------------------');

  -- Create global hash of SQL token values
debug('begin populate sql tokens hash table');
   g_sql_tokens('##$$INV$$##') := nvl(to_char(p_invoice_id),'null');
   g_masked_tokens('##$$INV$$##') := mask_text( g_sql_tokens('##$$INV$$##'), 'NO_MASK');
   g_sql_tokens('##$$PMT$$##') := nvl(to_char(g_check_id),'null');
   g_masked_tokens('##$$PMT$$##') := mask_text( g_sql_tokens('##$$PMT$$##'), 'NO_MASK');
   g_sql_tokens('##$$VND$$##') := nvl(to_char(g_vendor_id),'null');
   g_masked_tokens('##$$VND$$##') := mask_text( g_sql_tokens('##$$VND$$##'), 'NO_MASK');
   g_sql_tokens('##$$SDT$$##') := to_char(g_start_date,'DD-MON-YYYY');
   g_masked_tokens('##$$SDT$$##') := mask_text( g_sql_tokens('##$$SDT$$##'), 'NO_MASK');
   g_sql_tokens('##$$EDT$$##') := to_char(g_end_date,'DD-MON-YYYY');
   g_masked_tokens('##$$EDT$$##') := mask_text( g_sql_tokens('##$$EDT$$##'), 'NO_MASK');
   g_sql_tokens('##$$ORGS$$##') := g_org_ids;
   g_masked_tokens('##$$ORGS$$##') := mask_text( g_sql_tokens('##$$ORGS$$##'), 'NO_MASK');
   g_sql_tokens('##$$IVIEW$$##') := g_iview;
   g_masked_tokens('##$$IVIEW$$##') := mask_text( g_sql_tokens('##$$IVIEW$$##'), 'NO_MASK');
   g_sql_tokens('##$$MIVIEW$$##') := g_miview;
   g_masked_tokens('##$$MIVIEW$$##') := mask_text( g_sql_tokens('##$$MIVIEW$$##'), 'NO_MASK');
   g_sql_tokens('##$$CVIEW$$##') := g_cview;
   g_masked_tokens('##$$CVIEW$$##') := mask_text( g_sql_tokens('##$$CVIEW$$##'), 'NO_MASK');
   g_sql_tokens('##$$MCVIEW$$##') := g_mcview;
   g_masked_tokens('##$$MCVIEW$$##') := mask_text( g_sql_tokens('##$$MCVIEW$$##'), 'NO_MASK');
debug('end populate sql tokens hash table');



  l_key := g_masked_tokens.first;
  -- Print token values to the log

  -- if max rows param is not set and does not have a default, g_max_output_rows might end up being -1. We don't want that.
  IF (g_max_output_rows <= 0) THEN
     print_log ('Max rows was not set and there is no default value for it. Defaulting to 20.');
     g_max_output_rows := 20;
  ELSIF (g_max_output_rows > 100000) THEN
     print_log ('Max rows was set too high. Defaulting to 100000.');
     g_max_output_rows := 100000;
  END IF;

  l_step := '12';
  print_log('SQL Token Values');

  WHILE l_key IS NOT NULL LOOP
    -- Ensure tokens do not contain invalid characters (EBSAF-263)
    g_sql_tokens(l_key) := filter_html(g_sql_tokens(l_key), 'I', 'D' );
    g_masked_tokens(l_key) := filter_html(g_masked_tokens(l_key), 'I', 'D' );

    -- Allow tokens to be masked in log (EBSAF-275)
    print_log(l_key||': '|| g_masked_tokens(l_key));
    l_key := g_masked_tokens.next(l_key);
  END LOOP;

EXCEPTION
  WHEN INVALID_PARAMETERS THEN
    print_error_args('Invalid parameters provided. Process cannot continue.', l_step);
    raise;
  WHEN INVALID_ESCAPE THEN
    print_error('INVALID ESCAPE: Regular expression search results are incorrect.' ||
        ' Calling method "' || g_rep_info('Calling From') || '" module "' || g_rep_info('Calling Module') || '".' );
    raise;
  WHEN OTHERS THEN
    print_error_args('Error validating parameters: '||sqlerrm, l_step);
    raise;
END validate_parameters;


