debug('begin add_signature: 245');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'PO Matching';
   l_info('bug_number'):= '21497508';
   l_info('category'):= 'GENERAL';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1489862.1';
   l_info('problem'):= 'Unmatched Purchase Orders with invoice related quantities and amounts.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1489862.1.  <br><br>
<b>NOTE:</b> Ensure when running ap_one_off_scripts_sel.sql that you provide <b>MATCHING</b> when prompted to enter the <b>Component Value</b> parameter .';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3772',
      p_sig_id                 => '245',
      p_sig_sql                => 'SELECT /*+ parallel(pod,8) */ ''MAT1.1'' category
	,pod.po_header_id
	,pod.po_line_id
	,pod.line_location_id
	,pod.po_distribution_id
	,pod.quantity_billed
	,pod.amount_billed
	,pod.quantity_financed
	,pod.amount_financed
	,pod.quantity_recouped
	,pod.amount_recouped
	,NULL rcv_transaction_id
FROM po_distributions_all pod
WHERE NOT EXISTS (
		SELECT 1
		FROM ap_invoice_distributions_all aid
			,ap_invoices_all ai
		WHERE aid.po_distribution_id = pod.po_distribution_id
			AND aid.line_type_lookup_code IN (
				''ITEM''
				,''ACCRUAL''
				)
			AND ai.invoice_id = aid.invoice_id
			AND ai.invoice_type_lookup_code <> ''PREPAYMENT''
		)
	AND (
		nvl(pod.quantity_billed, 0) <> 0
		OR nvl(pod.amount_billed, 0) <> 0
		)

UNION

SELECT /*+ parallel(pod,8) */ ''MAT1.2''
	,pod.po_header_id
	,pod.po_line_id
	,pod.line_location_id
	,pod.po_distribution_id
	,pod.quantity_billed
	,pod.amount_billed
	,pod.quantity_financed
	,pod.amount_financed
	,pod.quantity_recouped
	,pod.amount_recouped
	,NULL
FROM po_distributions_all pod
WHERE NOT EXISTS (
		SELECT 1
		FROM ap_invoice_distributions_all aid
			,ap_invoices_all ai
		WHERE aid.po_distribution_id = pod.po_distribution_id
			AND aid.line_type_lookup_code IN (
				''ITEM''
				,''ACCRUAL''
				)
			AND ai.invoice_id = aid.invoice_id
			AND ai.invoice_type_lookup_code = ''PREPAYMENT''
		)
	AND (
		nvl(pod.quantity_financed, 0) <> 0
		OR nvl(pod.amount_financed, 0) <> 0
		)

UNION

SELECT /*+ parallel(pod,8) */ ''MAT1.3''
	,pod.po_header_id
	,pod.po_line_id
	,pod.line_location_id
	,pod.po_distribution_id
	,pod.quantity_billed
	,pod.amount_billed
	,pod.quantity_financed
	,pod.amount_financed
	,pod.quantity_recouped
	,pod.amount_recouped
	,NULL
FROM po_distributions_all pod
WHERE NOT EXISTS (
		SELECT 1
		FROM ap_invoice_distributions_all aid
			,ap_invoices_all ai
		WHERE aid.po_distribution_id = pod.po_distribution_id
			AND aid.line_type_lookup_code IN (''PREPAY'')
			AND ai.invoice_id = aid.invoice_id
			AND ai.invoice_type_lookup_code <> ''PREPAYMENT''
		)
	AND (
		nvl(pod.quantity_recouped, 0) <> 0
		OR nvl(pod.amount_recouped, 0) <> 0
		)

UNION

SELECT /*+ parallel(rt,8) */ ''MAT5''
	,rt.po_header_id
	,rt.po_line_id
	,rt.po_line_location_id
	,rt.po_distribution_id
	,rt.quantity_billed
	,rt.amount_billed
	,NULL
	,NULL
	,NULL
	,NULL
	,rt.transaction_id
FROM rcv_transactions rt
WHERE NOT EXISTS (
		SELECT 1
		FROM ap_invoice_distributions_all aid
		WHERE aid.rcv_transaction_id = rt.transaction_id
		)
	AND NOT EXISTS (
		SELECT 1
		FROM ap_invoice_lines_all ail
		WHERE ail.rcv_transaction_id = rt.transaction_id
		)
	AND (
		nvl(rt.quantity_billed, 0) <> 0
		OR nvl(rt.amount_billed, 0) <> 0
		)
',
      p_title                  => 'MGD-245',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Unmatched Purchase Orders with invoice related quantities and amounts.<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Solution GDF: </strong>21497508</br><strong>Note: </strong>[1489862/KB611407]</br><strong>Script Name: </strong>ap_one_off_scripts_sel.sql General Matching</br></br>Apply the GDF patch following the instructions provided in [1489862/KB611407].  <br><br>
<b>NOTE:</b> Ensure when running ap_one_off_scripts_sel.sql that you provide <b>MATCHING</b> when prompted to enter the <b>Component Value</b> parameter .',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '19'
      );
   l_info.delete;
debug('end add_signature: 245');



debug('begin add_signature: 280');
   l_info('##SHOW_SQL##'):= 'Y';
