debug('begin add_signature: 1');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Holds';
   l_info('bug_number'):= '13102335';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '967242.1';
   l_info('problem'):= 'Automatic Withholding TAX (AWT) invoice distributions which will not validate due to rounding differences';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 967242.1';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4003',
      p_sig_id                 => '1',
      p_sig_sql                => 'SELECT maxdist.invoice_id,
          aid2.org_id,
          maxdist.invoice_line_number,
          maxdist.dist_line_number,
          maxdist.line_amt,
          maxdist.line_base_amt,
          maxdist.dist_amt_tot,
          maxdist.dist_base_amt_tot,
          maxdist.amount_adj,
          maxdist.base_amt_adj,
          aid2.posted_flag,
          aid2.awt_invoice_payment_id
   FROM (
          SELECT /*+ push_pred */
                 aid.invoice_id,
                 aid.invoice_line_number,
                 max(aid.distribution_line_number) dist_line_number,
                 ail.amount line_amt,
                 nvl(ail.base_amount,0) line_base_amt,
                 sum(aid.amount) dist_amt_tot,
                 sum(nvl(aid.base_amount,0)) dist_base_amt_tot,
                 (ail.amount- sum(aid.amount)) amount_adj,
                 (nvl(ail.base_amount,0) - sum(nvl(aid.base_amount,0))) base_amt_adj
          FROM ap_invoice_distributions_all aid,
               ap_invoice_lines_all ail,
               (
                 ##$$IVIEW$$##
               ) invs
          WHERE aid.invoice_id = ail.invoice_id
          AND   ail.line_number = aid.invoice_line_number
          AND   ail.line_type_lookup_code = ''AWT''
          AND   aid.line_type_lookup_code = ''AWT''
          AND   nvl(aid.historical_flag,''N'') <> ''Y''
          AND   ail.LINE_SOURCE = ''AUTO WITHHOLDING''
          AND   nvl(ail.discarded_flag,''N'') <> ''Y''
          AND   aid.invoice_id = invs.invoice_id
          GROUP BY aid.invoice_id, aid.invoice_line_number,
                   ail.amount, ail.base_amount
          HAVING   ail.amount <> sum(aid.amount)) maxdist,
        ap_invoice_distributions_all aid2
   WHERE aid2.invoice_id = maxdist.invoice_id
   AND   aid2.invoice_line_number = maxdist.invoice_line_number
   AND   aid2.distribution_line_number = maxdist.dist_line_number',
      p_title                  => 'MGD-1',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Automatic Withholding TAX (AWT) invoice distributions which will not validate due to rounding differences<br/><strong>Impact Area(s): </strong>Invoice Holds',
      p_solution               => '<strong>Solution GDF: </strong>13102335</br><strong>Note: </strong>[967242/KB428313]</br><strong>Script Name: </strong>AP_AWT_ROUNDING_DIFF_SEL.sql</br></br>Apply the GDF patch following the instructions provided in [967242/KB428313]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: 1');



debug('begin add_signature: 2');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Holds';
   l_info('bug_number'):= '19637573';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '964952.1';
   l_info('problem'):= 'Witholding invoice distributions which are not reversed, but the withholding line amount is 0. These invoices will be on distribution variance hold after cancelation.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 964952.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3910',
      p_sig_id                 => '2',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT aid.invoice_id,
          aid.org_id,
          aid.invoice_distribution_id unreversed_dist_id,
          aid.invoice_line_number unreversed_dist_line_num,
          aid.distribution_line_number unreversed_dist_num,
          aid.line_type_lookup_code unreversed_dist_line_type,
          aid.amount unreversed_dist_amt,
          ''1'' issue_type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid,
        ap_holds_all aha
   WHERE ai.invoice_id = invs.invoice_id
   AND   ail.invoice_id = ai.invoice_id
   AND   aid.invoice_id = ail.invoice_id
   AND   aha.invoice_id = ai.invoice_id
   AND   aha.hold_lookup_code = ''DIST VARIANCE''
   AND   aha.release_lookup_code is null
   AND   ai.invoice_amount = 0
   AND   nvl(ai.historical_flag,''N'') = ''N''
   AND   aid.awt_invoice_payment_id is null
   AND   ap_invoices_utility_pkg.get_approval_status (
           ai.invoice_id,
           ai.invoice_amount,
           ai.payment_status_flag,
           ai.invoice_type_lookup_code) = ''NEEDS REAPPROVAL''
   AND   ai.cancelled_date is null
   AND   ai.temp_cancelled_amount is not null
   AND   ail.line_type_lookup_code = ''AWT''
   AND   ail.invoice_id = ai.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.parent_reversal_id is null
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid1
           WHERE  aid1.invoice_id = aid.invoice_id
           AND    aid1.parent_reversal_id = aid.invoice_distribution_id)
   UNION
   SELECT aid.invoice_id,
          aid.org_id,
          aid.invoice_distribution_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.line_type_lookup_code,
          aid.amount,
          ''2''
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid,
        ap_holds_all aha
   WHERE ai.invoice_id = invs.invoice_id
   AND   ail.invoice_id = ai.invoice_id
   AND   aid.invoice_id = ail.invoice_id
   AND   aha.invoice_id(+) = ai.invoice_id
   AND   aha.release_lookup_code IS NOT NULL
   AND   ai.invoice_amount = 0
   AND   nvl(ai.historical_flag,''N'') = ''Y''
   AND   ai.cancelled_date IS NOT NULL
   AND   ail.line_type_lookup_code = ''AWT''
   AND   aid.invoice_line_number = ail.line_number
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.parent_reversal_id is null
   AND   nvl(aid.historical_flag,''N'') = ''Y''
   AND   aid.awt_invoice_id is null
   AND   aid.awt_invoice_payment_id is null
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = aid.invoice_id
           AND   aid1.parent_reversal_id = aid.invoice_distribution_id)',
      p_title                  => 'MGD-2',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Witholding invoice distributions which are not reversed, but the withholding line amount is 0. These invoices will be on distribution variance hold after cancelation.<br/><strong>Impact Area(s): </strong>Invoice Holds',
      p_solution               => '<strong>Solution GDF: </strong>19637573</br><strong>Note: </strong>[964952/KB202492]</br><strong>Script Name: </strong>unrev_man_awt_sel.sql</br></br>Apply the GDF patch following the instructions provided in [964952/KB202492]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
