debug('begin add_signature: 7');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Holds';
   l_info('bug_number'):= '9296562';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
