debug('begin add_signature: 12');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Holds';
   l_info('bug_number'):= '9227325';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1063226.1';
   l_info('problem'):= 'Upgraded invoices have reversal distributions with amounts different from the parent causing accounted invoices to require re-validation';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1063226.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3777',
      p_sig_id                 => '12',
      p_sig_sql                => 'SELECT  /*+ no_push_pred(@iview) ordered use_nl(ail) */
           ail.invoice_id,
           ail.org_id,
           ail.line_number,
           ail.historical_flag,
           ail.line_type_lookup_code
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoice_lines_all ail
   WHERE ail.historical_flag = ''Y''
   AND   ail.discarded_flag = ''Y''
   AND   ail.line_type_lookup_code <> ''AWT''
   AND   ail.amount = 0
   AND   ail.amount <>   (
           SELECT sum(amount)
           FROM ap_invoice_distributions_all aid
           WHERE ail.invoice_id = aid.invoice_id
           AND   ail.line_number = aid.invoice_line_number
           AND   aid.historical_flag = ''Y''  )
   AND   NOT EXISTS  (
           SELECT 1 /*+ no_unnest */ FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = ail.invoice_id
           AND   aid1.invoice_line_number = ail.line_number
           AND (nvl(aid1.historical_flag,''N'') = ''N'' OR
                nvl(aid1.reversal_flag,''N'')  <> ''Y''))
   AND   ail.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-12',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Upgraded invoices have reversal distributions with amounts different from the parent causing accounted invoices to require re-validation<br/><strong>Impact Area(s): </strong>Invoice Holds',
      p_solution               => '<strong>Solution GDF: </strong>9227325</br><strong>Note: </strong>[1063226/KB318081]</br><strong>Script Name: </strong>upd_rev_flg_11i_corup_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1063226/KB318081]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
