   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1072774.1';
   l_info('problem'):= 'Invoices with validation_request_id populated after invoice validation has completed with error';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1072774.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3758',
      p_sig_id                 => '14',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
