   l_info('problem'):= 'Invoices with duplicate AWT distributions created during payment with Payment Process Request (PPR)';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1188825.1';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3806',
      p_sig_id                 => '23',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ''1-A'' category,
          aid.invoice_id,
          aid.org_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.invoice_distribution_id,
          aid.accounting_event_id,
          aid.posted_flag,
          aid.parent_reversal_id
   FROM invs,
        ap_invoice_distributions_all aid,
        ap_invoice_lines_all ail,
        ap_system_parameters_all asp
   WHERE aid.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.awt_flag = ''A''
   AND   aid.historical_flag is null
   AND   aid.org_id = asp.org_id
   AND   ail.invoice_id = aid.invoice_id
   AND   ail.line_number = aid.invoice_line_number
   AND   asp.create_awt_dists_type = ''PAYMENT''
   AND   aid.awt_invoice_payment_id is null
   AND   NOT EXISTS (
           SELECT ''Invoice already withheld by AutoApproval''
           FROM ap_invoices_all ai
           WHERE ai.invoice_id = aid.invoice_id
           AND   nvl(ai.awt_flag, ''N'') = ''Y'')
   AND   EXISTS (
           SELECT 1 FROM fnd_product_installations pi
           WHERE  pi.application_id = 200
           AND substr(pi.patch_level, 8, 1) = ''A'')
   UNION ALL
   SELECT ''1-B'' category,
          aid.invoice_id,
          aid.org_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.invoice_distribution_id,
          aid.accounting_event_id,
          aid.posted_flag,
          aid.parent_reversal_id
   FROM invs,
        ap_invoice_distributions_all aid,
        ap_invoice_lines_all ail,
        ap_system_parameters_all asp
   WHERE aid.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.awt_flag = ''A''
   AND   aid.historical_flag is null
   AND   aid.org_id = asp.org_id
   AND   ail.invoice_id = aid.invoice_id
   AND   ail.line_number = aid.invoice_line_number
   AND   asp.create_awt_dists_type = ''PAYMENT''
   AND   ail.awt_group_id is not null
   AND   ail.pay_awt_group_id is null
   AND   NOT EXISTS (
           SELECT ''Invoice already withheld by AutoApproval''
           FROM ap_invoices_all ai
           WHERE ai.invoice_id = aid.invoice_id
           AND   nvl(ai.awt_flag, ''N'') = ''Y'')
   AND   EXISTS (
           SELECT 1 FROM fnd_product_installations pi
           WHERE  pi.application_id = 200
           AND   substr(pi.patch_level, 8, 1) <> ''A'')
   UNION ALL
   SELECT ''2-B'',
          aid.invoice_id,
          aid.org_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.invoice_distribution_id,
          aid.accounting_event_id,
          aid.posted_flag,
          aid.parent_reversal_id
   FROM invs,
        ap_invoice_distributions_all aid,
        ap_system_parameters_all asp,
        ap_invoice_lines_all ail
   WHERE aid.line_type_lookup_code = ''AWT''
   AND   aid.awt_flag = ''A''
   AND   aid.awt_invoice_payment_id is null
   AND   aid.historical_flag is null
   AND   aid.org_id = asp.org_id
   AND   aid.invoice_id = ail.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   asp.create_awt_dists_type = ''PAYMENT''
   AND   ail.awt_group_id is null
   AND   ail.pay_awt_group_id is not null
   AND   NOT EXISTS (
           SELECT ''Invoice already withheld by AutoApproval''
           FROM ap_invoices_all ai
           WHERE ai.invoice_id = aid.invoice_id
           AND   nvl(ai.awt_flag, ''N'') = ''Y'')
   AND   aid.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-23',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices with duplicate AWT distributions created during payment with Payment Process Request (PPR)<br/><strong>Impact Area(s): </strong>Automatic Witholding Tax, Period Close',
      p_solution               => '<strong>Solution GDF: </strong>17311645</br><strong>Note: </strong>[1188825/KB764574]</br><strong>Script Name: </strong>AP_DUP_PMT_AWT_DISTS_SEL.sql Duplicate Dists</br></br>Apply the GDF patch following the instructions provided in [1188825/KB764574]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
