debug('begin add_signature: 24');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '18681921';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1272497.1';
   l_info('problem'):= 'Functional currency invoices created through import/quick invoicing which have BASE_AMOUNT populated causing incorrect accounting entries to be created.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1272497.1';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3807',
      p_sig_id                 => '24',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_type_lookup_code invoice_type,
          ai.source,
          asp.base_currency_code base_currency,
          ai.invoice_currency_code invoice_currency,
          ai.exchange_rate,
          ai.exchange_rate_type,
          ai.exchange_date,
          ai.invoice_amount,
          ai.base_amount invoice_base_amt,
          aid.invoice_line_number,
          aid.line_type_lookup_code,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          aid.posted_flag,
          aid.accounting_event_id event_id,
          aid.bc_event_id bc_event_id,
          aid.amount distribution_amt,
          aid.base_amount dist_base_amt,
          decode(aid.posted_flag,
            ''Y'',''Accounted'',
            ''Not Accounted'') accounting_status,
          decode(ai.attribute15,
            ''DUMMY_9884253'', ai.attribute15,
            '''') error_message,
          decode((SELECT tax.invoice_distribution_id
                  FROM ap_invoice_distributions_all tax
                  WHERE tax.line_type_lookup_code in (''NONREC_TAX'',''REC_TAX'',
                          ''TRV'',''TIPV'',''TERV'')
                  AND   ai.invoice_id = tax.invoice_id(+)
                  AND   rownum < 2),
            null, ''N'',
            ''Y'') tax_dists_exists,
          decode((SELECT tax.invoice_distribution_id
                  FROM ap_self_assessed_tax_dist_all tax
                  WHERE ai.invoice_id = tax.invoice_id(+)
                  AND   rownum < 2),
            null, ''N'',
            ''Y'') self_assess_tax_exists,
          decode((SELECT ipv.invoice_distribution_id
                  FROM ap_invoice_distributions_all ipv
                  WHERE ipv.line_type_lookup_code in (''IPV'')
                  AND   ipv.corrected_invoice_dist_id IS NULL
                  AND   ai.invoice_id = ipv.invoice_id(+)
                  AND   rownum < 2),
            null, ''N'',
            ''Y'') ipv_dists_exists,
          decode((SELECT ''variance calculated''
                  FROM ap_invoice_distributions_all aidvar
                  WHERE ai.invoice_id = aidvar.invoice_id
                  AND   (aidvar.quantity_variance is not null OR
                         aidvar.amount_variance is not null OR
                         aidvar.base_quantity_variance is not null OR
                         aidvar.base_amount_variance is not null)
                  AND   rownum < 2),
             null, ''N'',
             ''Y'') var_dists_exists
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        ap_system_parameters_all asp
   WHERE ai.invoice_id = aid.invoice_id
   AND   ai.invoice_type_lookup_code <> ''EXPENSE REPORT''
   AND   ai.source <> ''ERS''
   AND   asp.org_id = ai.org_id
   AND   ai.invoice_currency_code = asp.base_currency_code
   AND   (aid.line_type_lookup_code NOT IN (''NONREC_TAX'',''REC_TAX'',
           ''TRV'',''TIPV'',''TERV'', ''IPV'', ''ERV'', ''AWT'') OR
          (aid.line_type_lookup_code = ''IPV'' AND
           aid.corrected_invoice_dist_id IS NOT NULL))
   AND   ((aid.base_amount  is not null AND
           aid.amount <> aid.base_amount) OR (
          EXISTS (
            SELECT 1 FROM ap_invoice_distributions_all aid1
            WHERE aid.invoice_id = aid1.invoice_id
            AND   aid1.line_type_lookup_code = ''ERV'')))
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-24',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Functional currency invoices created through import/quick invoicing which have BASE_AMOUNT populated causing incorrect accounting entries to be created.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>18681921</br><strong>Note: </strong>[1272497/KB328520]</br><strong>Script Name: </strong>ap_func_curr_inv_with_base_amt_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1272497/KB328520]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: 24');



debug('begin add_signature: 25');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Validation Selection';
   l_info('bug_number'):= '17399548';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1272433.1';
   l_info('problem'):= 'Tax lines without distributions caused by inconsistent cancellation information in ZX_LINES and ZX_LINES_SUMMARY. These invoices are repeatedly picked up for validation even though they are already validated.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1272433.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3796',
      p_sig_id                 => '25',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ail.invoice_id,
          ail.org_id,
          ail.line_number,
          ail.line_type_lookup_code,
          ail.summary_tax_line_id,
          ail.amount,
          ail.cancelled_flag,
          ail.discarded_flag
   FROM invs,
        ap_invoice_lines_all ail
   WHERE ail.line_type_lookup_code = ''TAX''
   AND   ail.summary_tax_line_id is not null
   AND   nvl(ail.cancelled_flag,''N'') = ''N''
   AND   nvl(ail.discarded_flag,''N'') = ''N''
   AND   ail.generate_dists = ''Y''
   AND   EXISTS (
           SELECT 1 FROM zx_lines zl1
           WHERE zl1.trx_id = ail.invoice_id
           AND   zl1.application_id = 200
           AND   zl1.entity_code = ''AP_INVOICES''
           AND   zl1.event_class_code IN (''STANDARD INVOICES'' ,
                   ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'')
           AND   zl1.summary_tax_line_id = ail.summary_tax_line_id)
   AND   NOT EXISTS (
           SELECT 1 FROM zx_lines zl
           WHERE zl.trx_id = ail.invoice_id
           AND   zl.application_id = 200
           AND   zl.entity_code = ''AP_INVOICES''
           AND   zl.event_class_code IN (''STANDARD INVOICES'' ,
                   ''PREPAYMENT INVOICES'',''EXPENSE REPORTS'')
           AND zl.summary_tax_line_id = ail.summary_tax_line_id
           AND nvl(cancel_flag,''N'') = ''N'')
   AND   NOT EXISTS (
           SELECT 1 FROM zx_lines_summary zls
           WHERE zls.trx_id = ail.invoice_id
           AND   zls.application_id = 200
           AND   zls.entity_code = ''AP_INVOICES''
           AND   zls.event_class_code IN (''STANDARD INVOICES'' ,
                   ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'')
           AND zls.summary_tax_line_id = ail.summary_tax_line_id
           AND nvl(zls.cancel_flag,''N'') = ''Y'')
   AND   ail.invoice_id = invs.invoice_id
   UNION ALL
   SELECT ail.invoice_id,
          ail.org_id,
          ail.line_number,
          ail.line_type_lookup_code,
          ail.summary_tax_line_id,
          ail.amount,
          ail.cancelled_flag,
          ail.discarded_flag
   FROM invs,
        ap_invoice_lines_all ail
   WHERE ail.line_type_lookup_code = ''TAX''
   AND   ail.summary_tax_line_id is not null
   AND   nvl(ail.cancelled_flag,''N'') = ''N''
   AND   nvl(ail.discarded_flag,''N'') = ''N''
   AND   ail.generate_dists = ''Y''
   AND   EXISTS (
           SELECT 1
           FROM zx_lines zl2,
                ap_invoice_lines_all ail2
           WHERE zl2.trx_line_id = ail2.line_number
           AND zl2.summary_tax_line_id = ail.summary_tax_line_id
           AND zl2.trx_id = ail2.invoice_id
           AND ail2.invoice_id = ail.invoice_id
           AND zl2.application_id = 200
           AND zl2.entity_code = ''AP_INVOICES''
           AND zl2.event_class_code IN (''STANDARD INVOICES'',
                 ''PREPAYMENT INVOICES''  , ''EXPENSE REPORTS'')
           AND nvl(ail2.discarded_flag,''N'') = ''Y'')
   AND   EXISTS (
           SELECT 1 FROM zx_lines zl1
           WHERE zl1.trx_id = ail.invoice_id
           AND   zl1.application_id = 200
           AND   zl1.entity_code = ''AP_INVOICES''
           AND   zl1.event_class_code IN (''STANDARD INVOICES'',
                   ''PREPAYMENT INVOICES''  , ''EXPENSE REPORTS'')
           AND zl1.summary_tax_line_id = ail.summary_tax_line_id)
   AND   NOT EXISTS (
           SELECT 1 FROM zx_lines zl
           WHERE zl.trx_id = ail.invoice_id
           AND   zl.application_id = 200
           AND   zl.entity_code = ''AP_INVOICES''
           AND   zl.event_class_code IN (''STANDARD INVOICES'',
                   ''PREPAYMENT INVOICES''  , ''EXPENSE REPORTS'')
           AND   zl.summary_tax_line_id = ail.summary_tax_line_id
           AND   NVL(cancel_flag,''N'') = ''Y'')
   AND   NOT EXISTS (
           SELECT 1 FROM zx_lines_summary zls
           WHERE zls.trx_id = ail.invoice_id
           AND   zls.application_id = 200
           AND   zls.entity_code = ''AP_INVOICES''
           AND   zls.event_class_code IN (''STANDARD INVOICES'',
                   ''PREPAYMENT INVOICES''  , ''EXPENSE REPORTS'')
           AND   zls.summary_tax_line_id = ail.summary_tax_line_id
           AND   NVL(zls.cancel_flag,''N'') = ''Y'' )
   AND   ail.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-25',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Tax lines without distributions caused by inconsistent cancellation information in ZX_LINES and ZX_LINES_SUMMARY. These invoices are repeatedly picked up for validation even though they are already validated.<br/><strong>Impact Area(s): </strong>Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>17399548</br><strong>Note: </strong>[1272433/KB779034]</br><strong>Script Name: </strong>ap_canc_tax_lines_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1272433/KB779034]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: 25');



debug('begin add_signature: 26');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '21087115';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1272440.1';
   l_info('problem'):= 'Invoices which are not part of the legal entity or ledger context of the balancing segment values of its account code combinations result in error# 95311 during accounting';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1272440.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3800',
      p_sig_id                 => '26',
      p_sig_sql                => 'SELECT  a.invoice_date,
                 a.org_id,
                 a.invoice_num,
                 a.invoice_id,
          a.invoice_line_number,
          a.invoice_distribution_id,
          a.line_type_lookup_code,
          a.posted_flag,
          a.accounting_date,
          a.period_name,
          a.chart_of_accounts_id,
          a.set_of_books_id,
          a.dist_match_type,
          a.po_distribution_id,
          a.rcv_transaction_id,
          a.detail_tax_dist_id,
          a.detail_posting_allowed_flag,
          a.enabled_flag,
          a.account_type,
          a.summary_flag,
          a.old_code_combid,
          a.new_code_combid,
          a.old_balancing_seg_value,
          a.new_balancing_seg_value,
          a.old_concat_account,
          a.new_concat_account,
          a.error_message,
          a.bal_seg_valid
   FROM (
          SELECT /*+ leading(invs) */
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_num,
                 ai.invoice_id,
                 aid.invoice_line_number,
                 aid.invoice_distribution_id,
                 aid.line_type_lookup_code,
                 aid.posted_flag,
                 aid.accounting_date,
                 aid.period_name,
                 gsb.chart_of_accounts_id,
                 aid.set_of_books_id,
                 aid.dist_match_type,
                 aid.po_distribution_id,
                 aid.rcv_transaction_id,
                 aid.detail_tax_dist_id,
                 gcc.detail_posting_allowed_flag,
                 gcc.enabled_flag,
                 gcc.account_type,
                 gcc.summary_flag,
                 nvl((SELECT ''1'' /*+cardinality(glsv 1)*/
                      FROM gl_ledger_segment_values glsv
                      WHERE glsv.segment_value =
                              ap_invoice_distributions_pkg.get_balancing_segment_value(
                                aid.dist_code_combination_id,
                                aid.set_of_books_id)
                      AND glsv.segment_type_code = ''B''
                      AND glsv.ledger_id = aid.set_of_books_id
                      AND aid.accounting_date BETWEEN
                            nvl(glsv.start_date, aid.accounting_date) AND
                            nvl(glsv.end_date, aid.accounting_date)
                      AND rownum = 1), 0) "BAL_SEG_VALID",
                 ap_invoice_distributions_pkg.get_balancing_segment_value(
                   aid.dist_code_combination_id,
                   aid.set_of_books_id) "OLD_BALANCING_SEG_VALUE",
                 decode(gcc.segment1,
                   ''DUMMY'',gcc.segment1,
                   '''') "NEW_BALANCING_SEG_VALUE",
                 aid.dist_code_combination_id "OLD_CODE_COMBID",
                 decode(gcc.code_combination_id,
                   000000,gcc.code_combination_id,
                   null) "NEW_CODE_COMBID",
                 fnd_flex_ext.get_segs(''SQLGL'', ''GL#'', gsb.chart_of_accounts_id,
                   aid.dist_code_combination_id) "OLD_CONCAT_ACCOUNT",
                   decode(aid.global_attribute_category,
                     ''DUMMY'',aid.global_attribute_category,
                     '''') "NEW_CONCAT_ACCOUNT",
                 decode(aid.global_attribute1,
                   ''DUMMY'',aid.global_attribute1,
                   '''') "ERROR_MESSAGE"
          FROM (
                 ##$$IVIEW$$##
               ) invs,
               ap_invoices_all              ai,
               ap_invoice_distributions_all aid,
               ap_system_parameters_all     asp,
               gl_code_combinations         gcc,
               gl_ledgers                   gl,
               gl_sets_of_books             gsb
          WHERE ai.invoice_id = invs.invoice_id
          AND   aid.invoice_id = ai.invoice_id
          AND   aid.dist_code_combination_id = gcc.code_combination_id
          AND   aid.set_of_books_id = gl.ledger_id
          AND   aid.historical_flag is null
          AND   aid.posted_flag <> ''Y''
          AND   nvl(gl.bal_seg_value_option_code, ''A'') <> ''A''
          AND   ai.org_id = asp.org_id
          AND   asp.set_of_books_id = gsb.set_of_books_id
          UNION ALL
          SELECT /*+ leading(invs) */
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_num,
                 ai.invoice_id,
                 aid.invoice_line_number,
                 aid.invoice_distribution_id,
                 aid.line_type_lookup_code,
                 aid.posted_flag,
                 aid.accounting_date,
                 aid.period_name,
                 gsb.chart_of_accounts_id,
                 aid.set_of_books_id,
                 aid.dist_match_type,
                 aid.po_distribution_id,
                 aid.rcv_transaction_id,
                 aid.detail_tax_dist_id,
                 gcc.detail_posting_allowed_flag,
                 gcc.enabled_flag,
                 gcc.account_type,
                 gcc.summary_flag,
                 nvl((
                   SELECT ''1'' /*+cardinality(glsv 1)*/
                   FROM gl_ledger_segment_values glsv
                   WHERE glsv.segment_value =
                           ap_invoice_distributions_pkg.get_balancing_segment_value(
                             aid.dist_code_combination_id,
                             aid.set_of_books_id)
                   AND   glsv.segment_type_code = ''B''
                   AND   glsv.ledger_id = aid.set_of_books_id
                   AND   aid.accounting_date BETWEEN
                           nvl(glsv.start_date, aid.accounting_date) AND
                           nvl(glsv.end_date, aid.accounting_date)
                   AND   rownum = 1), 0) "BAL_SEG_VALID",
                 ap_invoice_distributions_pkg.get_balancing_segment_value(
                   aid.dist_code_combination_id,
                   aid.set_of_books_id) "OLD_BALANCING_SEG_VALUE",
                 decode(gcc.segment1,
                   ''DUMMY'',gcc.segment1,'''') "NEW_BALANCING_SEG_VALUE",
                 aid.dist_code_combination_id "OLD_CODE_COMBID",
                 decode(gcc.code_combination_id,
                   000000,gcc.code_combination_id,null) "NEW_CODE_COMBID",
                 fnd_flex_ext.get_segs(''SQLGL'',
                   ''GL#'',
                   gsb.chart_of_accounts_id,
                   aid.dist_code_combination_id) "OLD_CONCAT_ACCOUNT",
                   decode(aid.global_attribute_category,
                     ''DUMMY'',aid.global_attribute_category,'''') "NEW_CONCAT_ACCOUNT",
                 decode(aid.global_attribute1,
                     ''DUMMY'',aid.global_attribute1,'''') "ERROR_MESSAGE"
          FROM (
                 ##$$IVIEW$$##
               ) invs,
               ap_invoices_all ai,
               ap_self_assessed_tax_dist_all aid,
               gl_ledgers gl,
               gl_code_combinations gcc,
               ap_system_parameters_all asp,
               gl_sets_of_books gsb
          WHERE ai.invoice_id = invs.invoice_id
          AND   ai.historical_flag is null
          AND   aid.invoice_id = ai.invoice_id
          AND   aid.posted_flag <> ''Y''
          AND   aid.dist_code_combination_id = gcc.code_combination_id
          AND   aid.set_of_books_id = gl.ledger_id
          AND   nvl(gl.bal_seg_value_option_code, ''A'') <> ''A''
          AND   ai.org_id = asp.org_id
          AND   asp.set_of_books_id = gsb.set_of_books_id
        ) a
   WHERE a.bal_seg_valid = 0',
      p_title                  => 'MGD-26',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices which are not part of the legal entity or ledger context of the balancing segment values of its account code combinations result in error# 95311 during accounting<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>21087115</br><strong>Note: </strong>[1272440/KB778204]</br><strong>Script Name: </strong>ap_wrong_bal_segment_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1272440/KB778204]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: 26');



debug('begin add_signature: 27');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure, Invoice Cancellation, Validation Selection';
   l_info('bug_number'):= '19637587';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1266869.1';
   l_info('problem'):= 'Multiple common invoice related issues. See [1266869.1] for a full listing of the detailed issues captured by this query';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1266869.1';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3801',
      p_sig_id                 => '27',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
)
SELECT /*+ ordered use_nl(ai, aid) */
    1                           corruption_type,
    aid.invoice_id,
    aid.org_id, 
    ai.invoice_date,
    aid.invoice_distribution_id child_id,
    aid.accounting_event_id,
    aid.bc_event_id,
    aid.posted_flag,
          aid.match_status_flag
FROM
    invs,
    ap_invoices_all              ai,
    ap_invoice_distributions_all aid,
    financials_system_params_all fsp
WHERE
        ai.invoice_id = invs.invoice_id
    AND aid.invoice_id = ai.invoice_id
    AND aid.posted_flag = ''Y''
    AND ai.org_id = fsp.org_id
    AND ( ( nvl(fsp.purch_encumbrance_flag, ''N'') = ''N''
            AND aid.match_status_flag NOT IN ( ''T'', ''A'' ) )
          OR ( nvl(fsp.purch_encumbrance_flag, ''N'') = ''Y''
               AND aid.match_status_flag <> ''A'' ) )
    AND EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            xla_events x
        WHERE
                x.application_id = 200
            AND x.event_id = aid.accounting_event_id
            AND x.event_status_code IN ( ''N'', ''P'' )
            AND x.process_status_code = ''P''
    )
UNION ALL
SELECT /*+ordered use_nl(asa) */
    1.1 corruption_type,
    asa.invoice_id,
    asa.org_id,
    ai.invoice_date,
    asa.invoice_distribution_id,
    asa.accounting_event_id,
    asa.bc_event_id,
    asa.posted_flag,
         null
FROM
    invs,
    ap_self_assessed_tax_dist_all asa,
    ap_invoices_all ai
WHERE
        asa.invoice_id = invs.invoice_id
        and ai.invoice_id=invs.invoice_id
    AND asa.posted_flag = ''Y''
    AND nvl(asa.match_status_flag, ''N'') <> ''A''
    AND EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            xla_events x
        WHERE
                x.application_id = 200
            AND x.event_id = asa.accounting_event_id
            AND x.event_status_code IN ( ''N'', ''P'' )
            AND x.process_status_code = ''P''
    )
UNION ALL
SELECT /*+ ordered use_nl(aid) */
    2,
    aid.invoice_id,
    aid.org_id,
     ai.invoice_date,
    aid.invoice_distribution_id,
    aid.accounting_event_id,
    aid.bc_event_id,
    aid.posted_flag,
          aid.match_status_flag
FROM
    invs,
    ap_invoice_distributions_all aid,
    ap_invoices_all ai
WHERE
    line_type_lookup_code IN ( ''REC_TAX'', ''NONREC_TAX'', ''TRV'', ''TERV'', ''TIPV'' )
    AND detail_tax_dist_id IS NULL
    AND summary_tax_line_id IS NULL
    AND nvl(aid.historical_flag, ''N'') = ''N''
    AND aid.invoice_id = invs.invoice_id
    and ai.invoice_id=invs.invoice_id
UNION ALL
SELECT /*+ ordered use_nl(asad) */
    3,
    asad.invoice_id,
    asad.org_id,
     ai.invoice_date,
    asad.invoice_distribution_id,
    asad.accounting_event_id,
    asad.bc_event_id,
    asad.posted_flag,
null
FROM
    invs,
    ap_self_assessed_tax_dist_all asad,
    ap_invoices_all ai
WHERE
    EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            zx_rec_nrec_dist zd
        WHERE
                zd.trx_id = asad.invoice_id
            AND zd.rec_nrec_tax_dist_id = asad.detail_tax_dist_id
            AND zd.entity_code = ''AP_INVOICES''
            AND zd.event_class_code IN ( ''STANDARD INVOICES'', ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'' )
            AND zd.application_id = 200
            AND zd.self_assessed_flag = ''N''
    )
    AND asad.invoice_id = invs.invoice_id
    and ai.invoice_id=invs.invoice_id
UNION ALL
SELECT /*+ ordered use_nl(aid) */
    4,
    aid.invoice_id,
    aid.org_id,
     ai.invoice_date,
    aid.invoice_distribution_id,
    aid.accounting_event_id,
    aid.bc_event_id,
    aid.posted_flag,
          aid.match_status_flag
FROM
    invs,
    ap_invoice_distributions_all aid,
    ap_invoices_all ai
WHERE
    aid.detail_tax_dist_id IS NOT NULL
    AND nvl(aid.historical_flag, ''N'') = ''N''
    AND EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            zx_rec_nrec_dist zd
        WHERE
                zd.trx_id = aid.invoice_id
            AND zd.rec_nrec_tax_dist_id = aid.detail_tax_dist_id
            AND zd.entity_code = ''AP_INVOICES''
            AND zd.event_class_code IN ( ''STANDARD INVOICES'', ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'' )
            AND zd.application_id = 200
            AND zd.self_assessed_flag = ''Y''
    )
    AND aid.invoice_id = invs.invoice_id
    and ai.invoice_id=invs.invoice_id
UNION ALL
SELECT /*+ ordered use_nl(ai, asad) */
    5,
    ai.invoice_id,
    ai.org_id,
     ai.invoice_date,
    asad.invoice_distribution_id,
    NULL,
    NULL,
    NULL,
null
FROM
    invs,
    ap_invoices_all               ai,
    ap_self_assessed_tax_dist_all asad
WHERE
        ai.invoice_id = asad.invoice_id
    AND asad.accounting_event_id IS NULL
    AND asad.bc_event_id IS NULL
    AND ai.cancelled_date IS NULL
    AND nvl(ai.force_revalidation_flag, ''N'') <> ''Y''
    AND ap_invoices_pkg.get_approval_status(ai.invoice_id, ai.invoice_amount, ai.payment_status_flag, ai.invoice_type_lookup_code) IN (
    ''APPROVED'', ''AVAILABLE'',
                                                                                                                                 ''UNPAID'',
                                                                                                                                 ''FULL'' )
    AND ai.invoice_id = invs.invoice_id
UNION ALL
SELECT /*+ ordered use_nl(aha) */
    6,
    aha.invoice_id,
    aha.org_id,
     ai.invoice_date,
    aha.hold_id,
    NULL,
    NULL,
    NULL,
null
FROM
    invs,
    ap_holds_all aha,
    ap_invoices_all ai
WHERE
        hold_lookup_code = ''CANNOT EXECUTE ALLOCATION''
    AND release_lookup_code IS NULL
    AND NOT EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            ap_invoice_lines_all ail
        WHERE
                ail.invoice_id = aha.invoice_id
            AND line_type_lookup_code IN ( ''FREIGHT'', ''MISCELLANEOUS'' )
            AND nvl(discarded_flag, ''N'') = ''N''
            AND nvl(generate_dists, ''N'') = ''Y''
    )
    AND aha.invoice_id = invs.invoice_id
    and ai.invoice_id=invs.invoice_id
UNION ALL
SELECT /*+ ordered use_nl(ai) */
    7,
    ai.invoice_id,
    ai.org_id,
     ai.invoice_date,
    NULL,
    NULL,
    NULL,
    NULL,
null
FROM
    invs,
    ap_invoices_all ai
WHERE
        nvl(ai.historical_flag, ''N'') = ''N''
    AND ai.cancelled_date IS NOT NULL
    AND nvl(ai.amount_paid, 0) <> 0
    AND ai.invoice_id = invs.invoice_id
UNION ALL
SELECT /*+ ordered use_nl(ai) */
    8,
    ai.invoice_id,
    ai.org_id,
     ai.invoice_date,
    NULL,
    NULL,
    NULL,
    NULL,
null
FROM
    invs,
    ap_invoices_all ai
WHERE
    ai.cancelled_date IS NOT NULL
    AND ai.invoice_amount = 0
    AND nvl(ai.historical_flag, ''N'') = ''N''
    AND EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            ap_payment_schedules_all aps
        WHERE
                aps.invoice_id = ai.invoice_id
            AND aps.hold_flag = ''Y''
    )
    AND ai.invoice_id = invs.invoice_id
UNION ALL
SELECT /*+ ordered use_nl(ai, aidrev) */
    9,
    ai.invoice_id,
    ai.org_id,
     ai.invoice_date,
    aidrev.invoice_distribution_id,
    aidrev.accounting_event_id,
    aidrev.bc_event_id,
    aidrev.posted_flag,
          aidrev.match_status_flag
FROM
    invs,
    ap_invoices_all              ai,
    ap_invoice_distributions_all aidrev
WHERE
        ai.invoice_id = aidrev.invoice_id
    AND nvl(ai.historical_flag, ''N'') = ''N''
    AND aidrev.parent_reversal_id IS NOT NULL
    AND aidrev.reversal_flag = ''Y''
    AND EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            ap_invoice_distributions_all aidori
        WHERE
                aidori.invoice_id = aidrev.invoice_id
            AND aidori.invoice_line_number = aidrev.invoice_line_number
            AND aidori.invoice_distribution_id = aidrev.parent_reversal_id
            AND abs(nvl(aidori.amount, 0)) <> abs(nvl(aidrev.amount, 0))
    )
    AND ai.invoice_id = invs.invoice_id
UNION ALL
SELECT  /*+ ordered use_nl(aid) */
    10,
    aid.invoice_id,
    aid.org_id,
     ai.invoice_date,
    aid.invoice_distribution_id,
    aid.accounting_event_id,
    aid.bc_event_id,
    aid.posted_flag,
          aid.match_status_flag
FROM
    invs,
    ap_invoice_distributions_all aid,
    ap_invoices_all ai
WHERE
        match_status_flag = ''S''
    AND nvl(aid.historical_flag, ''N'') = ''N''
    AND EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            ap_invoices_all ai
        WHERE
                ai.invoice_id = aid.invoice_id
            AND ai.validation_request_id IS NULL
    )
    AND aid.invoice_id = invs.invoice_id
    and ai.invoice_id=invs.invoice_id
UNION ALL
SELECT /*+ ordered use_nl(ai, aid) */
    11,
    ai.invoice_id,
    ai.org_id,
     ai.invoice_date,
    aid.invoice_distribution_id,
    aid.accounting_event_id,
    aid.bc_event_id,
    aid.posted_flag,
          aid.match_status_flag
FROM
    invs,
    ap_invoices_all              ai,
    ap_invoice_distributions_all aid,
    financials_system_params_all fsp
WHERE
        ai.org_id = fsp.org_id
    AND ai.invoice_id = aid.invoice_id
    AND ai.cancelled_date IS NOT NULL
    AND aid.accounting_event_id IS NOT NULL
    AND ai.invoice_amount = 0
    AND nvl(ai.historical_flag, ''N'') = ''N''
    AND ai.validation_request_id IS NULL
    AND 0 = (
        SELECT /*+ no_unnest */
            SUM(aid1.amount)
        FROM
            ap_invoice_distributions_all aid1
        WHERE
            aid1.invoice_id = ai.invoice_id
    )
    AND NOT EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            ap_invoice_distributions_all aid2
        WHERE
                aid2.invoice_id = ai.invoice_id
            AND aid2.parent_reversal_id IS NULL
            AND aid2.reversal_flag = ''Y''
            AND 1 <> (
                SELECT /*+ no_unnest */
                    COUNT(1)
                FROM
                    ap_invoice_distributions_all aid3
                WHERE
                    aid3.parent_reversal_id = aid2.invoice_distribution_id
            )
    )
    AND ( ( nvl(aid.match_status_flag, ''N'') <> ''A''
            AND fsp.purch_encumbrance_flag = ''Y'' )
          OR ( nvl(aid.match_status_flag, ''N'') NOT IN ( ''A'', ''T'' )
               AND fsp.purch_encumbrance_flag = ''N'' ) )
    AND ai.invoice_id = invs.invoice_id
UNION ALL
SELECT /*+ ordered use_nl(ai, ail, aid) */
    12,
    ai.invoice_id,
    ai.org_id,
     ai.invoice_date,
    aid.invoice_distribution_id,
    aid.accounting_event_id,
    aid.bc_event_id,
    aid.posted_flag,
          aid.match_status_flag
FROM
    invs,
    ap_invoices_all              ai,
    financials_system_params_all fsp,
    ap_invoice_lines_all         ail,
    ap_invoice_distributions_all aid
WHERE
        ai.invoice_id = invs.invoice_id
    AND ail.invoice_id = ai.invoice_id
    AND aid.invoice_id = ail.invoice_id
    AND ai.org_id = fsp.org_id
    AND ( nvl(ail.cancelled_flag, ''N'') = ''Y''
          OR nvl(ail.discarded_flag, ''N'') = ''Y'' )
    AND ai.cancelled_date IS NOT NULL
    AND aid.line_type_lookup_code = ''AWT''
    AND aid.parent_reversal_id IS NOT NULL
    AND aid.awt_invoice_payment_id IS NULL
    AND aid.reversal_flag = ''Y''
    AND aid.accounting_event_id IS NULL
    AND nvl(aid.match_status_flag, ''N'') = ''N''
    AND EXISTS (
        SELECT /*+ no_unnest */
            1
        FROM
            xla_transaction_entities_upg xte,
            xla_events                   xe
        WHERE
                xte.entity_id = xe.entity_id
            AND xte.ledger_id = aid.set_of_books_id
            AND nvl(xte.source_id_int_1, - 99) = aid.invoice_id
            AND xte.entity_code = ''AP_INVOICES''
            AND xte.application_id = 200
            AND xe.event_type_code LIKE ''%CANCELLED''
            AND xe.budgetary_control_flag = ''N''
    )
    AND NOT EXISTS (
        SELECT
            1
        FROM
            ap_holds_all aha
        WHERE
                aha.invoice_id = ai.invoice_id
            AND aha.release_lookup_code IS NULL
    )
    AND fsp.purch_encumbrance_flag = ''N''',
      p_title                  => 'MGD-27',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Multiple common invoice related issues. See [1266869/KB748792] for a full listing of the detailed issues captured by this query<br/><strong>Impact Area(s): </strong>Accounting Failure, Invoice Cancellation, Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>19637587</br><strong>Note: </strong>[1266869/KB748792]</br><strong>Script Name: </strong>AP_MISC_INVOICE_DIAG.sql</br></br>Apply the GDF patch following the instructions provided in [1266869/KB748792]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '24'
      );
   l_info.delete;
debug('end add_signature: 27');



debug('begin add_signature: 28');
