      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: 29');



debug('begin add_signature: 30');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Cancellation';
   l_info('bug_number'):= '17495389';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1359299.1';
   l_info('problem'):= 'Canceled invoices having extra miscellaneous lines and distributions';
   l_info('solution'):= 'generic datafix patch (GDF)';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3803',
      p_sig_id                 => '30',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ail.line_type_lookup_code,
          ail.line_number,
          ail.amount
   FROM ap_invoice_lines_all ail,
        ap_invoices_all ai,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE ai.cancelled_date is not null
   AND   ail.invoice_id = ai.invoice_id
   AND   nvl(ail.historical_flag, ''N'') = ''N''
   AND   ail.line_type_lookup_code = ''MISCELLANEOUS''
   AND   (ail.amount <> 0 OR
          (SELECT sum(amount) FROM ap_invoice_distributions_all
           WHERE invoice_id = ail.invoice_id
           AND   invoice_line_number = ail.line_number) <> 0)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-30',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Canceled invoices having extra miscellaneous lines and distributions<br/><strong>Impact Area(s): </strong>Invoice Cancellation',
      p_solution               => '<strong>Solution GDF: </strong>17495389</br><strong>Note: </strong>[1359299/KB794233]</br><strong>Script Name: </strong>ap_misc_del_sel.sql</br></br>generic datafix patch (GDF)</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: 30');



debug('begin add_signature: 31');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Discard';
   l_info('bug_number'):= '18018607';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1329681.1';
   l_info('problem'):= 'Matched distributions are reversed when line is discarded but the line is not discarded';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1329681.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3802',
      p_sig_id                 => '31',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ail.line_number,
          aid.parent_reversal_id inv_dist_id,
          ail.line_type_lookup_code line_type,
          ail.discarded_flag,
          1 corruption_type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = ail.invoice_id
   AND   ail.invoice_id = aid.invoice_id
   AND   ail.line_number = aid.invoice_line_number
   AND   ai.cancelled_date is null
   AND   nvl(ail.historical_flag,''N'') = ''N''
   AND   nvl(ail.discarded_flag,''N'') = ''Y''
   AND   nvl(aid.posted_flag,''N'') <> ''Y''
   AND   nvl(aid.reversal_flag,''N'') = ''Y''
   AND   aid.parent_reversal_id is not null
   AND   (aid.amount)*-1 <> (
           SELECT amount FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = aid.invoice_id
           AND   aid1.invoice_distribution_id = aid.parent_reversal_id)
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT ail.invoice_id,
           null,
           ail.org_id,
           ail.line_number,
           null,
           ail.line_type_lookup_code,
           ail.discarded_flag,
           2
   FROM invs,
        ap_invoice_lines_all ail
   WHERE nvl(ail.discarded_flag,''N'') = ''Y''
   AND   ail.amount <> 0
   AND   nvl(ail.historical_flag,''N'') <> ''Y''
   AND   (NOT EXISTS (
            SELECT 1 FROM ap_invoice_distributions_all aid
            WHERE aid.invoice_id = ail.invoice_id
            AND   aid.invoice_line_number = ail.line_number) OR
         (SELECT sum(aid.amount) FROM ap_invoice_distributions_all aid
          WHERE aid.invoice_id = ail.invoice_id
          AND   aid.invoice_line_number = ail.line_number) = 0)
   AND   ail.invoice_id = invs.invoice_id
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ail.line_number,
          null,
          ail.line_type_lookup_code,
          ail.discarded_flag,
          3
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail
   WHERE ai.invoice_id = ail.invoice_id
   AND   nvl(ail.discarded_flag,''N'') <> ''Y''
   AND   nvl(ail.cancelled_flag, ''N'') <> ''Y''
   AND   ail.po_line_location_id is not null
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all dist
           WHERE dist.invoice_id = ail.invoice_id
           AND   dist.invoice_line_number = ail.line_number
           AND   dist.po_distribution_id is not null
           AND   dist.reversal_flag = ''Y''  )
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-31',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Matched distributions are reversed when line is discarded but the line is not discarded<br/><strong>Impact Area(s): </strong>Invoice Discard',
      p_solution               => '<strong>Solution GDF: </strong>18018607</br><strong>Note: </strong>[1329681/KB796151]</br><strong>Script Name: </strong>AP_DISCARD_LINE_SEL.sql</br></br>Apply the GDF patch following the instructions provided in [1329681/KB796151]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: 31');



debug('begin add_signature: 32');
   l_info('##SHOW_SQL##'):= 'Y';
