   l_info('note_number'):= '1276536.1';
   l_info('problem'):= 'Invoice batches with duplicate batch names';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1276536.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3845',
      p_sig_id                 => '32',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ''Duplicate Batch Name'' Issue_type,
          ab.batch_id,
          ab.org_id,
          ab.batch_name,
          ab.batch_name||''-''||to_char(org_id) NEW_BATCH_NAME,
          ''N/A'' old_inv_type,
          ''N/A'' new_inv_type
   FROM ap_batches_all ab
   WHERE EXISTS (
           SELECT 1 FROM ap_batches_all ab1
           WHERE ab1.batch_name = ab.batch_name
           AND   ab1.batch_id    <> ab.batch_id )
   AND   ab.batch_id IN (
           SELECT a.batch_id
           FROM ap_invoices_all a,
                invs
           WHERE a.invoice_id = invs.invoice_id)
   UNION ALL
   SELECT ''Incorrect Invoice Type'',
          ab.batch_id,
          ab.org_id,
          ab.batch_name,
          ''N/A'',
          ab.invoice_type_lookup_code,
          ''STANDARD''
   FROM ap_batches_all ab
   WHERE ab.invoice_type_lookup_code IN (''QUICKMATCH'', ''QUICKDEFAULT'')
   AND   ab.batch_id IN (
           SELECT a.batch_id
           FROM ap_invoices_all a,
                invs
           WHERE a.invoice_id = invs.invoice_id)',
      p_title                  => 'MGD-32',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice batches with duplicate batch names<br/><strong>Impact Area(s): </strong>Invoice Data',
      p_solution               => '<strong>Solution GDF: </strong>17480384</br><strong>Note: </strong>[1276536/KB283368]</br><strong>Script Name: </strong>ap_duplicate_batch_names_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1276536/KB283368]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: 32');



debug('begin add_signature: 33');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'PO Matching';
   l_info('bug_number'):= '17428747';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1322280.1';
   l_info('problem'):= 'Purchase order shipments which have quantity or amount data which does not match the values on the distributions.';
   l_info('solution'):= 'Apply the GDF patch as detailed in Doc ID 1322280.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3991',
      p_sig_id                 => '33',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(pll, pod) */
          pll.po_header_id,
          pll.org_id,
          pll.line_location_id,
          nvl(pll.quantity_billed,0) qty_billed,
          sum(nvl(pod.quantity_billed,0)) dist_qty_billed,
          nvl(pll.amount_billed,0) amt_billed,
          sum(nvl(pod.amount_billed,0)) dist_amt_billed,
          nvl(pll.quantity_financed,0) qty_financed,
          sum(nvl(pod.quantity_financed,0)) dist_qty_financed,
          nvl(pll.amount_financed,0) amt_financed,
          sum(nvl(pod.amount_financed,0)) dist_amt_financed,
          nvl(pll.quantity_recouped,0) qty_recouped,
          sum(nvl(pod.quantity_recouped,0)) dist_qty_recouped,
          nvl(pll.amount_recouped,0) amt_recouped,
          sum(nvl(pod.amount_recouped,0)) dist_amt_recouped
   FROM (
           SELECT /*+ no_merge ordered use_nl(ail) */ DISTINCT
                  ail.po_header_id
           FROM (
                  ##$$IVIEW$$##
                ) invs,
                ap_invoice_lines_all ail
           WHERE ail.invoice_id = invs.invoice_id
         ) pos,
        po_line_locations_all pll,
        po_distributions_all pod
   WHERE pll.line_location_id = pod.line_location_id
   AND   pll.po_header_id = pos.po_header_id
   GROUP BY pll.po_header_id, pll.org_id, pll.line_location_id,
            pll.quantity_billed,pll.amount_billed, pll.quantity_financed,
            pll.amount_financed, pll.quantity_recouped, pll.amount_recouped
   HAVING  (nvl(pll.quantity_billed,0) <> sum(nvl(pod.quantity_billed,0)) OR
            nvl(pll.amount_billed,0) <> sum(nvl(pod.amount_billed,0)) OR
            nvl(pll.quantity_financed,0) <> sum(nvl(pod.quantity_financed,0)) OR
            nvl(pll.amount_financed,0) <> sum(nvl(pod.amount_financed,0)) OR
            nvl(pll.quantity_recouped,0) <> sum(nvl(pod.quantity_recouped,0)) OR
            nvl(pll.amount_recouped,0) <> sum(nvl(pod.amount_recouped,0)))',
      p_title                  => 'MGD-33',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Purchase order shipments which have quantity or amount data which does not match the values on the distributions.<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Solution GDF: </strong>17428747</br><strong>Note: </strong>[1322280/KB215717]</br><strong>Script Name: </strong>ap_po_line_sync_sel.sql</br></br>Apply the GDF patch as detailed in [1322280/KB215717]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '31'
      );
   l_info.delete;
debug('end add_signature: 33');



debug('begin add_signature: 34');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Validation Selection';
   l_info('bug_number'):= '13538637';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1276069.1';
   l_info('problem'):= 'Tax lines with no corresponding taxable line in AP_INVOICE_LINES_ALL.  These lines cause issues in validation and invoice cancelation.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1276069.1 and apply the code fix as detailed in Doc ID 1382794.1.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3766',
      p_sig_id                 => '34',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, zl) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          zl.trx_id,
          zl.trx_line_id,
          zl.trx_line_number,
          zl.tax_line_id,
          zl.entity_code,
          zl.event_class_code,
          zl.tax_only_line_flag,
          zl.tax_rate_id,
          zl.tax_rate
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        zx_lines zl
   WHERE zl.application_id = 200
   AND   zl.entity_code = ''AP_INVOICES''
   AND   zl.event_class_code IN (''STANDARD INVOICES'', ''PREPAYMENT INVOICES'',
           ''EXPENSE REPORTS'')
   AND   nvl(zl.tax_only_line_flag,''N'') = ''N''
   AND   zl.trx_id = ai.invoice_id
   AND   ai.cancelled_date is null
   AND   ai.temp_cancelled_amount is null
  AND   sign(zl.trx_line_id) > 0
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_lines_all ail
           WHERE ail.invoice_id = zl.trx_id
           AND   ail.line_type_lookup_code NOT IN (''TAX'',''AWT'')
           AND   ail.line_number = zl.trx_line_id)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-34',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Tax lines with no corresponding taxable line in AP_INVOICE_LINES_ALL.  These lines cause issues in validation and invoice cancelation.<br/><strong>Impact Area(s): </strong>Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>13538637</br><strong>Note: </strong>[1276069/KB350513]</br><strong>Script Name: </strong>zx_orphn_tax_lines_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1276069/KB350513] and apply the code fix as detailed in [1382794/KB488918].',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: 34');



debug('begin add_signature: 37');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '22297430';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1276043.1';
   l_info('problem'):= 'Identifies a series of invoice related issues with amounts and base amounts.  See [1276043.1] for the complete list of issues addressed in this query';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1276043.1';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3792',
      p_sig_id                 => '37',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ ordered use_nl(ai) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount, 
          ai.base_amount,
          ai.org_id,
          ai.cancelled_date,
          to_number(null) line_number,
          ''header base amount issue'' reason
   FROM invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp
   WHERE ai.exchange_rate is not null
   AND   ai.org_id = asp.org_id
   AND   ap_utilities_pkg.ap_round_currency(
            invoice_amount * exchange_rate, base_currency_code)
            <> nvl(ai.base_amount,0)
   AND   ai.invoice_currency_code <> asp.base_currency_code
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered us_nl(ai) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount, 
          ai.base_amount,
          ai.org_id,
          ai.cancelled_date,
          null line_number,
          ''lines base amount issue''
   FROM  invs,
         ap_invoices_all ai,
         ap_system_parameters_all asp
   WHERE ai.exchange_rate is not null
   AND   ai.org_id = asp.org_id
   AND   ai.invoice_currency_code <> asp.base_currency_code
   AND   ap_invoices_utility_pkg.get_approval_status(
           ai.invoice_id,ai.invoice_amount, ai.payment_status_flag,
           ai.invoice_type_lookup_code) <> ''NEVER APPROVED''
   AND   ai.invoice_type_lookup_code <> ''PO PRICE ADJUST''
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ ''Adjustment corrections exists''
           FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.dist_match_type=''ADJUSTMENT_CORRECTION'')
   AND   ai.invoice_amount = (
           SELECT sum(ail.amount) +
                    decode(nvl(ai.net_of_retainage_flag,''N''),
                      ''Y'',sum(nvl(retained_amount,0)),0)
           FROM ap_invoice_lines_all ail
           WHERE ail.invoice_id = ai.invoice_id
           AND   ail.line_type_lookup_code <> ''AWT''
           AND   ((ail.prepay_invoice_id is not null AND
                   nvl(ail.invoice_includes_prepay_flag, ''N'') = ''Y'') OR
                  ail.prepay_invoice_id is null))
   AND   nvl(ai.base_amount,0) <> (
           SELECT sum(nvl(base_amount,0))  +
                    decode(nvl(ai.net_of_retainage_flag,''N''),
                      ''Y'',ap_utilities_pkg.ap_round_currency(
                      sum(nvl(retained_amount,0))*ai.exchange_rate,
                      asp.base_currency_code), 0)
           FROM ap_invoice_lines_all ail
           WHERE ail.invoice_id = ai.invoice_id
           AND   ail.line_type_lookup_code <> ''AWT''
           AND   ((ail.prepay_invoice_id is not null AND
                   nvl(ail.invoice_includes_prepay_flag, ''N'') = ''Y'') OR
                  ail.prepay_invoice_id is null))
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, ail) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount, 
          ai.base_amount,
          ai.org_id,
          ai.cancelled_date,
          ail.line_number line_number,
          ''dists base amount issue - lines vs distributions''
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_system_parameters_all asp
   WHERE ai.exchange_rate is not null
   AND   ai.invoice_id = ail.invoice_id
   AND   ai.org_id = asp.org_id
   AND   ai.invoice_currency_code <> asp.base_currency_code
   AND   ail.base_amount is not null
   AND   ai.invoice_type_lookup_code <> ''PO PRICE ADJUST''
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ ''unvalidated dists exists''
           FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = ai.invoice_id
           AND   (aid1.dist_match_type=''ADJUSTMENT_CORRECTION'' OR
                  nvl(aid1.match_status_flag,''N'') = ''N''))
   AND   ail.amount = (
           SELECT /*+ no_unnest */ sum(aid2.amount)
           FROM ap_invoice_distributions_all aid2
           WHERE aid2.invoice_id = ail.invoice_id
           AND   aid2.invoice_line_number = ail.line_number)
   AND   (ail.line_type_lookup_code in (''ITEM'',''FREIGHT'',''MISCELLANEOUS'') OR
          ai.cancelled_date is not null)
   AND   ail.base_amount <> (
           SELECT /*+ no_unnest */ sum(nvl(aid.base_amount,0))
           FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ail.invoice_id
           AND   aid.invoice_line_number = ail.line_number)
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount, 
          ai.base_amount,
          ai.org_id,
          ai.cancelled_date,
          null line_number,
          ''opposite signs''
   FROM invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp
   WHERE ai.exchange_rate is not null
   AND   ai.org_id = asp.org_id
   AND   ai.invoice_currency_code <> asp.base_currency_code
   AND   ai.invoice_type_lookup_code <> ''PO PRICE ADJUST''
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ ''Adjustment corrections exists''
           FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = ai.invoice_id
           AND   aid1.dist_match_type=''ADJUSTMENT_CORRECTION'')
   AND   EXISTS(
           SELECT /*+ no_unnest */ ''opposite signs''
           FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.base_amount is not null
           AND   ((aid.amount > 0 AND aid.base_amount <0) OR
                  (aid.amount < 0 AND aid.base_amount >0))
           AND   aid.line_type_lookup_code NOT IN (''REC_TAX'',
                   ''NONREC_TAX'',''TRV'',''TIPV'',''TERV''))
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount, 
          ai.base_amount,
          ai.org_id,
          ai.cancelled_date,
          null line_number,
          ''wrong variance''
   FROM invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp
   WHERE nvl(ai.historical_flag,''N'') <> ''Y''
   AND   ai.exchange_rate is not null
   AND   ai.cancelled_date is null
   AND   ai.org_id = asp.org_id
   AND   ai.invoice_currency_code <> asp.base_currency_code
   AND   ai.invoice_type_lookup_code <> ''PO PRICE ADJUST''
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ ''Adjustment corrections exists''
           FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = ai.invoice_id
           AND   aid1.dist_match_type=''ADJUSTMENT_CORRECTION'')
   AND   EXISTS (
           SELECT /*+ no_unnest */ ''wrong variance''
           FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   (aid.po_distribution_id is not null OR
                  aid.rcv_transaction_id is not null)
           AND   nvl(aid.dist_match_type,''NOT_MATCHED'') IN
                   (''ITEM_TO_PO'',''ITEM_TO_RECEIPT'',
                    ''ITEM_TO_SERVICE_PO'',''ITEM_TO_SERVICE_RECEIPT'',
                    ''QTY_CORRECTION'',''AMOUNT_CORRECTION'')
           AND   nvl(aid.reversal_flag,''N'') <> ''Y''
           AND   aid.line_type_lookup_code in (''ITEM'',''ACCRUAL'')
           AND   abs(aid.base_amount -
                   (SELECT /*+ no_unnest */ ap_utilities_pkg.ap_round_currency(
                             aid1.amount * nvl(rt.currency_conversion_rate,pod.rate),
                             asp.base_currency_code)
                    FROM ap_invoice_distributions_all aid1,
                         po_distributions_all pod,
                         rcv_transactions rt,
                         ap_system_parameters_all asp
                    WHERE aid1.invoice_distribution_id = aid.invoice_distribution_id
                    AND aid1.po_distribution_id = pod.po_distribution_id
                    AND aid1.rcv_transaction_id = rt.transaction_id (+)
                    AND aid1.org_id = asp.org_id))
                   > .99 )
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount, 
          ai.base_amount,
          ai.org_id,
          ai.cancelled_date,
          aid.invoice_line_number line_number,
          ''dists base amount issue - exchange rate calculation''
   FROM invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.exchange_rate is not null
   AND   ai.org_id = asp.org_id
   AND   ai.invoice_currency_code <> asp.base_currency_code
   AND   ai.invoice_id = aid.invoice_id
   AND   ai.org_id = asp.org_id
   AND   ai.invoice_currency_code <> asp.base_currency_code
   AND   ai.invoice_type_lookup_code <> ''PO PRICE ADJUST''
   AND   NOT EXISTS (
           SELECT ''unvalidated dists exists''
           FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = ai.invoice_id
           AND  (aid1.dist_match_type=''ADJUSTMENT_CORRECTION'' OR
                 nvl(aid1.match_status_flag,''N'') = ''N'' ))
   AND   aid.line_type_lookup_code IN (''ITEM'',''FREIGHT'',
           ''MISCELLANEOUS'')
   AND   aid.po_distribution_id is null
   AND   (aid.base_amount is null  OR
          ((aid.base_amount - aid.rounding_amt) <> (
              SELECT ap_utilities_pkg.ap_round_currency(
                       aid.amount * ai.exchange_rate,
                       asp.base_currency_code)
                    FROM dual)))',
      p_title                  => 'MGD-37',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Identifies a series of invoice related issues with amounts and base amounts.  See [1276043/KB438282] for the complete list of issues addressed in this query<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>22297430</br><strong>Note: </strong>[1276043/KB438282]</br><strong>Script Name: </strong>ap_wrong_base_amt_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1276043/KB438282]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '23'
      );
   l_info.delete;
debug('end add_signature: 37');



debug('begin add_signature: 38');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Payment Selection';
   l_info('bug_number'):= '23338547';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1174813.1';
   l_info('problem'):= 'Invoices with incorrect data in payment schedules or payment fields.  See [1174813.1] for complete details of all conditions captured.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1174813.1.

NOTE:  If  the payment schedule is a split schedule, in a small number of cases this query may produce false positives. If you believe the transaction is in incorrect please work with Support to correct the data.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3767',
      p_sig_id                 => '38',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT ''Incorrect Amt Paid'' Reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(aid.amount) *
                          nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid,
                       ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND aid.invoice_id = ai.invoice_id
                  AND ail.line_number = aid.invoice_line_number
                  AND aid.prepay_distribution_id is not null
                  AND nvl(ail.invoice_includes_prepay_flag,''N'')<>''Y'') prepay_amt,
                 (SELECT sum(aip.amount) FROM ap_invoice_payments_all aip
                  WHERE aip.invoice_id = ai.invoice_id) pay_amt
          FROM invs,
               ap_invoices_all ai
          WHERE ai.validation_request_id is null
          AND   ai.cancelled_date is null
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   WHERE (nvl(ap.pay_amt,0)-nvl(ap.prepay_amt,0)) <> nvl(ap.amount_paid,0)
   UNION ALL
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT /*+ ordered use_nl(ai) */
                 ''Incorrect Amt Remaining'' Reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid,
                 nvl(ai.discount_amount_taken,0) disc_amt,
                 nvl(ai.payment_cross_rate,1) payment_cross_rate,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(ail.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND ail.line_type_lookup_code = ''AWT'') awt_amt,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(ail.retained_amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND nvl(ai.net_of_retainage_flag,''N'')<>''Y'') retained_amt,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(aid.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid,
                       ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND   aid.invoice_id = ai.invoice_id
                  AND   ail.line_number = aid.invoice_line_number
                  AND   aid.prepay_distribution_id is not null
                  AND   nvl(ail.invoice_includes_prepay_flag,''N'')<>''Y'') prepay_amt,
                 (SELECT sum(aip.amount) FROM ap_invoice_payments_all aip
                  WHERE aip.invoice_id = ai.invoice_id) pay_amt,
                 -- Modified per request 11646
                 (SELECT /*+ no_unnest */ sum(nvl(amount_remaining,0))
                  FROM ap_payment_schedules_all aps
                  WHERE aps.invoice_id = ai.invoice_id) amount_remain
          FROM invs,
               ap_invoices_all ai
          WHERE ai.validation_request_id is null
          AND   ai.cancelled_date is null
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   -- Remove nvl on ap.amount_remain as per request 11646
   WHERE (((ap.invoice_amount * ap.payment_cross_rate) - disc_amt +
            nvl(ap.awt_amt,0) + nvl(ap.retained_amt,0)) -
           (nvl(ap.pay_amt,0) - nvl(ap.prepay_amt,0))) <>
            ap.amount_remain
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ''Null Amt Remaining''
   FROM invs,
        ap_invoices_all ai,
        ap_payment_schedules_all ap
   WHERE ap.amount_remaining is null
   AND   ap.invoice_id = ai.invoice_id
   AND   ap.checkrun_id is null
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ no_query_transformation */
          ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT /*+ ordered use_nl(ai, aps1) */
                 ''Fully paid but Payment_status_flag not Y'' reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(aid.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid,
                       ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND aid.invoice_id = ai.invoice_id
                  AND ail.line_number = aid.invoice_line_number
                  AND aid.prepay_distribution_id is not null
                  AND nvl(ail.invoice_includes_prepay_flag,''N'')<>''Y'') prepay_amt,
                 (SELECT sum(aip.amount) FROM ap_invoice_payments_all aip
                  WHERE aip.invoice_id = ai.invoice_id) pay_amt,
                 (SELECT sum(aps.amount_remaining)
                  FROM ap_payment_schedules_all aps
                  WHERE aps.invoice_id = ai.invoice_id) amount_remain
          FROM invs,
               ap_invoices_all ai,
               ap_payment_schedules_all aps1
          WHERE ai.invoice_id = invs.invoice_id
          AND   aps1.invoice_id = ai.invoice_id
          AND   (ai.payment_status_flag <> ''Y'' OR aps1.payment_status_flag<>''Y'')
          AND   ai.cancelled_date is null
          AND   ai.validation_request_id is null
          AND   aps1.checkrun_id is null
        ) ap
   WHERE nvl(ap.pay_amt,0) - nvl(ap.prepay_amt,0) = nvl(ap.amount_paid,0)
   AND   ap.amount_paid <> 0
   AND   ap.amount_remain = 0
   UNION ALL
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT ''Inv unpaid but Payment_status_flag not N'' Reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid
          FROM invs,
               ap_invoices_all ai,
               ap_payment_schedules_all aps
          WHERE ai.invoice_id = aps.invoice_id
          AND   (nvl(ai.payment_status_flag,''N'') <> ''N'' OR
                 nvl(aps.payment_status_flag,''N'') <> ''N'')
          AND   ai.cancelled_date is null
          AND   aps.amount_remaining <> 0
          AND   ai.validation_request_id is null
          AND   aps.checkrun_id is null
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   WHERE nvl(ap.amount_paid,0)=0
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ap.org_id,
          ''Null Payment status flag'' Reason
   FROM invs,
        ap_invoices_all ai,
        ap_payment_schedules_all ap
   WHERE (ap.payment_status_flag is null OR
          ai.payment_status_flag is null)
   AND   ai.validation_request_id is null
   AND   ap.invoice_id = ai.invoice_id
   AND   ap.checkrun_id is null
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.reason
   FROM (
          SELECT ''Wrong pay status flag for partial paid invoices'' reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 ai.org_id,
                 ai.invoice_amount,
                 ai.amount_paid,
                 nvl(ai.discount_amount_taken,0) disc_amt,
                 (SELECT ap_utilities_pkg.ap_round_currency(sum(aid.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid,
                       ap_invoice_lines_all ail
                  WHERE ail.invoice_id = ai.invoice_id
                  AND   aid.invoice_id = ai.invoice_id
                  AND   ail.line_number = aid.invoice_line_number
                  AND   aid.prepay_distribution_id is not null
                  AND   nvl(ail.invoice_includes_prepay_flag,''N'')<>''Y'') prepay_amt,
                 (SELECT sum(aip.amount) FROM ap_invoice_payments_all aip
                  WHERE aip.invoice_id = ai.invoice_id) pay_amt,
                 (SELECT sum(aps.amount_remaining) FROM ap_payment_schedules_all aps
                  WHERE aps.invoice_id = ai.invoice_id) amount_remain
          FROM invs,
               ap_invoices_all ai
          WHERE ai.payment_status_flag in (''N'',''Y'')
          AND   ai.cancelled_date is null
          AND   ai.validation_request_id is null
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   WHERE nvl(ap.amount_remain,0) <> 0
   AND   nvl(ap.amount_paid,0) <> 0
   AND   (nvl(ap.prepay_amt,0) <> 0 OR
          nvl(ap.pay_amt,0) <> 0)
   UNION ALL
   SELECT ap.invoice_id,
          ap.invoice_num,
          ap.invoice_date,
          ap.org_id,
          ap.Reason
   FROM (
          SELECT ''Incorrect pay status flag for partial paid invoices'' Reason,
                 ai.invoice_id,
                 ai.invoice_num,
                 ai.invoice_date,
                 aps.org_id,
                 aps.payment_num,
                 aps.amount_remaining,
                 aps.gross_amount,
                 aps.payment_status_flag,
                 ai.payment_currency_code,
                 (SELECT AP_UTILITIES_PKG.ap_round_currency(sum(aid.amount) *
                           nvl(ai.payment_cross_rate,1),ai.payment_currency_code)
                  FROM ap_invoice_distributions_all aid
                  WHERE aid.invoice_id = ai.invoice_id
                  AND   aid.line_type_lookup_code = ''AWT''
                  AND   aid.awt_invoice_payment_id is null) inv_awt_amt,
                 (SELECT sum(aps.gross_amount) FROM ap_payment_schedules_all aps
                  WHERE aps.invoice_id = ai.invoice_id) tot_gross_amt
          FROM ap_invoices_all ai,
               ap_payment_schedules_all aps, invs
          WHERE ai.invoice_id = aps.invoice_id
          AND   aps.amount_remaining <> 0
          AND   ai.cancelled_date is null
          AND   ai.validation_request_id is null
          AND   aps.checkrun_id is null
          AND   nvl(ai.historical_flag,''N'')<>''Y''
          AND   ai.invoice_id = invs.invoice_id
        ) ap
   WHERE ap.gross_amount<>0
   AND   ap.tot_gross_amt<>0
   AND   ap.payment_status_flag <> decode(nvl(ap.amount_remaining,0), 0, ''Y'', AP_UTILITIES_PKG.ap_round_currency(ap.gross_amount + (nvl(ap.inv_awt_amt,0) * nvl(ap.gross_amount,0) / nvl(ap.tot_gross_amt,1)),payment_currency_code), ''N'', ''P'')
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ''Inc Amt Remn, paid for cancelled invs'' Reason
   FROM invs,
        ap_invoices_all ai
   WHERE ai.cancelled_date is not null
   AND   (nvl(ai.amount_paid,0) <> 0 OR
         EXISTS (
           SELECT 1 FROM ap_payment_schedules_all aps
           WHERE aps.invoice_id = ai.invoice_id
           AND amount_remaining <> 0))
   AND   ai.validation_request_id is null
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT  ai.invoice_id,
           ai.invoice_num,
           ai.invoice_date,
           ai.org_id,
           ''Incorrect Gross Amount on Schedule''
   FROM invs,
        ap_invoices ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   ((ai.pay_curr_invoice_amount <>
             ap_utilities_pkg.ap_round_currency((ai.invoice_amount - (
               CASE
                 WHEN nvl(ai.net_of_retainage_flag, ''N'') = ''N'' THEN
                   nvl(abs(ap_invoices_utility_pkg.get_retained_total(
                             ai.invoice_id,
                             ai.org_id)),0)
                 ELSE 0
               END)) * ai.payment_cross_rate,
               ai.payment_currency_code)
           ) OR
           (ai.pay_curr_invoice_amount <> (
              SELECT sum(aps.gross_amount)
              FROM ap_payment_schedules_all aps
              WHERE aps.invoice_id = ai.invoice_id)))
   AND   ai.historical_flag is null
   AND   EXISTS (
           SELECT 1 FROM ap_payment_schedules_all aps
           WHERE aps.invoice_id = ai.invoice_id
           HAVING count(aps.invoice_id) = 1)
   AND   ai.cancelled_date is null
   AND   ai.validation_request_id is null',
      p_title                  => 'MGD-38',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices with incorrect data in payment schedules or payment fields.  See [1174813/KB738668] for complete details of all conditions captured.<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>23338547</br><strong>Note: </strong>[1174813/KB738668]</br><strong>Script Name: </strong>ap_inc_payment_schedules_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1174813/KB738668].

NOTE:  If  the payment schedule is a split schedule, in a small number of cases this query may produce false positives. If you believe the transaction is in incorrect please work with Support to correct the data.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '32'
      );
   l_info.delete;
debug('end add_signature: 38');



debug('begin add_signature: 39');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Discard';
   l_info('bug_number'):= '17558081';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '982072.1';
   l_info('problem'):= 'PO distributions out of synch with AP distributions for quantity or amount billed, financed or recouped';
   l_info('solution'):= 'Apply the GDF patch as detailed in Doc ID 982072.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4148',
      p_sig_id                 => '39',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ ordered use_nl(ai2, aid2, pod2) */
          ai2.invoice_id,
          ai2.invoice_num,
          pod2.po_header_id,
          pod2.po_distribution_id,
          aid2.invoice_line_number,
          aid2.invoice_distribution_id,
          aid2.corrected_quantity,
          aid2.quantity_invoiced,
          aid2.matched_uom_lookup_code,
          aid2.amount aid_amt,
          fsp2.purch_encumbrance_flag,
          1 match_type
   FROM   invs,
          ap_invoices_all ai2,
          ap_invoice_distributions_all aid2,
          po_distributions_all pod2,
          financials_system_params_all fsp2
   WHERE ai2.invoice_id = invs.invoice_id
   AND   aid2.invoice_id = ai2.invoice_id
   AND   aid2.invoice_id = ai2.invoice_id
   AND   ai2.org_id = fsp2.org_id
   AND   aid2.line_type_lookup_code IN (''ITEM'', ''ACCRUAL'',
           ''IPV'',''RETROACCRUAL'',''RETROEXPENSE'')
   AND   ai2.invoice_type_lookup_code = ''PREPAYMENT''
   AND   pod2.po_distribution_id = aid2.po_distribution_id
   AND   EXISTS (
           SELECT 1 match_type
           FROM (
                  SELECT pod.po_header_id,
                         pod.po_line_id,
                         pod.line_location_id,
                         pod.po_release_id,
                         pod.po_distribution_id,
                         decode(aid.dist_match_type,
                           ''PRICE_CORRECTION'', 0,
                           ''AMOUNT_CORRECTION'', 0,
                           ''ITEM_TO_SERVICE_PO'', 0,
                           ''ITEM_TO_SERVICE_RECEIPT'', 0,
                           nvl(aid.corrected_quantity,0) +
                           nvl(aid.quantity_invoiced,0)) *
                           decode(nvl(aid.matched_uom_lookup_code,
                             pll.unit_meas_lookup_code),
                             pll.unit_meas_lookup_code, 1 ,
                             nvl(ap_gdf_detect_analyzer_pkg.uom_convert(
                               nvl(aid.matched_uom_lookup_code,
                                 pll.unit_meas_lookup_code),
                               pll.unit_meas_lookup_code,rsl.item_id),0)) aid_quan,
                         aid.amount aid_amt,
                         pod.quantity_financed po_quantity,
                         pod.amount_financed po_amount,
                         decode(nvl(ap_gdf_detect_analyzer_pkg.uom_convert(
                                      nvl(aid.matched_uom_lookup_code,
                                          pll.unit_meas_lookup_code),
                                      pll.unit_meas_lookup_code,
                                      rsl.item_id),-999),
                           -999, aid.matched_uom_lookup_code||'' and ''||
                             pll.unit_meas_lookup_code,
                           ''None'') uom_codes,
                         decode(nvl(ap_gdf_detect_analyzer_pkg.uom_convert(
                                      nvl(aid.matched_uom_lookup_code,
                                          pll.unit_meas_lookup_code),
                                      pll.unit_meas_lookup_code, rsl.item_id),-999),
                           -999,''E'',
                           ''N'') process_flag
                  FROM po_distributions_all pod,
                       ap_invoice_distributions_all aid,
                       po_lines_all pol,
                       po_line_locations_all pll,
                       ap_invoices_all ai,
                       financials_system_params_all fsp,
                       rcv_transactions rtxn,
                       rcv_shipment_lines rsl
                  WHERE pod.po_distribution_id = aid.po_distribution_id
                  AND   pod.line_location_id = pll.line_location_id
                  AND   pll.po_line_id = pol.po_line_id
                  AND   aid.invoice_id = ai.invoice_id
                  AND   ai.org_id = fsp.org_id
                  AND   (nvl(fsp.purch_encumbrance_flag,''N'') = ''N'' OR
                         (nvl(pll.approved_flag,''N'') = ''Y'' AND
                          nvl(pll.cancel_flag,''N'') = ''N''  AND
                          nvl(pll.closed_code,'' '') <> ''FINALLY CLOSED''))
                  AND   aid.line_type_lookup_code IN (''ITEM'', ''ACCRUAL'',
                          ''IPV'',''RETROACCRUAL'',''RETROEXPENSE'')
                  AND   ai.invoice_type_lookup_code = ''PREPAYMENT''
                  AND   aid.rcv_transaction_id = RTXN.transaction_id (+)
                  AND   rtxn.shipment_line_id = rsl.shipment_line_id (+)
                ) apd
           WHERE apd.po_distribution_id = aid2.po_distribution_id
           GROUP BY apd.po_header_id, apd.po_line_id, apd.line_location_id,
                    apd.po_release_id, apd.po_distribution_id,
                    apd.po_quantity, apd.po_amount, apd.uom_codes,
                    apd.process_flag
           HAVING ((round(nvl(apd.po_quantity,0),15) <>
                    round(sum(nvl(apd.aid_quan,0)),15) OR
                    round(nvl(apd.po_amount,0),15) <>
                    round(sum(nvl(apd.aid_amt,0)),15)) AND
                   ((round(sum(nvl(apd.aid_quan,0)),15) >= 0 AND
                     round(sum(nvl(apd.aid_amt,0)),15) >= 0) OR
                    apd.process_flag <> ''N'')))
   UNION ALL
   SELECT /*+ ordered use_nl(ai2, aid2, pod2) */
          ai2.invoice_id,
          ai2.invoice_num,
          pod2.po_header_id,
          pod2.po_distribution_id,
          aid2.invoice_line_number,
          aid2.invoice_distribution_id,
          aid2.corrected_quantity,
          aid2.quantity_invoiced,
          aid2.matched_uom_lookup_code,
          aid2.amount aid_amt,
          fsp2.purch_encumbrance_flag,
          2 match_type
   FROM   invs,
          ap_invoices_all ai2,
          ap_invoice_distributions_all aid2,
          po_distributions_all pod2,
          financials_system_params_all fsp2
   WHERE ai2.invoice_id = invs.invoice_id
   AND   aid2.invoice_id = ai2.invoice_id
   AND   ai2.org_id = fsp2.org_id
   AND   aid2.line_type_lookup_code = ''PREPAY''
   AND   ai2.invoice_type_lookup_code <> ''PREPAYMENT''
   AND   pod2.po_distribution_id = aid2.po_distribution_id
   AND   EXISTS (
           SELECT 2 match_type
           FROM (
                  SELECT pod.po_header_id,
                         pod.po_line_id,
                         pod.line_location_id,
                         pod.po_release_id,
                         pod.po_distribution_id,
                         decode(aid.dist_match_type,
                           ''PRICE_CORRECTION'', 0,
                           ''AMOUNT_CORRECTION'', 0,
                           ''ITEM_TO_SERVICE_PO'', 0,
                           ''ITEM_TO_SERVICE_RECEIPT'', 0,
                           nvl(aid.corrected_quantity,0 ) +
                           nvl(aid.quantity_invoiced,0)) * -1 *
                           decode(nvl(aid.matched_uom_lookup_code,
                                  pll.unit_meas_lookup_code),
                                  pll.unit_meas_lookup_code, 1 ,
                                  nvl(ap_gdf_detect_analyzer_pkg.uom_convert(
                                    nvl(aid.matched_uom_lookup_code,
                                        pll.unit_meas_lookup_code),
                                 pll.unit_meas_lookup_code,
                                 rsl.item_id),0)) aid_quan,
                         aid.amount * -1 aid_amt,
                         pod.quantity_recouped  po_quantity,
                         pod.amount_recouped   po_amount,
                         decode(nvl(ap_gdf_detect_analyzer_pkg.uom_convert(
                                      nvl(aid.matched_uom_lookup_code,
                                          pll.unit_meas_lookup_code),
                                      pll.unit_meas_lookup_code,
                                      rsl.item_id), -999),
                           -999, aid.matched_uom_lookup_code||'' and ''||
                                   pll.unit_meas_lookup_code,
                           ''None'') uom_codes,
                         decode(nvl(ap_gdf_detect_analyzer_pkg.uom_convert(
                                     nvl(aid.matched_uom_lookup_code,
                                         pll.unit_meas_lookup_code),
                                     pll.unit_meas_lookup_code,
                                     rsl.item_id),-999),
                           -999,''E'',
                           ''N'') process_flag
                  FROM po_distributions_all pod,
                       ap_invoice_distributions_all aid,
                       po_lines_all pol,
                       po_line_locations_all pll,
                       ap_invoices_all ai,
                       financials_system_params_all fsp,
                       rcv_transactions rtxn,
                       rcv_shipment_lines rsl
                  WHERE pod.po_distribution_id = aid.po_distribution_id
                  AND   pod.line_location_id = pll.line_location_id
                  AND   pll.po_line_id = pol.po_line_id
                  AND   aid.invoice_id = ai.invoice_id
                  AND   ai.org_id = fsp.org_id
                  AND   (nvl(fsp.purch_encumbrance_flag,''N'') = ''N'' OR
                         (nvl(pll.approved_flag,''N'') = ''Y'' AND
                          nvl(pll.cancel_flag,''N'') = ''N''  AND
                          nvl(pll.closed_code,'' '') <> ''FINALLY CLOSED''))
                  AND   aid.line_type_lookup_code = ''PREPAY''
                  AND   ai.invoice_type_lookup_code <> ''PREPAYMENT''
                  AND   aid.rcv_transaction_id = rtxn.transaction_id (+)
                  AND   rtxn.shipment_line_id = rsl.shipment_line_id (+)
                ) apd
           WHERE apd.po_distribution_id = aid2.po_distribution_id
           GROUP BY apd.po_header_id, apd.po_line_id, apd.line_location_id,
                    apd.po_release_id, apd.po_distribution_id, apd.po_quantity,
                    apd.po_amount, apd.uom_codes, apd.process_flag
           HAVING ((round(nvl(apd.po_quantity,0),15) <> -1 *
                      round(sum(nvl(apd.aid_quan,0)),15) OR
                    round(nvl(apd.po_amount,0),15) <> -1 *
                      round(sum(nvl(apd.aid_amt,0)),15))
            AND    (round(nvl(apd.po_quantity,0),15) <>
                      round(sum(nvl(apd.aid_quan,0)),15) OR
                    round(nvl(apd.po_amount,0),15) <>
                      round(sum(nvl(apd.aid_amt,0)),15))
            AND   ((round(sum(nvl(apd.aid_quan,0)),15) >= 0 AND
                     round(sum(nvl(apd.aid_amt,0)),15) >= 0) OR
                    apd.process_flag <> ''N'')))
   UNION ALL
   SELECT /*+ ordered use_nl(ai2, aid2, pod2) */
          ai2.invoice_id,
          ai2.invoice_num,
          pod2.po_header_id,
          pod2.po_distribution_id,
          aid2.invoice_line_number,
          aid2.invoice_distribution_id,
          aid2.corrected_quantity,
          aid2.quantity_invoiced,
          aid2.matched_uom_lookup_code,
          aid2.amount aid_amt,
          fsp2.purch_encumbrance_flag,
          3 match_type
   FROM   invs,
          ap_invoices_all ai2,
          ap_invoice_distributions_all aid2,
          po_distributions_all pod2,
          financials_system_params_all fsp2
   WHERE ai2.invoice_id = invs.invoice_id
   AND   aid2.invoice_id = ai2.invoice_id
   AND   ai2.org_id = fsp2.org_id
   AND   aid2.line_type_lookup_code IN (''ITEM'', ''ACCRUAL'',
           ''IPV'',''RETROACCRUAL'',''RETROEXPENSE'')
   AND   ai2.invoice_type_lookup_code <> ''PREPAYMENT''
   AND   pod2.po_distribution_id = aid2.po_distribution_id
   AND   EXISTS (
           SELECT 3 match_type
           FROM (
                  SELECT pod.po_header_id,
                         pod.po_line_id,
                         pod.line_location_id,
                         pod.po_release_id,
                         pod.po_distribution_id,
                         decode(aid.dist_match_type,
                           ''PRICE_CORRECTION'', 0,
                           ''AMOUNT_CORRECTION'', 0,
                           ''ITEM_TO_SERVICE_PO'', 0,
                           ''ITEM_TO_SERVICE_RECEIPT'', 0,
                           nvl(aid.corrected_quantity,0) +
                           nvl(aid.quantity_invoiced,0)) *
                           decode(nvl(aid.matched_uom_lookup_code,
                                      pll.unit_meas_lookup_code),
                             pll.unit_meas_lookup_code, 1,
                             nvl(ap_gdf_detect_analyzer_pkg.uom_convert(
                                   nvl(aid.matched_uom_lookup_code,
                                       pll.unit_meas_lookup_code),
                                   pll.unit_meas_lookup_code,
                                   rsl.item_id),0)) aid_quan,
                         aid.amount aid_amt,
                         pod.quantity_billed     po_quantity,
                         pod.amount_billed       po_amount,
                         decode(nvl(ap_gdf_detect_analyzer_pkg.uom_convert(
                                      nvl(aid.matched_uom_lookup_code,
                                          pll.unit_meas_lookup_code),
                                      pll.unit_meas_lookup_code,
                                      rsl.item_id),-999),
                           -999, aid.matched_uom_lookup_code||'' and ''||
                                   pll.unit_meas_lookup_code,
                           ''None'') uom_codes,
                         decode(nvl(ap_gdf_detect_analyzer_pkg.uom_convert(
                                      nvl(aid.matched_uom_lookup_code,
                                          pll.unit_meas_lookup_code),
                                      pll.unit_meas_lookup_code,
                                      rsl.item_id),-999),
                           -999,''E'',
                           ''N'') process_flag
                  FROM po_distributions_all pod,
                       ap_invoice_distributions_all aid,
                       po_lines_all pol,
                       po_line_locations_all pll,
                       ap_invoices_all ai,
                       financials_system_params_all fsp,
                       rcv_transactions rtxn,
                       rcv_shipment_lines rsl
                  WHERE pod.po_distribution_id = aid.po_distribution_id
                  AND   pod.line_location_id = pll.line_location_id
                  AND   pll.po_line_id = pol.po_line_id
                  AND   aid.invoice_id = ai.invoice_id
                  AND   ai.org_id = fsp.org_id
                  AND   (nvl(fsp.purch_encumbrance_flag,''N'') = ''N'' OR
                         (nvl(pll.approved_flag,''N'') = ''Y'' AND
                          nvl(pll.cancel_flag,''N'') = ''N''  AND
                          nvl(pll.closed_code,'' '') <> ''FINALLY CLOSED''))
                  AND   aid.line_type_lookup_code IN (''ITEM'', ''ACCRUAL'',
                          ''IPV'',''RETROACCRUAL'',''RETROEXPENSE'')
                  AND   ai.invoice_type_lookup_code <> ''PREPAYMENT''
                  AND   aid.rcv_transaction_id = RTXN.transaction_id (+)
                  AND   RTXN.shipment_line_id = rsl.shipment_line_id (+)
                ) apd
           WHERE apd.po_distribution_id = aid2.po_distribution_id
           GROUP BY apd.po_header_id, apd.po_line_id, apd.line_location_id,
                    apd.po_release_id, apd.po_distribution_id, apd.po_quantity,
                    apd.po_amount, apd.uom_codes,
                    apd.process_flag
           HAVING ((round(nvl(apd.po_quantity,0),15) <>
                      round(sum(nvl(apd.aid_quan,0)),15) OR
                    round(nvl(apd.po_amount,0),15) <>
                      round(sum(nvl(apd.aid_amt,0)),15)) AND
                    ((round(sum(nvl(apd.aid_quan,0)),15) >= 0 AND
                      round(sum(nvl(apd.aid_amt,0)),15) >= 0) OR
                     apd.process_flag <> ''N'')))',
      p_title                  => 'MGD-39',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'PO distributions out of synch with AP distributions for quantity or amount billed, financed or recouped<br/><strong>Impact Area(s): </strong>Invoice Discard',
      p_solution               => '<strong>Solution GDF: </strong>17558081</br><strong>Note: </strong>[982072/KB679525]</br><strong>Script Name: </strong>ap_sync_po_qty_amt_sel.sql PO Data</br></br>Apply the GDF patch as detailed in [982072/KB679525]',
      p_success_msg            => '',
