debug('begin add_signature: 44');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Validation Selection';
   l_info('bug_number'):= '17415455';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1072750.1';
   l_info('problem'):= 'Upgraded recurring invoice templates in ap_recurring_payments_all which have a null legal entity id or payment method code or an incorrect external bank account id.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1072750.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3779',
      p_sig_id                 => '44',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ''Null Legal Entity ID'' issue_type,
          1 type_id,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          arp.recurring_pay_num recurring_payment_number,
          arp.recurring_payment_id,
          arp.legal_entity_id,
          arp.payment_method_code payment_method,
          ''**********'' external_bank_account_id
   FROM invs,
        ap_invoices_all ai,
        ap_recurring_payments_all arp
   WHERE arp.legal_entity_id is null
   AND   ai.recurring_payment_id = arp.recurring_payment_id
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT ''Null Payment Method Code'',
          2 type_id,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          arp.recurring_pay_num,
          arp.recurring_payment_id,
          arp.legal_entity_id,
          arp.payment_method_code,
          ''**********''
   FROM invs,
        ap_invoices_all ai,
        ap_recurring_payments_all arp
   WHERE arp.payment_method_code is null
   AND   ai.recurring_payment_id = arp.recurring_payment_id
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, arp) */
          ''Incorrect External Bank Account'',
          3 type_id,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          arp.recurring_pay_num,
          arp.recurring_payment_id,
          arp.legal_entity_id,
          arp.payment_method_code,
          ''<invalid>''
   FROM invs,
        ap_invoices_all ai,
        ap_recurring_payments_all arp
   WHERE arp.external_bank_account_id is not null
   AND   ai.recurring_payment_id = arp.recurring_payment_id
   AND   EXISTS (
           SELECT /*+ no_unnest */ ''11i bank''
           FROM iby_upg_instruments upg
           WHERE upg.bank_account_id = arp.external_bank_account_id
           AND   upg.supplier_site_id = arp.vendor_site_id
           AND   upg.org_id = arp.org_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ ''No R12 Bank''
           FROM iby_pmt_instr_uses_all piu,
                iby_external_payees_all iepa
           WHERE iepa.ext_payee_id = piu.ext_pmt_party_id
           AND   iepa.supplier_site_id = arp.vendor_site_id
           AND   iepa.org_id = arp.org_id
           AND   piu.payment_function = ''PAYABLES_DISB''
           AND   piu.instrument_type = ''BANKACCOUNT''
           AND   piu.instrument_id = arp.external_bank_account_id)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-44',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Upgraded recurring invoice templates in ap_recurring_payments_all which have a null legal entity id or payment method code or an incorrect external bank account id.<br/><strong>Impact Area(s): </strong>Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>17415455</br><strong>Note: </strong>[1072750/KB769779]</br><strong>Script Name: </strong>ap_updt_le_rec_inv_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1072750/KB769779]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '12'
      );
   l_info.delete;
debug('end add_signature: 44');



