debug('begin add_signature: 75');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure, Period Close';
   l_info('bug_number'):= '21916712';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '972261.1';
   l_info('problem'):= 'Approved and validated invoice distributions and/or payments are missing accounting_event_id''s along with the respective event row in XLA_EVENTS.';
   l_info('solution'):= '<strong>Data Fix:</strong>  Follow the instructions provided in Doc ID 972261.1 to apply Generic Data Fix (GDF) patch 21916712. <br/>
<br/>
<strong>Code Fix:</strong> Follow the instructions provided in Doc ID 2938160.1 to upgrade APXPAWKB.fmx.<br/>
<br/>
<strong>Note:</strong> Although this GDF is selected when there are missing event ids, it will not work for Prepayment applications.  The fix will not error, however, it will not show any message on why it did not work.  The process flag will remain Y.  An alternate fix for prepayment applications will be needed.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3770',
      p_sig_id                 => '75',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          aid.invoice_distribution_id,
          aid.cancellation_flag,
          aid.prepay_distribution_id,
          aid.parent_reversal_id,
          ai.invoice_date,
          aid.historical_flag,
          aid.posted_flag,
          aid.prepay_tax_parent_id,
          aid.line_type_lookup_code,
          ap_invoices_utility_pkg.get_approval_status(
            ai.invoice_id,
            ai.invoice_amount,
            ai.payment_status_flag,
            ai.invoice_type_lookup_code) invoice_status,
          ''Invoice Distribution'' distribution_type,
          aid.accounting_event_id
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        financials_system_params_all fsp
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.invoice_id = ai.invoice_id
   AND   fsp.org_id = aid.org_id
   AND   ((fsp.purch_encumbrance_flag = ''Y'' AND
           aid.match_status_flag = ''A'') OR
          (fsp.purch_encumbrance_flag = ''N'' AND
           aid.match_status_flag IN (''A'',   ''T'')))
   AND   nvl(aid.posted_flag,   ''N'') <> ''Y''
   AND   aid.accounting_event_id is null
   AND NOT EXISTS (SELECT 1
                   FROM ap_holds_all ah, ap_hold_codes ahc
                   WHERE ah.invoice_id = ai.invoice_id
                   AND   ah.hold_lookup_code = ahc.hold_lookup_code
                   AND   ah.release_lookup_code IS NULL
                   AND   nvl(ahc.postable_flag,''N'') = ''N'')
   AND   aid.awt_invoice_payment_id is null
   AND   NOT EXISTS (
           SELECT 1
           FROM ap_accounting_events_all aae,
                ap_invoices_all ai2
           WHERE ai2.invoice_id = ai.invoice_id
           AND   ai2.historical_flag = ''Y''
           AND   aae.source_id = ai2.invoice_id
           AND   aae.source_table IN (''AP_INVOICES'', ''AP_INVOICES_ALL'')
           AND   NOT EXISTS (
                   SELECT 1 FROM ap_invoice_distributions_all aid2
                   WHERE aid2.invoice_id = ai2.invoice_id
                   AND   aid2.accounting_event_id = aae.accounting_event_id))
   AND   NOT (
          aid.historical_flag = ''Y'' AND
          aid.posted_flag = ''Y'' AND
          aid.line_type_lookup_code <> ''PREPAY'' AND
          aid.prepay_distribution_id is null AND
          aid.prepay_tax_parent_id is null AND
          EXISTS (
            SELECT 1 FROM ap_system_parameters_all asp
            WHERE asp.org_id = ai.org_id
            AND   asp.accounting_method_option = ''Cash''))
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          asad.invoice_distribution_id,
          asad.cancellation_flag cancellation_flag,
          asad.prepay_distribution_id prepay_distribution_id,
          asad.parent_reversal_id parent_reversal_id,
          ai.invoice_date,
          null,
          asad.posted_flag,
          null,
          asad.line_type_lookup_code,
          ap_invoices_utility_pkg.get_approval_status(
            ai.invoice_id, ai.invoice_amount, ai.payment_status_flag,
            ai.invoice_type_lookup_code) invoice_status,
          ''Self Assessed Tax Distribution'' distribution_type,
          asad.accounting_event_id
   FROM invs,
        ap_invoices_all ai,
        ap_self_assessed_tax_dist_all asad,
        financials_system_params_all fsp
   WHERE ai.invoice_id = invs.invoice_id
   AND   asad.invoice_id = ai.invoice_id
   AND   fsp.org_id = asad.org_id
   AND   ((fsp.purch_encumbrance_flag = ''Y'' AND
           asad.match_status_flag = ''A'') OR
          (fsp.purch_encumbrance_flag = ''N'' AND
           asad.match_status_flag IN (''A'',   ''T'')))
   AND   nvl(asad.posted_flag,   ''N'') <> ''Y''
   AND   asad.accounting_event_id is null
   AND   asad.prepay_distribution_id is null
   AND   NOT EXISTS (
           SELECT 1
           FROM ap_holds_all ah,
                ap_hold_codes ahc
           WHERE ah.invoice_id = ai.invoice_id
           AND   ah.hold_lookup_code = ahc.hold_lookup_code
           AND   ah.release_lookup_code is null
           AND   nvl(ahc.postable_flag,''N'') = ''N'')
   AND asad.awt_invoice_payment_id is null
   AND   NOT EXISTS (
           SELECT 1
           FROM ap_accounting_events_all aae,
                ap_invoices_all ai2
           WHERE ai2.invoice_id = ai.invoice_id
           AND   ai2.historical_flag = ''Y''
           AND   aae.source_id = ai2.invoice_id
           AND   aae.source_table IN (''AP_INVOICES'', ''AP_INVOICES_ALL'')
           AND   NOT EXISTS (
                   SELECT 1 FROM ap_invoice_distributions_all aid2
                   WHERE aid2.invoice_id = ai2.invoice_id
                   AND   aid2.accounting_event_id = aae.accounting_event_id))',
      p_title                  => 'MGD-75',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Approved and validated invoice distributions and/or payments are missing accounting_event_id''s along with the respective event row in XLA_EVENTS.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close',
      p_solution               => '<strong>Solution GDF: </strong>21916712</br><strong>Note: </strong>[972261/KB202043]</br><strong>Script Name: </strong>ap_trx_missing_event_sel.sql</br></br><strong>Data Fix:</strong>  Follow the instructions provided in [972261/KB202043] to apply Generic Data Fix (GDF) patch 21916712. <br/>
<br/>
<strong>Code Fix:</strong> Follow the instructions provided in [2938160/KB766620] to upgrade APXPAWKB.fmx.<br/>
<br/>
<strong>Note:</strong> Although this GDF is selected when there are missing event ids, it will not work for Prepayment applications.  The fix will not error, however, it will not show any message on why it did not work.  The process flag will remain Y.  An alternate fix for prepayment applications will be needed.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '20'
      );
