debug('begin add_signature: 76');
   l_info('##MASK##INVOICE_NUM'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure, Period Close';
   l_info('bug_number'):= '19877760';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1054299.1';
   l_info('problem'):= 'Missing records in XLA_DISTRIBUTION_LINKS for migrated transactions';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1054299.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3771',
      p_sig_id                 => '76',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, xte, xe) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          xe.event_id,
          xte.entity_id,
          xah.ae_header_id,
          xte.source_id_int_1 transaction_id,
          xte.transaction_number,
          xte.entity_code,
          xte.ledger_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp,
        gl_period_statuses upg,
        xla_transaction_entities_upg xte,
        xla_events xe,
        xla_ae_headers xah,
        xla_ae_lines xal
   WHERE xe.application_id = 200
   AND   xe.event_status_code = ''P''
   AND   xe.entity_id = xte.entity_id
   AND   xe.upg_batch_id is not null
   AND   xe.upg_batch_id <> - 9999
   AND   xah.application_id = 200
   AND   xal.application_id = 200
   AND   xte.application_id = 200
   AND   upg.application_id = 200
   AND   xah.event_id = xe.event_id
   AND   xah.ledger_id = xte.ledger_id
   AND   xal.ae_header_id = xah.ae_header_id
   AND   xah.upg_batch_id is not null
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.ledger_id = upg.ledger_id
   AND   nvl(xte.source_id_int_1,-99) = ai.invoice_id
   AND   asp.set_of_books_id = xte.ledger_id
   AND   upg.set_of_books_id = asp.set_of_books_id
   AND   asp.org_id = ai.org_id
   AND   ai.gl_date BETWEEN upg.start_date AND upg.end_date
   AND   upg.migration_status_code = ''U''
   AND   upg.closing_status in (''O'',''C'',''P'')
   AND   trunc(upg.start_date) < (
           SELECT min(trunc(creation_date)) FROM ad_applied_patches
           WHERE patch_type = ''MAINTENANCE-PACK''
           AND   maint_pack_level LIKE ''12.%'')
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.accounting_event_id = xe.event_id
           AND   aid.Historical_flag = ''Y'')
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM xla_distribution_links xdl
           WHERE xdl.application_id = 200
           AND   xdl.ae_header_id = xah.ae_header_id
           AND   xdl.ae_line_num = xal.ae_line_num)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-76',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Missing records in XLA_DISTRIBUTION_LINKS for migrated transactions<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close',
      p_solution               => '<strong>Solution GDF: </strong>19877760</br><strong>Note: </strong>[1054299/KB202267]</br><strong>Script Name: </strong>ap_trx_missing_xdl.sql</br></br>Apply the GDF patch following the instructions provided in [1054299/KB202267]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '18'
      );
   l_info.delete;
debug('end add_signature: 76');



