      p_problem_descr          => 'Reversing distribution pairs which have not been encumbered but which have been stamped with BC_EVENT_ID.<br/><strong>Impact Area(s): </strong>Period Close',
      p_solution               => '<strong>Solution GDF: </strong>17956201</br><strong>Note: </strong>[985228/KB729439]</br><strong>Script Name: </strong>ap_psa_cleanup_s.sql check 1</br></br>Apply the GDF patch following the instructions provided in [985228/KB729439]',
      p_success_msg            => '',
