          ##$$IVIEW$$##
        ) invs
   WHERE nvl(aid.historical_flag,   ''N'') = ''N''
   AND   nvl(aid.posted_flag, ''N'') <> ''Y''
   AND   aid.po_distribution_id is null
   AND   aid.org_id = fsp.org_id
   AND   nvl(fsp.purch_encumbrance_flag, ''N'') = ''Y''
