debug('begin add_signature: 88');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Prepay Application';
   l_info('bug_number'):= '19327661';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1179414.1';
   l_info('problem'):= 'Prepayment application/unapplication resulting in accounted amounts which are multiples of the actual prepayment application amount';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1179414.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3855',
      p_sig_id                 => '88',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_date,
          ai.invoice_amount,
          ai.set_of_books_id,
          xe.event_id,
          xe.event_type_code,
          apph.prepay_history_id,
          apph.invoice_line_number,
          apph.prepay_invoice_id,
          ai_prepay.invoice_num prepay_invoice_num,
          apph.prepay_line_num,
          dist_sum.amt prepay_appl_amt,
          acct_sum.amt prepay_acct_amt
   FROM xla_events xe,
        xla_transaction_entities_upg xte,
        ap_prepay_history_all apph,
        ap_invoices_all ai,
        ap_invoices_all ai_prepay,
        (
          SELECT decode(sum(aid.amount),
                   0, 1,
                   sum(aid.amount))  amt,
                 aid.accounting_event_id
          FROM ap_invoice_distributions_all aid
          WHERE aid.line_type_lookup_code IN (''PREPAY'',''REC_TAX'',''NONREC_TAX'')
          AND   aid.prepay_distribution_id is not null
          GROUP BY aid.accounting_event_id
        ) dist_sum,
        (
          SELECT sum(nvl(xal.entered_cr, 0) - nvl(xal.entered_dr, 0)) amt,
                 xe.event_id,
                 xah.ledger_id
          FROM xla_ae_lines xal,
               xla_ae_headers xah,
               xla_events xe,
               xla_transaction_entities_upg xte
          WHERE xal.application_id = 200
          AND   xah.application_id = 200
          AND   xe.application_id = 200
          AND   xal.ae_header_id = xah.ae_header_id
          AND   xah.event_id = xe.event_id
          AND   xe.entity_id = xte.entity_id
          AND   xte.entity_code = ''AP_INVOICES''
          AND   xte.ledger_id = xah.ledger_id
          AND   xal.accounting_class_code = ''PREPAID_EXPENSE''
          AND   xe.event_type_code IN (''PREPAYMENT APPLIED'',''PREPAYMENT UNAPPLIED'')
          GROUP BY xe.event_id, xah.ledger_id
        ) acct_sum,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE xe.application_id = 200
   AND   xe.event_type_code IN (''PREPAYMENT APPLIED'',''PREPAYMENT UNAPPLIED'')
   AND   xe.event_status_code = ''P''
   AND   xe.event_id = dist_sum.accounting_event_id
   AND   xe.event_id = acct_sum.event_id
   AND   abs(abs(acct_sum.amt)/abs(dist_sum.amt)) > 2
   AND   xe.event_id = apph.accounting_event_id
   AND   apph.prepay_invoice_id = ai_prepay.invoice_id
   AND   xte.application_id = 200
   AND   xe.entity_id = xte.entity_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-88',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Prepayment application/unapplication resulting in accounted amounts which are multiples of the actual prepayment application amount<br/><strong>Impact Area(s): </strong>Prepay Application',
      p_solution               => '<strong>Solution GDF: </strong>19327661</br><strong>Note: </strong>[1179414/KB725632]</br><strong>Script Name: </strong>ap_prepay_triplicate_s.sql</br></br>Apply the GDF patch following the instructions provided in [1179414/KB725632]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: 88');



