   l_info('problem'):= 'Prepayment Application and Unapplication distributions have the same Accounting_Event_ID causing issues with Accounting ';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1284162.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4158',
      p_sig_id                 => '94',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, aid) */
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_date,
          ai.invoice_amount,
          aid.invoice_distribution_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.line_type_lookup_code,
          aid.amount,
          aid.base_amount,
          aid.accounting_date,
          aid.accounting_event_id event_id,
          aid.posted_flag,
          aid.set_of_books_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_amount > = 0
   AND   aid.invoice_id = ai.invoice_id
   AND   aid.line_type_lookup_code = ''PREPAY''
   AND   aid.accounting_event_id is not null
   AND   aid.amount < 0
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = ai.invoice_id
           AND   aid1.parent_reversal_id = aid.invoice_distribution_id
           AND   aid1.accounting_event_id is not null
           AND   aid1.line_type_lookup_code = ''PREPAY''
           AND   aid1.amount = (0-aid.amount)
           AND   aid1.accounting_event_id = aid.accounting_event_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM xla_events xe
           WHERE xe.application_id = 200
           AND   xe.event_type_code = ''PREPAYMENT APPLIED''
           AND   xe.event_id = aid.accounting_event_id)
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1 FROM xla_events xe
           WHERE xe.application_id = 200
           AND   xe.event_type_code = ''PREPAYMENT UNAPPLIED''
           AND   xe.event_id = aid.accounting_event_id)
