  add_signature(
      p_sig_repo_id            => '3894',
      p_sig_id                 => '99',
      p_sig_sql                => 'WITH ai AS (
     SELECT /*+ ordered use_nl(ai) */
            ai.invoice_id,
            ai.invoice_num,
            ai.invoice_date,
            ai.org_id
     FROM (
            ##$$IVIEW$$##
          ) invs,
          ap_invoices_all ai
     WHERE ai.invoice_id = invs.invoice_id
   )
   SELECT /*+ ordered use_nl(aid, xe) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aid.accounting_date,
          xe.event_date,
          xe.event_id,
          aid.posted_flag,
          aid.invoice_distribution_id,
          null rec_nrec_tax_dist_id,
          null prepay_history_id,
          ''Invoice Distribution'' trx_type
   FROM ai,
        ap_invoice_distributions_all aid,
        xla_events xe
   WHERE aid.accounting_event_id = xe.event_id
   AND   xe.application_id = 200
   AND   ai.invoice_id = aid.invoice_id
   AND   aid.accounting_date <> xe.event_date
   UNION ALL
   SELECT /*+ ordered use_nl(aid, xe) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aid.accounting_date,
          xe.event_date,
          xe.event_id,
          aid.posted_flag,
          aid.invoice_distribution_id,
          null,
          null,
          ''Self Assessed Tax Dist''
   FROM ai,
        ap_self_assessed_tax_dist_all aid,
        xla_events xe
   WHERE aid.accounting_event_id = xe.event_id
   AND   xe.application_id = 200
   AND   ai.invoice_id = aid.invoice_id
   AND   aid.accounting_DATE <> xe.event_date
   UNION ALL
   SELECT /*+ ordered use_nl(aid, zrnd, xe) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          zrnd.gl_date,
          xe.event_date,
          xe.event_id,
          aid.posted_flag,
          null,
          zrnd.rec_nrec_tax_dist_id,
          null,
          ''Tax Detail For Inv Dist''
   FROM ai,
        ap_invoice_distributions_all aid,
        zx_rec_nrec_dist zrnd,
        xla_events xe
   WHERE aid.accounting_event_id = xe.event_id
   AND   aid.detail_tax_dist_id = zrnd.rec_nrec_tax_dist_id
   AND   zrnd.application_id = 200
   AND   zrnd.entity_code = ''AP_INVOICES''
   AND   zrnd.event_class_code IN (''STANDARD INVOICES'',
           ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'')
   AND   zrnd.trx_id = aid.invoice_id
   AND   aid.invoice_id = ai.invoice_id
   AND   xe.application_id = 200
   AND   zrnd.gl_date <> xe.event_date
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          zrnd.gl_date,
          xe.event_date,
          xe.event_id,
          aid.posted_flag,
          null,
          zrnd.rec_nrec_tax_dist_id,
          null,
          ''Tax Detail for Self Assessed Tax Dist''
   FROM ai,
        ap_self_assessed_tax_dist_all aid,
        zx_rec_nrec_dist zrnd,
        xla_events xe
   WHERE aid.accounting_event_id = xe.event_id
   AND   aid.detail_tax_dist_id = zrnd.rec_nrec_tax_dist_id
   AND   zrnd.application_id = 200
   AND   zrnd.entity_code = ''AP_INVOICES''
   AND   zrnd.event_class_code IN (''STANDARD INVOICES'',
           ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'')
   AND   zrnd.trx_id = aid.invoice_id
   AND   aid.invoice_id = ai.invoice_id
   AND   xe.application_id = 200
   AND   zrnd.gl_date <> xe.event_date
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          apph.accounting_date,
          xe.event_date,
          xe.event_id,
          apph.posted_flag,
          null,
          null,
          apph.prepay_history_id,
          ''Prepay History''
   FROM ai,
        ap_prepay_history_all apph,
        xla_events xe
   WHERE apph.accounting_event_id = xe.event_id
   AND   xe.application_id = 200
   AND   ai.invoice_id = apph.invoice_id
   AND   apph.accounting_date <> xe.event_date',
      p_title                  => 'MGD-99',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Out of Sync Accounting dates between the Invoicing transaction tables and the Accounting Events table<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close, Sweep',
      p_solution               => '<strong>Solution GDF: </strong>26255537</br><strong>Note: </strong>[874904/KB769084]</br><strong>Script Name: </strong>ap_AcctgDateOutOfSynch_sel.sql</br></br>Apply the GDF patch following the instructions provided in [874904/KB769084]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '18'
      );
