      p_solution               => '<strong>Solution GDF: </strong>18997150</br><strong>Note: </strong>[875012/KB628145]</br><strong>Script Name: </strong>ap_unacct_trx_closed_prd_sel.sql</br></br>Apply the GDF patch following the instructions provided in [875012/KB628145]',
      p_success_msg            => '',
