          xah.accounting_date,
          xah.entity_id,
          xah.event_type_code,
          null,
          xah.upg_batch_id
   FROM invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah
   WHERE xah.application_id = xte.application_id
