debug('begin add_signature: 103');
   l_info('##MASK##INVOICE_NUM'):= 'DISPLAY_FIRST_25_PCNT';
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure, Period Close';
   l_info('bug_number'):= '18997188';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '742429.1';
   l_info('problem'):= 'Accounting Events marked as Incomplete in the Accounting events table even though the Invoices related to the event do not contain any Non-Postable holds';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 742429.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4179',
      p_sig_id                 => '103',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          xe.event_id,
          xe.event_date,
          xe.event_status_code,
          xe.process_status_code,
          xe.budgetary_control_flag,
          xte.entity_code,
          xte.source_id_int_1 source_id,
          xte.ledger_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_events xe
   WHERE ai.invoice_id = invs.invoice_id
   AND   xte.entity_id = xe.entity_id
   AND   xte.application_id = 200
   AND   xe.application_id = 200
   AND   xe.event_status_code = ''I''
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.ledger_id = ai.set_of_books_id
   AND   NOT EXISTS (
           SELECT 1 FROM ap_holds_all ah
           WHERE ah.invoice_id = xte.source_id_int_1
           AND   xte.entity_code = ''AP_INVOICES''
           AND   ah.release_lookup_code is null)
   AND   NOT EXISTS (
           SELECT 1
           FROM ap_invoice_distributions_all aid,
                financials_system_params_all fsp
           WHERE aid.invoice_id = nvl(xte.source_id_int_1, -99)
           AND   xte.entity_code = ''AP_INVOICES''
           AND   xte.ledger_id = aid.set_of_books_id
           AND   aid.org_id = fsp.org_id
           AND   aid.set_of_books_id = fsp.set_of_books_id
           AND   ((nvl(fsp.purch_encumbrance_flag,''N'') = ''N'' AND
                   aid.match_status_flag NOT IN (''T'',''A'')) OR
                  (nvl(fsp.purch_encumbrance_flag,''N'') = ''Y'' AND
                   aid.match_Status_flag != ''A'')))
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id',
      p_title                  => 'MGD-103',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Accounting Events marked as Incomplete in the Accounting events table even though the Invoices related to the event do not contain any Non-Postable holds<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close',
      p_solution               => '<strong>Solution GDF: </strong>18997188</br><strong>Note: </strong>[742429/KB619667]</br><strong>Script Name: </strong>ap_inv_event_status_code_sel.sql</br></br>Apply the GDF patch following the instructions provided in [742429/KB619667]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
