debug('begin add_signature: 106');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '17879448';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1315907.1';
   l_info('problem'):= 'Prepayment unapplication event in a NO Action status, even though the Prepayment Application event is Accounted';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1315907.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3881',
      p_sig_id                 => '106',
      p_sig_sql                => 'SELECT ''Primary Prepay Events'' category,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_type_lookup_code,
          aidp.invoice_line_number prepay_app_line_num,
          aidp.distribution_line_number prepay_app_dist_num,
          aidp.invoice_distribution_id prepay_app_distribution_id,
          aidp.line_type_lookup_code prepay_app_dist_type,
          aidp.amount prepay_app_amount,
          aidp.base_amount prepay_app_base_amount,
          aidp.posted_flag prepay_app_posted_flag,
          aidp.accounting_date prepay_app_accounting_date,
          aidp.accounting_event_id prepay_app_event_id,
          aidp.accounting_event_id event_id,
          xep.event_status_code prepay_app_event_status,
          xep.process_status_code prepay_app_process_status,
          aidu.distribution_line_number prepay_unapp_dist_num,
          aidu.invoice_distribution_id prepay_unapp_distribution_id,
          aidu.posted_flag prepay_unapp_posted_flag,
          aidu.accounting_date prepay_unapp_accounting_date,
          aidu.accounting_event_id prepay_unapp_event_id,
          xeu.event_status_code prepay_unapp_event_status,
          xeu.process_status_code prepay_unapp_process_status,
          aidp.set_of_books_id
   FROM ap_invoice_distributions_all aidp,
        ap_invoice_distributions_all aidu,
        ap_invoices_all ai,
        ap_suppliers asu,
        ap_supplier_sites_all assi,
        xla_events xep,
        xla_events xeu,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE aidp.invoice_id = aidu.invoice_id
   AND   aidp.invoice_id = ai.invoice_id
   AND   ai.vendor_id = asu.vendor_id(+)
   AND   ai.vendor_site_id = assi.vendor_site_id(+)
   AND   aidp.invoice_distribution_id = aidu.parent_reversal_id
   AND   aidp.prepay_distribution_id is not null
   AND   aidu.prepay_distribution_id is not null
   AND   aidp.posted_flag = ''Y''
   AND   aidu.posted_flag = ''Y''
   AND   aidp.accounting_event_id = xep.event_id
   AND   xep.application_id = 200
   AND   aidu.accounting_event_id = xeu.event_id
   AND   xeu.application_id = 200
   AND   xep.event_status_code = ''P''
   AND   xep.process_status_code = ''P''
   AND   xep.upg_batch_id is null
   AND   xeu.event_status_code = ''N''
   AND   xeu.process_status_code = ''P''
   AND   xeu.upg_batch_id is null
   AND   xep.event_type_code = ''PREPAYMENT APPLIED''
   AND   xeu.event_type_code = ''PREPAYMENT UNAPPLIED''
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-106',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Prepayment unapplication event in a NO Action status, even though the Prepayment Application event is Accounted<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>17879448</br><strong>Note: </strong>[1315907/KB415090]</br><strong>Script Name: </strong>ApAppAccUnappNoActionSel.sql</br></br>Apply the GDF patch following the instructions provided in [1315907/KB415090]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: 106');



debug('begin add_signature: 107');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Trial Balance';
   l_info('bug_number'):= '19367714';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1321370.1';
   l_info('problem'):= 'Missing records in AP_Liability_Balance';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1321370.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4053',
      p_sig_id                 => '107',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   ),
   ae_lines_v AS (
   SELECT /*+ leading(invs) use_nl(ael) */
          ael.ae_line_id,
          ael.ae_header_id,
          ael.ae_line_number,
          ael.ae_line_type_code,
          ael.code_combination_id,
          ael.currency_code,
          ael.entered_dr,
          ael.entered_cr,
          ael.accounted_dr,
          ael.accounted_cr,
          ael.description,
          ael.gl_sl_link_id,
          ael.reference2
   FROM invs,
        ap_ae_lines_all ael
   WHERE ael.source_table IN (''AP_INVOICES'',''AP_INVOICES_ALL'')
   AND   ael.source_id = invs.invoice_id
   UNION
   SELECT /*+ ordered use_nl(aip, ael) */
          ael.ae_line_id,
          ael.ae_header_id,
          ael.ae_line_number,
          ael.ae_line_type_code,
          ael.code_combination_id,
          ael.currency_code,
          ael.entered_dr,
          ael.entered_cr,
          ael.accounted_dr,
          ael.accounted_cr,
          ael.description,
          ael.gl_sl_link_id,
          ael.reference2
   FROM invs,
        ap_invoice_payments_all aip,
        ap_ae_lines_all ael
   WHERE aip.invoice_id = invs.invoice_id
   AND   ael.source_table = ''AP_INVOICE_PAYMENTS''
   AND   ael.source_id = aip.invoice_payment_id
   UNION
   SELECT /*+ ordered use_nl(aid, ael) */
          ael.ae_line_id,
          ael.ae_header_id,
          ael.ae_line_number,
          ael.ae_line_type_code,
          ael.code_combination_id,
          ael.currency_code,
          ael.entered_dr,
          ael.entered_cr,
          ael.accounted_dr,
          ael.accounted_cr,
          ael.description,
          ael.gl_sl_link_id,
          ael.reference2
   FROM invs,
        ap_invoice_distributions_all aid,
        ap_ae_lines_all ael
   WHERE aid.invoice_id = invs.invoice_id
   AND   ael.source_table = ''AP_INVOICE_DISTRIBUTIONS''
   AND   ael.source_id = aid.invoice_distribution_id
   )
   SELECT /*+ leading(ael) use_nl(ai, aeh, aae) */
          ''Missing Records APLB'' category,
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id org_id,
          ai.invoice_date,
          ai.invoice_type_lookup_code,
          ai.invoice_amount,
          ai.base_amount,
          aeh.accounting_event_id,
          aae.event_type_code,
          aeh.ae_header_id,
          aeh.gl_transfer_flag,
          ael.ae_line_id,
          ael.ae_line_number,
          ael.ae_line_type_code,
          ael.code_combination_id,
          ael.currency_code,
          ael.entered_dr,
          ael.entered_cr,
          ael.accounted_dr,
          ael.accounted_cr,
          ael.description,
          ael.gl_sl_link_id,
          aeh.set_of_books_id
   FROM ae_lines_v ael,
        ap_invoices_all ai,
        ap_ae_headers_all aeh,
        ap_accounting_events_all aae
   WHERE aae.accounting_event_id = aeh.accounting_event_id
   AND   aeh.ae_header_id = ael.ae_header_id
   AND   ael.ae_line_type_code = ''LIABILITY''
   AND   to_number(ael.reference2) = ai.invoice_id
   AND   aeh.gl_transfer_flag = ''Y''
   AND   NOT EXISTS (
           SELECT 1 FROM ap_liability_balance aplb1
           WHERE aplb1.ae_line_id = ael.ae_line_id
           AND   aplb1.ae_header_id = ael.ae_header_id
           AND   aplb1.set_of_books_id = aeh.set_of_books_id
           AND   aplb1.code_combination_id = ael.code_combination_id
           AND   aplb1.invoice_id = ai.invoice_id)
   AND   NOT EXISTS (
           SELECT 1 FROM xla_events xe
           WHERE xe.application_id = 200
           AND   xe.event_id = aeh.accounting_event_id
           AND   xe.upg_batch_id = -9999)
   AND   EXISTS (
           SELECT /*+ ordered use_nl(tiv, xte, hzp, hzps, as1) */
                  tiv.invoice_id
           FROM ap_invoices_all tiv,
                xla_transaction_entities_upg xte,
                hz_parties hzp,
                hz_party_sites hzps,
                ap_suppliers as1
           WHERE xte.entity_code = ''AP_INVOICES''
           AND   xte.ledger_id = ai.set_of_books_id
           AND   xte.application_id = 200
           AND   NVL(xte.source_id_int_1,-99) = tiv.invoice_id
           AND   tiv.party_id = hzp.party_id
           AND   tiv.vendor_id = as1.vendor_id(+)
           AND   ai.party_site_id = hzps.party_site_id(+)
           AND   ((as1.employee_id is null AND
                   hzps.party_site_id is not null) OR
                  (as1.employee_id is not null))
           AND   (tiv.payment_status_flag = ''Y'' OR
                  tiv.cancelled_date is not null)
           AND  tiv.invoice_id = ai.invoice_id)
   UNION ALL
   SELECT /*+ leading(ael) use_nl(ai, aeh, aae) */
          ''Lines Created in 11i, Transferred to GL in R12'',
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_date,
          ai.invoice_type_lookup_code,
          ai.invoice_amount,
          ai.base_amount,
          aeh.accounting_event_id,
          aae.event_type_code,
          aeh.ae_header_id,
          aeh.gl_transfer_flag,
          ael.ae_line_id,
          ael.ae_line_number,
          ael.ae_line_type_code,
          ael.code_combination_id,
          ael.currency_code,
          ael.entered_dr,
          ael.entered_cr,
          ael.accounted_dr,
          ael.accounted_cr,
          ael.description,
          ael.gl_sl_link_id,
          aeh.set_of_books_id
   FROM ae_lines_v ael,
        ap_invoices_all ai,
        ap_ae_headers_all aeh,
        ap_accounting_events_all aae
   WHERE aae.accounting_event_id = aeh.accounting_event_id
   AND   aeh.ae_header_id = ael.ae_header_id
   AND   ael.ae_line_type_code = ''LIABILITY''
   AND   to_number(ael.reference2) = ai.invoice_id
   AND   nvl(aeh.gl_transfer_flag, ''N'') <> ''Y''
   AND   EXISTS (
           SELECT 1 FROM xla_ae_headers xah
           WHERE xah.application_id = 200
           AND   xah.upg_batch_id is not null
           AND   xah.gl_transfer_status_code = ''Y''
           AND   xah.event_id = aeh.accounting_event_id
           AND   xah.Completion_Acct_Seq_Value = aeh.ae_header_id
           AND   xah.group_id is not null)
   AND   NOT EXISTS (
           SELECT 1 FROM ap_liability_balance aplb1
           WHERE aplb1.ae_line_id = ael.ae_line_id
           AND   aplb1.ae_header_id = ael.ae_header_id
           AND   aplb1.set_of_books_id = aeh.set_of_books_id
           AND   aplb1.code_combination_id = ael.code_combination_id
           AND   aplb1.invoice_id = ai.invoice_id)
   AND   NOT EXISTS (
           SELECT 1 FROM xla_events xe
           WHERE xe.application_id = 200
           AND   xe.event_id = aeh.accounting_event_id
           AND   xe.upg_batch_id = -9999)
   UNION ALL
   SELECT /*+ leading(ael) use_nl(ai, aeh, aae) */
          ''Non-Fully Paid Non-Canceled Invoices'',
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_date,
          ai.invoice_type_lookup_code,
          ai.invoice_amount,
          ai.base_amount,
          aeh.accounting_event_id,
          aae.event_type_code,
          aeh.ae_header_id,
          aeh.gl_transfer_flag,
          ael.ae_line_id,
          ael.ae_line_number,
          ael.ae_line_type_code,
          ael.code_combination_id,
          ael.currency_code,
          ael.entered_dr,
          ael.entered_cr,
          ael.accounted_dr,
          ael.accounted_cr,
          ael.description,
          ael.gl_sl_link_id,
          aeh.set_of_books_id
   FROM ae_lines_v ael,
        ap_invoices_all ai,
        ap_ae_headers_all aeh,
        ap_accounting_events_all aae
   WHERE aae.accounting_event_id = aeh.accounting_event_id
   AND   aeh.ae_header_id = ael.ae_header_id
   AND   ael.ae_line_type_code = ''LIABILITY''
   AND   to_number(ael.reference2) = ai.invoice_id
   AND   aeh.gl_transfer_flag = ''Y''
   AND   ai.cancelled_date IS NULL
   AND   ai.payment_status_flag <> ''Y''
   AND   ai.invoice_amount <> 0
   AND   NOT EXISTS (
           SELECT 1 FROM ap_liability_balance aplb1
           WHERE aplb1.ae_line_id = ael.ae_line_id
           AND   aplb1.ae_header_id = ael.ae_header_id
           AND   aplb1.set_of_books_id = aeh.set_of_books_id
           AND   aplb1.code_combination_id = ael.code_combination_id
           AND   aplb1.invoice_id = ai.invoice_id)
   AND   NOT EXISTS (
           SELECT 1 FROM xla_events xe
           WHERE xe.application_id = 200
           AND   xe.event_id = aeh.accounting_event_id
           AND   xe.upg_batch_id = -9999)',
      p_title                  => 'MGD-107',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Missing records in AP_Liability_Balance<br/><strong>Impact Area(s): </strong>Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>19367714</br><strong>Note: </strong>[1321370/KB785552]</br><strong>Script Name: </strong>ap_aplb_missing_s.sql</br></br>Apply the GDF patch following the instructions provided in [1321370/KB785552]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: 107');



debug('begin add_signature: 108');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '17480656';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1335562.1';
   l_info('problem'):= 'Accrual Posted flag and Cash Posted flag as ''N'' on AP distributions for Prepayment Application and Unapplication dists even though the corresponding events have been accounted ';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1335562.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4154',
      p_sig_id                 => '108',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai aid xe) */
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          ai.invoice_type_lookup_code,
          ai.invoice_date,
          ai.invoice_amount,
          aid.line_type_lookup_code,
          aid.amount,
          aid.base_amount,
          aid.match_status_flag,
          aid.accounting_event_id,
          aid.posted_flag,
          aid.accrual_posted_flag,
          aid.cash_posted_flag,
          xe.event_status_code,
          xe.process_status_code,
          gl.sla_ledger_cash_basis_flag,
          aid.set_of_books_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        gl_ledgers gl,
        xla_events xe
   WHERE aid.invoice_id = ai.invoice_id
   AND   ai.set_of_books_id = gl.ledger_id
   AND   aid.accounting_event_id = xe.event_id
   AND   xe.application_id = 200
   AND   xe.event_type_code IN (''PREPAYMENT APPLIED'',
           ''PREPAYMENT UNAPPLIED'')
   AND   aid.prepay_distribution_id is not null
   AND   xe.event_status_code IN (''N'',''P'')
   AND   xe.process_status_code = ''P''
   AND   (nvl(aid.posted_flag, ''N'') <> ''Y'' OR
          (gl.sla_ledger_cash_basis_flag = ''Y'' AND
           nvl(aid.cash_posted_flag, ''N'') <> ''Y'') OR
          (gl.sla_ledger_cash_basis_flag = ''N'' AND
           nvl(aid.accrual_posted_flag, ''N'') <> ''Y''))
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-108',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Accrual Posted flag and Cash Posted flag as ''N'' on AP distributions for Prepayment Application and Unapplication dists even though the corresponding events have been accounted <br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>17480656</br><strong>Note: </strong>[1335562/KB381257]</br><strong>Script Name: </strong>ap_prepay_incorr_posted_s.sql check 1</br></br>Apply the GDF patch following the instructions provided in [1335562/KB381257]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: 108');



