           AND   nvl(d.match_status_flag, ''N'') <> ''A''
           UNION
           SELECT 1 FROM ap_invoice_distributions_all d
           WHERE d.invoice_id = ai.invoice_id
           AND   nvl(d.posted_flag, ''N'') <> ''Y''
