      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, xte, xe) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          xe.event_id,
          xe.event_type_code,
          xe.event_status_code,
          xe.process_status_code,
          xe.event_date,
          xte.entity_id,
          xte.source_id_int_1,
          fsp.purch_encumbrance_flag
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        financials_system_params_all fsp,
        xla_transaction_entities_upg xte,
        xla_events xe
   WHERE xe.application_id = 200
   AND   xe.application_id = xte.application_id
   AND   xe.event_type_code IN (''INVOICE VALIDATED'',
           ''INVOICE ADJUSTED'', ''INVOICE ADJUSTMENT'',
           ''INVOICE CANCELLED'', ''PREPAYMENT VALIDATED'',
           ''PREPAYMENT ADJUSTED'', ''PREPAYMENT CANCELLED'',
           ''DEBIT MEMO VALIDATED'', ''DEBIT MEMO ADJUSTED'',
           ''DEBIT MEMO CANCELLED'', ''CREDIT MEMO VALIDATED'',
           ''CREDIT MEMO ADJUSTED'', ''CREDIT MEMO CANCELLED'')
   AND   xe.event_type_code NOT IN (''MANUAL'', ''REVERSAL'')
   AND   xe.upg_batch_id is not null
   AND   xe.upg_batch_id <> -9999
   AND   nvl(xe.budgetary_control_flag, ''N'') = ''N''
   AND   xe.entity_id = xte.entity_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   ai.set_of_books_id = xte.ledger_id
   AND   ai.set_of_books_id = fsp.set_of_books_id
   AND   ai.org_id = fsp.org_id
   AND   NOT EXISTS (
           SELECT ''missing acctg evt for aprvd dists''
           FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.historical_flag = ''Y''
           AND   aid.accounting_event_id is null
           AND   (aid.match_status_flag = ''A'' OR
                  (aid.match_status_flag IN (''A'', ''T'') AND
                   purch_encumbrance_flag = ''N'')))
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */
                  ''No Invoice rows exist for this event''
           FROM ap_invoice_distributions_all aid
           WHERE aid.accounting_event_id = xe.event_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */
                  ''No Distributions exist for the bc_event_id''
           FROM ap_invoice_distributions_all aid
           WHERE aid.bc_event_id = xe.event_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */
                  ''No payment rows exist for this event''
           FROM ap_invoice_payments_all aip
           WHERE aip.accounting_event_id = xe.event_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */
                  ''No payment history rows exists for this event''
           FROM ap_payment_history_all aph
           WHERE aph.accounting_event_id = xe.event_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */
                  ''No self assessed tax rows exists for this event''
           FROM ap_self_assessed_tax_dist_all asatd
           WHERE asatd.accounting_event_id = xe.event_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */
                  ''No self assessed tax rows exists for the bc_event_id''
           FROM ap_self_assessed_tax_dist_all asatd
           WHERE asatd.bc_event_id = xe.event_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */
                  ''No prepay history rows exists for this event''
           FROM ap_prepay_history_all aprh
           WHERE aprh.accounting_event_id = xe.event_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */
                  ''No prepayment history rows exists for the bc_event_id''
           FROM ap_prepay_history_all apph
           WHERE apph.bc_event_id = xe.event_id)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-116',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphan upgraded invoice accounting events not associated to any transaction<br/><strong>Impact Area(s): </strong>Period Close, Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>17488502</br><strong>Note: </strong>[1333548/KB325559]</br><strong>Script Name: </strong>ap_orphan_upg_events_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1333548/KB325559]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '15'
      );
   l_info.delete;
debug('end add_signature: 116');



debug('begin add_signature: 117');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '17480776';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '970912.1';
   l_info('problem'):= 'Unaccounted prepay apply and unapply events for canceled invoices';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 970912.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4030',
      p_sig_id                 => '117',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, aid, xe, xe2) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          aid.parent_reversal_id,
          xe.event_type_code,
          aid.accounting_event_id,
          aid.bc_event_id,
          aid.amount,
          aid.base_amount
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        xla_events xe,
        xla_events xe2
   WHERE aid.invoice_id = ai.invoice_id
   AND   ai.cancelled_date is not null
   AND   ai.invoice_amount = 0
   AND   aid.prepay_distribution_id is not null
   AND   nvl(aid.reversal_flag, ''N'') = ''Y''
   AND   nvl(aid.posted_flag, ''N'')  <> ''Y''
   AND   aid.accounting_event_id = xe.event_id (+)
   AND   nvl(xe.application_id, 200) = 200
   AND   nvl(xe.event_status_code, ''N'') <> ''P''
   AND   nvl(aid.encumbered_flag, ''N'') <> ''Y''
   AND   aid.bc_event_id = xe2.event_id (+)
   AND   nvl(xe2.application_id, 200) = 200
   AND   nvl(xe2.event_status_code, ''N'') <> ''P''
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = aid.invoice_id
           AND   aid1.prepay_distribution_id IS NOT NULL
           AND   nvl(aid1.reversal_flag, ''N'') = ''Y''
           AND   (aid.parent_reversal_id = aid1.invoice_distribution_id OR
                  aid.invoice_distribution_id = aid1.parent_reversal_id)
           AND   nvl(aid1.posted_flag, ''N'') <> ''Y''
           AND   nvl(aid1.encumbered_flag, ''N'') <> ''Y'')
   AND EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_distributions_all aid2
           WHERE aid2.invoice_id = ai.invoice_id
           AND aid2.prepay_distribution_id is null)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-117',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Unaccounted prepay apply and unapply events for canceled invoices<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>17480776</br><strong>Note: </strong>[970912/KB860738]</br><strong>Script Name: </strong>ap_prepay_apply_unapply_sel.sql</br></br>Apply the GDF patch following the instructions provided in [970912/KB860738]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: 117');



debug('begin add_signature: 160');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Discard';
   l_info('bug_number'):= '19637629';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1940180.1';
   l_info('problem'):= 'Invoices where the invoice_num value does not correspond to the value in Payments, EBTax, or Subledger Accounting tables.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1940180.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4171',
      p_sig_id                 => '160',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id
   FROM invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(xte.source_id_int_1,-99) = ai.invoice_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   xte.application_id = 200
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.transaction_number <> ai.invoice_num
   UNION ALL
   SELECT /*+ ordered no_merge(chkrun) use_nl(ai, idp) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id
   FROM (
           SELECT distinct aps.invoice_id,
                  to_char(aps.checkrun_id) chkrun_id_chr,
                  to_char(aps.invoice_id) invoice_id_chr
           FROM invs,
                ap_payment_schedules_all aps
           WHERE aps.invoice_id = invs.invoice_id
           UNION
           SELECT aip.invoice_id,
                  to_char(nvl(ac.checkrun_id, ac.check_id)),
                  to_char(aip.invoice_id)
           FROM invs,
                ap_invoice_payments_all aip,
                ap_checks_all ac
           WHERE aip.invoice_id = invs.invoice_id
           AND   ac.check_id = aip.check_id
         )  chkrun,
        ap_invoices_all ai,
        iby_docs_payable_all idp
   WHERE ai.invoice_id = chkrun.invoice_id
   AND   idp.calling_app_id = 200
   AND   idp.calling_app_doc_unique_ref1 = chkrun.chkrun_id_chr
   AND   idp.calling_app_doc_unique_ref2 = chkrun.invoice_id_chr
   AND   idp.pay_proc_trxn_type_code IN (''PAYABLES_DOC'',''EMPLOYEE_EXP'')
   AND   idp.calling_app_doc_ref_number <> ai.invoice_num
   AND   idp.org_id = ai.org_id
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id
   FROM invs,
        ap_invoices_all ai,
        zx_lines zl
   WHERE ai.invoice_id = invs.invoice_id
   AND   zl.trx_id = ai.invoice_id
   AND   zl.application_id = 200
   AND   zl.entity_code = ''AP_INVOICES''
   AND   zl.trx_number <> ai.invoice_num',
      p_title                  => 'MGD-160',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices where the invoice_num value does not correspond to the value in Payments, EBTax, or Subledger Accounting tables.<br/><strong>Impact Area(s): </strong>Invoice Discard',
      p_solution               => '<strong>Solution GDF: </strong>19637629</br><strong>Note: </strong>[1940180/KB724881]</br><strong>Script Name: </strong>ap_syncup_inv_num_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1940180/KB724881]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '21'
      );
   l_info.delete;
debug('end add_signature: 160');



