debug('end add_signature: 204');



debug('begin add_signature: 205');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '17493968';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1370202.1';
   l_info('problem'):= 'Invoices with different amounts in xla_ae_lines and xla_distribution_links causing issues with AP-PO accrual reconciliation';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1370202.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3930',
      p_sig_id                 => '205',
      p_sig_sql                => 'SELECT ''XAL_XDL_MISMATCH'' category,
          ai.invoice_id,
          ai.invoice_date,
          ai.org_id,
          ai.Invoice_Num,
          ai.Invoice_type_lookup_code,
          ai.Invoice_Amount,
          ai.Invoice_date,
          ai.set_of_books_id,
          xah.event_id,
          xah.event_type_code,
          xah.accounting_date,
          xah.ae_header_id,
          xal.ae_line_num,
          xal.code_combination_id,
          xal.accounting_class_code,
          xal.accounted_dr,
          xal.accounted_cr,
          xdl_v.net_amt
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah,
        xla_ae_lines xal,
        cst_accrual_accounts cst,
        gl_period_statuses glps,
        (
          SELECT xdl.ae_header_id,
                 xdl.ae_line_num,
                 sum(nvl(xdl.unrounded_accounted_dr, 0) -
                   nvl(xdl.unrounded_accounted_cr, 0)) net_amt
          FROM xla_distribution_links xdl
          WHERE xdl.application_id = 200
          GROUP BY xdl.ae_header_id, xdl.ae_line_num
        ) xdl_v
   WHERE xal.application_id = 200
   AND   xah.application_id = 200
   AND   xte.application_id = 200
   AND   xal.ae_header_id = xah.ae_header_id
   AND   xah.entity_id = xte.entity_id
   AND   xah.upg_batch_id is not null
   AND   xah.event_type_code not in (''PREPAYMENT APPLIED'',
             ''PREPAYMENT UNAPPLIED'')
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.accounting_event_id = xah.event_id
           AND   aid.po_distribution_id is not null)
   AND   xah.ledger_id = xte.ledger_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   nvl(xte.source_id_int_1, -99) = ai.Invoice_ID
   AND   xte.entity_code = ''AP_INVOICES''
   AND   ai.set_of_books_id = glps.set_of_books_id
   AND   nvl(glps.adjustment_period_flag, ''N'') = ''N''
   AND   ai.gl_date BETWEEN glps.start_date AND glps.end_date
   AND   glps.application_id = 200
   AND   glps.migration_status_code = ''U''
   AND   xal.code_combination_id = cst.accrual_account_id
   AND   xdl_v.ae_header_id = xal.ae_header_id
   AND   xdl_v.ae_line_num = xal.ae_line_num
   AND   (nvl(xal.accounted_dr, 0) - nvl(xal.accounted_cr, 0)) <> xdl_v.net_amt
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-205',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices with different amounts in xla_ae_lines and xla_distribution_links causing issues with AP-PO accrual reconciliation<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>17493968</br><strong>Note: </strong>[1370202/KB266606]</br><strong>Script Name: </strong>ApPoAccrualReconcSel.sql Check 1</br></br>Apply the GDF patch following the instructions provided in [1370202/KB266606]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: 205');



debug('begin add_signature: 206');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '17493968';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1370202.1';
   l_info('problem'):= 'Accrual invoice distributions with exchange rate variance distributions having incorrect amounts in xla_distribution_links causing issues with AP-PO accrual reconciliation';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1370202.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3931',
      p_sig_id                 => '206',
      p_sig_sql                => 'SELECT ''INCORRECT_XDL_WHEN_ERV'' category,
          ai.invoice_id,
          ai.org_id,
          ai.invoice_num,
          ai.invoice_type_lookup_code,
          ai.invoice_Amount,
          ai.invoice_date,
          ai.set_of_books_id,
          xah.event_id,
          xah.event_type_code,
          xah.accounting_date,
          xah.ae_header_id,
          xal.ae_line_num,
          xal.code_combination_id,
          xal.accounting_class_code,
          xdl.unrounded_accounted_dr,
          xdl.unrounded_accounted_cr,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          aid.base_amount,
          aidv.invoice_distribution_id var_inv_dist_id,
          aidv.line_type_lookup_code var_line_type_code,
          aidv.amount var_amount,
          aidv.base_amount var_base_amount,
          aid.po_distribution_ID
   FROM xla_distribution_links xdl,
        xla_ae_lines xal,
        cst_accrual_accounts cst,
        xla_ae_headers xah,
        ap_invoice_distributions_all aid,
        ap_invoice_distributions_all aidv,
        ap_invoices_all ai,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE xdl.application_id = 200
   AND   xdl.accounting_line_type_code = ''S''
   AND   xdl.line_definition_code = ''ACCRUAL_INVOICES_ALL''
   AND   xdl.event_class_code = ''INVOICES''
   AND   xdl.event_type_code = ''INVOICES_ALL''
   AND   xdl.source_distribution_type = ''AP_INV_DIST''
   AND   xdl.upg_batch_id IS NOT NULL
   AND   xal.application_id = 200
   AND   xdl.ae_header_id = xal.ae_header_id
   AND   xdl.ae_line_num = xal.ae_line_num
   AND   xal.upg_batch_id IS NOT NULL
   AND   xal.code_combination_id = cst.accrual_account_id
   AND   xah.application_id = 200
   AND   xah.ae_header_id = xal.ae_header_id
   AND   xah.upg_batch_id IS NOT NULL
   AND   xah.event_id = aid.accounting_event_id
   AND   xah.event_type_code NOT IN (''PREPAYMENT APPLIED'',''PREPAYMENT UNAPPLIED'')
   AND   xah.ledger_id = aid.set_of_books_id
   AND   aid.invoice_distribution_id = xdl.source_distribution_id_num_1
   AND   aid.po_distribution_id IS NOT NULL
   AND   aid.line_type_lookup_code NOT IN (''ERV'',''TERV'')
   AND   aidv.invoice_id = aid.invoice_id
   AND   aid.invoice_distribution_id = aidv.related_id
   AND   aid.invoice_id = aidv.invoice_id
   AND   aidv.line_type_lookup_code IN (''ERV'',''TERV'')
   AND   aidv.base_amount <> 0
   AND   abs(
           abs(aid.base_amount) -
           abs(nvl(xdl.unrounded_accounted_cr,xdl.unrounded_accounted_dr))
         ) > 0.01
   AND   aid.invoice_id = ai.invoice_id
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-206',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Accrual invoice distributions with exchange rate variance distributions having incorrect amounts in xla_distribution_links causing issues with AP-PO accrual reconciliation<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>17493968</br><strong>Note: </strong>[1370202/KB266606]</br><strong>Script Name: </strong>ApPoAccrualReconcSel.sql Check 2</br></br>Apply the GDF patch following the instructions provided in [1370202/KB266606]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: 206');



debug('begin add_signature: 209');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Trial Balance';
   l_info('bug_number'):= '17494470';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1083599.1';
   l_info('problem'):= 'Upgraded invoices having multiple parties for the liability lines';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1083599.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3935',
      p_sig_id                 => '209',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   ),
   dups_v AS (
     SELECT to_number(ael_v.invoice_id) "INVOICE_ID"
     FROM (
             SELECT /*+ leading(invs) use_nl(ael) */
                    ael.reference2 invoice_id,
                    ael.third_party_id
             FROM invs,
                  ap_ae_lines_all ael
             WHERE ael.source_table IN (''AP_INVOICES'',''AP_INVOICES_ALL'')
             AND   ael.source_id = invs.invoice_id
             AND   ael.ae_line_type_code = ''LIABILITY''
             UNION ALL
             SELECT /*+ ordered use_nl(aip, ael) */
                    ael.reference2,
                    ael.third_party_id
             FROM invs,
                  ap_invoice_payments_all aip,
                  ap_ae_lines_all ael
             WHERE aip.invoice_id = invs.invoice_id
             AND   ael.source_table = ''AP_INVOICE_PAYMENTS''
             AND   ael.source_id = aip.invoice_payment_id
             AND   ael.ae_line_type_code = ''LIABILITY''
             UNION ALL
             SELECT /*+ ordered use_nl(aid, ael) */
                    ael.reference2,
                    ael.third_party_id
             FROM invs,
                  ap_invoice_distributions_all aid,
                 ap_ae_lines_all ael
             WHERE aid.invoice_id = invs.invoice_id
             AND   ael.source_table = ''AP_INVOICE_DISTRIBUTIONS''
             AND   ael.source_id = aid.invoice_distribution_id
             AND   ael.ae_line_type_code = ''LIABILITY''
          ) ael_v
   GROUP BY ael_v.invoice_id
   HAVING count(distinct ael_v.third_party_id) > 1
   ),
   xte_v AS (
     SELECT DISTINCT
            inv_pay_info.orig_invoice,
            inv_pay_info.ael_source_table,
            inv_pay_info.ael_source_id,
            xte.entity_id,
            xte.entity_code,
            xte.ledger_id,
            xte.security_id_int_1 org_id,
            tiv.invoice_num,
            tiv.party_name
     FROM xla_transaction_entities_upg xte,
          ap_sla_invoices_transaction_v tiv,
          (
            SELECT /*+ leading(dups_v) use_nl(inv) */ DISTINCT
                   dups_v.invoice_id "ORIG_INVOICE",
                   inv.invoice_id xte_source_id,
                   ''AP_INVOICES'' xte_source_table,
                   inv.invoice_id ael_source_id ,
                   ''AP_INVOICES'' ael_source_table ,
                   inv.set_of_books_id
            FROM dups_v,
                 ap_invoices_all inv
            WHERE inv.invoice_id = dups_v.invoice_id
            UNION
            SELECT /*+ leading(dups_v) use_nl(invpay)*/ DISTINCT
                   dups_v.invoice_id,
                   invpay.check_id,
                   ''AP_PAYMENTS'',
                   invpay.invoice_payment_id,
                   ''AP_INVOICE_PAYMENTS'',
                   invpay.set_of_books_id
            FROM dups_v,
                 ap_invoice_payments_all invpay
            WHERE dups_v.invoice_id = invpay.invoice_id
          ) inv_pay_info
     WHERE xte.application_id = 200
     AND   inv_pay_info.orig_invoice = tiv.invoice_id
     AND   xte.ledger_id = inv_pay_info.set_of_books_id
     AND   xte.entity_code = inv_pay_info.xte_source_table
     AND   nvl(xte.source_id_int_1 , -99 ) = inv_pay_info.xte_source_id
     AND   nvl(xte.source_id_int_2 , -99 ) = -99
     AND   nvl(xte.source_id_int_3 , -99 ) = -99
     AND   nvl(xte.source_id_int_4 , -99 ) = -99
     AND   nvl(xte.SOURCE_ID_CHAR_1,'' '') = '' ''
     AND   nvl(xte.SOURCE_ID_CHAR_2,'' '') = '' ''
     AND   nvl(xte.SOURCE_ID_CHAR_3,'' '') = '' ''
     AND   nvl(xte.SOURCE_ID_CHAR_4,'' '') = '' ''
   )
   SELECT xte_v.orig_invoice invoice_id,
          xte_v.invoice_num,
          xte_v.org_id,
          xal.ae_header_id,
          xal.ae_line_num,
          xal.party_id,
          xal.party_site_id,
          inv.party_id new_party_id,
          inv.party_site_id  new_party_site_id,
          xal.source_id,
          xal.source_table,
          xah.entity_id source_entity_id,
          inv.entity_id applied_to_entity_id,
          xah.ledger_id
   FROM xte_v,
        xla_ae_headers xah,
        xla_ae_lines xal,
        (
          SELECT DISTINCT
                 xal_inv.party_id,
                 xal_inv.party_site_id,
                 xte_inv.orig_invoice,
                 xah_inv.entity_id,
                 rank() OVER (
                   PARTITION BY xte_inv.entity_id
                   ORDER BY xah_inv.upg_batch_id DESC,
                            xah_inv.ae_header_id DESC,
                            xal_inv.ae_line_num DESC) rank
          FROM xla_ae_headers xah_inv,
               xla_ae_lines xal_inv,
               xte_v xte_inv
          WHERE xte_inv.entity_code = ''AP_INVOICES''
          AND   xah_inv.entity_id = xte_inv.entity_id
          AND   xah_inv.ledger_id = xte_inv.ledger_id
          AND   xah_inv.accounting_entry_status_code = ''F''
          AND   xah_inv.gl_transfer_status_code = ''Y''
          AND   xah_inv.application_id = 200
          AND   xal_inv.ae_header_id = xah_inv.ae_header_id
          AND   xal_inv.accounting_class_code = ''LIABILITY''
          AND   xah_inv.event_type_code not like ''PREPAY%APPL%''
          AND   xal_inv.application_id = 200
        ) inv,
        invs
   WHERE xah.entity_id = xte_v.entity_id
   AND   xah.upg_batch_id is not null
   AND   xah.upg_batch_id NOT IN (-9999, -5672)
   AND   xah.application_id = 200
   AND   xal.ae_header_id = xah.ae_header_id
   AND   xal.accounting_class_code = ''LIABILITY''
   AND   xal.source_table = xte_v.ael_source_table
   AND   xal.source_id = xte_v.ael_source_id
   AND   nvl(xal.gl_sl_link_id , 0) >= 0
   AND   xal.application_id = 200
   AND   xte_v.orig_invoice = inv.orig_invoice (+)
   AND   inv.rank(+)= 1
   AND   inv.party_id is not null
   AND   inv.party_site_id is not null
   AND   (xal.party_id <> inv.party_id OR
          xal.party_site_id <> inv.party_site_id)
   AND   xte_v.orig_invoice = invs.invoice_id',
      p_title                  => 'MGD-209',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Upgraded invoices having multiple parties for the liability lines<br/><strong>Impact Area(s): </strong>Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>17494470</br><strong>Note: </strong>[1083599/KB711135]</br><strong>Script Name: </strong>ap_party_id_mismatch_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1083599/KB711135]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: 209');



debug('begin add_signature: 216');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'EBTax, Validation Selection';
   l_info('bug_number'):= '16090199';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1152029.1';
   l_info('problem'):= 'Invoices with tax distributions in Payables that do not exist in the EBTax distributions table ZX_REC_NREC_DIST';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1152029.1';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3960',
      p_sig_id                 => '216',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai) */
         ai.invoice_id,
         ai.invoice_num,
         ai.org_id,
         ai.invoice_date
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_invoice_distributions_all dist
           WHERE dist.invoice_id = ai.invoice_id
           AND   nvl(dist.historical_flag,''N'') <> ''Y''
           AND   dist.summary_tax_line_id is not null
           AND   dist.detail_tax_dist_id is not null
           AND   NOT EXISTS (
                   SELECT /*+ no_unnest */ 1 FROM zx_rec_nrec_dist zd
                   WHERE zd.rec_nrec_tax_dist_id = dist.detail_tax_dist_id
                   AND   zd.summary_tax_line_id = dist.summary_tax_line_id)
           UNION
           SELECT /*+ no_unnest */ 2
           FROM ap_self_assessed_tax_dist_all sa_dist
           WHERE sa_dist.invoice_id = ai.invoice_id
           AND   sa_dist.summary_tax_line_id is not null
           AND   sa_dist.detail_tax_dist_id is not null
           AND   NOT EXISTS (
                   SELECT /*+ no_unnest */ 1
                   FROM zx_rec_nrec_dist zd
                   WHERE zd.rec_nrec_tax_dist_id = sa_dist.detail_tax_dist_id
                   AND   zd.summary_tax_line_id = sa_dist.summary_tax_line_id))
   AND   ai.cancelled_date is null',
      p_title                  => 'MGD-216',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices with tax distributions in Payables that do not exist in the EBTax distributions table ZX_REC_NREC_DIST<br/><strong>Impact Area(s): </strong>EBTax, Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>16090199</br><strong>Note: </strong>[1152029/KB738316]</br><strong>Script Name: </strong>zx_frzn_dist_pop.sql</br></br>Apply the GDF patch following the instructions provided in [1152029/KB738316]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '12'
      );
   l_info.delete;
debug('end add_signature: 216');



debug('begin add_signature: 217');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Automatic Witholding Tax';
   l_info('bug_number'):= '11838058';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1403715.1';
   l_info('problem'):= 'Invoices with AWT reversal distributions which do not have the awt_invoice_id populated';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1403715.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3955',
      p_sig_id                 => '217',
      p_sig_sql                => 'SELECT ai.invoice_id awt_invoice_id,
          ai.invoice_amount,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          substr(ai.invoice_num,
            instr(ai.invoice_num, ''-'', 1, 1) + 2,
            ((instr(ai.invoice_num, ''-'', 1, 2) - 1) -
             (instr(ai.invoice_num, ''-'', 1, 1) + 2))) invoice_id,
          substr(ai.invoice_num,
            instr(ai.invoice_num, ''-'', 1, 2) + 2,
              decode(instr(ai.invoice_num, ''Cancelled'',1,1),
                0, length(ai.invoice_num),
                   (instr(ai.invoice_num, ''-'', 1, 3) - 1) -
                   (instr(ai.invoice_num, ''-'', 1, 2) + 2))) invoice_line_number,
          decode(instr(ai.invoice_num, ''Cancelled'', 1, 1),
            0, '''',
            ''cancelled'') status,
          CASE
            WHEN (
              SELECT count(1) FROM ap_invoice_distributions_all aid1
              WHERE aid1.invoice_id = ai.invoice_id
              AND   rownum = 1) <> 0
            THEN ''Y''
            ELSE
              ''N''
            END awt_inv_dist_exists
   FROM ap_invoices_all ai,
        ap_system_parameters_all asp,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE ai.org_id = asp.org_id
   AND   asp.create_awt_invoices_type = ''PAYMENT''
   AND   ai.invoice_type_lookup_code = ''AWT''
   AND   ai.source = substrb(ap_utilities_pkg.ap_get_displayed_field(''NLS TRANSLATION'',
           ''AWT''),1,25)
   AND   NOT EXISTS (
           SELECT ''no dists'' FROM ap_invoice_distributions_all aid
           WHERE aid.awt_invoice_id = ai.invoice_id
           AND   aid.line_type_lookup_code = ''AWT''
           AND   aid.org_id = ai.org_id)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-217',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices with AWT reversal distributions which do not have the awt_invoice_id populated<br/><strong>Impact Area(s): </strong>Automatic Witholding Tax',
      p_solution               => '<strong>Solution GDF: </strong>11838058</br><strong>Note: </strong>[1403715/KB161687]</br><strong>Script Name: </strong>ap_pop_awt_invoice_id_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1403715/KB161687]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 217');



debug('begin add_signature: 218');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Prepay Application';
   l_info('bug_number'):= '17380383';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1404763.1';
   l_info('problem'):= 'Prepayment invoice distributions with incorrect values in the PREPAY_AMOUNT_REMAINING column.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1404763.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3973',
      p_sig_id                 => '218',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ ordered */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aid_p.invoice_distribution_id,
          ''PAID'' invoice_state,
          aid_p.prepay_amount_remaining
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid_p
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_type_lookup_code = ''PREPAYMENT''
   AND   ai.payment_status_flag=''Y''
   AND   ai.invoice_id = aid_p.invoice_id
   AND   nvl(aid_p.prepay_amount_remaining, aid_p.total_dist_amount) <>
          (aid_p.total_dist_amount + (
           SELECT nvl(SUM(aid_s.amount), 0)
           FROM ap_invoice_distributions_all aid_s
           WHERE aid_s.prepay_distribution_id = aid_p.invoice_distribution_id))
   UNION ALL
   SELECT /*+ leading(invs) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aid_p.invoice_distribution_id,
          ''CHECK VOIDED''    invoice_state,
          aid_p.prepay_amount_remaining
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid_p
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_type_lookup_code = ''PREPAYMENT''
   AND   ai.invoice_id = aid_p.invoice_id
   AND   nvl(aid_p.prepay_amount_remaining, aid_p.total_dist_amount) <>
         (aid_p.total_dist_amount + (
            SELECT nvl(sum(aid_s.amount), 0)
            FROM ap_invoice_distributions_all aid_s
            WHERE aid_s.prepay_distribution_id = aid_p.invoice_distribution_id))
   AND   ai.payment_status_flag=''N''
   AND   EXISTS (
           SELECT ''voided payment''
           FROM ap_invoice_payments_all aip,
                ap_checks_all ac
           WHERE aip.invoice_id = ai.invoice_id
           AND   aip.check_id = ac.check_id
           and   ac.void_date is not null)',
      p_title                  => 'MGD-218',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Prepayment invoice distributions with incorrect values in the PREPAY_AMOUNT_REMAINING column.<br/><strong>Impact Area(s): </strong>Prepay Application',
      p_solution               => '<strong>Solution GDF: </strong>17380383</br><strong>Note: </strong>[1404763/KB225747]</br><strong>Script Name: </strong>ap_prepay_amount_rem_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1404763/KB225747]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: 218');



debug('begin add_signature: 219');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Data';
   l_info('bug_number'):= '17445609';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1410403.1';
   l_info('problem'):= 'The AMOUNT_APPLICABLE_TO_DISCOUNT column in AP_INVOICES_ALL was incorrectly updated (due to bug 9911823) causing incorrect discounts in AP_PAYMENT_SCHEDULES_ALL and over payment to suppliers';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1410403.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4155',
      p_sig_id                 => '219',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.source,
          ai.vendor_id,
          ai.vendor_site_id,
          ai.invoice_amount,
          nvl(ai.amount_applicable_to_discount, 0) amount_applicable_to_discount,
          nvl(ai.total_tax_amount, 0) total_tax_amount,
          nvl(ap_invoices_utility_pkg.get_freight_total(ai.invoice_id, ai.org_id),0)
            freight_total,
          nvl(abs(ap_invoices_utility_pkg.get_retained_total(ai.invoice_id, ai.org_id)),0)
            retained_amt,
          nvl(ai.exclude_freight_from_discount, ''N'') exclude_freight_from_discount,
          nvl(ai.disc_is_inv_less_tax_flag, ''N'') disc_is_inv_less_tax_flag,
          nvl(ai.net_of_retainage_flag, ''N'') net_of_retainage_flag,
          nvl((
            SELECT (0 - sum(nvl(amount,0)))
            FROM ap_invoice_distributions_all aid_awt
            WHERE aid_awt.invoice_id = ai.invoice_id
            AND   line_type_lookup_code = ''AWT'')
          , 0) total_awt,
          nvl((
            SELECT nvl(sum(aid_awt.amount),0)
            FROM ap_invoice_distributions_all aid_fre,
                 ap_invoice_distributions_all aid_awt
            WHERE aid_fre.invoice_id = ai.invoice_Id
            AND   aid_fre.invoice_id = aid_awt.invoice_id
            AND   aid_fre.line_type_lookup_code = ''FREIGHT''
            AND   aid_awt.line_type_lookup_code = ''AWT''
            AND   aid_fre.invoice_distribution_id = aid_awt.awt_related_id)
          , 0) awt_on_freight,
       ai.terms_id,
       decode(nvl(ai.payment_status_flag, ''N''),
              ''N'', ''UNPAID'',
              ''P'', ''PARTIALLY PAID'',
              ''Y'', ''PAID'') payment_status,
              atl.discount_percent,
              atl.discount_percent_2,
              atl.discount_percent_3
   FROM ap_invoices_all ai,
        ap_terms_lines atl,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE atl.term_id = ai.terms_id
   AND   ai.invoice_amount <> 0
   AND   ai.historical_flag is null
   AND   ai.cancelled_date is null
   AND   ai.invoice_type_lookup_code NOT IN (''INTEREST'')
   AND   nvl(ai.amount_applicable_to_discount, 0) <>
           (ai.invoice_amount -
             (CASE
                WHEN nvl(ai.exclude_freight_from_discount, ''N'') = ''Y'' THEN
                  nvl(ap_invoices_utility_pkg.get_freight_total(
                        ai.invoice_id,
                        ai.org_id),0)
                ELSE 0
              END) -
             (CASE
                WHEN nvl(ai.net_of_retainage_flag, ''N'') = ''N'' THEN
                  nvl(abs(ap_invoices_utility_pkg.get_retained_total(
                            ai.invoice_id,
                            ai.org_id))
                    ,0)
                ELSE 0
              END) -
             (CASE
                WHEN nvl(ai.disc_is_inv_less_tax_flag, ''N'') = ''Y'' THEN
                  nvl(ai.total_tax_amount, 0)
                ELSE 0
              END) -
	     (nvl((
                SELECT (0 - sum(nvl(amount,0)))
                FROM ap_invoice_distributions_all aid_awt
                WHERE aid_awt.invoice_id = ai.invoice_id
                AND   line_type_lookup_code = ''AWT'')
              , 0)) -
             (CASE
                WHEN nvl(ai.exclude_freight_from_discount, ''N'') = ''Y'' THEN
	          nvl((
                    SELECT nvl(sum(aid_awt.Amount),0)
                    FROM ap_invoice_distributions_all aid_fre,
                         ap_invoice_distributions_all aid_awt
                    WHERE aid_fre.invoice_id = ai.invoice_id
                    AND   aid_fre.invoice_id = aid_awt.invoice_id
                    AND   aid_fre.line_type_lookup_code = ''FREIGHT''
                    AND   aid_awt.line_type_lookup_code = ''AWT''
                    AND   aid_fre.invoice_distribution_id = aid_awt.awt_related_id)
                  ,0)
                ELSE 0
              END))
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-219',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The AMOUNT_APPLICABLE_TO_DISCOUNT column in AP_INVOICES_ALL was incorrectly updated (due to bug 9911823) causing incorrect discounts in AP_PAYMENT_SCHEDULES_ALL and over payment to suppliers<br/><strong>Impact Area(s): </strong>Invoice Data',
      p_solution               => '<strong>Solution GDF: </strong>17445609</br><strong>Note: </strong>[1410403/KB723936]</br><strong>Script Name: </strong>ap_amt_appl_to_disc_wrng_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1410403/KB723936]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: 219');



