debug('begin add_signature: 222');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect, EBTax';
   l_info('bug_number'):= '13365761';
   l_info('category'):= 'INVOICE';
