      p_fail_condition         => 'RS',
      p_problem_descr          => 'Non-historical invoices with tax distributions having exchange rate defined, but no conversion rate populated on EBTax distribution<br/><strong>Impact Area(s): </strong>Accounting Incorrect, EBTax',
      p_solution               => '<strong>Solution GDF: </strong>13365761</br><strong>Note: </strong>[1396732/KB764362]</br><strong>Script Name: </strong>zx_funcl_backup.sql</br></br>Apply the GDF patch following the instructions provided in [1396732/KB764362]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
