   l_info('note_number'):= '1445214.1';
   l_info('problem'):= 'The value for GL_SL_LINK is missing on upgraded accounting lines which are not transferred to GL.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1445214.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4159',
      p_sig_id                 => '223',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, xte, aeh, ael) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aeh.ae_header_id,
          ael.ae_line_num,
          ael.application_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers aeh,
        xla_ae_lines ael
   WHERE aeh.application_id = ael.application_id
   AND   aeh.ae_header_id = ael.ae_header_id
   AND   aeh.gl_transfer_status_code = ''N''
   AND   aeh.accounting_entry_status_code = ''F''
   AND   aeh.upg_batch_id is not null
   AND   ael.gl_sl_link_id is null
   AND   aeh.application_id = 200
   AND   aeh.ledger_id = xte.ledger_id
   AND   aeh.entity_id = xte.entity_id
   AND   xte.application_id = 200
   AND   xte.ledger_id = ai.set_of_books_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-223',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The value for GL_SL_LINK is missing on upgraded accounting lines which are not transferred to GL.<br/><strong>Impact Area(s): </strong>GL Transfer',
      p_solution               => '<strong>Solution GDF: </strong>13622318</br><strong>Note: </strong>[1445214/KB353083]</br><strong>Script Name: </strong>xla_xdl_miss_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1445214/KB353083]',
      p_success_msg            => '',
