debug('begin add_signature: 227');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure, Period Close, Sweep';
   l_info('bug_number'):= '9651687';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1133423.1';
   l_info('problem'):= 'Invoices with multiple transaction entity records in SLA';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1133423.1.
Note: GDF 9651687 is released for 12.0 & 12.2.  GDF patch 21221141 is released for 12.1.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4007',
      p_sig_id                 => '227',
      p_sig_sql                => 'SELECT /*+ leading(invs) use_nl(ai, xte2) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          xte2.application_id,
          xte2.entity_id,
          xte2.ledger_id,
          xte2.entity_code,
	  xte2.source_id_int_1,
          xte2.transaction_number,
          count(DISTINCT xe2.event_id) event_count
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte2,
        xla_events xe2
   WHERE 1 < (
           SELECT count(*)
           FROM xla_transaction_entities_upg xte
           WHERE xte.application_id = xte2.application_id
           AND   xte.ledger_id = xte2.ledger_id
           AND   xte.entity_code = xte2.entity_code
           AND   nvl(xte.source_id_int_1,-99) = xte2.source_id_int_1)
   AND   xe2.application_id(+) = xte2.application_id
   AND   xe2.entity_id(+) = xte2.entity_id
   AND   xte2.ledger_id = ai.set_of_books_id
   AND   xte2.application_id = 200
   AND   xte2.entity_code = ''AP_INVOICES''
   AND   nvl(xte2.source_id_int_1, -99) = ai.invoice_id
   AND   ai.invoice_id = invs.invoice_id
   GROUP BY ai.invoice_id, ai.invoice_num, ai.invoice_date, ai.org_id,
            xte2.application_id, xte2.entity_id, xte2.ledger_id,
            xte2.entity_code, xte2.source_id_int_1, xte2.transaction_number',
      p_title                  => 'MGD-227',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices with multiple transaction entity records in SLA<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close, Sweep',
      p_solution               => '<strong>Solution GDF: </strong>9651687</br><strong>Note: </strong>[1133423/KB787666]</br><strong>Script Name: </strong>xla_mulent_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1133423/KB787666].
Note: GDF 9651687 is released for 12.0 & 12.2.  GDF patch 21221141 is released for 12.1.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '14'
      );
