debug('begin add_signature: 230');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '13475314';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1445175.1';
   l_info('problem'):= 'Accounting reversal events are not getting accounted because of an existing reversal event.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1445175.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3992',
      p_sig_id                 => '230',
      p_sig_sql                => 'SELECT xdl.source_distribution_id_num_1,
          xah.event_type_code,
          xah.application_id,
          xah.upg_batch_id,
          xah.ledger_id,
          xah.balance_type_code,
          xdl.ae_header_id,
          xdl.ref_ae_header_id,
          xdl.ref_event_id,
          xdl.temp_line_num,
          xdl.ref_temp_line_num
   FROM  xla_distribution_links xdl,
         xla_ae_headers xah
   WHERE (xdl.application_id, xdl.ref_ae_header_id,
          xdl.temp_line_num, xah.ledger_id) IN (
           SELECT /*+ ordered use_nl(xah1, xdl1) */
                  xdl1.application_id,
                  xah1.ae_header_id,
                  -1 * xdl1.temp_line_num,
                  xah1.ledger_id
           FROM (
                  SELECT /*+ ordered use_nl(ai, xte, xe) */ DISTINCT
                         xe.application_id,
                         xe.entity_id
                  FROM (
                          ##$$IVIEW$$##
                        ) invs,
                       ap_invoices_all ai,
                       xla_transaction_entities_upg xte,
                       xla_events xe
                  WHERE xe.application_id = xte.application_id
                  AND   xe.entity_id = xte.entity_id
                  AND   xe.event_status_code = ''U''
                  AND   xte.application_id = 200
                  AND   xte.ledger_id = ai.set_of_books_id
                  AND   xte.entity_code = ''AP_INVOICES''
                  AND   nvl(xte.source_id_int_1,-99) = ai.invoice_id
                  AND   ai.invoice_id = invs.invoice_id
                ) xe,
                xla_ae_headers xah1,
                xla_distribution_links xdl1
           WHERE xah1.application_id = xe.application_id
           AND   xah1.entity_id = xe.entity_id
           AND   xdl1.application_id = xah1.application_id
           AND   xdl1.ae_header_id = xah1.ae_header_id
           AND   xdl1.temp_line_num > 0)
   AND   xah.ae_header_id = xdl.ae_header_id
   AND   xah.application_id = xdl.application_id
   AND   xdl.ref_temp_line_num = -1 * xdl.temp_line_num
   AND   ((xdl.ref_event_id   = xdl.ref_ae_header_id AND
           xah.event_type_code <> ''MANUAL'') OR
          (xah.event_type_code = ''MANUAL'' AND
           xah.upg_batch_id = -9999))',
      p_title                  => 'MGD-230',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Accounting reversal events are not getting accounted because of an existing reversal event.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>13475314</br><strong>Note: </strong>[1445175/KB658305]</br><strong>Script Name: </strong>xla_acct_reversal_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1445175/KB658305]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 230');



