debug('begin add_signature: 243');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Cancellation';
   l_info('bug_number'):= '21497508';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1489862.1';
   l_info('problem'):= 'Various invoice cancellation related issues are addressed. See [1489862.1] for a description of all issues covered.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1489862.1.
<br><br>
<b>NOTE:</b> Ensure when running ap_one_off_scripts_sel.sql that you provide <b>CANCEL</b> when prompted to enter the <b>Component Value</b> parameter .';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3790',
      p_sig_id                 => '243',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ ordered */
          ''CAN1''corruption_type,
          ai.invoice_id,
          ai.invoice_date,
          ai.org_id,
          ai.batch_id,
          ail.line_number,
          NULL invoice_distribution_id,
          ''Included tax amount is not null on cancelled invoice'' problem_description
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail
   WHERE ai.invoice_id = ail.invoice_id
   AND   ai.cancelled_date IS NOT NULL
   AND   NVL(ail.included_tax_amount,0) <> 0
   AND   (SELECT /*+ index(ZL ZX_LINES_U1) */
                 NVL(SUM(NVL(zl.tax_amt, 0)),0)
          FROM zx_lines zl
          WHERE zl.application_id  =  200
          AND   zl.entity_code  =  ''AP_INVOICES''
          AND   zl.trx_id   = ail.invoice_id
          AND   zl.trx_line_id = ail.line_number
          AND   NVL(zl.self_assessed_flag,    ''N'')  = ''N''
          AND   NVL(zl.reporting_only_flag,   ''N'') = ''N''
          AND   NVL(zl.tax_amt_included_flag, ''N'') = ''Y'') = 0
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered */
          ''CAN2'',
          ai.invoice_id,
          ai.invoice_date,
          ai.org_id,
          ai.batch_id,
          NULL,
          NULL,
          ''Incorrect approval status on cancelled invoice''
   FROM invs,
        ap_invoices_all ai
   WHERE ai.cancelled_date is not null
   AND   ai.WFAPPROVAL_STATUS NOT IN (''NOT REQUIRED'',''APPROVED'',''MANUALLY APPROVED'')
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-243',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Various invoice cancellation related issues are addressed. See [1489862/KB611407] for a description of all issues covered.<br/><strong>Impact Area(s): </strong>Invoice Cancellation',
      p_solution               => '<strong>Solution GDF: </strong>21497508</br><strong>Note: </strong>[1489862/KB611407]</br><strong>Script Name: </strong>ap_one_off_scripts_sel.sql Cancel</br></br>Apply the GDF patch following the instructions provided in [1489862/KB611407].
<br><br>
<b>NOTE:</b> Ensure when running ap_one_off_scripts_sel.sql that you provide <b>CANCEL</b> when prompted to enter the <b>Component Value</b> parameter .',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '18'
      );
