debug('begin add_signature: 249');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Prepay Application';
   l_info('bug_number'):= '21497508';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1489862.1';
   l_info('problem'):= 'Various invoice prepay related issues are addressed. See problem description for each row, and see note 1489862.1 for a description of all issues covered.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1489862.1  <br><br>
<b>NOTE:</b> Ensure when running ap_one_off_scripts_sel.sql that you provide <b>PREPAY</b> when prompted to enter the <b>Component Value</b> parameter.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3784',
      p_sig_id                 => '249',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ ordered use_nl(ai_std, ail_std, aid_std) */
          ''PRE1'' corruption_type,
          aid_std.invoice_id,
          aid_std.org_id,
          ail_std.line_number,
          aid_std.invoice_distribution_id,
          aid_std.accounting_event_id,
          ''Prepayment applied belongs to different org or currency code''
            problem_description
   FROM invs,
        ap_invoices_all ai_std,
        ap_invoice_lines_all ail_std,
        ap_invoice_distributions_all aid_std,
        ap_invoices_all ai_prepay
   WHERE ai_std.invoice_id = ail_std.invoice_id
   AND   ail_std.invoice_id = aid_std.invoice_id
   AND   ail_std.line_number = aid_std.invoice_line_number
   AND   ail_std.prepay_invoice_id is not null
   AND   ail_std.line_type_lookup_code = ''PREPAY''
   AND   ail_std.prepay_invoice_id = ai_prepay.invoice_id
   AND   aid_std.posted_flag = ''N''
   AND   (ai_prepay.invoice_currency_code <> ai_std.invoice_currency_code OR
          ai_prepay.org_id <> ai_std.org_id)
   AND   ai_std.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(aid_app, aid_unap) */
          ''PRE2'',
          aid_app.invoice_id,
          aid_app.org_id,
          aid_app.invoice_line_number,
          aid_unap.invoice_distribution_id,
          aid_app.accounting_event_id,
          ''Prepayment unapplication event is less than the application event''
   FROM invs,
        ap_invoice_distributions_all aid_app,
        ap_invoice_distributions_all aid_unap
   WHERE aid_app.invoice_id = aid_unap.invoice_id
   AND   nvl(aid_app.posted_flag,''N'')   <> ''Y''
   AND   nvl(aid_unap.posted_flag,''N'')  <>''Y''
   AND   aid_app.reversal_flag = ''Y''
   AND   aid_unap.reversal_flag = ''Y''
   AND   aid_app.prepay_distribution_id is not null
   AND   aid_unap.prepay_distribution_id is not null
   AND   aid_unap.parent_reversal_id is not null
   AND   aid_unap.parent_reversal_id = aid_app.invoice_distribution_id
   AND   aid_unap.accounting_event_id < aid_app.accounting_event_id
   AND   aid_app.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, ail) */
          ''PRE3'' corruption_type,
          ai.invoice_id,
          ai.org_id,
          ail.line_number,
          NULL,
          NULL,
          ''No data in ZX_DET_LINE_FACTORS for prepay invoice''
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = ail.invoice_id
   AND   ai.org_id = ail.org_id
   AND   ai.cancelled_date is null
   AND   ai.cancelled_by is null
   AND   ai.historical_flag is null
   AND   ai.invoice_type_lookup_code IN (''PREPAYMENT'')
   AND   ail.line_type_lookup_code NOT IN (''TAX'', ''AWT'')
   AND   ail.tax_already_calculated_flag is null
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM zx_lines_det_factors
           WHERE application_id = 200
           AND   entity_code = ''AP_INVOICES''
           AND   trx_id = ail.invoice_id
           AND   trx_line_id = line_number)
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_distributions_all aid
           WHERE ail.invoice_id = aid.invoice_id
           AND   ail.line_number = aid.invoice_line_number
           AND   ail.org_id = aid.org_id
              AND   aid.MATCH_STATUS_FLAG = ''A'')',
      p_title                  => 'MGD-249',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Various invoice prepay related issues are addressed. See problem description for each row, and see note 1489862.1 for a description of all issues covered.<br/><strong>Impact Area(s): </strong>Prepay Application',
      p_solution               => '<strong>Solution GDF: </strong>21497508</br><strong>Note: </strong>[1489862/KB611407]</br><strong>Script Name: </strong>ap_one_off_scripts_sel.sql Prepayment</br></br>Apply the GDF patch following the instructions provided in [1489862/KB611407]  <br><br>
<b>NOTE:</b> Ensure when running ap_one_off_scripts_sel.sql that you provide <b>PREPAY</b> when prompted to enter the <b>Component Value</b> parameter.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '16'
      );
   l_info.delete;
debug('end add_signature: 249');



debug('begin add_signature: 250');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'EBTax, Invoice Cancellation, Validation Selection';
   l_info('bug_number'):= '23728207';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1152123.1';
   l_info('problem'):= 'Tax lines contain invalid value combinations for record_type_code and historical_flag, taxable_basis_formula and manually_entered_flag, or adjusted_doc_trx_level_type and applied_from_trx_level_type';
   l_info('solution'):= 'Apply the GDF patch 23728207 following the instructions provided in Doc ID 1152123.1 Pattern #1, #8 or #9.';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3764',
      p_sig_id                 => '250',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(l) */
          l.trx_id invoice_id,
          l.adjusted_doc_application_id,
          l.adjusted_doc_trx_level_type,
          l.applied_from_application_id,
          l.applied_from_trx_level_type,
          l.taxable_basis_formula,
          l.manually_entered_flag,
          l.tax_calculation_formula,
          l.record_type_code,
          l.historical_flag
   FROM (
          ##$$IVIEW$$##
        ) invs,
          zx_lines l
   WHERE l.trx_id = invs.invoice_id
   AND   l.application_id = 200
   AND   l.entity_code = ''AP_INVOICES''
   AND   l.event_class_code IN (''STANDARD INVOICES'',
           ''PREPAYMENT INVOICES'',''EXPENSE REPORTS'')
   AND   ((nvl2(l.adjusted_doc_application_id, 1, 2 ) <>
           nvl2(l.adjusted_doc_trx_level_type, 1, 2 )) OR
          (nvl2(l.applied_from_application_id, 1, 2 ) <>
           nvl2(l.applied_from_trx_level_type, 1, 2 )) OR
          (( l.manually_entered_flag = ''Y'' AND
             nvl(l.taxable_basis_formula,''#!X!#'') <> ''PRORATED_TB'' AND
             l.tax_provider_id is null) OR
           (l.taxable_basis_formula is null AND
            l.tax_provider_id is null) OR
           (l.taxable_basis_formula is not null AND
            l.tax_provider_id is not null)) OR
          (l.tax_calculation_formula is null AND
           l.tax_provider_id is null) OR
          (l.tax_calculation_formula is not null AND
           l.tax_provider_id is not null) OR
          ((nvl(l.historical_flag,''N'') = ''Y'' AND
            l.record_type_code <> ''MIGRATED'') OR
           (nvl(l.historical_flag,''N'') = ''N'' AND
            l.record_type_code <> ''ETAX_CREATED'')))',
      p_title                  => 'MGD-250',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Tax lines contain invalid value combinations for record_type_code and historical_flag, taxable_basis_formula and manually_entered_flag, or adjusted_doc_trx_level_type and applied_from_trx_level_type<br/><strong>Impact Area(s): </strong>EBTax, Invoice Cancellation, Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>23728207</br><strong>Note: </strong>[1152123/KB723674]</br><strong>Script Name: </strong>zx_lines_mismatch_upd.sql</br></br>Apply the GDF patch {23728207} following the instructions provided in [1152123/KB723674] Pattern #1, #8 or #9.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: 250');



debug('begin add_signature: 251');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'EBTax, Invoice Cancellation, Validation Selection';
   l_info('bug_number'):= '10095488';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1152123.1';
   l_info('problem'):= 'Incorrect currency conversion attributes on historical/migrated transactions which can result in ORA-00001 unique constraint errors on ZX_LINES_SUMMARY_U1.';
   l_info('solution'):= 'Apply the GDF patch 10095488 following the instructions provided in Doc ID 1152123.1 Pattern #7.';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3925',
      p_sig_id                 => '251',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(zl) */
          zl.summary_tax_line_id,
          zl.currency_conversion_date,
          zl.currency_conversion_type,
          zl.currency_conversion_rate
   FROM (
          ##$$IVIEW$$##
        ) invs,
        zx_lines zl
   WHERE zl.record_type_code = ''MIGRATED''
   AND   zl.application_id = 200
   AND   zl.entity_code = ''AP_INVOICES''
   AND   zl.event_class_code IN (''STANDARD INVOICES'', ''PREPAYMENT INVOICES'',
           ''EXPENSE REPORTS'')
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM zx_lines_det_factors ldf
           WHERE ldf.application_id = zl.application_id
           AND   ldf.entity_code = zl.entity_code
           AND   ldf.event_class_code = zl.event_class_code
           AND   ldf.trx_id = zl.trx_id
           AND   ldf.trx_line_id = zl.trx_line_id
           AND   ldf.record_type_code = ''MIGRATED''
           AND   (nvl(ldf.currency_conversion_date,sysdate) <>
                    nvl(zl.currency_conversion_date,sysdate) OR
                  nvl(ldf.currency_conversion_type,''C'') <>
                    nvl(zl.currency_conversion_type,''C'') OR
                  nvl(ldf.currency_conversion_rate,-10) <>
                    nvl(zl.currency_conversion_rate,-10)))
   AND   zl.trx_id = invs.invoice_id',
      p_title                  => 'MGD-251',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incorrect currency conversion attributes on historical/migrated transactions which can result in ORA-00001 unique constraint errors on ZX_LINES_SUMMARY_U1.<br/><strong>Impact Area(s): </strong>EBTax, Invoice Cancellation, Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>10095488</br><strong>Note: </strong>[1152123/KB723674]</br><strong>Script Name: </strong>zx_pop_curr_lines.sql</br></br>Apply the GDF patch {10095488} following the instructions provided in [1152123/KB723674] Pattern #7.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: 251');



