debug('begin add_signature: 253');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'EBTax, Invoice Cancellation, Validation Selection';
   l_info('bug_number'):= '14317362';
