   l_info('problem'):= 'The establishment_id value is null in table zx_lines/zx_lines_summary which can result in ORA-00001 unique constraint errors on ZX_LINES_SUMMARY_U1.';
   l_info('solution'):= 'Apply the GDF patch(es) 14317362 and/or 14122718 following the instructions provided in Doc ID 1152123.1 Pattern#2.';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3914',
      p_sig_id                 => '253',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(zl) */
          zl.trx_id,
          zl.trx_line_id,
          zl.event_class_code,
          zl.tax_line_id,
          zl.summary_tax_line_id,
          etb.establishment_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        zx_lines zl,
        xle_etb_profiles etb,
        zx_party_tax_profile ptp
   WHERE zl.application_id = 200
   AND   zl.entity_code = ''AP_INVOICES''
   AND   zl.event_class_code IN (''STANDARD INVOICES'',''EXPENSE REPORTS'',
           ''PREPAYMENT INVOICES'')
   AND   zl.legal_entity_id = etb.legal_entity_id
   AND   zl.establishment_id is null
   AND   etb.main_establishment_flag = ''Y''
   AND   nvl(etb.main_effective_from, zl.trx_date) <= zl.trx_date
   AND   nvl(etb.main_effective_to, zl.trx_date) >= zl.trx_date
   AND   etb.party_id = ptp.party_id
   AND   ptp.party_type_code = ''LEGAL_ESTABLISHMENT''
   AND   zl.trx_id = invs.invoice_id',
