      p_solution               => '<strong>Solution GDF: </strong>14317362</br><strong>Note: </strong>[1152123/KB723674]</br><strong>Script Name: </strong>zx_pop_estb_id.sql</br></br>Apply the GDF patch(es) {14317362} and/or {14122718} following the instructions provided in [1152123/KB723674] Pattern#2.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
