   l_info('problem'):= 'Incorrect tax_rate stamped on tax lines and tax summary lines which can result in ORA-00001 unique constraint errors on ZX_LINES_SUMMARY_U1.';
   l_info('solution'):= 'Apply the GDF patch 14700514 following the instructions provided in Doc ID 1152123.1 Pattern #4.';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3918',
      p_sig_id                 => '254',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   ap_invoices_utility_pkg.get_approval_status (
           ai.invoice_id,
           ai.invoice_amount,
           ai.payment_status_flag,
           ai.invoice_type_lookup_code) <> ''APPROVED''
    AND   ai.cancelled_date is null
    AND   EXISTS (
            SELECT /*+first_rows(1)*/
                   zl.summary_tax_line_id
            FROM zx_lines zl
