debug('begin add_signature: 255');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Mass Additions';
   l_info('bug_number'):= '17454983';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1500241.1';
   l_info('problem'):= 'Performance degradation due to large numbers of non-asset tax distributions with asset_addition_flag set to ''U''';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1500241.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3954',
      p_sig_id                 => '255',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ ordered use_nl(ai, apid, item) */
          ''Type 1'' type,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          apid.invoice_distribution_id,
          apid.invoice_line_number,
          apid.distribution_line_number,
          apid.line_type_lookup_code
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all apid,
        ap_invoice_distributions_all item
   WHERE apid.invoice_id = ai.invoice_id
   AND   apid.assets_addition_flag = ''U''
   AND   apid.line_type_lookup_code NOT IN (''ITEM'',''ACCRUAL'')
   AND   item.assets_tracking_flag = ''N''
   AND   nvl(nvl(apid.charge_applicable_to_dist_id, apid.related_id),
           apid.corrected_invoice_dist_id) is not null
   AND   item.invoice_distribution_id =
           nvl(nvl(apid.charge_applicable_to_dist_id, apid.related_id),
           apid.corrected_invoice_dist_id)
   AND   apid.invoice_distribution_id <> item.invoice_distribution_id
   AND   apid.posted_flag = ''Y''
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, apid, item) */
          ''Type 1'' type,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          apid.invoice_distribution_id,
          apid.invoice_line_number,
          apid.distribution_line_number,
          apid.line_type_lookup_code
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all apid,
        ap_invoice_distributions_all item
   WHERE apid.invoice_id = ai.invoice_id
   AND   apid.assets_addition_flag = ''U''
   AND   apid.line_type_lookup_code NOT IN (''ITEM'',''ACCRUAL'')
   AND   item.assets_tracking_flag = ''Y''
   AND   item.assets_addition_flag = ''N''
   AND   nvl(nvl(apid.charge_applicable_to_dist_id, apid.related_id),
           apid.corrected_invoice_dist_id) is not null
   AND    item.invoice_distribution_id =
            nvl(nvl(apid.charge_applicable_to_dist_id, apid.related_id),
            apid.corrected_invoice_dist_id)
   AND   apid.invoice_distribution_id <> item.invoice_distribution_id
   AND   apid.posted_flag = ''Y''
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, apid) */
          ''Type 2'' type,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          apid.invoice_distribution_id,
          apid.invoice_line_number,
          apid.distribution_line_number,
          apid.line_type_lookup_code
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all apid
   WHERE apid.invoice_Id = ai.invoice_id
   AND   apid.assets_addition_flag = ''U''
   AND   apid.line_type_lookup_code NOT IN (''ITEM'',''ACCRUAL'')
   AND   nvl(nvl(apid.charge_applicable_to_dist_id, apid.related_id)
               , apid.corrected_invoice_dist_id ) is null
   AND   apid.posted_flag = ''Y''
   AND   apid.assets_tracking_flag = ''N''
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-255',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Performance degradation due to large numbers of non-asset tax distributions with asset_addition_flag set to ''U''<br/><strong>Impact Area(s): </strong>Mass Additions',
      p_solution               => '<strong>Solution GDF: </strong>17454983</br><strong>Note: </strong>[1500241/KB355323]</br><strong>Script Name: </strong>ap_upd_tax_asset_add_flg_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1500241/KB355323]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: 255');



debug('begin add_signature: 256');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Automatic Witholding Tax';
   l_info('bug_number'):= '14067373';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1500291.1';
   l_info('problem'):= 'AWT invoices on which proper distributions have not been created.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1500291.1';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3988',
      p_sig_id                 => '256',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_type_lookup_code,
          ai.historical_flag,
          ai.invoice_amount
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai
   WHERE ai.invoice_type_lookup_code = ''AWT''
   AND   nvl(ai.historical_flag,''N'') = ''N''
   AND   ai.invoice_amount <> (
           SELECT /*+ no_unnest */
                  nvl(sum(aid.amount),ai.invoice_amount+1)
           FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-256',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'AWT invoices on which proper distributions have not been created.<br/><strong>Impact Area(s): </strong>Automatic Witholding Tax',
      p_solution               => '<strong>Solution GDF: </strong>14067373</br><strong>Note: </strong>[1500291/KB519154]</br><strong>Script Name: </strong>ap_corr_awt_inv_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1500291/KB519154]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
