      p_solution               => '<strong>Solution GDF: </strong>14487885</br><strong>Note: </strong>[1496461/KB202425]</br><strong>Script Name: </strong>ap_missing_attributes_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1496461/KB202425]',
      p_success_msg            => '',
