debug('begin add_signature: 260');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'EBTax, Invoice Cancellation';
   l_info('bug_number'):= '17603319';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1316316.1';
   l_info('problem'):= 'Tax lines for discarded or cancelled invoice lines are not marked as canceled and have amounts assigned.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1316316.1 (Section 5)';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3886',
      p_sig_id                 => '260',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, ail, ah) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ail.line_number,
          ail.discarded_flag,
          ail.cancelled_flag
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_holds_all ah
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvL(ai.historical_flag,''N'') <> ''Y''
   AND   ai.cancelled_date is null
   AND   ah.invoice_id = ai.invoice_id
   AND   ah.hold_lookup_code IN (''DIST VARIANCE'',''LINE VARIANCE'')
   AND   ah.release_lookup_code IS NULL
   AND   ail.invoice_id = ai.invoice_id
   AND   ail.line_type_lookup_code <> ''TAX''
   AND   (nvl(ail.discarded_flag,''N'') = ''Y'' OR
          nvl(ail.cancelled_flag,''N'') = ''Y'')
   AND EXISTS (
         SELECT /*+ no_unnest */
                null
         FROM zx_lines zl
         WHERE zl.application_id = 200
         AND   zl.entity_code = ''AP_INVOICES''
         AND   zl.event_class_code IN (''STANDARD INVOICES'',
                 ''PREPAYMENT INVOICES'',''EXPENSE REPORTS'')
         AND   zl.trx_id = ai.invoice_id
         AND   zl.trx_level_type = ''LINE''
         AND   zl.trx_line_id = ail.line_number
         AND   (nvl(zl.cancel_flag,''N'') <> ''Y'' OR
                zl.tax_amt <> 0))',
      p_title                  => 'MGD-260',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Tax lines for discarded or cancelled invoice lines are not marked as canceled and have amounts assigned.<br/><strong>Impact Area(s): </strong>EBTax, Invoice Cancellation',
      p_solution               => '<strong>Solution GDF: </strong>17603319</br><strong>Note: </strong>[1316316/KB731274]</br><strong>Script Name: </strong>zx_dist_var_pop.sql Pattern 1</br></br>Apply the GDF patch following the instructions provided in [1316316/KB731274] (Section 5)</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: 260');



debug('begin add_signature: 261');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'EBTax, Invoice Holds, Validation Selection';
   l_info('bug_number'):= '17603319';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1316316.1';
   l_info('problem'):= 'Invoices on Distribution or Line Variance hold where tax line tax amount does not match the sum of the distributions.';
   l_info('solution'):= '<strong>For R12.0 and 12.1:</strong> Apply the Data Fix and Code Fix patches as detailed in [1316316.1#aref_section35] Section 5.</br>
<strong>For R12.2: </strong>Apply the patches as detailed in Doc ID 2089108.1.';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4150',
      p_sig_id                 => '261',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, ah) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ah.hold_lookup_code
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_holds_all ah
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(ai.historical_flag,''N'') <> ''Y''
   AND   ai.cancelled_date is null
   AND   ah.invoice_id = ai.invoice_id
   AND   ah.hold_lookup_code IN (''DIST VARIANCE'',''LINE VARIANCE'')
   AND   ah.release_lookup_code is null
   AND   EXISTS (
           SELECT /*+ no_unnest
                      index(zl zx_lines_n4)
                      index(zd zx_rec_nrec_dist_u2) */
                  null
           FROM zx_lines zl,
                zx_rec_nrec_dist zd
           WHERE zl.application_id = 200
           AND   zl.trx_id = ai.invoice_id
           AND   zd.tax_line_id = zl.tax_line_id
           AND   zd.application_id = zl.application_id
           AND   zd.entity_code = zl.entity_code
           AND   zd.event_class_code = zl.event_class_code
           AND   zd.trx_id = zl.trx_id
           GROUP BY zd.tax_line_id, zl.tax_amt
           HAVING zl.tax_amt <> SUM(zd.rec_nrec_tax_amt))',
      p_title                  => 'MGD-261',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices on Distribution or Line Variance hold where tax line tax amount does not match the sum of the distributions.<br/><strong>Impact Area(s): </strong>EBTax, Invoice Holds, Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>17603319</br><strong>Note: </strong>[1316316/KB731274]</br><strong>Script Name: </strong>zx_dist_var_pop.sql Pattern 2</br></br><strong>For R12.0 and 12.1:</strong> Apply the Data Fix and Code Fix patches as detailed in [1316316/KB731274#aref_section35] Section 5.</br>
<strong>For R12.2: </strong>Apply the patches as detailed in [2089108/KB418147].</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
