debug('begin add_signature: 262');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'EBTax, Invoice Holds, Validation Selection';
   l_info('bug_number'):= '17603319';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1316316.1';
   l_info('problem'):= 'Invoices on Distribution or Line Variance hold where the amount of the tax distributions in EBTax does not match the amounts in Payables.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1316316.1 (Section 5). If you are on release 12.2.X, please see instead Doc ID 2089108.1.';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3921',
      p_sig_id                 => '262',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, ah) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ah.hold_lookup_code
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_holds_all ah
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(ai.historical_flag,''N'') <> ''Y''
   AND   ai.cancelled_date is null
   AND   ah.invoice_id = ai.invoice_id
   AND   ah.hold_lookup_code IN (''DIST VARIANCE'',''LINE VARIANCE'')
   AND   ah.release_lookup_code IS NULL
   AND   (EXISTS (
            SELECT /*+ no_unnest leading(aid) index(zd zx_rec_nrec_dist_u1) */
                   null
            FROM ap_invoice_distributions_all aid,
                 zx_rec_nrec_dist zd
            WHERE aid.invoice_id = ai.invoice_id
            AND   aid.line_type_lookup_code IN (''REC_TAX'',''NONREC_TAX'',
                    ''TRV'',''TIPV'',''TERV'')
            AND   aid.detail_tax_dist_id is not null
            AND   zd.rec_nrec_tax_dist_id = aid.detail_tax_dist_id
            GROUP BY aid.detail_tax_dist_id, zd.rec_nrec_tax_amt
            HAVING zd.rec_nrec_tax_amt <> sum(aid.amount)) OR
          EXISTS (
            SELECT /*+ no_unnest leading(asad) index(zd zx_rec_nrec_dist_u1) */
                   null
            FROM ap_self_assessed_tax_dist_all asad,
                 zx_rec_nrec_dist zd
            WHERE asad.invoice_id = ai.invoice_id
            AND   asad.line_type_lookup_code IN (''REC_TAX'',''NONREC_TAX'')
            AND   asad.detail_tax_dist_id is not null
            AND   zd.rec_nrec_tax_dist_id = asad.detail_tax_dist_id
            AND   zd.rec_nrec_tax_amt <> asad.amount))',
      p_title                  => 'MGD-262',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices on Distribution or Line Variance hold where the amount of the tax distributions in EBTax does not match the amounts in Payables.<br/><strong>Impact Area(s): </strong>EBTax, Invoice Holds, Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>17603319</br><strong>Note: </strong>[1316316/KB731274]</br><strong>Script Name: </strong>zx_dist_var_pop.sql Pattern 3</br></br>Apply the GDF patch following the instructions provided in [1316316/KB731274] (Section 5). If you are on release 12.2.X, please see instead [2089108/KB418147].</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: 262');



