      p_solution               => '<strong>Solution GDF: </strong>12644252</br><strong>Note: </strong>[1316316/KB731274]</br><strong>Script Name: </strong>zx_frz_mig_tax_dist.sql</br></br>Apply the generic data fix patch {12644252} as described in [1316316/KB731274] Section 6.',
      p_success_msg            => '',
