debug('begin add_signature: 271');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Archive/Purge';
   l_info('bug_number'):= '17500004';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1536344.1';
   l_info('problem'):= 'Invoice line and accounting data from 11i have last updated dates marked with the upgrade date preventing the purge of information based on dates prior to the upgrade.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1536344.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3808',
      p_sig_id                 => '271',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ ordered use_nl(ail, aid) */
          ''Invoice'' trx_type,
          ail.invoice_id trx_id,
          ail.line_number invoice_line_number,
          null entity_id,
          max(ail.last_update_date) last_update_date,
          max(nvl(aid.last_update_date,aid.creation_date)) correct_upd_date
   FROM invs,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid
   WHERE ail.invoice_id = invs.invoice_id
   AND   ail.historical_flag = ''Y''
   AND   aid.historical_flag = ''Y''
   AND   aid.invoice_id = ail.invoice_id
   AND   ail.line_number = aid.invoice_line_number
   GROUP BY ail.invoice_id, ail.line_number
   HAVING   max(ail.last_update_date) <>
              max(nvl(aid.last_update_date,aid.creation_date))
   UNION
   SELECT /*+ ordered use_nl(aid, xe, aae) */
          ''Event'',
          xe.event_id,
          null,
          xe.entity_id,
          xe.last_update_date,
          aae.last_update_date
   FROM invs,
        ap_invoice_distributions_all aid,
        xla_events xe,
        ap_accounting_events_all aae
   WHERE aid.invoice_id = invs.invoice_id
   AND   xe.event_id = aid.accounting_event_id
   AND   xe.application_id = 200
   AND   nvl(xe.upg_batch_id,-9999) <> -9999
   AND   xe.event_id = aae.accounting_event_id
   AND   xe.last_update_date <> aae.last_update_date',
      p_title                  => 'MGD-271',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice line and accounting data from 11i have last updated dates marked with the upgrade date preventing the purge of information based on dates prior to the upgrade.<br/><strong>Impact Area(s): </strong>Archive/Purge',
      p_solution               => '<strong>Solution GDF: </strong>17500004</br><strong>Note: </strong>[1536344/KB792173]</br><strong>Script Name: </strong>ap_upg_incor_lstupddate_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1536344/KB792173]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: 271');



debug('begin add_signature: 274');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Drilldown';
   l_info('bug_number'):= '13783741';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1445563.1';
   l_info('problem'):= 'The value for GL_SL_LINK is missing on upgraded accounting lines which are transferred to GL.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1445563.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3997',
      p_sig_id                 => '274',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, xte, xah, xal, gir) index(gir gl_import_references_n3) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          xah.ae_header_id ,
          xal.ae_line_num,
          xah.application_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah,
        xla_ae_lines xal,
        gl_import_references gir,
        gl_je_headers gjh,
        gl_je_batches gjb
   WHERE upper(gjh.je_source) = ''PAYABLES''
   AND   gjh.ledger_id = xah.ledger_id
   AND   gjb.je_batch_id = gjh.je_batch_id
   AND   gjh.je_header_id = gir.je_header_id
   AND   gjh.je_batch_id = gir.je_batch_id
   AND   gir.gl_sl_link_ID is null
   AND   gjh.je_from_sla_flag = ''Y''
   AND   gir.reference_5 = to_char(xah.entity_id)
   AND   gir.reference_6 = to_char(xah.event_id)
   AND   gir.reference_7 = to_char(xah.ae_header_id)
   AND   gir.reference_8 = to_char(xal.ae_line_num)
   AND   xal.ae_header_id = xah.ae_header_id
   AND   xal.application_id = xah.application_id
   AND   xah.entity_id = xte.entity_id
   AND   xah.application_id = xte.application_id
   AND   xte.application_id = 200
   AND   xte.ledger_id = ai.set_of_books_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-274',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The value for GL_SL_LINK is missing on upgraded accounting lines which are transferred to GL.<br/><strong>Impact Area(s): </strong>Drilldown',
      p_solution               => '<strong>Solution GDF: </strong>13783741</br><strong>Note: </strong>[1445563/KB464222]</br><strong>Script Name: </strong>xla_transR12_xdl_miss_sel.sql Invoice</br></br>Apply the GDF patch following the instructions provided in [1445563/KB464222]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 274');



debug('begin add_signature: 276');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Prepay Application';
   l_info('bug_number'):= '18062771';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1540400.1';
   l_info('problem'):= 'Upgraded prepayment invoices that were fully applied on standard invoices, appear as available.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1540400.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3915',
      p_sig_id                 => '276',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ ordered use_nl(ai, aid) */
          ai.invoice_num,
          ai.invoice_id,
          ai.invoice_amount,
          aid.invoice_distribution_id
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.historical_flag = ''Y''
   AND   aid.historical_flag = ''Y''
   AND   ai.invoice_type_lookup_code = ''PREPAYMENT''
   AND   ai.cancelled_Date is null
   AND   ai.payment_status_flag = ''Y''
   AND   ai.invoice_id = aid.invoice_id
   AND   (aid.prepay_amount_remaining is null OR
        abs(aid.prepay_amount_remaining) > 0)
   AND   ai.invoice_amount = 0
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid) */
          ai.invoice_num,
          ai.invoice_id,
          ai.invoice_amount,
          aid.invoice_distribution_id
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid
  WHERE ai.invoice_id = invs.invoice_id
  AND   ai.historical_flag = ''Y''
  AND   aid.historical_flag = ''Y''
  AND   ai.invoice_type_lookup_code = ''PREPAYMENT''
  AND   ai.cancelled_Date is null
  AND   ai.payment_status_flag = ''Y''
  AND   aid.line_type_lookup_code <> ''AWT''
  AND   ai.invoice_id = aid.invoice_id
  AND   nvl(aid.reversal_flag,''N'') <> ''Y''
  AND   (aid.prepay_amount_remaining is null OR
         abs(aid.prepay_amount_remaining) > 0)
  AND   ai.invoice_amount > 0
  AND   EXISTS (
          SELECT /*+ no_unnest */ ''1'' prepay_applied_completely
          FROM ap_invoice_lines_all ail,
               ap_invoices_all ai2
          WHERE ail.prepay_invoice_id = ai.invoice_id
          AND   ail.amount < 0
          AND   nvl(ail.discarded_flag, ''N'') = ''N''
          AND   ail.line_type_lookup_code = ''PREPAY''
          AND   ai2.invoice_id = ail.invoice_id
          AND   ai2.invoice_type_lookup_code NOT IN
                  (''PREPAYMENT'', ''CREDIT'', ''DEBIT'')
          HAVING nvl(sum((-1) * (ail.amount - nvl(ail.included_tax_amount, 0)) +
                   nvl(nullif((-1) * (nvl(ail.total_rec_tax_amount, 0) +
                     nvl(ail.total_nrec_tax_amount, 0)), 0), 0)), 0)
                    = ai.invoice_amount)',
      p_title                  => 'MGD-276',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Upgraded prepayment invoices that were fully applied on standard invoices, appear as available.<br/><strong>Impact Area(s): </strong>Prepay Application',
      p_solution               => '<strong>Solution GDF: </strong>18062771</br><strong>Note: </strong>[1540400/KB428894]</br><strong>Script Name: </strong>ap_neg_amt_dist_ppay_11i_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1540400/KB428894]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: 276');



