      p_problem_descr          => 'The payment method code is null on the payment schedule record for an invoice.<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>17400717</br><strong>Note: </strong>[1546680/KB730094]</br><strong>Script Name: </strong>ap_pay_met_code_null_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1546680/KB730094]',
      p_success_msg            => '',
