debug('begin add_signature: 278');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Prepay Application';
   l_info('bug_number'):= '17499987';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1546685.1';
   l_info('problem'):= 'The amount paid is negative after a prepay application and unapplication.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1546685.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4031',
      p_sig_id                 => '278',
      p_sig_sql                => 'SELECT /*+ leading(invs) use_nl(ai) */
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.amount_paid,
          ai.invoice_amount,
          ai.invoice_type_lookup_code,
          ai.vendor_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_type_lookup_code = ''STANDARD''
   AND   nvl(ai.historical_flag,''N'') = ''N''
   AND   sign(ai.amount_paid) = -1
   AND   nvl(ai.payment_status_flag,''N'') = ''N''
   AND   ai.invoice_currency_code = ai.payment_currency_code
   AND   EXISTS (
           SELECT 1 FROM ap_payment_schedules_all aps
           WHERE aps.invoice_id = ai.invoice_id
           AND   nvl(aps.payment_status_flag,''N'') = ''N''
           HAVING sum(aps.amount_remaining) = ai.invoice_amount)
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_lines_all ail
           WHERE ail.invoice_id = ai.invoice_id
           AND   ail.line_type_lookup_code = ''PREPAY''
           HAVING sum(ail.amount) = 0)',
      p_title                  => 'MGD-278',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The amount paid is negative after a prepay application and unapplication.<br/><strong>Impact Area(s): </strong>Prepay Application',
      p_solution               => '<strong>Solution GDF: </strong>17499987</br><strong>Note: </strong>[1546685/KB214459]</br><strong>Script Name: </strong>ap_ppay_unap_cau_neg_pd_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1546685/KB214459]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 278');



debug('begin add_signature: 296');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '20317799';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2149693.1';
   l_info('problem'):= 'Prepayment unapplication events will not account because the prepay application distributions for the corresponding application have been deleted and recreated after they were accounted. This causes the line level reversal for the prepayment unapplication to fail to account.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2149693.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4029',
      p_sig_id                 => '296',
      p_sig_sql                => 'SELECT DISTINCT
         phu.invoice_id,
         phu.prepay_invoice_id,
         phu.accounting_event_id,
         phu.prepay_history_id,
         pha.accounting_event_id app_acct_event_id,
         pha.prepay_history_id app_prepay_hist_id
    FROM (
           ##$$IVIEW$$##
         ) invs,
         ap_prepay_history_all pha,
         ap_prepay_history_all phu,
         ap_prepay_app_dists   ada,
         ap_prepay_app_dists   adu,
         xla_events xea,
         xla_events xeu
   WHERE pha.invoice_id = invs.invoice_id
   AND   phu.prepay_history_id = adu.prepay_history_id
   AND   pha.prepay_history_id = ada.prepay_history_id
   AND   phu.invoice_id = pha.invoice_id
   AND   phu.invoice_line_number = pha.invoice_line_number
   AND   pha.transaction_type = ''PREPAYMENT APPLIED''
   AND   phu.transaction_type = ''PREPAYMENT UNAPPLIED''
   AND   pha.accounting_event_id = xea.event_id
   AND   xea.application_id = 200
   AND   phu.accounting_event_id = xeu.event_id
   AND   xeu.application_id = 200
   AND   xea.event_status_code = ''P''
   AND   xeu.event_status_code <> ''P''
   AND   xea.event_type_code = ''PREPAYMENT APPLIED''
   AND   xeu.event_type_code = ''PREPAYMENT UNAPPLIED''
   AND   adu.reversed_prepay_app_dist_id = ada.prepay_app_dist_id
   AND   NOT EXISTS (
           SELECT 1 FROM xla_distribution_links xdl
           WHERE xdl.application_id = 200
           AND   xdl.source_distribution_type = ''AP_PREPAY''
           AND   xdl.source_distribution_id_num_1 = ada.prepay_app_dist_id
           AND   xdl.event_id = ada.accounting_event_id)',
      p_title                  => 'MGD-296',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Prepayment unapplication events will not account because the prepay application distributions for the corresponding application have been deleted and recreated after they were accounted. This causes the line level reversal for the prepayment unapplication to fail to account.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>20317799</br><strong>Note: </strong>[2149693/KB188116]</br><strong>Script Name: </strong>ap_prep_unap_apd_invld_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2149693/KB188116]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: 296');



debug('begin add_signature: 297');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '20317621';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2150690.1';
   l_info('problem'):= 'Prepay event accounting lines are missing descriptions though these are present on the distributions.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2150690.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4010',
      p_sig_id                 => '297',
      p_sig_sql                => 'SELECT DISTINCT
          xah.event_id,
          xah.event_type_code,
          xal.ae_header_id,
          xal.ae_line_num,
          xal.accounting_class_code,
          xal.description accounting_line_desc,
          xal.entered_dr,
          xal.entered_cr,
          xal.accounted_dr,
          xal.accounted_cr,
          aid.invoice_id,
          aid.invoice_distribution_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.base_amount,
          aid.description inv_dist_desc,
          xah.upg_batch_id,
          aid.historical_flag
    FROM (
          ##$$IVIEW$$##
         ) invs,
         ap_invoice_distributions_all aid,
         xla_ae_lines xal,
         xla_ae_headers xah,
         xla_distribution_links xdl,
         ap_prepay_app_dists apad
   WHERE aid.invoice_id = invs.invoice_id
   AND   xal.application_id = 200
   AND   xal.accounting_class_code IN (''PREPAID_EXPENSE'',''RTAX'',''NRTAX'')
   AND   xal.description is null
   AND   xah.application_id = xal.application_id
   AND   xah.ae_header_id = xal.ae_header_id
   AND   xah.event_type_code IN (''PREPAYMENT APPLIED'',
           ''PREPAYMENT UNAPPLIED'',''PREPAYMENT APPLICATION ADJ'')
   AND   xal.ae_header_id = xdl.ae_header_id
   AND   xal.ae_line_num = xdl.ae_line_num
   AND   xdl.application_id = xal.application_id
   AND   xdl.source_distribution_type = ''AP_PREPAY''
   AND   xdl.source_distribution_id_num_1 = apad.prepay_app_dist_id
   AND   apad.prepay_app_distribution_id = aid.invoice_distribution_id
   AND   decode(xal.accounting_class_code
               , ''PREPAID_EXPENSE'',''PREPAY''
               , ''RTAX'',''REC_TAX''
               , ''NRTAX'',''NONREC_TAX'' ) = aid.line_type_lookup_code
   AND   aid.description is not null
   ORDER BY xah.event_id, xal.ae_header_id, xal.ae_line_num',
      p_title                  => 'MGD-297',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Prepay event accounting lines are missing descriptions though these are present on the distributions.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>20317621</br><strong>Note: </strong>[2150690/KB745894]</br><strong>Script Name: </strong>ap_prep_xal_no_desc_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2150690/KB745894]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: 297');



debug('begin add_signature: 302');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'PO Matching';
   l_info('bug_number'):= '24828024';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1906407.1';
   l_info('problem'):= 'The values of match_type and dist_match_type are not in sync between invoice lines and distributions.  This results in issues with quantities and amounts billed which can cause issues when matching or cancelling the invoice.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1906407.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4014',
      p_sig_id                 => '302',
      p_sig_sql                => 'WITH invs AS (
          ##$$MIVIEW$$##
   )
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          pll.match_option,
          pll.matching_basis,
          ail.line_type_lookup_code,
          ail.po_line_location_id,
          ail.rcv_transaction_id,
          ail.match_type line_match_type,
          aid.dist_match_type,
          ail.line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          ''NON SYNC'' type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid,
        po_line_locations_all pll
   WHERE ai.invoice_id = invs.invoice_id
   AND   ail.invoice_id = ai.invoice_id
   AND   aid.invoice_id = ail.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   ail.corrected_inv_id is null
   AND   ail.corrected_line_number is null
   AND   ail.po_line_location_id is not null
   AND   ail.po_line_location_id = pll.line_location_id
   AND   (nvl(ail.match_type,''NOT_MATCHED'') <>
            nvl(aid.dist_match_type,''NOT_MATCHED'') OR
          nvl(ail.match_type,''NOT_MATCHED'') = ''NOT_MATCHED'')
   AND   ail.line_type_lookup_code IN (''ITEM'',
           ''FREIGHT'', ''MISCELLANEOUS'')
   AND   ((aid.line_type_lookup_code IN (''ITEM'',
            ''ACCRUAL'',''FREIGHT'',''MISCELLANEOUS'') AND
           nvl(ail.match_type,''NOT_MATCHED'') <>
            nvl(aid.dist_match_type,''NOT_MATCHED'')) OR
          nvl(ail.match_type,''XXX'') <> (
            CASE
              WHEN(ail.rcv_transaction_id is not null AND
                   pll.matching_basis =''QUANTITY'' AND
                   ail.line_type_lookup_code=''ITEM'') THEN
                ''ITEM_TO_RECEIPT''
              WHEN(ail.rcv_transaction_id is not null AND
                   pll.matching_basis =''AMOUNT'' AND
                   ail.line_type_lookup_code=''ITEM'')   THEN
                ''ITEM_TO_SERVICE_RECEIPT''
              WHEN(ail.rcv_transaction_id is not null AND
                   ail.line_type_lookup_code in (''FREIGHT'',''MISCELLANEOUS'')) THEN
                ''OTHER_TO_RECEIPT''
              WHEN(ail.rcv_transaction_id is null AND
                   ail.po_line_location_id is not null AND
                   pll.matching_basis =''QUANTITY'' AND
                   ail.line_type_lookup_code=''ITEM'') THEN
                ''ITEM_TO_PO''
              WHEN(ail.rcv_transaction_id is null AND
                   ail.po_line_location_id is not null AND
                   pll.matching_basis =''AMOUNT'' AND
                   ail.line_type_lookup_code=''ITEM'') THEN
                ''ITEM_TO_SERVICE_PO''
              WHEN(ail.rcv_transaction_id is null AND
                   ail.po_line_location_id is null) THEN
                ''NOT_MATCHED''
            END))
   UNION
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          null match_option,
          null matching_basis,
          ail.line_type_lookup_code,
          ail.po_line_location_id,
          ail.rcv_transaction_id,
          ail.match_type,
          aid.dist_match_type,
          ail.line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          ''NON MATCHED''
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = ail.invoice_id
   AND   ail.invoice_id = aid.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   ail.match_type IN (''ITEM_TO_PO'',''ITEM_TO_RECEIPT'')
   AND   nvl(ail.discarded_flag,''N'') <> ''Y''
   AND   nvl(ail.cancelled_flag,''N'') <> ''Y''
   AND   ail.po_header_id is null
   AND   ail.po_line_id is null
   AND   ail.po_line_location_id is null
   AND   ail.po_distribution_id is null
   AND   ail.rcv_transaction_id is null
   AND   ail.corrected_inv_id  is null
   AND   ail.corrected_line_number is null
   UNION
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          null,
          null,
          ail.line_type_lookup_code,
          ail.po_line_location_id,
          ail.rcv_transaction_id,
          ail.match_type,
          aid.dist_match_type,
          ail.line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          ''NULL VALUED''
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = ail.invoice_id
   AND   ail.invoice_id = aid.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   aid.line_type_lookup_code IN (''ITEM'', ''FREIGHT'',
           ''MISCELLANEOUS'')
   AND   aid.po_distribution_id is null
   AND   aid.rcv_transaction_id is null
   AND   aid.dist_match_type is null
   AND   ail.line_source IN (''MANUAL LINE ENTRY'', ''IMPORTED'')
   AND   ail.po_header_id is null
   AND   ail.po_line_id is null
   AND   ail.po_line_location_id is null',
      p_title                  => 'MGD-302',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The values of match_type and dist_match_type are not in sync between invoice lines and distributions.  This results in issues with quantities and amounts billed which can cause issues when matching or cancelling the invoice.<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Solution GDF: </strong>24828024</br><strong>Note: </strong>[1906407/KB318210]</br><strong>Script Name: </strong>ap_sync_match_type_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1906407/KB318210]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: 302');



debug('begin add_signature: 303');
