      p_solution               => '<strong>Solution GDF: </strong>18847390</br><strong>Note: </strong>[1919121/KB578546]</br><strong>Script Name: </strong>ap_trans_flg_ipv_rev_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1919121/KB578546]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
