debug('begin add_signature: 316');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '22733950';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2157173.1';
   l_info('problem'):= 'Orphan prepay application or unapplication events in ap_prepay_history_all which do not exist in xla_events or ap_invoice_distributions_all.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2157173.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4134',
      p_sig_id                 => '316',
      p_sig_sql                => 'SELECT aph.invoice_id,
          aph.org_id,
          aph.invoice_line_number,
          aph.prepay_invoice_id,
          aph.prepay_line_num,
          aph.accounting_date,
          aph.historical_flag,
          aph.accounting_event_id,
          aph.invoice_adjustment_event_id,
          aph.related_prepay_app_event_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_prepay_history_all aph
   WHERE aph.invoice_id = invs.invoice_id
   AND   aph.posted_flag <> ''Y''
   AND   aph.transaction_type IN (''PREPAYMENT APPLIED'', ''PREPAYMENT UNAPPLIED'')
   AND   NOT EXISTS (
           SELECT 1 FROM xla_events xe
           WHERE application_id = 200
           AND xe.event_id = aph.accounting_event_id
           AND xe.event_status_code = ''P'')
   AND   NOT EXISTS (
           SELECT 1 FROM xla_events xe
           WHERE xe.application_id = 200
           AND xe.event_id = aph.bc_event_id
           AND xe.event_status_code = ''P'')
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.accounting_event_id = aph.accounting_event_id)
   AND   NOT EXISTS (
           SELECT 1
           FROM ap_invoice_lines_all ail,
                ap_invoice_distributions_all aid
           WHERE ail.invoice_id = aph.invoice_id
           AND ail.line_number = aph.invoice_line_number
           AND ail.line_type_lookup_code = ''PREPAY''
           AND ail.invoice_id = aid.invoice_id
           AND ail.line_number = aid.invoice_line_number)',
      p_title                  => 'MGD-316',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphan prepay application or unapplication events in ap_prepay_history_all which do not exist in xla_events or ap_invoice_distributions_all.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>22733950</br><strong>Note: </strong>[2157173/KB371288]</br><strong>Script Name: </strong>ap_orphan_prep_events_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2157173/KB371288]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 316');



debug('begin add_signature: 317');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '18964372';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1336255.1';
   l_info('problem'):= 'Incorrect invoice event types for upgraded prepayment, credit memo, and debit memo invoices resulting in accounting error due to imbalanced journal entry in the subledger.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1336255.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4009',
      p_sig_id                 => '317',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ ordered use_nl(ai, xte, xe) */
          xe.event_id,
          xe.event_type_code,
          decode(xe.event_type_code,
            ''INVOICE VALIDATED'', decode(ai.invoice_type_lookup_code,
                                   ''DEBIT'', ''DEBIT MEMO VALIDATED'',
                                   ''CREDIT'', ''CREDIT MEMO VALIDATED'',
                                   ''PREPAYMENT'',''PREPAYMENT VALIDATED'',
                                   xe.event_type_code),
            ''INVOICE ADJUSTED'',  decode(ai.invoice_type_lookup_code,
                                   ''DEBIT'', ''DEBIT MEMO ADJUSTED'',
                                   ''CREDIT'', ''CREDIT MEMO ADJUSTED'',
                                   ''PREPAYMENT'', ''PREPAYMENT ADJUSTED'',
                                   xe.event_type_code),
            ''INVOICE CANCELLED'', decode(ai.invoice_type_lookup_code,
                                   ''DEBIT'', ''DEBIT MEMO CANCELLED'',
                                   ''CREDIT'', ''CREDIT MEMO CANCELLED'',
                                   ''PREPAYMENT'',''PREPAYMENT CANCELLED'',
                                   xe.event_type_code),
            xe.event_type_code) proposed_event_type,
          xe.event_date,
          xe.entity_id,
          xe.event_status_code,
          xe.process_status_code,
          xe.upg_batch_id,
          to_char(null) old_event_type,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount,
          ai.invoice_type_lookup_code,
          ai.org_id,
          ai.set_of_books_id
   FROM invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_events xe
   WHERE ai.invoice_id = invs.invoice_id
   AND   xte.application_id = 200
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   nvl(xte.security_id_int_1, -99) = ai.org_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   ai.invoice_type_lookup_code IN (''CREDIT'', ''DEBIT'', ''PREPAYMENT'')
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.application_id = 200
   AND   xe.entity_id = xte.entity_id
   AND   xe.event_type_code LIKE ''INVOICE%''
   AND   xe.application_id = 200
   AND   xe.upg_batch_id > 0
   UNION ALL
   SELECT /*+ ordered use_nl(ai, xte, xe, aae) */
          xe.event_id,
          xe.event_type_code,
          decode(ai.invoice_type_lookup_code,
            ''DEBIT'', ''DEBIT MEMO ADJUSTED'',
            ''CREDIT'', ''CREDIT MEMO ADJUSTED'',
            ''PREPAYMENT'', ''PREPAYMENT ADJUSTED'',
            ''INVOICE ADJUSTED'') proposed_event_type,
          xe.event_date,
          xe.entity_id,
          xe.event_status_code,
          xe.process_status_code,
          xe.upg_batch_id,
          aae.event_type_code old_event_type,
          ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount,
          ai.invoice_type_lookup_code,
          ai.org_id,
          ai.set_of_books_id
   FROM invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_events xe,
        ap_accounting_events_all aae
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   nvl(xte.security_id_int_1, -99) = ai.org_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.application_id = 200
   AND   xe.entity_id = xte.entity_id
   AND   xe.event_type_code not LIKE ''%ADJUSTED%''
   AND   aae.event_type_code LIKE ''%ADJUST%''
   AND   xe.event_id = aae.accounting_event_id
   AND   xe.application_id = 200
   AND   xe.upg_batch_id > 0',
      p_title                  => 'MGD-317',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incorrect invoice event types for upgraded prepayment, credit memo, and debit memo invoices resulting in accounting error due to imbalanced journal entry in the subledger.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>18964372</br><strong>Note: </strong>[1336255/KB224612]</br><strong>Script Name: </strong>ApIncorrEventTypeSel.sql</br></br>Apply the GDF patch following the instructions provided in [1336255/KB224612]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 317');



