debug('begin add_signature: 347');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Discard';
   l_info('bug_number'):= '22733893';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2157175.1';
   l_info('problem'):= 'Discarded or cancelled invoice lines have the generate_dists flag = Y causing errors when trying to view distributions.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2157175.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4088',
      p_sig_id                 => '347',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ail.line_number,
          ail.generate_dists,
          ail.discarded_flag,
          ail.cancelled_flag,
          ail.amount
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail
   WHERE ai.invoice_id = invs.invoice_id
   AND   ail.invoice_id = ai.invoice_id
   AND   (ail.discarded_flag = ''Y'' OR
          ail.cancelled_flag = ''Y'')
   AND   ail.generate_dists = ''Y''
   AND   ail.amount = 0
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ail.invoice_id
           AND   aid.invoice_line_number = ail.line_number)
   AND   ail.amount = (
           SELECT sum(aid.amount) FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ail.invoice_id
           AND   aid.invoice_line_number = ail.line_number)',
      p_title                  => 'MGD-347',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Discarded or cancelled invoice lines have the generate_dists flag = Y causing errors when trying to view distributions.<br/><strong>Impact Area(s): </strong>Invoice Discard',
      p_solution               => '<strong>Solution GDF: </strong>22733893</br><strong>Note: </strong>[2157175/KB726324]</br><strong>Script Name: </strong>ap_wrong_gen_dists_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2157175/KB726324]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
