debug('end add_signature: 347');



debug('begin add_signature: 350');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Automatic Witholding Tax';
   l_info('bug_number'):= '20312812';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2001007.1';
   l_info('problem'):= 'Payment Withholding Tax Group(pay_awt_group_id) is populated on the invoice header but not on matched distributions for the invoice causing AWT not to calculate properly.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2001007.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4091',
      p_sig_id                 => '350',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
SELECT
    aid.invoice_id,
    aid.invoice_line_number,
    aid.distribution_line_number,
    aid.amount,
    ''Paid'' payment_status
FROM
    invs,
    ap_invoices_all              ai,
    ap_invoice_distributions_all aid,
    ap_system_parameters_all     asp
WHERE
        ai.invoice_id = invs.invoice_id
    AND ai.historical_flag IS NULL
    AND ai.org_id = asp.org_id
    AND asp.allow_awt_flag = ''Y''
    AND asp.create_awt_dists_type = ''PAYMENT''
    AND ai.invoice_id = aid.invoice_id
    AND ai.pay_awt_group_id IS NOT NULL
    AND ai.awt_flag IS NULL
    AND aid.pay_awt_group_id IS NULL
    AND aid.po_distribution_id IS NOT NULL
    AND EXISTS (
        SELECT
            1
        FROM
            ap_invoice_payments_all aip
        WHERE
                aip.invoice_id = ai.invoice_id
            AND aip.reversal_inv_pmt_id IS NULL
            AND nvl(aip.reversal_flag, ''N'') = ''N''
    )
    AND NOT EXISTS (
        SELECT
            ''manual AWT lines''
        FROM
            ap_invoice_distributions_all aid2
        WHERE
                aid2.invoice_id = ai.invoice_id
            AND aid2.line_type_lookup_code = ''AWT''
            AND aid2.awt_flag IN ( ''M'', ''O'' )
    )
    AND ( asp.awt_include_tax_amt = ''Y''
          OR ( asp.awt_include_tax_amt = ''N''
               AND aid.line_type_lookup_code NOT IN ( ''NONREC_TAX'', ''REC_TAX'', ''RETROTAX'', ''TRV'', ''TIPV'',
                                                      ''TERV'' ) ) )
UNION ALL
SELECT
    aid.invoice_id,
    aid.invoice_line_number,
    aid.distribution_line_number,
    aid.amount,
    ''Voided'' payment_status
FROM
    invs,
    ap_invoices_all              ai,
    ap_invoice_distributions_all aid,
    ap_system_parameters_all     asp
WHERE
        ai.invoice_id = invs.invoice_id
    AND ai.historical_flag IS NULL
    AND ai.org_id = asp.org_id
    AND asp.allow_awt_flag = ''Y''
    AND asp.create_awt_dists_type = ''PAYMENT''
    AND ai.invoice_id = aid.invoice_id
    AND ai.pay_awt_group_id IS NOT NULL
    AND ai.awt_flag IS NULL
    AND aid.pay_awt_group_id IS NULL
    AND aid.po_distribution_id IS NOT NULL
    AND NOT EXISTS (
        SELECT
            1
        FROM
            ap_invoice_payments_all aip
        WHERE
                aip.invoice_id = ai.invoice_id
            AND aip.reversal_inv_pmt_id IS NULL
            AND nvl(aip.reversal_flag, ''N'') = ''N''
    )
    AND NOT EXISTS (
        SELECT
            ''manual awt lines exist''
        FROM
            ap_invoice_distributions_all aid2
        WHERE
                aid2.invoice_id = ai.invoice_id
            AND aid2.line_type_lookup_code = ''AWT''
            AND aid2.awt_flag IN ( ''M'', ''O'' )
    )
    AND ( asp.awt_include_tax_amt = ''Y''
          OR ( asp.awt_include_tax_amt = ''N''
               AND aid.line_type_lookup_code NOT IN ( ''NONREC_TAX'', ''REC_TAX'', ''RETROTAX'', ''TRV'', ''TIPV'', ''TERV'' ) ) )',
      p_title                  => 'MGD-350',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment Withholding Tax Group(pay_awt_group_id) is populated on the invoice header but not on matched distributions for the invoice causing AWT not to calculate properly.<br/><strong>Impact Area(s): </strong>Automatic Witholding Tax',
      p_solution               => '<strong>Solution GDF: </strong>20312812</br><strong>Note: </strong>[2001007/KB389877]</br><strong>Script Name: </strong>ap_pay_awt_nul_mthd_dist_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2001007/KB389877]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: 350');



debug('begin add_signature: 359');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Trial Balance';
   l_info('bug_number'):= '17571683';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1377248.1';
   l_info('problem'):= 'Accounting transactions which have not been merged to the destination supplier after Supplier/Site merge';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1377248.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4082',
      p_sig_id                 => '359',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   ),
   ap_ledger_options AS (
     SELECT ai.set_of_books_id,
            nvl(xlo.merge_acct_option_code,''NONE'') merge_acct_option_code,
            adv.org_id,
            adv.vendor_id to_vendor_id,
            adv.vendor_site_id to_vendor_site_id,
            adv.duplicate_vendor_id from_vendor_id,
            adv.duplicate_vendor_site_id from_vendor_site_id,
            adv.process,
            adv.paid_invoices_flag
     FROM invs,
          ap_duplicate_vendors_all adv,
          ap_invoices_all ai,
          xla_ledger_options xlo
     WHERE ai.invoice_id = invs.invoice_id
     AND   ai.set_of_books_id = xlo.ledger_id
     AND   xlo.application_id = 200
     AND   xlo.merge_acct_option_code IN (''CHANGE'',''TRANSFER'')
     AND   ai.vendor_id = adv.vendor_id
     AND   nvl(adv.vendor_site_id,ai.vendor_site_id) = ai.vendor_site_id
     AND   adv.process_flag = ''Y''
     AND   adv.process <> ''P'')
   SELECT alo.to_vendor_id,
          nvl(alo.to_vendor_site_id,ai.vendor_site_id) to_vendor_site_id,
          alo.org_id,
          ai.invoice_id source_id_int_1,
          alo.from_vendor_id,
          alo.from_vendor_site_id,
          ai.invoice_num source_number,
          ''AP_INVOICES'' entity_code,
          ai.set_of_books_id ledger_id
   FROM invs,
        ap_invoices_all ai,
        ap_ledger_options alo
    WHERE ai.invoice_id = invs.invoice_id
    AND   ai.set_of_books_id = alo.set_of_books_id
    AND   ai.vendor_id = alo.to_vendor_id
    AND   ai.vendor_site_id = nvl(alo.to_vendor_site_id,ai.vendor_site_id)
    AND   alo.merge_acct_option_code = ''TRANSFER''
    AND   NOT EXISTS (
            SELECT ''No Merge Entry in xla for this vendor site''
            FROM xla_transaction_entities_upg xte,
                 xla_events xe
            WHERE xte.application_id = 200
            AND   xte.ledger_id = alo.set_of_books_id
            AND   xte.entity_code = ''THIRD_PARTY_MERGE''
            AND   xe.entity_id = xte.entity_id
            AND   xe.application_id = 200
            AND   xe.event_type_code  IN (''FULL_MERGE'',''PARTIAL_MERGE'')
            AND   xe.reference_num_1 = alo.from_vendor_id
            AND   xe.reference_num_2 = alo.from_vendor_site_id
            AND   xe.reference_num_3 = alo.to_vendor_id
            AND   xe.reference_num_4 = nvl(alo.to_vendor_site_id,xe.reference_num_4))
   AND   EXISTS (
           SELECT ''Need to merger invoice''
           FROM xla_ae_lines xel,
                xla_ae_headers xeh,
                xla_transaction_entities_upg xte
           WHERE xte.application_id = 200
           AND   xel.application_id = xeh.application_id
           AND   xeh.accounting_entry_status_code = ''F''
           AND   xte.application_id = xeh.application_id
           AND   xel.ae_header_id = xeh.ae_header_id
           AND   xte.entity_code = ''AP_INVOICES''
           AND   xte.ledger_id = ai.set_of_books_id
           AND   nvl(xte.source_id_int_1,(-99)) = ai.invoice_id
           AND   xte.entity_id = xeh.entity_id
           AND   xel.party_id = alo.from_vendor_id
           AND   xel.party_site_id = alo.from_vendor_site_id)
   UNION ALL
   SELECT alo.to_vendor_id,
          nvl(alo.to_vendor_site_id,ai.vendor_site_id) to_vendor_site_id,
          alo.org_id,
          ai.invoice_id source_id_int_1,
          alo.from_vendor_id,
          alo.from_vendor_site_id,
          ai.invoice_num source_number,
          ''AP_INVOICES'' entity_code,
          ai.set_of_books_id ledger_id
   FROM invs,
        ap_invoices_all ai,
        ap_ledger_options alo
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.set_of_books_id = alo.set_of_books_id
   AND   ai.vendor_id = alo.to_vendor_id
   AND   ai.vendor_site_id = nvl(alo.to_vendor_site_id,ai.vendor_site_id)
   AND   alo.merge_acct_option_code = ''CHANGE''
   AND   EXISTS (
           SELECT ''Need to merger invoice''
           FROM xla_ae_lines xel,
                xla_ae_headers xeh,
                xla_transaction_entities_upg xte
           WHERE xte.application_id = 200
           AND   xel.application_id = xeh.application_id
           AND   xeh.accounting_entry_status_code = ''F''
           AND   xte.application_id = xeh.application_id
           AND   xel.ae_header_id = xeh.ae_header_id
           AND   xte.entity_code = ''AP_INVOICES''
           AND   xte.ledger_id = ai.set_of_books_id
           AND   nvl(xte.source_id_int_1,(-99)) = ai.invoice_id
           AND   xte.entity_id = xeh.entity_id
           AND   xel.party_id = alo.from_vendor_id
           AND   xel.party_site_id = alo.from_vendor_site_id)',
      p_title                  => 'MGD-359',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Accounting transactions which have not been merged to the destination supplier after Supplier/Site merge<br/><strong>Impact Area(s): </strong>Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>17571683</br><strong>Note: </strong>[1377248/KB300876]</br><strong>Script Name: </strong>ap_xla_supmg_sel.sql Invoice</br></br>Apply the GDF patch following the instructions provided in [1377248/KB300876]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 359');



debug('begin add_signature: 362');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '18846591';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1916767.1';
   l_info('problem'):= 'Invoice or Payment time AWT distributions for foreign currency invoices have incorrect base amounts.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1916767.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4097',
      p_sig_id                 => '362',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aip.exchange_rate exchange_rate,
          asp.base_currency_code,
          aid.invoice_distribution_id,
          aid.invoice_line_number
   FROM invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp,
        ap_invoice_distributions_all aid,
        ap_invoice_payments_all aip
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid.invoice_id
   AND   asp.org_id = ai.org_id
   AND   asp.base_currency_code <> ai.invoice_currency_code
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.awt_invoice_payment_id is not null
   AND   aip.invoice_payment_id = aid.awt_invoice_payment_id
   AND   aip.exchange_rate is not null
   AND   aid.base_amount is not null
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aidx
           WHERE aidx.invoice_id = aid.invoice_id
           AND   aidx.related_id = aid.awt_related_id
           AND   aidx.line_type_lookup_code in (''ERV'',''TERV''))
   AND   aid.base_amount <>
           (ap_utilities_pkg.ap_round_currency(
              aid.amount * aip.exchange_rate,asp.base_currency_code) +
            nvl(aid.rounding_amt,0))
  AND   aid.amount <>
          ap_utilities_pkg.ap_round_currency(
           (aid.base_amount - nvl(aid.rounding_amt,0))/
             aip.exchange_rate, ai.invoice_currency_code)
  UNION ALL
  SELECT ai.invoice_id,
         ai.invoice_num,
         ai.invoice_date,
         ai.org_id,
         ai.exchange_rate exchange_rate,
         asp.base_currency_code,
         aid.invoice_distribution_id,
         aid.invoice_line_number
   FROM invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(ai.awt_flag,''N'') = ''Y''
   AND   ai.exchange_rate is not null
   AND   ai.invoice_id = aid.invoice_id
   AND   asp.org_id = ai.org_id
   AND   asp.base_currency_code <> ai.invoice_currency_code
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.awt_invoice_payment_id is null
   AND   aid.base_amount is not null
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aidx
           WHERE aidx.invoice_id = aid.invoice_id
           AND   aidx.related_id = aid.awt_related_id
           AND   aidx.line_type_lookup_code in (''ERV'',''TERV''))
   AND   aid.base_amount <>
           (ap_utilities_pkg.ap_round_currency(
              aid.amount * ai.exchange_rate,asp.base_currency_code) +
            nvl(aid.rounding_amt,0))
   AND   aid.amount <>
           ap_utilities_pkg.ap_round_currency(
             (aid.base_amount - nvl(aid.rounding_amt,0))/ai.exchange_rate,
              ai.invoice_currency_code)',
      p_title                  => 'MGD-362',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice or Payment time AWT distributions for foreign currency invoices have incorrect base amounts.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>18846591</br><strong>Note: </strong>[1916767/KB768160]</br><strong>Script Name: </strong>ap_incorr_awt_base_amt_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1916767/KB768160]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 362');



debug('begin add_signature: 372');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Cancellation';
   l_info('bug_number'):= '19643319';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1968118.1';
   l_info('problem'):= 'Cancelled/discarded invoices do not have related_retainage_dist_id stamped on reversed distributions.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1968118.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4168',
      p_sig_id                 => '372',
      p_sig_sql                => 'SELECT ai.invoice_num,
          aid1.invoice_id,
          aid1.invoice_line_number,
          aid1.line_type_lookup_code,
          aid1.related_retainage_dist_id,
          aid1.invoice_distribution_id,
          aid1.parent_reversal_id,
          aid2.related_retainage_dist_id rev_retainage_dist_id,
          aid2.invoice_distribution_id rev_invoice_dist_id,
          aid2.parent_reversal_id rev_parent_rev_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid1,
        ap_invoice_distributions_all aid2
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = ail.invoice_id
   AND   ail.invoice_id = aid1.invoice_id
   AND   ail.line_number= aid1.invoice_line_number
   AND   ai.invoice_type_lookup_code <> ''RETAINAGE RELEASE''
   AND   aid1.invoice_distribution_id = aid2.parent_reversal_id
   AND   aid1.invoice_id = aid2.invoice_id
   AND   aid1.invoice_line_number = aid2.invoice_line_number
   AND   aid1.parent_reversal_id is null
   AND   ai.historical_flag is null
   AND   (ail.discarded_flag=''Y'' OR ail.cancelled_flag=''Y'')
   AND   aid1.line_type_lookup_code = ''RETAINAGE''
   AND   aid1.related_retainage_dist_id is not null
   AND   aid2.related_retainage_dist_id is null',
      p_title                  => 'MGD-372',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Cancelled/discarded invoices do not have related_retainage_dist_id stamped on reversed distributions.<br/><strong>Impact Area(s): </strong>Invoice Cancellation',
      p_solution               => '<strong>Solution GDF: </strong>19643319</br><strong>Note: </strong>[1968118/KB729002]</br><strong>Script Name: </strong>ap_upd_rel_retainage_id_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1968118/KB729002]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 372');



debug('begin add_signature: 376');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Mass Additions';
   l_info('bug_number'):= '22070497';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1922786.1';
   l_info('problem'):= 'Invoice distributions on which the asset_tracking_flag has been incorrectly unchecked when the GL Date is changed on the invoice header.  This results in the Mass Additions process not selecting these transactions.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1922786.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4173',
      p_sig_id                 => '376',
      p_sig_sql                => 'SELECT /*+ leading(invs) */
          aid.invoice_id,
          aid.invoice_line_number inv_line_number,
          aid.distribution_line_number inv_dist_line_number,
          aid.line_type_lookup_code line_type,
          aid.amount,
          pd.accrue_on_receipt_flag,
          pd.code_combination_id po_code_combination_id,
          gcc_po.account_type po_acc_type,
          aid.dist_code_combination_id aid_code_combination_id,
          gcc_inv.account_type inv_acc_type,
          ail.assets_tracking_flag line_assets_track_flag,
          aid.assets_tracking_flag dist_assets_track_flag,
          aid.assets_addition_flag dist_assets_addition_flag,
          aid.invoice_distribution_id inv_dist_id,
          decode (pd.accrue_on_receipt_flag,
            ''Y'', (decode(gcc_po.account_type,
                    ''E'',nvl(ail.assets_tracking_flag,''N''),
                    ''A'',''Y'',
                    ''N'')),
            ''N'', (decode(gcc_inv.account_type,
                    ''E'',nvl(ail.assets_tracking_flag,''N''),
                    ''A'',''Y'',
                    ''N'')),
            ''N'') derived_assets_tracking_flag
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoice_distributions_all aid,
        ap_invoice_lines_all ail,
        po_distributions_all pd,
        gl_code_combinations gcc_po,
        gl_code_combinations gcc_inv
   WHERE aid.invoice_id = invs.invoice_id
   AND   pd.po_distribution_id = aid.po_distribution_id
   AND   ail.invoice_id  = aid.invoice_id
   AND   ail.line_number = aid.invoice_line_number
   AND   gcc_po.code_combination_id = pd.code_combination_id
   AND   gcc_inv.code_combination_id= aid.dist_code_combination_id
   AND   aid.assets_tracking_flag = ''N''
   AND   aid.line_type_lookup_code NOT IN (''NONREC_TAX'',
           ''REC_TAX'',''TRV'',''TIPV'',''TERV'')
   AND   ((pd.accrue_on_receipt_flag = ''Y'' AND
           gcc_po.account_type IN (''A'',''E'')) OR
          (pd.accrue_on_receipt_flag = ''N'' AND
           gcc_inv.account_type IN(''A'',''E'')))
   AND   ((nvl(aid.assets_tracking_flag,''X'') <>
             decode(pd.accrue_on_receipt_flag,
               ''Y'', (decode(gcc_po.account_type,
                      ''E'',nvl(ail.assets_tracking_flag,''N''),
                      ''A'',''Y'',
                      ''N'')),
               ''N'', (decode(gcc_inv.account_type,
                      ''E'',nvl(ail.assets_tracking_flag,''N''),
                      ''A'',''Y'',
                      ''N'')),
               ''N'')) OR
          (aid.assets_tracking_flag = ''Y'' AND
           aid.assets_addition_flag <> ''U''))',
      p_title                  => 'MGD-376',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice distributions on which the asset_tracking_flag has been incorrectly unchecked when the GL Date is changed on the invoice header.  This results in the Mass Additions process not selecting these transactions.<br/><strong>Impact Area(s): </strong>Mass Additions',
      p_solution               => '<strong>Solution GDF: </strong>22070497</br><strong>Note: </strong>[1922786/KB775439]</br><strong>Script Name: </strong>ap_set_assetstrack_flg_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1922786/KB775439]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: 376');



debug('begin add_signature: 379');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Validation Selection';
   l_info('bug_number'):= '20312939';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2632104.1';
   l_info('problem'):= 'Invoice validation is incorrectly picking old invoices for validation resulting in unnecessary processing and performance.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2632104.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4101',
      p_sig_id                 => '379',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT 1 type,
         ''Validationi error: CANNOTE EXECUTE ALLOCATION hold'' issue,
          ail.invoice_id,
          ail.line_number,
          ail.line_type_lookup_code,
          ail.amount,
          ail.historical_flag,
          ail.generate_dists,
          ail.discarded_flag,
          ail.cancelled_flag
   FROM invs,
        ap_invoice_lines_all ail
   WHERE ail.invoice_id = invs.invoice_id
   AND   (ail.discarded_flag = ''Y'' OR ail.cancelled_flag = ''Y'')
   AND   ail.generate_dists = ''Y''
   AND   ail.amount = 0
   UNION ALL
   SELECT 2,
          ''Old invoices in Needs Revalidation status'',
          ail.invoice_id,
          ail.line_number,
          ail.line_type_lookup_code,
          ail.amount,
          ail.historical_flag,
          ail.generate_dists,
          ail.discarded_flag,
          ail.cancelled_flag
   FROM invs,
        ap_invoice_lines_all ail
   WHERE ail.invoice_id = invs.invoice_id
   AND   ail.amount = 0
   AND   nvl(ail.cancelled_flag, ''N'') <> ''Y''
   AND   nvl(ail.discarded_flag, ''N'') <> ''Y''
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ail.invoice_id
           AND   aid.invoice_line_number = ail.line_number)
   AND    NOT EXISTS (
            SELECT 1 FROM ap_holds_all ah
            WHERE ah.invoice_id = ail.invoice_id
            AND   ah.release_lookup_code is null)',
      p_title                  => 'MGD-379',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice validation is incorrectly picking old invoices for validation resulting in unnecessary processing and performance.<br/><strong>Impact Area(s): </strong>Validation Selection',
      p_solution               => '<strong>Solution GDF: </strong>20312939</br><strong>Note: </strong>[2632104/KB767437]</br><strong>Script Name: </strong>ap_wrng_inv_val_pick_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2632104/KB767437]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 379');



debug('begin add_signature: 381');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Approval, Invoice Discard';
   l_info('bug_number'):= '18950901';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2000981.1';
   l_info('problem'):= 'Date columns in various invoice related tables contain timestamps which can cause inability to validate invoices or discard invoice lines as well as FRM-40654 errors when locking records in the forms.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2000981.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4167',
      p_sig_id                 => '381',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.gl_date,
          ai.org_id,
          null line_number,
          null expenditure_item_date,
          null start_expense_date,
          null end_expense_date,
          null accounting_date,
          null program_update_date,
          1 type
   FROM invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   ((ai.gl_date <> trunc(ai.gl_date) AND
           ai.gl_date is not null) OR
          (ai.invoice_date <> trunc(ai.invoice_date) AND
           ai.invoice_date is not null))
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.gl_date,
          ai.org_id,
          ail.line_number,
          ail.expenditure_item_date,
          ail.start_expense_date,
          ail.end_expense_date,
          ail.accounting_date,
          ail.program_update_date,
          2 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail
   WHERE ai.invoice_id = invs.invoice_id
   AND   ail.invoice_id = ai.invoice_id
   AND   ((ail.expenditure_item_date <> trunc(ail.expenditure_item_date) AND
           ail.expenditure_item_date is not null) OR
          (ail.start_expense_date <> trunc(ail.start_expense_date) AND
           ail.start_expense_date is not null) OR
          (ail.end_expense_date <> trunc(ail.end_expense_date) AND
           ail.end_expense_date is not null) OR
          (ail.accounting_date <> trunc(ail.accounting_date) AND
           ail.accounting_date is not null) OR
          (ail.program_update_date <> trunc(ail.program_update_date) AND
           ail.program_update_date  is not null))',
      p_title                  => 'MGD-381',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Date columns in various invoice related tables contain timestamps which can cause inability to validate invoices or discard invoice lines as well as FRM-40654 errors when locking records in the forms.<br/><strong>Impact Area(s): </strong>Invoice Approval, Invoice Discard',
      p_solution               => '<strong>Solution GDF: </strong>18950901</br><strong>Note: </strong>[2000981/KB750659]</br><strong>Script Name: </strong>ap_acc_dt_tmstmp_trnc_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2000981/KB750659]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
