debug('begin add_signature: 388');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'EBTax';
   l_info('bug_number'):= '19170382';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1316316.1';
   l_info('problem'):= 'Upgraded tax lines have a value in zx_lines.offset_tax_rate_code even when supplier site has offset tax calculation disabled causing issues in EMEA VAT Selection Based Reports and errors in invoice validation during tax calculation.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1316316.1';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4115',
      p_sig_id                 => '388',
      p_sig_sql                => 'SELECT DISTINCT
          ai.invoice_id,
          ai.invoice_date,
          ai.application_id,
          ai.legal_entity_id,
          ai.set_of_books_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_supplier_sites_all ss
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.vendor_site_id = ss.vendor_site_id
   AND   nvl(ss.offset_tax_flag,''Y'') = ''N''
   AND   ai.historical_flag = ''Y''
   AND   EXISTS (
           SELECT 1 FROM zx_lines zx
           WHERE zx.application_id = ai.application_id
           AND   zx.legal_entity_id = ai.legal_entity_id
           AND   zx.ledger_id = ai.set_of_books_id
           AND   zx.trx_date = ai.invoice_date
           AND   zx.entity_code = ''AP_INVOICES''
           AND   zx.event_class_code IN (''STANDARD INVOICES'',
                   ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'')
           AND   zx.trx_id = ai.invoice_id
           AND   zx.record_type_code = ''MIGRATED''
           AND   nvl(zx.offset_flag,''Y'') = ''N''
           AND   zx.offset_tax_rate_code is not null)',
      p_title                  => 'MGD-388',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Upgraded tax lines have a value in zx_lines.offset_tax_rate_code even when supplier site has offset tax calculation disabled causing issues in EMEA VAT Selection Based Reports and errors in invoice validation during tax calculation.<br/><strong>Impact Area(s): </strong>EBTax',
      p_solution               => '<strong>Solution GDF: </strong>19170382</br><strong>Note: </strong>[1316316/KB731274]</br><strong>Script Name: </strong>zx_lines_upd_offset_rate.sql</br></br>Apply the GDF patch following the instructions provided in [1316316/KB731274]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 388');



debug('begin add_signature: 394');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Payment Data, Payment Selection';
   l_info('bug_number'):= '19903129';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1937924.1';
   l_info('problem'):= 'Data is partially committed due to an exception, but data in AP is rolled back causing an inconsistence that prevents the PPR from being processed';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1937924.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3928',
      p_sig_id                 => '394',
      p_sig_sql                => 'SELECT DISTINCT
          pi.payment_instruction_id,
          pi.process_type,
          pi.payment_instruction_status,
          pi.payments_complete_code,
          pi.payment_count,
          pi.transmit_instr_immed_flag,
          pi.pay_admin_assigned_ref_code,
          pi.transmission_date,
          pi.org_id,
          pi.payment_date,
          pi.payment_document_id,
          p.completed_pmts_group_id,
          p.payment_process_request_name
   FROM (
          ##$$IVIEW$$##
        ) invs,
        iby_pay_instructions_all pi,
        iby_payments_all p,
        iby_docs_payable_all docs,
        ap_selected_invoices_all asi,
        ap_payment_schedules_all aps
   WHERE p.process_type = ''STANDARD''
   AND   p.payment_function = ''PAYABLES_DISB''
   AND   p.payments_complete_flag = ''Y''
   AND   pi.payment_instruction_id = p.payment_instruction_id
   AND   p.payment_status not in (''VOID'')
   AND   p.completed_pmts_group_id is not null
   AND   p.payment_id= docs.payment_id
   AND   docs.calling_app_id = 200
   AND   asi.invoice_id = invs.invoice_id
   AND   asi.checkrun_id = docs.calling_app_doc_unique_ref1
   AND   docs.calling_app_doc_unique_ref2 = invs.invoice_id
   AND   aps.checkrun_id = docs.calling_app_doc_unique_ref1
   AND   docs.calling_app_doc_unique_ref3 = 1
   AND   aps.invoice_id= asi.invoice_id
   AND   aps.payment_status_flag <> ''Y''
   AND   docs.payment_date >= p.payment_date
   AND   docs.completed_pmts_group_id is not null
   AND   NOT EXISTS (
           SELECT 1
           FROM AP_Checks_All c,
                IBY_Payments_All p2
           WHERE c.payment_id = p2.payment_id
           AND   p2.payment_instruction_id = pi.payment_instruction_id)',
      p_title                  => 'MGD-394',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Data is partially committed due to an exception, but data in AP is rolled back causing an inconsistence that prevents the PPR from being processed<br/><strong>Impact Area(s): </strong>Payment Data, Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>19903129</br><strong>Note: </strong>[1937924/KB215712]</br><strong>Script Name: </strong>ap_ppr_partial_commit_issue_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1937924/KB215712]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: 394');



debug('begin add_signature: 408');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Data';
   l_info('bug_number'):= '21118369';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1966076.1';
   l_info('problem'):= 'Consolidated fixes for non-modified upgraded invoices.  See [1966076.1] for the full list.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1966076.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4047',
      p_sig_id                 => '408',
      p_sig_sql                => 'WITH invs AS (
    SELECT /*+ materialize */ invoice_id
    FROM (
           ##$$IVIEW$$##
         ) ai
   WHERE NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid_sub
           WHERE aid_sub.invoice_id = ai.invoice_id
           AND   nvl(aid_sub.historical_flag,''N'') = ''N''
           UNION ALL
           SELECT 1
           FROM ap_invoice_distributions_all aid_sub,
                xla_events xe_sub,
                ap_accounting_events_all aae_sub
           WHERE aid_sub.accounting_event_id = xe_sub.event_id
           AND   xe_sub.event_id = aae_sub.accounting_event_id
           AND   xe_sub.upg_batch_id = -9999
           AND   aid_sub.invoice_id = ai.invoice_id
           UNION ALL
           SELECT 1
           FROM ap_invoice_payments_all aip_sub,
                ap_payment_history_all aph_sub,
                xla_events xe_sub,
                ap_accounting_events_all aae_sub
           WHERE aip_sub.invoice_id = ai.invoice_id
           AND   aip_sub.check_id = aph_sub.check_id
           AND   aph_sub.accounting_event_id = xe_sub.event_id
           AND   xe_sub.application_id = 200
           AND   xe_sub.event_id = aae_sub.accounting_event_id
           AND   xe_sub.upg_batch_id = -9999
           UNION ALL
           SELECT 1
           FROM ap_invoice_distributions_all aid_sub,
                xla_events xe_sub,
                xla_ae_headers xah_sub
           WHERE aid_sub.invoice_id = ai.invoice_id
           AND   aid_sub.accounting_event_id = xe_sub.event_id
           AND   xe_sub.application_id = 200
           AND   xe_sub.event_id = xah_sub.event_id
           AND   xah_sub.application_id = 200
           AND   xah_sub.upg_batch_id  is null
           UNION ALL
           SELECT 1
           FROM ap_invoice_payments_all aip_sub,
                ap_payment_history_all aph_sub,
                xla_events xe_sub,
                xla_ae_headers xah_sub
           WHERE aip_sub.invoice_id = ai.invoice_id
           AND   aip_sub.check_id = aph_sub.check_id
           AND   aph_sub.accounting_event_id = xe_sub.event_id
           AND   xe_sub.application_id = 200
           AND   xe_sub.event_id = xah_sub.event_id
           AND   xah_sub.application_id = 200
           AND   xah_sub.upg_batch_id  is null)
   )
   SELECT /*+ ordered use_nl(ai, aid_org, aid_rev)  */
          aid_rev.invoice_id invoice_id,
          aid_rev.invoice_line_number,
          aid_org.invoice_distribution_id parent_dist_id,
          aid_org.line_type_lookup_code,
          aid_org.amount,
          aid_rev.invoice_distribution_id reversal_dist_id,
          1.1 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid_org,
        ap_invoice_dists_arch aid_rev
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid_org.invoice_id
   AND   aid_rev.invoice_id = aid_org.invoice_id
   AND   aid_rev.parent_reversal_id = aid_org.invoice_distribution_id
   AND   aid_rev.amount <> (-1)*aid_org.amount
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid_org, aid_rev) */
          aid_rev.invoice_id,
          aid_rev.invoice_line_number,
          aid_org.invoice_distribution_id,
           aid_org.line_type_lookup_code,
          aid_org.amount,
          aid_rev.invoice_distribution_id,
          1.2 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid_org,
        ap_invoice_dists_arch aid_rev
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid_org.invoice_id
   AND   aid_rev.invoice_id = aid_org.invoice_id
   AND   aid_rev.parent_reversal_id = aid_org.invoice_distribution_id
   AND   aid_rev.line_type_lookup_code <> aid_org.line_type_lookup_code
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid1) */
          aid1.invoice_id,
          aid1.invoice_line_number,
          aid1.parent_reversal_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          NULL reversal_dist_id,
          1.3 type
   FROM invs,
        ap_invoices_all  ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid1.invoice_id = ai.invoice_id
   AND   aid1.parent_reversal_id is not null
   GROUP BY aid1.invoice_id, aid1.invoice_line_number, aid1.parent_reversal_id,
            aid1.line_type_lookup_code, aid1.amount
   HAVING   count(aid1.parent_reversal_id) > 1
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid_org, aid_rev)  */
          aid_rev.invoice_id,
          aid_rev.invoice_line_number,
          aid_rev.parent_reversal_id,
          aid_rev.line_type_lookup_code,
          aid_rev.amount,
          aid_rev.invoice_distribution_id,
          1.4 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid_org,
        ap_invoice_dists_arch aid_rev
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid_org.invoice_id
   AND   aid_rev.invoice_id = aid_org.invoice_id
   AND   aid_rev.parent_reversal_id = aid_org.invoice_distribution_id
   AND   aid_org.parent_reversal_id IS not null
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_dists_arch arcx
           WHERE arcx.invoice_id = aid_org.invoice_id
           AND   arcx.invoice_distribution_id = aid_org.parent_reversal_id
           AND   arcx.parent_reversal_id is null)
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid1) */
          aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          aid1.parent_reversal_id,
          1.5 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   aid1.parent_reversal_id is not null
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_dists_arch aid2
           WHERE aid2.invoice_id = aid1.invoice_id
           AND   aid2.invoice_distribution_id = aid1.parent_reversal_id)
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid1) */
          aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          aid1.parent_reversal_id,
          1.6 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   aid1.reversal_flag = ''Y''
   AND   aid1.parent_reversal_id is null
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_dists_arch aid2
           WHERE aid2.parent_reversal_id is not null
           AND     aid2.invoice_id = aid1.invoice_id
           AND   aid2.parent_reversal_id = aid1.invoice_distribution_id)
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid1) */
          aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          aid1.parent_reversal_id,
          1.7 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   aid1.parent_reversal_id is not null
   AND   nvl(aid1.reversal_flag,''N'') = ''N''
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid1, aid2) */
          aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid2.invoice_distribution_id,
          aid2.line_type_lookup_code,
          aid2.amount,
          aid1.invoice_distribution_id,
          1.8 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1,
        ap_invoice_dists_arch aid2
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   aid1.parent_reversal_id is not null
   AND   aid1.invoice_id = aid2.invoice_id
   AND   aid1.line_type_lookup_code = aid2.line_type_lookup_code
   AND   aid1.parent_reversal_id = aid2.invoice_distribution_id
   AND   aid2.parent_reversal_id is null
   AND   nvl(aid2.reversal_flag,''N'') = ''N''
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid_org, aid_rev) */
          ai.invoice_id parent_invoice_id,
          aid_org.invoice_line_number,
          aid_org.parent_reversal_id,
          aid_org.line_type_lookup_code,
          aid_org.amount,
          aid_org.invoice_distribution_id,
          1.9 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid_org,
        ap_invoice_dists_arch aid_rev
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid_org.invoice_id
   AND   aid_rev.invoice_id = aid_org.invoice_id
   AND   aid_rev.parent_reversal_id = aid_org.invoice_distribution_id
   AND   aid_org.parent_reversal_id is not null
   AND   aid_rev.invoice_distribution_id = aid_org.parent_reversal_id
   AND   aid_rev.invoice_distribution_id < aid_org.invoice_distribution_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid1) */
          aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid1.parent_reversal_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          aid1.invoice_distribution_id,
          1.10 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   reversal_flag IN (''U'', ''R'')',
      p_title                  => 'MGD-408',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Consolidated fixes for non-modified upgraded invoices.  See [1966076/KB202119] for the full list.<br/><strong>Impact Area(s): </strong>Invoice Data',
      p_solution               => '<strong>Solution GDF: </strong>21118369</br><strong>Note: </strong>[1966076/KB202119]</br><strong>Script Name: </strong>ap_upg_sel.sql Part 1</br></br>Apply the GDF patch following the instructions provided in [1966076/KB202119]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 408');



debug('begin add_signature: 409');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Data';
   l_info('bug_number'):= '21118369';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1966076.1';
   l_info('problem'):= 'Consolidated fixes for non-modified upgraded invoices. See [1966076.1] for the full list.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1966076.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3826',
      p_sig_id                 => '409',
      p_sig_sql                => 'WITH invs AS (
     SELECT /*+ materialize */ invoice_id
     FROM (
            ##$$IVIEW$$##
          ) ai
     WHERE NOT EXISTS (
             SELECT 1 FROM ap_invoice_distributions_all aid_sub
             WHERE aid_sub.invoice_id = ai.invoice_id
             AND   nvl(aid_sub.historical_flag,''N'') = ''N''
             UNION ALL
             SELECT 1
             FROM ap_invoice_distributions_all aid_sub,
                  xla_events xe_sub,
                  ap_accounting_events_all aae_sub
             WHERE aid_sub.accounting_event_id = xe_sub.event_id
             AND   xe_sub.event_id = aae_sub.accounting_event_id
             AND   xe_sub.upg_batch_id = -9999
             AND   aid_sub.invoice_id = ai.invoice_id
             UNION ALL
             SELECT 1
             FROM ap_invoice_payments_all aip_sub,
                  ap_payment_history_all aph_sub,
                  xla_events xe_sub,
                  ap_accounting_events_all aae_sub
             WHERE  aip_sub.invoice_id = ai.invoice_id
             AND   aip_sub.check_id = aph_sub.check_id
             AND   aph_sub.accounting_event_id = xe_sub.event_id
             AND   xe_sub.application_id = 200
             AND   xe_sub.event_id = aae_sub.accounting_event_id
             AND   xe_sub.upg_batch_id = -9999
             UNION ALL
             SELECT 1
             FROM ap_invoice_distributions_all aid_sub,
                  xla_events xe_sub,
                  xla_ae_headers xah_sub
             WHERE aid_sub.invoice_id = ai.invoice_id
             AND   aid_sub.accounting_event_id = xe_sub.event_id
             AND   xe_sub.application_id = 200
             AND   xe_sub.event_id = xah_sub.event_id
             AND   xah_sub.application_id = 200
             AND   xah_sub.upg_batch_id  is null
             UNION ALL
             SELECT 1
             FROM ap_invoice_payments_all aip_sub,
                  ap_payment_history_all aph_sub,
                  xla_events xe_sub,
                  xla_ae_headers xah_sub
             WHERE aip_sub.invoice_id = ai.invoice_id
             AND   aip_sub.check_id = aph_sub.check_id
             AND   aph_sub.accounting_event_id = xe_sub.event_id
             AND   xe_sub.application_id = 200
             AND   xe_sub.event_id = xah_sub.event_id
             AND   xah_sub.application_id = 200
             AND   xah_sub.upg_batch_id  is null)
   )
   SELECT /*+ ordered use_nl(ai, aid1, aid2, aca) */
          aid1.invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          2.1 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1,
        ap_invoice_dists_arch aid2,
        ap_chrg_allocations_all aca
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid1.invoice_id = aid2.invoice_id
   AND   aid1.invoice_distribution_id = aca.item_dist_id
   AND   aid2.invoice_distribution_id = aca.charge_dist_id
   AND   aid1.line_type_lookup_code = aid2.line_type_lookup_code
   AND   ai.invoice_id = aid1.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid1, aca) */
          aid1.invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          2.2 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1,
        ap_chrg_allocations_all aca
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid1.invoice_distribution_id = aca.charge_dist_id
   AND   aid1.line_type_lookup_code = ''ITEM''
   AND   ai.invoice_id = aid1.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid1, aid2, aca) */
          aid1.invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          2.3 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid2,
        ap_invoice_dists_arch aid1,
        ap_chrg_allocations_all aca
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid1.invoice_id = aid2.invoice_id
   AND   aid1.invoice_distribution_id = aca.item_dist_id
   AND   aid2.invoice_distribution_id = aca.charge_dist_id
   AND   aid2.line_type_lookup_code  IN (''FREIGHT'',''MISCELLANEOUS'')
   AND   aid1.line_type_lookup_code = ''TAX''
   AND   ai.invoice_id = aid2.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid, acax) */
          aid.invoice_id,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          2.4 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid,
        ap_chrg_allocations_all acax
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.prepay_tax_parent_id is not null
   AND   aid.line_type_lookup_code = ''TAX''
   AND   aid.invoice_distribution_id = acax.charge_dist_id
   AND   aid.prepay_tax_parent_id <> acax.item_dist_id
   AND   ai.invoice_id = aid.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid, acax, aid_i) */
          aid.invoice_id,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          2.5 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid,
        ap_chrg_allocations_all acax,
        ap_invoice_dists_arch aid_i
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.prepay_tax_parent_id is null
   AND   aid.line_type_lookup_code = ''TAX''
   AND   aid.invoice_distribution_id = acax.charge_dist_id
   AND   acax.item_dist_id = aid_i.invoice_distribution_id
   AND   aid_i.line_type_lookup_code = ''PREPAY''
   AND   ai.invoice_id = aid.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid) */
          aid.invoice_id,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          2.6 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code = ''TAX''
   AND   aid.amount <> (
           SELECT /*+ no_unnest */
                 sum(acax.allocated_amount) FROM ap_chrg_allocations_all acax
           WHERE acax.charge_dist_id = aid.invoice_distribution_id)
   AND   ai.invoice_id = aid.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, ada) */
          ada.invoice_id,
          ada.invoice_line_number,
          ada.invoice_distribution_id,
          ada.line_type_lookup_code,
          ada.amount,
          2.7 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch ada
   WHERE ai.invoice_id = invs.invoice_id
   AND   ada.line_type_lookup_code = ''TAX''
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_dists_arch aidi
           WHERE aidi.invoice_id = ada.invoice_id
           AND   aidi.line_type_lookup_code NOT IN (''AWT'', ''TAX'')
           AND   ada.tax_code_id = aidi.tax_code_id)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_chrg_allocations_all aca
           WHERE aca.charge_dist_id = ada.invoice_distribution_id)
   AND   ai.invoice_id = ada.invoice_id
   UNION ALL
   SELECT /*+ ordered use_nl(ai, arc) */
          arc.invoice_id,
          arc.distribution_line_number,
          arc.invoice_distribution_id,
          arc.line_type_lookup_code,
          arc.amount,
          3 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch arc
   WHERE ai.invoice_id = invs.invoice_id
   AND   arc.invoice_id = ai.invoice_id
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = arc.invoice_id
           AND   aid.old_distribution_id = arc.invoice_distribution_id)
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid_tax, aid_prepay) */
          aid_tax.invoice_id,
          aid_tax.invoice_line_number,
          aid_tax.invoice_distribution_id,
          aid_tax.line_type_lookup_code,
          aid_tax.amount,
          4 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid_tax,
        ap_invoice_distributions_all aid_prepay
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid_tax.charge_applicable_to_dist_id = aid_prepay.invoice_distribution_id
   AND   aid_tax.invoice_id = aid_prepay.invoice_id
   AND   ai.invoice_id = aid_tax.invoice_id
   AND   ai.historical_flag = ''Y''
   AND   aid_tax.prepay_distribution_id is null
   AND   aid_prepay.line_type_lookup_code = ''PREPAY''
   AND   aid_tax.line_type_lookup_code IN (''REC_TAX'', ''NONREC_TAX'')
   AND   aid_tax.prepay_tax_parent_id is not null
   AND   aid_tax.historical_flag = ''Y''
   UNION ALL
   SELECT /*+ ordered use_nl(ai, aid) */
          aid.invoice_id,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          5 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.invoice_id = ai.invoice_id
   AND   aid.historical_flag = ''Y''
   AND   ai.historical_flag = ''Y''
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.awt_related_id is null
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_distributions_all aidx
           WHERE aidx.invoice_id = aid.invoice_id
           AND   aidx.line_type_lookup_code not IN (''AWT'',''ERV'',''TERV'')
           AND   aidx.prepay_distribution_id is null
           AND   abs(aidx.amount) >= abs(aid.amount))
   UNION ALL
   SELECT /*+ ordered use_nl(ai, ail) */
          ail.invoice_id,
          ail.line_number,
          null invoice_distribution_id,
          ail.line_type_lookup_code,
          ail.amount,
          6 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = ail.invoice_id
   AND   nvl(ail.historical_flag, ''N'') = ''Y''
   AND   ail.line_type_lookup_code not IN (''TAX'', ''AWT'', ''PREPAY'')
   AND   ail.corrected_inv_id is not null
   AND   ail.corrected_line_number is null
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_invoice_distributions_all aid,
                ap_invoice_dists_arch arc
           WHERE aid.invoice_id = ail.invoice_id
           AND   aid.invoice_line_number = ail.line_number
           AND   aid.invoice_id = arc.invoice_id
           AND   arc.invoice_distribution_id = aid.old_distribution_id
           AND   arc.price_correct_inv_id is not null)',
      p_title                  => 'MGD-409',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Consolidated fixes for non-modified upgraded invoices. See [1966076/KB202119] for the full list.<br/><strong>Impact Area(s): </strong>Invoice Data',
      p_solution               => '<strong>Solution GDF: </strong>21118369</br><strong>Note: </strong>[1966076/KB202119]</br><strong>Script Name: </strong>ap_upg_sel.sql Part 2</br></br>Apply the GDF patch following the instructions provided in [1966076/KB202119]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 409');



debug('begin add_signature: 410');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Data';
   l_info('bug_number'):= '25762748';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1556126.1';
   l_info('problem'):= 'Consolidated fixes for upgraded invoices that have been modified since the upgrade.  See [1556126.1] for the complete list.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1556126.1.';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3827',
      p_sig_id                 => '410',
      p_sig_sql                => 'WITH invs AS (
     SELECT /*+ materialize */ ai.invoice_id
     FROM (
            ##$$IVIEW$$##
          ) ai
     WHERE EXISTS (
             SELECT 1 FROM ap_invoice_distributions_all aid_sub
             WHERE aid_sub.invoice_id = ai.invoice_id
             AND   nvl(aid_sub.historical_flag,''N'') = ''N''
             UNION ALL
             SELECT 1
             FROM ap_invoice_distributions_all aid_sub,
                  xla_events xe_sub,
                  ap_accounting_events_all aae_sub
             WHERE aid_sub.accounting_event_id = xe_sub.event_id
             AND   xe_sub.event_id = aae_sub.accounting_event_id
             AND   xe_sub.upg_batch_id = -9999
             AND   aid_sub.invoice_id = ai.invoice_id
             UNION ALL
             SELECT 1
             FROM ap_invoice_payments_all aip_sub,
                  ap_payment_history_all aph_sub,
                  xla_events xe_sub,
                  ap_accounting_events_all aae_sub
             WHERE  aip_sub.invoice_id = ai.invoice_id
             AND   aip_sub.check_id = aph_sub.check_id
             AND   aph_sub.accounting_event_id = xe_sub.event_id
             AND   xe_sub.application_id = 200
             AND   xe_sub.event_id = aae_sub.accounting_event_id
             AND   xe_sub.upg_batch_id = -9999
             UNION ALL
             SELECT 1
             FROM ap_invoice_distributions_all aid_sub,
                  xla_events xe_sub,
                  xla_ae_headers xah_sub
             WHERE aid_sub.invoice_id = ai.invoice_id
             AND   aid_sub.accounting_event_id = xe_sub.event_id
             AND   xe_sub.application_id = 200
             AND   xe_sub.event_id = xah_sub.event_id
             AND   xah_sub.application_id = 200
             AND   xah_sub.upg_batch_id  is null
             UNION ALL
             SELECT 1
             FROM ap_invoice_payments_all aip_sub,
                  ap_payment_history_all aph_sub,
                  xla_events xe_sub,
                  xla_ae_headers xah_sub
             WHERE aip_sub.invoice_id = ai.invoice_id
             AND   aip_sub.check_id = aph_sub.check_id
             AND   aph_sub.accounting_event_id = xe_sub.event_id
             AND   xe_sub.application_id = 200
             AND   xe_sub.event_id = xah_sub.event_id
             AND   xah_sub.application_id = 200
             AND   xah_sub.upg_batch_id  is null)
   )
   SELECT aid_rev.invoice_id invoice_id,
          aid_rev.invoice_line_number,
          aid_org.invoice_distribution_id parent_dist_id,
          aid_org.line_type_lookup_code,
          aid_org.amount,
          aid_rev.invoice_distribution_id reversal_dist_id,
          1.1 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid_org,
        ap_invoice_dists_arch aid_rev
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid_org.invoice_id
   AND   aid_rev.invoice_id = aid_org.invoice_id
   AND   aid_rev.parent_reversal_id = aid_org.invoice_distribution_id
   AND   aid_rev.amount <> (-1)*aid_org.amount
   UNION ALL
   SELECT aid_rev.invoice_id invoice_id,
          aid_rev.invoice_line_number,
          aid_org.invoice_distribution_id,
          aid_org.line_type_lookup_code,
          aid_org.amount,
          aid_rev.invoice_distribution_id,
          1.2 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid_org,
        ap_invoice_dists_arch aid_rev
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid_org.invoice_id
   AND   aid_rev.invoice_id = aid_org.invoice_id
   AND   aid_rev.parent_reversal_id = aid_org.invoice_distribution_id
   AND   aid_rev.line_type_lookup_code <> aid_org.line_type_lookup_code
   UNION ALL
   SELECT aid1.invoice_id invoice_id,
          aid1.invoice_line_number,
          aid1.parent_reversal_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          null,
          1.3 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid1.invoice_id = ai.invoice_id
   AND   aid1.parent_reversal_id is not null
   GROUP BY aid1.invoice_id, aid1.invoice_line_number,
            aid1.parent_reversal_id, aid1.line_type_lookup_code,
            aid1.amount
   HAVING COUNT(aid1.parent_reversal_id) > 1
   UNION ALL
   SELECT
          aid_rev.invoice_id invoice_id,
          aid_rev.invoice_line_number,
          aid_rev.parent_reversal_id,
          aid_rev.line_type_lookup_code,
          aid_rev.amount,
          aid_rev.invoice_distribution_id,
          1.4 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid_org,
        ap_invoice_dists_arch aid_rev
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid_org.invoice_id
   AND   aid_rev.invoice_id = aid_org.invoice_id
   AND   aid_rev.parent_reversal_id = aid_org.invoice_distribution_id
   AND   aid_org.parent_reversal_id is not null
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_dists_arch arcx
           WHERE arcx.invoice_id = aid_org.invoice_id
           AND   arcx.invoice_distribution_id = aid_org.parent_reversal_id
           AND   arcx.parent_reversal_id is null)
   UNION ALL
   SELECT aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          aid1.parent_reversal_id,
          1.5 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   aid1.parent_reversal_id is not null
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_dists_arch aid2
           WHERE aid2.invoice_id = aid1.invoice_id
           AND   aid2.invoice_distribution_id = aid1.parent_reversal_id)
   UNION ALL
   SELECT aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          aid1.parent_reversal_id,
          1.6 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   aid1.reversal_flag = ''Y''
   AND   aid1.parent_reversal_id is null
   AND   NOT EXISTS (
           SELECT 1
           FROM ap_invoice_dists_arch aid2
           WHERE aid2.parent_reversal_id is not null
           AND   aid2.invoice_id = aid1.invoice_id
           AND   aid2.parent_reversal_id = aid1.invoice_distribution_id)
   UNION ALL
   SELECT aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          aid1.parent_reversal_id,
          1.7 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   aid1.parent_reversal_id is not null
   AND   nvl(aid1.reversal_flag,''N'') = ''N''
   UNION ALL
   SELECT aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid2.invoice_distribution_id,
          aid2.line_type_lookup_code,
          aid2.amount,
          aid1.invoice_distribution_id,
          1.8 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1,
        ap_invoice_dists_arch aid2
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   aid1.parent_reversal_id is not null
   AND   aid1.invoice_id = aid2.invoice_id
   AND   aid1.line_type_lookup_code = aid2.line_type_lookup_code
   AND   aid1.parent_reversal_id = aid2.invoice_distribution_id
   AND   aid2.parent_reversal_id is null
   AND   nvl(aid2.reversal_flag,''N'') = ''N''
   UNION ALL
   SELECT ai.invoice_id parent_invoice_id,
          aid_org.invoice_line_number,
          aid_org.parent_reversal_id,
          aid_org.line_type_lookup_code,
          aid_org.amount,
          aid_org.invoice_distribution_id,
          1.9 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid_org,
        ap_invoice_dists_arch aid_rev
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid_org.invoice_id
   AND   aid_rev.invoice_id = aid_org.invoice_id
   AND   aid_rev.parent_reversal_id = aid_org.invoice_distribution_id
   AND   aid_org.parent_reversal_id is not null
   AND   aid_rev.invoice_distribution_id = aid_org.parent_reversal_id
   AND   aid_rev.invoice_distribution_id < aid_org.invoice_distribution_id
   UNION ALL
   SELECT aid1.invoice_id parent_invoice_id,
          aid1.invoice_line_number,
          aid1.parent_reversal_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          aid1.invoice_distribution_id,
          1.10 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid1.invoice_id
   AND   reversal_flag IN (''U'', ''R'')
   UNION ALL
   SELECT aid1.invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          null,
          2.1 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1,
        ap_invoice_dists_arch aid2,
        ap_chrg_allocations_all aca
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid1.invoice_id = aid2.invoice_id
   AND   aid1.invoice_distribution_id = aca.item_dist_id
   AND   aid2.invoice_distribution_id = aca.charge_dist_id
   AND   aid1.line_type_lookup_code = aid2.line_type_lookup_code
   AND   ai.invoice_id = aid1.invoice_id
   UNION ALL
   SELECT aid1.invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          null,
          2.2 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1,
        ap_chrg_allocations_all aca
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid1.invoice_distribution_id = aca.charge_dist_id
   AND   aid1.line_type_lookup_code = ''ITEM''
   AND   ai.invoice_id = aid1.invoice_id
   UNION ALL
   SELECT aid1.invoice_id,
          aid1.invoice_line_number,
          aid1.invoice_distribution_id,
          aid1.line_type_lookup_code,
          aid1.amount,
          null,
          2.3 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid1,
        ap_invoice_dists_arch aid2,
        ap_chrg_allocations_all aca
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid1.invoice_id = aid2.invoice_id
   AND   aid1.invoice_distribution_id = aca.item_dist_id
   AND   aid2.invoice_distribution_id = aca.charge_dist_id
   AND   aid2.line_type_lookup_code  IN (''FREIGHT'',''MISCELLANEOUS'')
   AND   aid1.line_type_lookup_code = ''TAX''
   AND   ai.invoice_id = aid1.invoice_id
   UNION ALL
   SELECT aid.invoice_id,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          null,
          2.4 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid,
        ap_chrg_allocations_all acax
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.prepay_tax_parent_id is not null
   AND   aid.line_type_lookup_code = ''TAX''
   AND   aid.invoice_distribution_id = acax.charge_dist_id
   AND   aid.prepay_tax_parent_id <> acax.item_dist_id
   AND   ai.invoice_id = aid.invoice_id
   UNION ALL
   SELECT aid.invoice_id,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          null,
          2.5 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid,
        ap_chrg_allocations_all acax,
        ap_invoice_dists_arch aid_i
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.prepay_tax_parent_id is null
   AND   aid.line_type_lookup_code = ''TAX''
   AND   aid.invoice_distribution_id = acax.charge_dist_id
   AND   acax.item_dist_id = aid_i.invoice_distribution_id
   AND   aid_i.line_type_lookup_code = ''PREPAY''
   AND   ai.invoice_id = aid.invoice_id
   UNION ALL
   SELECT aid.invoice_id,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          null,
          2.6 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code = ''TAX''
   AND   aid.amount <> (
           SELECT sum(acax.allocated_amount) FROM ap_chrg_allocations_all acax
           WHERE acax.charge_dist_id = aid.invoice_distribution_id)
   AND   ai.invoice_id = aid.invoice_id
   UNION ALL
   SELECT ada.invoice_id,
          ada.invoice_line_number,
          ada.invoice_distribution_id,
          ada.line_type_lookup_code,
          ada.amount,
          null,
          2.7 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch ada
   WHERE ai.invoice_id = invs.invoice_id
   AND   ada.line_type_lookup_code = ''TAX''
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_dists_arch aidi
           WHERE aidi.invoice_id = ada.invoice_id
           AND   aidi.line_type_lookup_code not IN (''AWT'', ''TAX'')
           AND   ada.tax_code_id = aidi.tax_code_id)
   AND   NOT EXISTS (
           SELECT 1 FROM ap_chrg_allocations_all aca
           WHERE aca.charge_dist_id = ada.invoice_distribution_id)
   AND   ai.invoice_id = ada.invoice_id
   UNION ALL
   SELECT
          arc.invoice_id,
          arc.distribution_line_number,
          arc.invoice_distribution_id,
          arc.line_type_lookup_code,
          arc.amount,
          null,
          3 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch arc
   WHERE ai.invoice_id = invs.invoice_id
   AND   arc.invoice_id = ai.invoice_id
   AND   NOT EXISTS (
      SELECT 1 FROM ap_invoice_distributions_all aid
      WHERE aid.invoice_id = arc.invoice_id
      AND   aid.old_distribution_id = arc.invoice_distribution_id)
   UNION ALL
   SELECT
          ail.invoice_id,
          ail.line_number,
          null invoice_distribution_id,
          ail.line_type_lookup_code,
          ail.amount,
          null,
          6 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = ail.invoice_id
   AND   nvl(ail.historical_flag, ''N'') = ''Y''
   AND   ail.line_type_lookup_code not IN (''TAX'', ''AWT'', ''PREPAY'')
   AND   ail.corrected_inv_id is not null
   AND   ail.corrected_line_number is null
   AND   EXISTS (
           SELECT 1
           FROM ap_invoice_distributions_all aid,
                ap_invoice_dists_arch arc
           WHERE aid.invoice_id = ail.invoice_id
           AND   aid.invoice_line_number = ail.line_number
           AND   aid.invoice_id = arc.invoice_id
           AND   arc.invoice_distribution_id = aid.old_distribution_id
           AND   arc.price_correct_inv_id is not null)
   UNION
   SELECT /*+ ORDERED */
          aid_t.invoice_id,
          aid_t.distribution_line_number,
          aid_t.invoice_distribution_id,
          aid_t.line_type_lookup_code,
          aid_t.amount,
          null,
          7 type
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_dists_arch aid_t,
        ap_chrg_allocations_all aca,
        ap_invoice_dists_arch aid_i
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid_i.line_type_lookup_code IN (''ITEM'', ''FREIGHT'', ''MISCELLANEOUS'')
   AND   aid_i.reversal_flag = ''Y''
   AND   aca.charge_dist_id = aid_t.invoice_distribution_id
   AND   aca.item_dist_id = aid_i.invoice_distribution_id
   AND   aid_t.line_type_lookup_code = ''TAX''
   AND   aid_t.prepay_tax_parent_id is null
   AND   aid_t.invoice_id = ai.invoice_id
   AND   nvl(aid_t.reversal_flag, ''N'') = ''N''',
      p_title                  => 'MGD-410',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Consolidated fixes for upgraded invoices that have been modified since the upgrade.  See [1556126/KB501037] for the complete list.<br/><strong>Impact Area(s): </strong>Invoice Data',
      p_solution               => '<strong>Solution GDF: </strong>25762748</br><strong>Note: </strong>[1556126/KB501037]</br><strong>Script Name: </strong>ap_trxupg_m.sql</br></br>Apply the GDF patch following the instructions provided in [1556126/KB501037].</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: 410');



