   l_info('problem'):= 'The HQ Establishment Registration Number is populated with NULL or an incorrect value on tax lines which impacts EMEA VAT Reports';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1316316.1 (SECTION 34)';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3912',
      p_sig_id                 => '412',
      p_sig_sql                => 'SELECT DISTINCT
          zl.trx_id,
          zl.trx_number,
          zl.trx_date,
          zl.legal_entity_id,
          zl.application_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        zx_lines zl
   WHERE zl.trx_id = invs.invoice_id
   AND   zl.application_id = 200
   AND   zl.entity_code = ''AP_INVOICES''
   AND   EXISTS (
           SELECT 1
           FROM zx_registrations reg,
                xle_etb_profiles etb,
                zx_party_tax_profile ptp
           WHERE ptp.party_id = etb.party_id
           AND   ptp.party_type_code = ''LEGAL_ESTABLISHMENT''
           AND   etb.main_establishment_flag = ''Y''
           AND   etb.legal_entity_id = zl.legal_entity_id
           AND   (nvl(zl.hq_estb_reg_number,''XX'') <>
                    nvl(ptp.rep_registration_number,reg.registration_number) OR
                  nvl(zl.hq_estb_party_tax_prof_id,-99) <> ptp.party_tax_profile_id)
           AND   reg.party_tax_profile_id (+) = ptp.party_tax_profile_id)',
      p_title                  => 'MGD-412',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The HQ Establishment Registration Number is populated with NULL or an incorrect value on tax lines which impacts EMEA VAT Reports<br/><strong>Impact Area(s): </strong>EBTax',
      p_solution               => '<strong>Solution GDF: </strong>27857755</br><strong>Note: </strong>[1316316/KB731274]</br><strong>Script Name: </strong>zx_hq_estb_reg_num.sql</br></br>Apply the GDF patch following the instructions provided in [1316316/KB731274] (SECTION 34)',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 412');



debug('begin add_signature: 433');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Cancellation, Trial Balance';
   l_info('bug_number'):= '21832708';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2100488.1';
   l_info('problem'):= 'Cancelled R12 invoices with non-zero amount, missing reversal or parent distributions, or missing accounting event ID.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2100488.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3981',
      p_sig_id                 => '433',
      p_sig_sql                => 'WITH invs as (
     ##$$MIVIEW$$##
   )
   SELECT ai.invoice_id,
          ai.invoice_amount,
          1 type
   FROM invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(historical_flag, ''N'') = ''N''
   AND   cancelled_date is not null
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_lines_all ail
           WHERE ail.invoice_id = ai.invoice_id
           AND   ail.amount <> 0)
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_amount,
           2.1
   FROM invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(historical_flag, ''N'') = ''N''
   AND   cancelled_date is not null
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.parent_reversal_id is null
           AND   NOT EXISTS (
                   SELECT 1 FROM ap_invoice_distributions_all aid_rev
                   WHERE aid_rev.invoice_id = ai.invoice_id
                   AND   aid_rev.parent_reversal_id = aid.invoice_dIStribution_id))
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_amount,
          2.2
   FROM invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(historical_flag, ''N'') = ''N''
   AND   cancelled_date IS NOT NULL
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.parent_reversal_id IS NOT NULL
           AND   NOT EXISTS (
                   SELECT 1 FROM ap_invoice_distributions_all aid_par
                   WHERE aid_par.invoice_id = ai.invoice_id
                   AND   aid_par.invoice_distribution_id = aid.parent_reversal_id))
   UNION ALL
   SELECT ai.invoice_id,
          ai.invoice_amount,
          3
   FROM invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(historical_flag, ''N'') = ''N''
   AND   cancelled_date IS NOT NULL
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.accounting_event_id is null)',
      p_title                  => 'MGD-433',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Cancelled R12 invoices with non-zero amount, missing reversal or parent distributions, or missing accounting event ID.<br/><strong>Impact Area(s): </strong>Invoice Cancellation, Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>21832708</br><strong>Note: </strong>[2100488/KB751377]</br><strong>Script Name: </strong>ap_uncancel_inv_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2100488/KB751377]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 433');



debug('begin add_signature: 448');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Data';
