   l_info('problem'):= 'Incorrect accounting class code for self-assessed recoverable tax and self-assessed liability which may cause APP-ZX-999967220 errors during invoice entry when trying to setup or update tax.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2225565.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '5717',
      p_sig_id                 => '448',
      p_sig_sql                => '   SELECT DISTINCT
          xal.ae_header_id,
          xal.ae_line_num,
          xal.application_id,
          xal.code_combination_id,
          xal.gl_transfer_mode_code,
          xal.gl_sl_link_id,
          xal.accounting_class_code,
          xal.entered_dr,
          xal.entered_cr,
          xal.accounted_dr,
          xal.accounted_cr,
          xal.currency_code,
          xal.description,
          xal.accounting_date,
          xal.ledger_id,
          asad.invoice_id,
          asad.org_id,
          asad.invoice_line_number,
          asad.distribution_line_number,
          asad.invoice_distribution_id
  FROM  (
           ##$$IVIEW$$##
         ) invs,
         xla_ae_lines xal,
         xla_distribution_links xdl,
         ap_self_assessed_tax_dist_all asad,
         xla_ae_headers xah
   WHERE asad.invoice_id = invs.invoice_id
   AND   xal.application_id = 200
   AND   xal.accounting_class_code = ''SELF_ASSESSED_TAX''
   AND   xdl.application_id = 200
   AND   xal.ae_header_id = xdl.ae_header_id
   AND   xal.ae_line_num = xdl.ae_line_num
   AND   xdl.source_distribution_type = ''AP_INV_DIST''
   AND   xdl.source_distribution_id_num_1 = asad.INVOICE_DISTRIBUTION_ID
   AND   ((xdl.accounting_line_code IN (''AP_SELF_ASSESSED_REC_TAX_CM'',
             ''AP_SELF_ASSESSED_RECTAX_PREPAY'', ''AP_SELF_ASSESSED_REC_TAX_INV'',
             ''AP_SELF_ASSESSED_REC_TAX_DM'' ) AND
           NOT EXISTS (
             SELECT 1 FROM xla_distribution_links xdl1
             WHERE xdl1.application_id = 200
             ANd   xdl1.ae_header_id = xal.ae_header_id
             ANd   xdl1.ae_line_num = xal.ae_line_num
             ANd   xdl1.accounting_line_code NOT IN (''AP_SELF_ASSESSED_REC_TAX_CM'',
                    ''AP_SELF_ASSESSED_RECTAX_PREPAY'', ''AP_SELF_ASSESSED_REC_TAX_INV'',
                    ''AP_SELF_ASSESSED_REC_TAX_DM'' ))) OR
          (xdl.accounting_line_code IN (''AP_SELF_ASSESSED_TAX_CRL_INV'',
             ''AP_SELF_ASSESSED_TAX_CLR_CM'', ''AP_SELF_ASSESSED_TAX_CLR_DM'',
             ''AP_SELF_ASSESSED_TAX_LIB_PP'' ) AND
           NOT EXISTS (
             SELECT 1 FROM xla_distribution_links xdl1
             WHERE xdl1.application_id = 200
             AND   xdl1.ae_header_id = xal.ae_header_id
             AND   xdl1.ae_line_num = xal.ae_line_num
             AND   xdl1.accounting_line_code NOT IN (''AP_SELF_ASSESSED_TAX_CRL_INV'',
                     ''AP_SELF_ASSESSED_TAX_CLR_CM'', ''AP_SELF_ASSESSED_TAX_CLR_DM'',
                     ''AP_SELF_ASSESSED_TAX_LIB_PP'' ))))
   AND   xah.ae_header_id   = xdl.ae_header_id
   AND   xah.event_id       = asad.accounting_event_id
   AND   xah.application_id = 200',
      p_title                  => 'MGD-448',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incorrect accounting class code for self-assessed recoverable tax and self-assessed liability which may cause APP-ZX-999967220 errors during invoice entry when trying to setup or update tax.<br/><strong>Impact Area(s): </strong>Invoice Data',
      p_solution               => '<strong>Solution GDF: </strong>12322999</br><strong>Note: </strong>[2225565/KB157177]</br><strong>Script Name: </strong>ApSelfAssAccClassSel.sql</br></br>Apply the GDF patch following the instructions provided in [2225565/KB157177]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: 448');



debug('begin add_signature: 450');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'GL Transfer';
   l_info('bug_number'):= '9481239';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2225571.1';
   l_info('problem'):= 'Journals marked as transferred in SLA are not in the General Ledger.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2225571.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '5845',
      p_sig_id                 => '450',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, xte, h, l) */
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          h.event_id,
          h.ledger_id,
          h.application_id,
          h.ae_header_id,
          h.accounting_date,
          h.period_name,
          h.entity_id,
          h.gl_transfer_status_code,
          h.group_id,
          l.gl_sl_link_id,
          l.gl_sl_link_table
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers h,
        xla_ae_lines l
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(xte.source_id_int_1,-99) = ai.invoice_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.application_id = 200
   AND   h.application_id = xte.application_id
   AND   h.entity_id = xte.entity_id
   AND   h.gl_transfer_status_code=''Y''
   AND   h.accounting_entry_status_code=''F''
   AND   (h.upg_batch_id is null OR h.upg_batch_id = -9999)
   AND   h.ledger_id IN (
           SELECT gled.ledger_id
           FROM gl_ledger_relationships glr,
                gl_ledgers gled
           WHERE glr.primary_ledger_id = ai.set_of_books_id
           AND   glr.application_id = 101
           AND   ((glr.target_ledger_category_code IN (''SECONDARY'',''ALC'') AND
                   glr.relationship_type_code = ''SUBLEDGER'') OR
                  (glr.target_ledger_category_code IN (''PRIMARY'') AND
                   glr.relationship_type_code = ''NONE''))
           AND   glr.target_ledger_id = gled.ledger_id
           AND   nvl(gled.complete_flag,''Y'') = ''Y'')
   AND   l.application_id = h.application_id
   AND   l.ae_header_id = h.ae_header_id
   AND   l.gl_sl_link_id is not null
   AND   NOT EXISTS  (
           SELECT /*+ no_unnest */ 1
           FROM gl_import_references ir,
                gl_je_headers gh
           WHERE ir.gl_sl_link_id = l.gl_sl_link_id
           AND   ir.gl_sl_link_table = l.gl_sl_link_table
           AND   ir.je_header_id = gh.je_header_id
           AND   ir.je_batch_id = gh.je_batch_id
           AND   gh.ledger_id = h.ledger_id)',
      p_title                  => 'MGD-450',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Journals marked as transferred in SLA are not in the General Ledger.<br/><strong>Impact Area(s): </strong>GL Transfer',
      p_solution               => '<strong>Solution GDF: </strong>9481239</br><strong>Note: </strong>[2225571/KB410909]</br><strong>Script Name: </strong>xla_insla_notingl_sel.sql Invoice</br></br>Apply the GDF patch following the instructions provided in [2225571/KB410909]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 450');



debug('begin add_signature: 452');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'GL Transfer';
   l_info('bug_number'):= '13699255';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2225570.1';
   l_info('problem'):= 'EC12 Errors in Journal Import due to unnecessary Gain/Loss lines.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2225570.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '5850',
      p_sig_id                 => '452',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ai, xte, xah, xal, gll) */
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          xal.ae_header_id,
          sum(nvl(xal.accounted_dr,0)) sum_accounted_dr,
          sum(nvl(xal.accounted_cr,0)) sum_accounted_cr,
          sum(nvl(xal.entered_dr,0)) sum_entered_dr,
          sum(nvl(xal.entered_cr,0)) sum_entered_cr
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah,
        xla_ae_Lines xal,
        gl_ledgers gll
   WHERE ai.invoice_id = invs.invoice_id
   AND   nvl(xte.source_id_int_1,-99) = ai.invoice_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.application_id = 200
   AND   xah.application_id = xte.application_id
   AND   xah.entity_id = xte.entity_id
   AND   xah.ledger_id = xte.ledger_id
   AND   xah.gl_transfer_status_code = ''N''
   AND   xah.accounting_entry_status_code = ''F''
   AND   xal.application_id = xah.application_id
   AND   xal.ae_header_id = xah.ae_header_id
   AND   xal.gain_or_loss_flag = ''Y''
   AND   gll.ledger_id = xal.ledger_id
   AND   gll.currency_code = xal.currency_code
   GROUP BY ai.invoice_id, ai.invoice_num, ai.org_id, xal.ae_header_id
   HAVING   sum(nvl(xal.accounted_dr,0)) = sum(nvl(xal.accounted_cr,0))
   AND      sum(nvl(xal.entered_dr,0)) = sum(nvl(xal.entered_cr,0))',
      p_title                  => 'MGD-452',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'EC12 Errors in Journal Import due to unnecessary Gain/Loss lines.<br/><strong>Impact Area(s): </strong>GL Transfer',
      p_solution               => '<strong>Solution GDF: </strong>13699255</br><strong>Note: </strong>[2225570/KB301413]</br><strong>Script Name: </strong>xla_incorrect_gainloss_sel.sql Invoice</br></br>Apply the GDF patch following the instructions provided in [2225570/KB301413]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 452');



debug('begin add_signature: 470');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Approval, Payment Selection';
   l_info('bug_number'):= '24579872';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2202234.1';
   l_info('problem'):= 'Invoices which have been approved still have workflow status of INITIATED.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2202234.1.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '13811',
      p_sig_id                 => '470',
      p_sig_sql                => 'SELECT ai.invoice_id,
       ai.org_id,
       ai.invoice_num,
       ai.wfapproval_status,
       h.approval_history_id,
       h.response
FROM  (
        ##$$IVIEW$$##
      ) invs,
      ap_invoices_all ai,
      ap_inv_aprvl_hist_all h
WHERE ai.invoice_id = invs.invoice_id
AND   ai.wfapproval_status = ''INITIATED''
AND   h.invoice_id = ai.invoice_id
AND   h.response = ''APPROVED''
