debug('begin add_signature: 149');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Discarded invoice lines on non-paid, non-cancelled invoices which have no posted or tax distributions but with non-zero amounts or un-reversed distributions';
   l_info('solution'):= 'Log an SR and request the data fix from Doc ID 2184616.1.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4025',
      p_sig_id                 => '149',
      p_sig_sql                => 'SELECT ail.invoice_id,
          ail.org_id,
          ail.line_number
   FROM ap_invoice_lines_all ail,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE discarded_flag = ''Y''
   AND   EXISTS (
           SELECT 1 FROM ap_invoices_all ai
           WHERE ai.invoice_id = ail.invoice_id
           AND   ai.cancelled_date is  null)
   AND   ((nvl(ail.amount,0) <> 0 OR nvl(ail.base_amount,0) <> 0) OR
          EXISTS (
            SELECT 1 FROM ap_invoice_distributions_all  aid
            WHERE ail.invoice_id = aid.invoice_id
            AND   ail.line_number = aid.invoice_line_number
            AND   aid.parent_reversal_id is null
            AND   NOT EXISTS (
                    SELECT 1 FROM ap_invoice_distributions_all  aid1
                    WHERE aid1.invoice_id = aid.invoice_id
                    AND   aid1.invoice_line_number = aid.invoice_line_number
                    AND   aid1.parent_reversal_id = aid.invoice_distribution_id)))
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all  aid
           WHERE ail.invoice_id = aid.invoice_id
           AND   ail.line_number=aid.invoice_line_number
           AND   aid.posted_flag = ''Y'')
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE ail.invoice_id = aid.invoice_id
           AND   ail.line_number=aid.invoice_line_number
           AND   aid.line_type_lookup_code like  ''%TAX%'')
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_payments_all aip
           WHERE ail.invoice_id = aip.invoice_id )
   AND   ail.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-149',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Discarded invoice lines on non-paid, non-cancelled invoices which have no posted or tax distributions but with non-zero amounts or un-reversed distributions<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Script Name: </strong>None</br></br>Log an SR and request the data fix from [2184616/KB709451].',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: 149');



