debug('begin add_signature: 153');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Holds';
   l_info('bug_number'):= '10279750';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Canceled invoices which still have line or distribution variance holds';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for affected invoices and log a Service Request';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3887',
      p_sig_id                 => '153',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_amount,
          ai.payment_status_flag,
          ai.cancelled_date
   FROM ap_invoices_all ai,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE ai.cancelled_date is not null
   AND   ai.temp_cancelled_amount is not null
   AND   NOT EXISTS (
           SELECT ''non zero amt line'' FROM ap_invoice_lines_all ail
           WHERE ail.invoice_id = ai.invoice_id
           AND   ail.amount <> 0)
   AND   0 = (
           SELECT sum(amount) FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id)
   AND   EXISTS(
           SELECT ''line dist var hold'' FROM ap_holds_all ah
           WHERE ai.invoice_id = ah.invoice_id
           AND   ah.hold_lookup_code in (''LINE VARIANCE'',''DIST VARIANCE'')
           AND   ah.release_lookup_code is null)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-153',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Canceled invoices which still have line or distribution variance holds<br/><strong>Impact Area(s): </strong>Invoice Holds',
      p_solution               => '<strong>Bug Number: </strong>10279750</br><strong>Script Name: </strong>None</br></br>Generate the Create Accounting Analyzer ([1665706/KB627726]) output for affected invoices and log a Service Request',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: 153');



