   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Orphan non-recoverable tax distributions created due to bug 7422547, where a normal tax line is modified to be self-assessed';
