debug('end add_signature: 154');



debug('begin add_signature: 155');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Cancellation';
   l_info('bug_number'):= '10034598';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '2102440.1';
   l_info('problem'):= 'Paid invoices which have been allowed to be canceled due to incorrect payment status flag in ap_payment_schedules';
   l_info('solution'):= 'Apply the root cause fix from Doc ID 2102440.1 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3885',
      p_sig_id                 => '155',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.amount_paid,
          ai.invoice_currency_code,
          ai.payment_currency_code
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_payments_all p,
        financials_system_params_all fsp
   WHERE ai.invoice_id = invs.invoice_id
   AND   p.invoice_id = ai.invoice_id
   AND   nvl(p.reversal_flag,''N'') <> ''Y''
   AND   p.amount is not null
   AND   EXISTS (
           SELECT ''non void check'' FROM ap_checks_all A
           WHERE A.check_id = P.check_id
           AND   void_date is null)
   AND   ai.cancelled_date is not null
   AND   ai.cancelled_by is not null
   AND   fsp.org_id = ai.org_id
   AND   nvl(fsp.purch_encumbrance_flag, ''N'') = ''N''',
      p_title                  => 'MGD-155',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Paid invoices which have been allowed to be canceled due to incorrect payment status flag in ap_payment_schedules<br/><strong>Impact Area(s): </strong>Invoice Cancellation',
      p_solution               => '<strong>Bug Number: </strong>10034598</br><strong>Note: </strong>[2102440/KB438018]</br><strong>Script Name: </strong>paid_invoice_cancel_sel.sql</br></br>Apply the root cause fix from [2102440/KB438018] if you have not done so, and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
