debug('begin add_signature: 168');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect, EBTax';
   l_info('bug_number'):= '21118369';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Tax Invoice Price Variance (TIPV) distributions which are reversed but the reversal distributions are not created in R12.';
   l_info('solution'):= 'Apply the root cause fix from bug 16804798 if you have not done so, and then re-upgrade the affected invoice(s) using patch 20344709, following the instructions provided in Doc ID 1556126.1';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3950',
      p_sig_id                 => '168',
      p_sig_sql                => 'SELECT aid.invoice_id,
          aid.org_id,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          aid.reversal_flag,
          aid.cancellation_flag
   FROM ap_invoice_distributions_all aid,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE aid.line_type_lookup_code = ''TIPV''
   AND   aid.historical_flag = ''Y''
   AND   aid.parent_reversal_id     is null
   AND   aid.reversal_flag = ''Y''
   AND   NOT EXISTS (
           SELECT ''no reversal'' FROM ap_invoice_distributions_all aid1
           WHERE aid.invoice_id = aid1.invoice_id
           AND   aid.invoice_line_number = aid1.invoice_line_number
           AND   (aid.invoice_distribution_id = aid1.parent_reversal_id OR
                  aid.old_distribution_id = aid1.parent_reversal_id)
           AND   aid1.line_type_lookup_code = ''TIPV'')
   AND EXISTS (
         SELECT ''reversed in R12''
         FROM ap_invoice_distributions_all aid2,
              ap_invoice_distributions_all aid3
         WHERE aid.related_id = aid2.invoice_distribution_id
         AND   aid2.line_type_lookup_code LIKE ''%TAX''
         AND   aid2.parent_reversal_id       is null
         AND   (aid2.invoice_distribution_id = aid3.parent_reversal_id OR
                aid2.old_distribution_id = aid3.parent_reversal_id)
         AND nvl(aid3.historical_flag,''N'') = ''N'')
   AND   aid.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-168',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Tax Invoice Price Variance (TIPV) distributions which are reversed but the reversal distributions are not created in R12.<br/><strong>Impact Area(s): </strong>Accounting Incorrect, EBTax',
      p_solution               => '<strong>Bug Number: </strong>21118369</br><strong>Script Name: </strong>None</br></br>Apply the root cause fix from bug {16804798} if you have not done so, and then re-upgrade the affected invoice(s) using patch {20344709}, following the instructions provided in [1556126/KB501037]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '11'
      );
   l_info.delete;
debug('end add_signature: 168');



