   l_info('note_number'):= '2400290.1';
   l_info('problem'):= 'Debit or credit memo invoices with events having incorrect event types';
   l_info('solution'):= 'Please follow the steps in Doc ID 2400290.1 to help resolve the issue.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3946',
      p_sig_id                 => '185',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_type_lookup_code,
          xe.event_id,
          xe.event_type_code
   FROM xla_transaction_entities_upg xte,
        xla_events xe,
        ap_invoices_all ai,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   nvl(xte.security_id_int_1, -99) = ai.org_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.application_id = 200
   AND   ai.invoice_type_lookup_code IN (''CREDIT'', ''DEBIT'')
   AND   xe.entity_id = xte.entity_id
   AND   xe.event_type_code LIKE ''INVOICE%''
   AND   xe.application_id = 200
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-185',
