   l_info('solution'):= 'Please raise an SR for the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3948',
      p_sig_id                 => '187',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_amount,
          ai.invoice_date,
          aid.invoice_distribution_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.encumbered_flag,
          aid.match_status_flag,
          aid.bc_event_id,
          aid.accounting_event_id,
          aid.posted_flag
   FROM ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        financials_system_params_all fsp,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE ai.invoice_id = aid.invoice_id
   AND   fsp.purch_encumbrance_flag = ''Y''
   AND   aid.accounting_event_id is null
   AND   ai.cancelled_date is not null
   AND   fsp.org_id = ai.org_id
   AND   fsp.set_of_books_id = ai.set_of_books_id
   AND   aid.match_status_flag <> ''A''
   AND   nvl(aid.encumbered_flag, ''N'') <> ''R''
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all d1
           WHERE d1.invoice_id = ai.invoice_id
           AND   d1.historical_flag is null
           AND   encumbered_flag = ''Y'')
   AND   NOT EXISTS (
           SELECT 1 FROM ap_holds_all ah
           WHERE ah.invoice_id = ai.invoice_id
           AND   ah.release_lookup_code is null)
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-187',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Cancelled invoices with unapproved distributions even though there are no holds on the invoice<br/><strong>Impact Area(s): </strong>Invoice Cancellation',
