  add_signature(
      p_sig_repo_id            => '3986',
      p_sig_id                 => '190',
      p_sig_sql                => 'SELECT glps.period_name,
          glps.start_date,
          glps.end_date,
          glps.set_of_books_id,
          glps.application_id,
          glps.adjustment_period_flag
   FROM ap_invoices_all ai,
        gl_period_statuses glps,
        (
          ##$$IVIEW$$##
        ) invs
   WHERE ai.historical_flag = ''Y''
   AND   EXISTS (
           SELECT 1
           FROM ap_invoice_distributions_all aid,
