debug('begin add_signature: 193');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Prepay Application';
   l_info('bug_number'):= '11683638';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Zero amount prepayment application distributions with null or incorrect accounting events';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for affected invoices and log a Service Request';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3956',
      p_sig_id                 => '193',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ''Null Accounting_Event_ID'' category,
          ai.invoice_id,
          ai.invoice_num,
          aid.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_amount,
          ai.invoice_date,
          ail.line_number,
          ail.amount line_amount,
          ail.discarded_flag,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          aid.amount,
          aid.base_amount,
          aid.match_status_flag,
          aid.accounting_event_id event_id,
          ''N'' budgetary_control_flag,
          aid.bc_event_id,
          aid.encumbered_flag,
          aid.posted_flag,
          aid.prepay_distribution_id,
          aid.parent_reversal_id,
          aid.reversal_flag,
          aid.set_of_books_id
   FROM invs,
        ap_invoices_all ai,
        financials_system_params_all fsp,
        ap_invoice_distributions_all aid,
        ap_invoice_lines_all ail
   WHERE aid.invoice_id = ai.invoice_id
   AND   aid.invoice_id = ail.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   aid.line_type_lookup_code = ''PREPAY''
   AND   nvl(ail.discarded_flag, ''N'') <> ''Y''
   AND   aid.amount = 0
   AND   aid.prepay_distribution_id is not null
   AND   ai.org_id = fsp.org_id
   AND   ((nvl(fsp.purch_encumbrance_flag, ''N'') = ''Y'' AND
           aid.match_status_flag = ''A'') OR
          (nvl(fsp.purch_encumbrance_flag, ''N'') = ''N'' AND
           aid.match_status_flag IN (''A'', ''T'')))
   AND   aid.accounting_event_id is null
   AND   aid.posted_flag <> ''Y''
   AND   ai.invoice_id = invs.invoice_id
   UNION ALL
   SELECT ''Incorrect Event Type'' category,
          ai.invoice_id,
          ai.invoice_num,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.invoice_amount,
          ai.invoice_date,
          ail.line_number,
          ail.amount,
          ail.discarded_flag,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          aid.amount,
          aid.base_amount,
          aid.match_status_flag,
          aid.accounting_event_id,
          ''N'' budgetary_control_flag,
          aid.bc_event_id,
          aid.encumbered_flag,
          aid.posted_flag,
          aid.prepay_distribution_id,
          aid.parent_reversal_id,
          aid.reversal_flag,
          aid.set_of_books_id
   FROM invs,
        ap_invoices_all ai,
        financials_system_params_all fsp,
        ap_invoice_lines_all ail,
        ap_invoice_distributions_all aid,
        xla_events xe
   WHERE aid.invoice_id = ai.invoice_id
   AND   aid.invoice_id = ail.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   ail.discarded_flag = ''Y''
   AND   aid.line_type_lookup_code = ''PREPAY''
   AND   aid.amount = 0
   AND   aid.prepay_distribution_id is not null
   AND   ai.org_id = fsp.org_id
   AND   aid.accounting_event_id is not null
   AND   xe.application_id = 200
   AND   aid.accounting_event_id = xe.event_id
   AND   decode(aid.parent_reversal_id,
           null, ''PREPAYMENT APPLIED'',
           ''PREPAYMENT UNAPPLIED'') <> xe.event_type_code
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid1
           WHERE aid1.invoice_id = aid.invoice_id
           AND   aid1.invoice_line_number = aid.invoice_line_number
           AND   aid1.prepay_distribution_id is not null
           AND   aid1.posted_flag <> ''Y'')
   AND   ai.invoice_id = invs.invoice_id',
      p_title                  => 'MGD-193',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Zero amount prepayment application distributions with null or incorrect accounting events<br/><strong>Impact Area(s): </strong>Prepay Application',
      p_solution               => '<strong>Bug Number: </strong>11683638</br><strong>Script Name: </strong>None</br></br>Generate the Create Accounting Analyzer ([1665706/KB627726]) output for affected invoices and log a Service Request</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '10'
      );
   l_info.delete;
debug('end add_signature: 193');



debug('begin add_signature: 279');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '2678821.1';
   l_info('problem'):= 'Create Accounting for Invoices fails with error number 95314: The entered amount and accounted amount for line xx are not on the same side.';
   l_info('solution'):= '<ul>
   <li>Please follow the instructions as detailed in Doc ID 2678821.1 to help resolve the issue.</li>
<li>If the above still does not resolve the 95314 error, please update the SR to request a data fix. </li></ul>';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4032',
      p_sig_id                 => '279',
      p_sig_sql                => 'WITH invs AS
        (
          ##$$MIVIEW$$##
        )
   SELECT ''INVOICE'' category,
          aid.invoice_id,
          aid.description,
          aid.dist_code_combination_id,
          aid.line_type_lookup_code,
          aid.accounting_event_id,
          sum(aid.amount) amount,
          sum(aid.base_amount) base_amount
   FROM ap_invoice_distributions_all aid
   WHERE (nvl(aid.description,'' ''), aid.dist_code_combination_id,
           aid.line_type_lookup_code, aid.accounting_event_id) IN (
             SELECT nvl(aid2.description,'' ''), aid2.dist_code_combination_id,
                    aid2.line_type_lookup_code, aid2.accounting_event_id
             FROM invs,
                  ap_invoice_distributions_all aid2
             WHERE aid2.invoice_id = invs.invoice_id
             AND   aid2.posted_flag <> ''Y''
             GROUP BY nvl(aid2.description,'' ''), aid2.dist_code_combination_id,
                      aid2.line_type_lookup_code, aid2.accounting_event_id
             HAVING   sum(aid2.amount) * sum(aid2.base_amount) < 0 )
   AND   NOT EXISTS (
           SELECT ''No opp. sign dists'' FROM ap_invoice_distributions_all
           WHERE invoice_id = aid.invoice_id
           AND (amount * base_amount) < 0)
   GROUP BY aid.invoice_id, aid.description,
          aid.dist_code_combination_id, aid.line_type_lookup_code,
          aid.accounting_event_id
   UNION
   SELECT ''TAX'',
          aid.invoice_id,
          aid.description,
          aid.dist_code_combination_id,
          aid.line_type_lookup_code,
          aid.accounting_event_id,
          sum(aid.amount) amount,
          sum(aid.base_amount) base_amount
   FROM ap_self_assessed_tax_dist_all aid
   WHERE (nvl(aid.description,'' ''), aid.dist_code_combination_id,
           aid.line_type_lookup_code, aid.accounting_event_id) IN (
             SELECT nvl(aid2.description,'' ''), aid2.dist_code_combination_id,
                    aid2.line_type_lookup_code, aid2.accounting_event_id
             FROM invs,
                  ap_self_assessed_tax_dist_all aid2
             WHERE aid2.invoice_id = invs.invoice_id
             AND   aid2.posted_flag <> ''Y''
             GROUP BY nvl(aid2.description,'' ''), aid2.dist_code_combination_id,
                      aid2.line_type_lookup_code, aid2.accounting_event_id
             HAVING sum(aid2.amount) * sum(aid2.base_amount) < 0 )
   AND   NOT EXISTS (
           SELECT ''No opp. sign dists''
           FROM ap_self_assessed_tax_dist_all
           WHERE invoice_id=aid.invoice_id
           AND (amount * base_amount) < 0)
   GROUP BY aid.invoice_id, aid.description,
          aid.dist_code_combination_id, aid.line_type_lookup_code,
          aid.accounting_event_id',
      p_title                  => 'MGD-279',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Create Accounting for Invoices fails with error number 95314: The entered amount and accounted amount for line xx are not on the same side.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Note: </strong>[2678821/KB163920]</br><strong>Script Name: </strong>None</br></br><ul>
   <li>Please follow the instructions as detailed in [2678821/KB163920] to help resolve the issue.</li>
<li>If the above still does not resolve the 95314 error, please update the SR to request a data fix. </li></ul>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 279');



