      p_sig_id                 => '281',
      p_sig_sql                => 'WITH invs as (
     ##$$MIVIEW$$##
   )
   SELECT /*+ leading(invs) use_nl(zl) */
          zl.trx_id invoice_id,
          zl.trx_level_type,
          zl.trx_line_number,
          zl.tax_line_id
   FROM invs,
        zx_lines zl
   WHERE zl.trx_id = invs.invoice_id
   AND   zl.application_id = 200
   AND   zl.entity_code = ''AP_INVOICES''
   AND   zl.event_class_code IN (''STANDARD INVOICES'',''EXPENSE REPORTS'',
           ''PREPAYMENT INVOICES'')
   AND   NOT EXISTS (
           SELECT 1 FROM zx_lines_det_factors zldf
           WHERE zldf.trx_id = zl.trx_id
           AND   zldf.application_id = zl.application_id
           AND   zldf.entity_code = zl.entity_code
           AND   zldf.event_class_code = zl.event_class_code
           AND   zldf.trx_line_id = zl.trx_line_id
           AND   nvl(zldf.trx_level_type,''X'') = nvl(zl.trx_level_type,''X''))
   AND   NOT EXISTS (
           SELECT 1 FROM zx_rec_nrec_dist zd
           WHERE zd.trx_id = zl.trx_id
           AND   zd.application_id = zl.application_id
           AND   zd.entity_code = zl.entity_code
           AND   zd.event_class_code = zl.event_class_code
           AND   zd.tax_line_id = zl.tax_line_id)
   UNION
   SELECT /*+ leading(invs)use_nl(zl) */
          zl.trx_id invoice_id,
          zl.trx_level_type,
          zl.trx_line_number,
          zl.tax_line_id
   FROM invs,
        zx_lines zl
   WHERE zl.trx_id = invs.invoice_id
   AND   zl.application_id = 200
   AND   zl.entity_code = ''AP_INVOICES''
   AND   zl.event_class_code IN (''STANDARD INVOICES'',''EXPENSE REPORTS'',
           ''PREPAYMENT INVOICES'')
   AND   zl.tax_amt IS NULL
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_lines_all ail
           WHERE ail.invoice_id = zl.trx_id
           AND   ail.line_number = zl.trx_line_id
           AND   ail.line_type_lookup_code <> ''TAX''
           AND   (nvl(ail.discarded_flag,''N'') = ''Y'' OR
           nvl(ail.cancelled_flag,''N'') = ''Y''))
   AND   NOT EXISTS (
           SELECT 1 FROM zx_rec_nrec_dist zd
           WHERE zd.trx_id = zl.trx_id
           AND   zd.application_id = zl.application_id
           AND   zd.entity_code = zl.entity_code
           AND   zd.event_class_code = zl.event_class_code
           AND   zd.tax_line_id = zl.tax_line_id)',
      p_title                  => 'MGD-281',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Non-cancelled tax lines with null tax_amt and which is allocated to a trx line which does not exist in ZX_LINES_DET_FACTORS or is discared, causing tax calculation failure: Cannot update AP_INVOICE_LINES_ALL.AMOUNT to NULL.<br/><strong>Impact Area(s): </strong>EBTax',
      p_solution               => '<strong>Note: </strong>[1316316/KB731274]</br><strong>Script Name: </strong>None</br></br>Follow the instructions provided in [1316316/KB731274] section #24.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 281');



