debug('begin add_signature: 307');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'The incorrect account is charged for prepay application encumbrance reversal accounting.';
   l_info('solution'):= 'Apply the root cause fix from bug 13620905 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4048',
      p_sig_id                 => '307',
      p_sig_sql                => 'SELECT aid.invoice_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.amount,
          aid.base_amount,
          apad.prepay_app_dist_id,
          apad.invoice_distribution_id,
          aid.dist_code_combination_id,
          xal.ae_header_id,
          xal.ae_line_num,
          xal.code_combination_id,
          xal.accounting_class_code,
          xal.entered_dr,
          xal.entered_cr,
          xal.upg_batch_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        xla_ae_headers xah,
        xla_events xe,
        xla_transaction_entities_upg xte,
        xla_ae_lines xal,
        xla_distribution_links xdl,
        ap_prepay_app_dists apad,
        ap_invoice_distributions_all aid
   WHERE aid.invoice_id = invs.invoice_id
   AND   nvl(xe.upg_batch_id, -9999) = -9999
   AND   xe.budgetary_control_flag = ''N''
   AND   xe.application_id = 200
   AND   xte.entity_id = xe.entity_id
   AND   xte.application_id = 200
   AND   xah.application_id = xe.application_id
   AND   xah.event_id = xe.event_id
   AND   xah.balance_type_code = ''E''
   AND   xah.ledger_id = xte.ledger_id
   AND   xah.ae_header_id = xal.ae_header_id
   AND   xal.application_id = xah.application_id
   AND   xal.accounting_class_code = ''PREPAID_EXPENSE''
   AND   xal.ae_header_id = xdl.ae_header_id
   AND   xal.ae_line_num = xdl.ae_line_num
   AND   xdl.application_id = xal.application_id
   AND   xdl.source_distribution_type = ''AP_PREPAY''
   AND   xdl.source_distribution_id_num_1 = apad.prepay_app_dist_id
   AND   apad.prepay_app_distribution_id = aid.invoice_distribution_id
   AND   aid.prepay_distribution_id is not null
   AND   aid.dist_code_combination_id <> xal.code_combination_id',
      p_title                  => 'MGD-307',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The incorrect account is charged for prepay application encumbrance reversal accounting.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Script Name: </strong>ap_x_pp_exp_enc_rev_acct_s.sql</br></br>Apply the root cause fix from bug {13620905} if you have not done so, and log a Service Request to obtain the data fix.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
