debug('end add_signature: 307');



debug('begin add_signature: 308');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Cancellation';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Invoices have incorrect quantity variance reversals, resulting in incorect encumbrance accounting.';
   l_info('solution'):= 'Apply the root cause fix from bug 12362963 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3995',
      p_sig_id                 => '308',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_type_lookup_code,
          ai.invoice_date,
          ai.invoice_amount,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.invoice_distribution_id,
          aid.amount,
          aid.base_amount,
          aid.match_status_flag,
          aid.encumbered_flag,
          aid.posted_flag,
          aid.bc_event_id,
          aid.accounting_event_id event_id,
          aid.org_id,
          aid.set_of_books_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        financials_system_params_all fsp,
        po_distributions_all pod,
        po_line_locations_all pll,
        xla_events xe,
        xla_ae_headers xah,
        xla_distribution_links xdl
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_type_lookup_code = ''CREDIT''
   AND   aid.invoice_id = ai.invoice_id
   AND   aid.quantity_variance is not null
   AND   aid.org_id = fsp.org_id
   AND   nvl(fsp.purch_encumbrance_flag, ''N'') = ''Y''
   AND   aid.line_type_lookup_code IN (''NONREC_TAX'', ''TRV'')
   AND   aid.po_distribution_id = pod.po_distribution_id
   AND   pod.line_location_id = pll.line_location_id
   AND   nvl(pll.accrue_on_receipt_flag, ''N'') = ''N''
   AND   aid.bc_event_id = xe.event_id
   AND   xe.budgetary_control_flag = ''Y''
   AND   xe.application_id = 200
   AND   xe.event_id = xah.event_id
   AND   xe.event_status_code = ''P''
   AND   xah.application_id = 200
   AND   xah.balance_type_code = ''E''
   AND   xah.ae_header_id = xdl.ae_header_id
   AND   xdl.application_id = 200
   AND   xdl.source_distribution_type = ''AP_INV_DIST''
   AND   xdl.source_distribution_id_num_1 = aid.invoice_distribution_id
   AND   xdl.accounting_line_code = ''AP_QUANTITY_VARIANCE_CM_ENC_DR''
   AND   nvl(xdl.unrounded_entered_dr, xdl.unrounded_entered_cr) <> 0
   AND   aid.posted_flag = ''Y''
   AND   NOT EXISTS (
           SELECT /*+ index(xdl1 XLA_DISTRIBUTION_LINKS_N1) */ 1
           FROM xla_distribution_links xdl1,
                xla_ae_headers xah1,
                xla_events xe1
           WHERE xe1.application_id = 200
           AND   xdl1.application_id = 200
           AND   xdl1.source_distribution_type = ''AP_INV_DIST''
           AND   xdl1.source_distribution_id_num_1 = aid.invoice_distribution_id
           AND   xdl1.accounting_line_code = ''AP_TAX_QTY_VARIANCE_CM_ENC''
           AND   xdl1.ae_header_id = xah1.ae_header_id
           AND   xah1.balance_type_code = ''E''
           AND   xah1.event_id = xe1.event_id
           AND   nvl(xe1.budgetary_control_flag, ''N'') = ''N'')',
      p_title                  => 'MGD-308',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices have incorrect quantity variance reversals, resulting in incorect encumbrance accounting.<br/><strong>Impact Area(s): </strong>Invoice Cancellation',
      p_solution               => '<strong>Script Name: </strong>cm_tqv_no_rev_sel.sql</br></br>Apply the root cause fix from bug {12362963} if you have not done so, and log a Service Request to obtain the data fix.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 308');



debug('begin add_signature: 309');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Trial Balance';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'When automatic offsets are enabled on the balancing segment, different liability accounts are being charged for exchange rate variance (ERV) and their related distributions. This causes problems with the trial balance.';
   l_info('solution'):= 'Apply the root cause fix from bug 13508145 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3970',
      p_sig_id                 => '309',
      p_sig_sql                => 'SELECT aidv.invoice_id,
          aidv.invoice_distribution_id var_dist_id,
          aidv.line_type_lookup_code var_line_type,
          aidv.amount var_amount,
          aidv.base_amount var_base_amount,
          aidv.accounting_event_id var_event_id,
          aidr.invoice_distribution_id related_dist_id,
          aidr.line_type_lookup_code related_line_type,
          aidr.amount related_dist_amount,
          aidr.base_amount related_base_amount,
          aidr.accounting_event_id related_dist_event_id,
          xdlv.ae_header_id,
          xdlv.ae_line_num,
          xalv.entered_dr,
          xalv.entered_cr,
          xalv.accounted_dr,
          xalv.accounted_cr,
          xalv.ledger_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoice_distributions_all aidv ,
        ap_invoice_distributions_all aidr,
        xla_distribution_links xdlv,
        xla_ae_lines xalv,
        xla_distribution_links xdlr,
        xla_ae_lines xalr
   WHERE aidv.invoice_id = invs.invoice_id
   AND   aidv.invoice_id = aidr.invoice_id
   AND   aidv.related_id = aidr.invoice_distribution_id
   AND   aidv.invoice_distribution_id <> aidr.invoice_distribution_id
   AND   aidv.line_type_lookup_code IN (''ERV'', ''TERV'')
   AND   xdlv.application_id = 200
   AND   xdlv.source_distribution_type = ''AP_INV_DIST''
   AND   xdlv.source_distribution_id_num_1 = aidv.invoice_distribution_id
   AND   xdlv.accounting_line_code LIKE ''%LIAB%''
   AND   xalv.application_id = xdlv.application_id
   AND   xalv.ae_header_id = xdlv.ae_header_id
   AND   xalv.ae_line_num = xdlv.ae_line_num
   AND   xalv.accounting_class_code LIKE ''LIABILITY''
   AND   xdlr.application_id = 200
   AND   xdlr.source_distribution_type = ''AP_INV_DIST''
   AND   xdlr.source_distribution_id_num_1 = aidr.invoice_distribution_id
   AND   xdlr.accounting_line_code LIKE ''%LIAB%''
   AND   xalr.application_id = xdlr.application_id
   AND   xalr.ae_header_id = xdlr.ae_header_id
   AND   xalr.ae_line_num = xdlr.ae_line_num
   AND   xalr.accounting_class_code LIKE ''LIABILITY''
   AND   xalv.ledger_id = xalr.ledger_id
   AND   xalv.code_combination_id <> xalr.code_combination_id',
      p_title                  => 'MGD-309',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'When automatic offsets are enabled on the balancing segment, different liability accounts are being charged for exchange rate variance (ERV) and their related distributions. This causes problems with the trial balance.<br/><strong>Impact Area(s): </strong>Trial Balance',
      p_solution               => '<strong>Script Name: </strong>ap_erv_accrual_diff_liab_ccid.txt</br></br>Apply the root cause fix from bug {13508145} if you have not done so, and log a Service Request to obtain the data fix.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 309');



