debug('begin add_signature: 313');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect, Invoice Holds';
   l_info('bug_number'):= '20312904';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2632112.1';
   l_info('problem'):= 'Invoices which have not been encumbered because the encumbrance accounting hold was released manually.';
   l_info('solution'):= 'Follow the instructions as detailed in Doc ID 2632112.1 to download the data fix script.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4008',
      p_sig_id                 => '313',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.invoice_amount,
          aid.invoice_distribution_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.base_amount,
          aid.line_type_lookup_code,
          aid.match_status_flag,
          aid.bc_event_id,
          aid.accounting_event_id,
          aid.encumbered_flag,
          aid.posted_flag,
          ai.cancelled_date,
          aid.org_id,
          aid.set_of_books_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        po_distributions_all pod,
        po_line_locations_all pll,
        financials_system_params_all fsp
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.invoice_id = ai.invoice_id
   AND   ai.org_id = fsp.org_id
   AND   fsp.purch_encumbrance_flag = ''Y''
   AND   aid.po_distribution_id = pod.po_distribution_id(+)
   AND   pod.line_location_id = pll.line_location_id(+)
   AND   aid.amount <> 0
   AND   aid.line_type_lookup_code <> ''REC_TAX''
   AND   (aid.po_distribution_id is null OR
          nvl(pll.accrue_on_receipt_flag, ''N'') = ''N'')
   AND   aid.match_status_flag = ''A''
   AND   NOT EXISTS (
           SELECT 1 FROM xla_events xe
           WHERE xe.event_id = aid.bc_event_id
           AND   xe.application_id = 200
           AND   xe.event_status_code = ''P''
           AND   xe.process_status_code = ''P'')
   AND   NOT EXISTS (
           SELECT 1 FROM ap_encumbrance_lines_all ael
           WHERE ael.invoice_distribution_id = aid.invoice_distribution_id
           AND   aid.encumbered_flag = ''Y'')
   AND   EXISTS (
           SELECT 1 FROM ap_holds_all aha
           WHERE aha.invoice_id = ai.invoice_id
           AND   aha.hold_lookup_code = ''Encumbrance Acctg Fail''
           AND   aha.release_lookup_code is not null
           AND   aha.release_lookup_code <> ''Encumbrance Acctg Ok''
           UNION
           SELECT 1
           FROM ap_holds_all aha,
                ap_hold_codes ahc
           WHERE aha.invoice_id = ai.invoice_id
           AND   aha.hold_lookup_code = ''Encumbrance Acctg Fail''
           AND   aha.release_lookup_code is null
           AND   aha.hold_lookup_code = ahc.hold_lookup_code
           AND   ahc.postable_flag = ''Y'')',
      p_title                  => 'MGD-313',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices which have not been encumbered because the encumbrance accounting hold was released manually.<br/><strong>Impact Area(s): </strong>Accounting Incorrect, Invoice Holds',
      p_solution               => '<strong>Solution GDF: </strong>20312904</br><strong>Note: </strong>[2632112/KB779171]</br><strong>Script Name: </strong>ap_unenc_inv_rel_hold_sel.sql</br></br>Follow the instructions as detailed in Doc ID 2632112.1 to download the data fix script.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 313');



