debug('begin add_signature: 315');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Prepay application accounting fails when final application rounding has been calculated on a deferred recoverable tax distribution and it is unable to find a required business flow item on the prepayment invoice''s payment.';
   l_info('solution'):= 'Apply the root cause fix from bug 13705794 (on 12.1) or bug 14113056 (on 12.0) if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4112',
      p_sig_id                 => '315',
      p_sig_sql                => 'SELECT apad.prepay_app_dist_id,
          apph.invoice_id,
          apad.prepay_dist_lookup_code,
          xal.ae_header_id,
          xal.ae_line_num,
          xal.code_combination_id,
