debug('begin add_signature: 328');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'An invoice validation event is accounted using Encumbrance Cash accounting setup. Subsequently the setup is changed to use Accrual Basis accounting and the invoice is cancelled. Since there are no parent distributions links in XLA_DISTRIBUTION_LINKS for the original validation event, the cancelled event fails to get accounted.';
   l_info('solution'):= 'Diagnostic information only. Please generate the Create Accounting Analyzer output for affected invoices and log a Service Request';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4114',
      p_sig_id                 => '328',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_type_lookup_code,
          ai.invoice_date,
          ai.invoice_amount,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.line_type_lookup_code,
          aid.amount,
          aid.base_amount,
          aid.accounting_event_id,
          aid.invoice_distribution_id,
          ai.org_id,
          xe.event_id,
          xe.event_type_code,
          xte.source_id_int_1 invoice_id,
          xte.transaction_number,
          xe.transaction_date,
          xte.entity_code source_type,
          xte.ledger_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        gl_ledgers gl,
        xla_events xe,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   xte.application_id = 200
   AND   xte.entity_code = ''AP_INVOICES''
   AND   nvl(xte.source_id_int_1,-99) = ai.invoice_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   gl.ledger_id = xte.ledger_id
   AND   nvl(gl.sla_ledger_cash_basis_flag, ''N'') = ''N''
   AND   xe.entity_id = xte.entity_id
   AND   xe.application_id = xte.application_id
   AND   xe.event_type_code LIKE ''INVOICE%CANCELLED''
   AND   xe.event_status_code <> ''P''
   AND   xe.budgetary_control_flag = ''N''
   AND   aid.invoice_id = ai.invoice_id
   AND   EXISTS (
           SELECT 1 FROM xla_events xe1
           WHERE xe1.application_id = 200
           AND   xe1.event_type_code LIKE ''INVOICE%VALIDATED''
           AND   xe1.entity_id = xe.entity_id
           AND   xe1.budgetary_control_flag = ''N''
           AND   xe1.event_status_code = ''P''
           AND   EXISTS (
                   SELECT 1 FROM ap_invoice_distributions_all aid
                   WHERE aid.accounting_event_id = xe1.event_id
                   AND   aid.cash_posted_flag = ''Y'')
           AND   NOT EXISTS (
                   SELECT 1 FROM xla_ae_headers xah1
                   WHERE xah1.application_id = 200
                   AND   xah1.event_id = xe1.event_id
                   AND   xah1.accounting_entry_status_code = ''F''))',
      p_title                  => 'MGD-328',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'An invoice validation event is accounted using Encumbrance Cash accounting setup. Subsequently the setup is changed to use Accrual Basis accounting and the invoice is cancelled. Since there are no parent distributions links in XLA_DISTRIBUTION_LINKS for the original validation event, the cancelled event fails to get accounted.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Script Name: </strong>None</br></br>Diagnostic information only. Please generate the Create Accounting Analyzer ([1665706/KB627726]) output for affected invoices and log a Service Request',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: 328');



debug('begin add_signature: 331');
