  add_signature(
      p_sig_repo_id            => '4074',
      p_sig_id                 => '331',
      p_sig_sql                => 'SELECT /* leading (invs) */
        ai.invoice_id,
        ai.invoice_num,
        ai.invoice_date,
        ai.org_id,
        xah.ae_header_id,
        xah.entity_id,
        xah.gl_transfer_status_code,
        xal.ae_header_id,
        xal.ae_line_num,
        xal.entered_dr,
        xal.entered_cr,
        xal.accounted_dr,
        xal.accounted_cr
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah,
        xla_ae_lines xal
   WHERE ai.invoice_id = invs.invoice_id
   AND   xte.ledger_id = ai.set_of_books_id
   AND   nvl(xte.source_id_int_1, -99) = ai.invoice_id
   AND   xte.application_id = 200
   AND   xte.entity_code IN (''AP_INVOICES'')
   AND   xah.application_id = 200
and   xah.ae_header_id=xal.ae_header_id ---Adding this line from feedback 205694
   AND   xah.entity_id = xte.entity_id
   AND   xah.gl_transfer_status_code = ''N''
   AND   xal.application_id = 200
   AND   (abs(nvl(xal.entered_dr,xal.entered_cr)) >= 1000000000000000000000000 OR
          abs(nvl(xal.accounted_dr,xal.accounted_cr)) >= 1000000000000000000000000 )
   AND   NOT EXISTS (
           SELECT 1 FROM xla_ae_headers xah1
           WHERE xah1.application_id = 200
           AND   xah1.entity_id = xte.entity_id
           AND   xah1.event_id  = xah.event_id
           AND   xah1.gl_transfer_status_code = ''Y'')',
      p_title                  => 'MGD-331',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'GL Transfer fails with exception EC13 due to very large amounts on the accounting lines.<br/><strong>Impact Area(s): </strong>GL Transfer',
      p_solution               => '<strong>Bug Number: </strong>16843556</br><strong>Note: </strong>[1562871/KB760709]</br><strong>Script Name: </strong>ap_gl_trnsfr_ec13_sel.sql Invoice</br></br>Apply the root cause fix from bug {16843556} if you have not done so, and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
