debug('begin add_signature: 339');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Discard';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Prepayment invoice lines with an original_amount value have discarded_flag = Y causing them not to be available for application.';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for the affected invoices and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4064',
      p_sig_id                 => '339',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_type_lookup_code,
          ai.amount_paid,
          ail.line_number,
          ail.amount,
          ail.original_amount,
          ail.discarded_flag,
          ail.line_type_lookup_code
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp,
        ap_invoice_lines_all ail
   WHERE ai.invoice_id = invs.invoice_id
   AND   ail.invoice_id = ai.invoice_id
   AND   ai.org_id = asp.org_id
   AND   asp.base_currency_code = ai.invoice_currency_code
   AND   ai.historical_flag is null
   AND   ai.amount_paid > 0
   AND   ai.payment_status_flag = ''Y''
   AND   ai.invoice_type_lookup_code = ''PREPAYMENT''
   AND   ail.amount > 0
   AND   ail.original_amount is not null
   AND   ail.discarded_flag = ''Y''
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ail.invoice_id
           AND   aid.invoice_line_number = ail.line_number
           AND   aid.parent_reversal_id is not null)',
      p_title                  => 'MGD-339',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Prepayment invoice lines with an original_amount value have discarded_flag = Y causing them not to be available for application.<br/><strong>Impact Area(s): </strong>Invoice Discard',
      p_solution               => '<strong>Script Name: </strong>ap_pre_unv_wrng_disc_flg_sel.sql</br></br>Generate the Create Accounting Analyzer ([1665706/KB627726]) output for the affected invoices and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
