debug('begin add_signature: 355');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Base Amount is null on unpaid, unaccounted, upgraded AWT invoice distributions causing payments to be stuck in accounting and the invoices to remain on the trial balance.';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for the affected invoices and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4057',
      p_sig_id                 => '355',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.historical_flag,
          aid.base_amount
   FROM invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp,
        ap_invoice_distributions_all aid,
        ap_payment_hist_dists aphd,
        xla_events xe
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code = ''AWT''
   AND   ai.invoice_id = aid.invoice_id
   AND   ai.invoice_currency_code = asp.invoice_currency_code
   AND   ai.org_id = asp.org_id
   AND   aid.base_amount is null
   AND   aid.awt_invoice_payment_id is not null
   AND   aid.historical_flag = ''Y''
   AND   aphd.invoice_distribution_id = aid.invoice_distribution_id
   AND   aphd.accounting_event_id = xe.event_id
   AND   xe.application_id = 200
   AND   (nvl(xe.upg_batch_id,-9999) = -9999 OR
          xe.event_status_code <> ''P'')
   UNION
   SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.historical_flag,
          aid.base_amount
   FROM invs,
        ap_invoices_all ai,
        ap_system_parameters_all asp,
        ap_invoice_distributions_all aid
   WHERE ai.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code = ''AWT''
   AND   ai.invoice_id = aid.invoice_id
   AND   ai.invoice_currency_code = asp.invoice_currency_code
   AND   ai.org_id = asp.org_id
   AND   aid.base_amount is null
   AND   aid.awt_invoice_payment_id is not null
   AND   aid.historical_flag = ''Y''
   AND   (ai.payment_status_flag IN (''N'',''P'') OR
          aid.posted_flag <> ''Y'')',
      p_title                  => 'MGD-355',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Base Amount is null on unpaid, unaccounted, upgraded AWT invoice distributions causing payments to be stuck in accounting and the invoices to remain on the trial balance.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Script Name: </strong>upg_awt_base_amt_null_sel.sql</br></br>Generate the Create Accounting Analyzer ([1665706/KB627726]) output for the affected invoices and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 355');



