debug('begin add_signature: 365');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Mass Additions';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1497203.1';
   l_info('problem'):= 'Miscellaneous, freight, or tax invoice distributions have incorrect assets_tracking_flag/asset_addition_flag values.';
   l_info('solution'):= 'Apply the root cause fix from bug 13821160 (12.0) or 14466506 (12.1) if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4098',
      p_sig_id                 => '365',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ''1'' corruption_type,
          aid.invoice_id,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.assets_tracking_flag,
          aid.assets_addition_flag,
          aid.accounting_date,
          aid.set_of_books_id
   FROM invs,
        ap_invoice_distributions_all aid
   WHERE aid.invoice_id = invs.invoice_id
   AND   nvl(aid.charge_applicable_to_dist_id,
           aid.corrected_invoice_dist_id) is null
   AND   aid.line_type_lookup_code IN (''MISCELLANEOUS'',
           ''FREIGHT'',''NONREC_TAX'',''REC_TAX'')
   AND   aid.posted_flag = ''Y''
   AND   aid.assets_tracking_flag = ''Y''
   AND   aid.assets_addition_flag = ''N''
   UNION ALL
   SELECT ''2'' CORRUPTION_TYPE,
          aid.invoice_id,
          aid.invoice_distribution_id,
          aid.line_type_lookup_code,
          aid.assets_tracking_flag,
          aid.assets_addition_flag,
          aid.accounting_date,
          aid.set_of_books_id
   FROM invs,
        ap_invoice_distributions_all aid,
        gl_code_combinations gcc
   WHERE aid.invoice_id = invs.invoice_id
   AND   nvl(aid.charge_applicable_to_dist_id,
