debug('begin add_signature: 369');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '9954778';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1300611';
   l_info('problem'):= 'Non-recoverable tax distributions assigned the account from the recoverable tax account from the tax setup rather than the account of the ITEM line to which the tax is applicable.';
   l_info('solution'):= 'Apply the GDF patch and code fix patch as detailed in [1300611/KB730058] to help resolve the issue.';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4160',
      p_sig_id                 => '369',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT /*+ leading(invs) */
         ''NORMAL TAX'' "TAX TYPE",
         aid.invoice_distribution_id,
         aid.invoice_id,
         aid.org_id,
         aid.line_type_lookup_code,
         aid.dist_code_combination_id "NONREC_TAX_ACCOUNT",
         aid1.dist_code_combination_id "REC_TAX_ACCOUNT",
         aid.charge_applicable_to_dist_id,
         aid.posted_flag,
         nvl(aid.encumbered_flag,''N'') encumbered_flag,
         aid.bc_event_id
   FROM invs,
        ap_invoices_all ai,
        ap_invoice_distributions_all aid,
        ap_invoice_distributions_all aid1,
        zx_rec_nrec_dist zrnd
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.historical_flag is null
   AND   ai.invoice_id = aid.invoice_id
   AND   aid.invoice_id = aid1.invoice_id
   AND   ai.cancelled_date is null
   AND   aid1.detail_tax_dist_id is not null
   AND   aid.detail_tax_dist_id is not null
   AND   aid.detail_tax_dist_id = zrnd.rec_nrec_tax_dist_id
   AND   aid.invoice_id = zrnd.trx_id
   AND   zrnd.application_id = 200
   AND   zrnd.entity_code = ''AP_INVOICES''
   AND   zrnd.applied_from_tax_dist_id is null
   AND   nvl(ai.quick_credit,''N'') <> ''Y''
   AND   aid.line_type_lookup_code = ''NONREC_TAX''
   AND   aid1.line_type_lookup_code = ''REC_TAX''
   AND   aid.charge_applicable_to_dist_id = aid1.charge_applicable_to_dist_id
   AND   aid.dist_code_combination_id = aid1.dist_code_combination_id
   AND   NOT EXISTS(
           SELECT 1 FROM ap_invoice_distributions_all aid3
           WHERE aid3.invoice_distribution_id = aid.charge_applicable_to_dist_id
           AND   (aid3.project_id is not null OR
                  aid3.po_distribution_id is not null))
   UNION ALL
   SELECT /*+ leading(invs)*/
          ''SELF_ASSESSED'',
          satx.invoice_distribution_id,
          satx.invoice_id,
          satx.org_id,
          satx.line_type_lookup_code,
          satx.dist_code_combination_id "NONREC_TAX_ACCOUNT",
          satx1.dist_code_combination_id "REC_TAX_ACCOUNT",
          satx.charge_applicable_to_dist_id,
          satx.posted_flag,
          nvl(satx.encumbered_flag,''N'') encumbered_flag,
          satx.bc_event_id
   FROM invs,
        ap_invoices_all ai,
        ap_self_assessed_tax_dist_all satx,
        ap_self_assessed_tax_dist_all satx1,
        zx_rec_nrec_dist zrnd
   WHERE ai.invoice_id = invs.invoice_id
   AND   satx.invoice_id = ai.invoice_id
   AND   satx.invoice_id = satx1.invoice_id
   AND   ai.historical_flag is null
   AND   ai.cancelled_date is null
   AND   satx1.detail_tax_dist_id is not null
   AND   satx.detail_tax_dist_id is not null
   AND   satx.detail_tax_dist_id = zrnd.rec_nrec_tax_dist_id
   AND   satx.invoice_id = zrnd.trx_id
   AND   zrnd.entity_code = ''AP_INVOICES''
   AND   zrnd.application_id = 200
   AND   zrnd.applied_from_tax_dist_id is null
   AND   nvl(ai.quick_credit,''N'') <> ''Y''
   AND   satx.line_type_lookup_code = ''NONREC_TAX''
   AND   satx1.line_type_lookup_code = ''REC_TAX''
   AND   satx.charge_applicable_to_dist_id = satx1.charge_applicable_to_dist_id
   AND   satx.dist_code_combination_id = satx1.dist_code_combination_id
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid4
           WHERE aid4.invoice_distribution_id = satx.charge_applicable_to_dist_id
           AND   (aid4.project_id is not null OR
                  aid4.po_distribution_id is not null))',
      p_title                  => 'MGD-369',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Non-recoverable tax distributions assigned the account from the recoverable tax account from the tax setup rather than the account of the ITEM line to which the tax is applicable.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Bug Number: </strong>9954778</br><strong>Note: </strong>[1300611]</br><strong>Script Name: </strong>ap_ccid_nrec_tax_incrt_sel.sql</br></br>Apply the GDF patch and code fix patch as detailed in [1300611/KB730058] to help resolve the issue.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: 369');



debug('begin add_signature: 371');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'PO Matching';
   l_info('bug_number'):= '9508416';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1193928.1';
   l_info('problem'):= 'Invoices which have been matched to a PO are not showing the PO Number in the PO Number field due to a missing value for quick_po_header_id.';
   l_info('solution'):= 'Apply the root cause fix from bug 9508416 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4161',
      p_sig_id                 => '371',
      p_sig_sql                => 'SELECT /*+ leading(invs) */
          ai.invoice_id,
          ai.invoice_date,
          ai.org_id,
          ai.invoice_amount,
          ai.quick_po_header_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   EXISTS (
           SELECT d.invoice_id
           FROM ap_invoice_distributions_all d,
                po_distributions_all pod
           WHERE d.invoice_id = ai.invoice_id
           AND   d.po_distribution_id = pod.po_distribution_id)
   AND   ai.quick_po_header_id is null
   AND   ai.cancelled_date is null
   AND   ai.invoice_amount <> 0
   AND   ai.historical_flag is null
   AND   1 = (
           SELECT count(*)
           FROM (
                  SELECT distinct
                         l.invoice_id,
                         ph.segment1,
                         ph.po_header_id,
                         nvl(sum(l.amount),0) line_matched_amt
                  FROM ap_invoice_lines_all l,
                       po_headers_all ph
                  WHERE l.po_header_id = ph.po_header_id
                  AND   l.match_type IN ( ''PRICE_CORRECTION'',
                          ''QTY_CORRECTION'',''ITEM_TO_PO'',
                          ''ITEM_TO_RECEIPT'', ''AMOUNT_CORRECTION'',
                          ''RETRO PRICE ADJUSTMENT'',''ITEM_TO_SERVICE_PO'',
                          ''ITEM_TO_SERVICE_RECEIPT'')
                  AND    NVL (l.discarded_flag, ''N'' ) <> ''Y''
                  AND    NVL (l.cancelled_flag, ''N'' ) <> ''Y''
                  GROUP BY ph.po_header_id, ph.segment1, l.invoice_id
                  HAVING (nvl(sum(l.amount), 0) <> 0 OR
                          nvl(sum(l.quantity_invoiced), 0) <> 0)
                ) po,
                (
                   SELECT ail.po_header_id,
                          ail.corrected_inv_id,
                          nvl(sum(ail.amount), 0) corrected_amt
                   FROM ap_invoice_lines_all ail
                   WHERE nvl(ail.discarded_flag, ''N'' ) <> ''Y''
                   AND   nvl(ail.cancelled_flag, ''N'' ) <> ''Y''
                   GROUP BY ail.po_header_id, ail.corrected_inv_id
                ) l
          WHERE l.po_header_id = po.po_header_id
          AND   po.invoice_id = ai.invoice_id
          AND   l.corrected_inv_id = ai.invoice_id
          AND   (ai.invoice_type_lookup_code NOT IN (''CREDIT'',''DEBIT'') OR
                 ((-1)*l.corrected_amt < (-1)*po.line_matched_amt))
          AND   (nvl(ai.invoice_type_lookup_code,''CREDIT'') IN (
                   ''CREDIT'',''DEBIT'') OR
                 ((-1)*l.corrected_amt < po.line_matched_amt)))',
      p_title                  => 'MGD-371',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices which have been matched to a PO are not showing the PO Number in the PO Number field due to a missing value for quick_po_header_id.<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Bug Number: </strong>9508416</br><strong>Note: </strong>[1193928/KB378881]</br><strong>Script Name: </strong>ap_quick_po_update_sel.sql</br></br>Apply the root cause fix from bug {9508416} if you have not done so, and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 371');



