debug('begin add_signature: 374');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'PO Matching';
   l_info('bug_number'):= '8973086';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1232144.1';
   l_info('problem'):= 'During quick match the Quantity Invoiced is populated with multiple precision on invoice lines and distributions causing the invoice to be placed on QUALITY hold with the reason "Quantity billed is more than quantity accepted"';
   l_info('solution'):= 'Apply the data fix and root cause patches as detailed in Doc ID 1232144.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4172',
      p_sig_id                 => '374',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_amount,
          ai.invoice_num,
          ai.vendor_id,
          ail.quantity_invoiced,
          ail.line_number,
          ail.line_type_lookup_code,
          ail.rcv_transaction_id,
          ail.po_distribution_id,
          ail.po_line_location_id,
          ail.po_line_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        fnd_currencies fnc
   WHERE ai.invoice_id = invs.invoice_id
   AND   fnc.currency_code = ai.invoice_currency_code
   AND   ai.historical_flag is null
   AND   ai.quick_po_header_id is not null
   AND   ai.invoice_id = ail.invoice_id
   AND   ail.po_line_location_id is not null
   AND   upper(ail.unit_meas_lookup_code) = ''EACH''
   AND   ail.quantity_invoiced is not null
   AND   EXISTS (
           SELECT 1 FROM po_distributions_all pod
           WHERE pod.po_header_id = ail.po_header_id
           AND   ail.po_line_id = pod.po_line_id
           AND   ail.po_line_location_id = pod.line_location_id
           AND   ((round(pod.quantity_billed) = quantity_ordered AND
                   pod.quantity_billed <> quantity_ordered) OR
                  (round(pod.quantity_billed) = quantity_delivered AND
                   pod.quantity_billed <>  Quantity_delivered))
           AND   decode(instr(pod.quantity_billed, ''.'', 1, 1),
                   0, 0,
                   length(substr(pod.quantity_billed,
                     instr(pod.quantity_billed, ''.'', 1, 1) + 1)))
                    > fnc.precision)',
      p_title                  => 'MGD-374',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'During quick match the Quantity Invoiced is populated with multiple precision on invoice lines and distributions causing the invoice to be placed on QUALITY hold with the reason "Quantity billed is more than quantity accepted"<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Bug Number: </strong>8973086</br><strong>Note: </strong>[1232144/KB784894]</br><strong>Script Name: </strong>quick_match_qty_rnd_sel.sql</br></br>Apply the data fix and root cause patches as detailed in [1232144/KB784894]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 374');



