debug('begin add_signature: 378');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '12660674';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'RELATED_ID is null for invoice price variance (IPV) distributions of price correction invoices and for ITEM/ACCRUAL distributions of quantity correction invoices causing incorrect base amounts and accounting.';
   l_info('solution'):= 'Apply the root cause fix from bug 12660674 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4099',
      p_sig_id                 => '378',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT aid.invoice_id,
          aid.invoice_distribution_id,
          aid.corrected_invoice_dist_id,
          aid.amount,
          aid.related_id
   FROM invs,
        ap_invoice_distributions_all aid
   WHERE aid.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code = ''IPV''
   AND   aid.dist_match_type IN (''PRICE_CORRECTION'')
   AND   aid.corrected_invoice_dist_id is not null
   AND   aid.related_id is null
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aidx
           WHERE aidx.invoice_id = aid.invoice_id
           AND   aidx.related_id = aid.invoice_distribution_id)
   UNION ALL
