   l_info('#IMPACT_AREAS#'):= 'Invoice Holds';
   l_info('bug_number'):= '21849065';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '2063663/KB787382';
   l_info('problem'):= 'Fully paid invoices with a schedule payment hold.';
   l_info('solution'):= 'Apply the root cause fix from [2063663/KB787382] and then log a Service Request to obtain the data fix from 21849065 if required.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4175',
      p_sig_id                 => '403',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          aps.payment_num
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_payment_schedules_all aps
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aps.invoice_id
   AND   nvl(aps.hold_flag,''N'') = ''Y''
   AND   nvl(aps.payment_status_flag,''N'') = ''Y''
   AND   nvl(ai.payment_status_flag,''N'') = ''Y''
   AND   aps.amount_remaining = ''0''
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_lines_all ail
           WHERE ail.invoice_id = aps.invoice_id
           AND   nvl(ail.cancelled_flag,''N'')= ''Y'')
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = aps.invoice_id
           HAVING sum(aid.amount) = (
                    SELECT sum(aip.amount) FROM ap_invoice_payments_all aip
                    WHERE aip.invoice_id = aps.invoice_id))',
      p_title                  => 'MGD-403',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Fully paid invoices with a schedule payment hold.<br/><strong>Impact Area(s): </strong>Invoice Holds',
      p_solution               => '<strong>Bug Number: </strong>21849065</br><strong>Note: </strong>[2063663/KB787382]</br><strong>Script Name: </strong>ap_ful_pay_sch_on_hold_sel.sql</br></br>Apply the root cause fix from [2063663/KB787382] and then log a Service Request to obtain the data fix from {21849065} if required.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 403');



debug('begin add_signature: 404');
   l_info('##SHOW_SQL##'):= 'Y';
