   l_info('bug_number'):= '17046524';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Old discounts which were not transferred to FA in 11i because automatic offsets were off, are transferred to FA after upgrading to R12.';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for the affected invoices and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4139',
      p_sig_id                 => '404',
      p_sig_sql                => 'SELECT DISTINCT
          aip.invoice_id,
          aip.check_id,
          aip.org_id,
          aip.posted_flag,
          aip.assets_addition_flag,
          aip.payment_num,
          aip.accounting_date,
          aip.amount,
          aip.posted_flag,
          aip.set_of_books_id,
          aip.accounting_event_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoice_payments_all aip,
        ap_ae_headers_all aeh,
        ap_ae_lines_all ael
   WHERE aip.invoice_id = invs.invoice_id
   AND   aip.assets_addition_flag = ''U''
   AND   aip.posted_flag = ''Y''
   AND   ael.source_table = ''AP_INVOICE_PAYMENTS''
   AND   ael.source_id = aip.invoice_payment_id
   AND   ael.ae_line_type_code = ''DISCOUNT''
   AND   aeh.ae_header_id = ael.ae_header_id
   AND   aeh.set_of_books_id = aip.set_of_books_id
   AND   aeh.gl_transfer_flag = ''Y''
   AND   ael.account_overlay_source_id is null',
      p_title                  => 'MGD-404',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Old discounts which were not transferred to FA in 11i because automatic offsets were off, are transferred to FA after upgrading to R12.<br/><strong>Impact Area(s): </strong>Fixed Assets',
      p_solution               => '<strong>Bug Number: </strong>17046524</br><strong>Script Name: </strong>ap_old_disc_fa_trans_sel.sql</br></br>Generate the Create Accounting Analyzer ([1665706/KB627726]) output for the affected invoices and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 404');



debug('begin add_signature: 405');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Cancellation';
   l_info('bug_number'):= '19400189';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1617159.1';
   l_info('problem'):= 'Line discard creates very large distribution line numbers which cause ORA-01438 errors when trying to cancel the invoice.';
   l_info('solution'):= 'Apply the root cause fix from bug 19400189 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4174',
      p_sig_id                 => '405',
      p_sig_sql                => 'SELECT aid.invoice_id,
          aid.invoice_line_number,
          aid.distribution_line_number,
          aid.amount,
          aid.last_updated_by,
          aid.last_update_login,
          aid.last_update_date
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoice_distributions_all aid
   WHERE aid.invoice_id = invs.invoice_id
   AND   aid.line_type_lookup_code in (''FREIGHT'', ''MISCELLANEOUS'')
   AND   aid.distribution_line_number > 100000
   AND   EXISTS (
           SELECT 1 FROM  ap_invoice_distributions_all aidx
           WHERE aidx.invoice_id = aid.invoice_id
           AND   aidx.parent_reversal_id = aid.invoice_distribution_id
           AND   aidx.distribution_line_number = aid.distribution_line_number * 2)
   AND   EXISTS (
           SELECT 1 FROM ap_allocation_rules aar
           WHERE aar.invoice_id = aid.invoice_id
           AND   aar.chrg_invoice_line_number = aid.invoice_line_number
           AND   aar.status = ''PENDING'')',
      p_title                  => 'MGD-405',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Line discard creates very large distribution line numbers which cause ORA-01438 errors when trying to cancel the invoice.<br/><strong>Impact Area(s): </strong>Invoice Cancellation',
      p_solution               => '<strong>Bug Number: </strong>19400189</br><strong>Note: </strong>[1617159/KB763729]</br><strong>Script Name: </strong>pending_alloc_large_num_chrg_line_sel.sql</br></br>Apply the root cause fix from bug {19400189} if you have not done so, and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: 405');



debug('begin add_signature: 406');
   l_info('##SHOW_SQL##'):= 'Y';
