   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4176',
      p_sig_id                 => '406',
      p_sig_sql                => 'SELECT n.notification_id,
       n.group_id,
       n.message_type,
       n.message_name,
       n.status,
       n.begin_date,
       n.end_date,
       n.subject,
       n.user_key,
       n.item_key,
        substr(n.item_key,1,(instr(n.item_key,''_'')- 1)) invoice_id,
