debug('begin add_signature: 417');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Data';
   l_info('bug_number'):= '19649854';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1933888.1';
   l_info('problem'):= 'Invoices exist in the application with duplicate invoice numbers';
   l_info('solution'):= 'Apply the root cause fix from bug 19649854 as detailed in Doc ID 1933888.1.

If a data fix is required log a Service Request to obtain the data fix from Doc ID 2094877.1.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4170',
      p_sig_id                 => '417',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.vendor_id,
          ai.party_site_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   (ai.vendor_id, ai.invoice_num, ai.org_id ,ai.party_site_id) IN (
           SELECT ai2.vendor_id,
                  ai2.invoice_num,
                  ai2.org_id,
                  ai2.party_site_id
           FROM ap_invoices_all ai2
           GROUP BY vendor_id, invoice_num, party_site_id,org_id
           HAVING COUNT(1) > 1)',
      p_title                  => 'MGD-417',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices exist in the application with duplicate invoice numbers<br/><strong>Impact Area(s): </strong>Invoice Data',
      p_solution               => '<strong>Solution GDF: </strong>19649854</br><strong>Note: </strong>[1933888/KB785475]</br><strong>Script Name: </strong>ap_dup_inv_number_sel.sql</br></br>Apply the root cause fix from bug 19649854 as detailed in [1933888/KB785475].

If a data fix is required log a Service Request to obtain the data fix from [2094877/KB706001].',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 417');



debug('begin add_signature: 418');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Cancellation, Invoice Data';
   l_info('bug_number'):= 'n/a';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '2224983.1';
   l_info('problem'):= 'Non-standard characters exist in the descriptions of imported invoices which can cause errors in invoice cancellation and other invoice workbench actions and warnings in some reports.';
   l_info('solution'):= 'Please log a Service Request to obtain a data fix from Doc ID 2224983.1.

If the issue persists, then follow the instructions as detailed in Doc ID 960115.1 to check and fix invalid leading/trailing spaces and control characters using afchrchk.sql. <br><br>';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4125',
      p_sig_id                 => '418',
      p_sig_sql                => 'SELECT ai.invoice_id,
          ai.invoice_num,
          ai.invoice_date,
          ai.org_id,
          ai.vendor_id,
          ai.description
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai
   WHERE ai.invoice_id = invs.invoice_id
   AND   translate(ai.description,
           '',''''ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789@#$%^&*()_+-=,!\`~{}./?:";''''[ ]'',
           '' '') <> '' ''
   AND   EXISTS (
        SELECT 1 FROM nls_database_parameters
        WHERE parameter = ''NLS_CHARACTERSET''
        AND   value IN (''UTF8'', ''WE8ISO8859P1'', ''AL32UTF8''))
   AND   EXISTS (
        SELECT 1 FROM ap_invoice_lines_all ail
        WHERE ail.invoice_id = ai.invoice_id
        AND   ail.line_source = ''IMPORTED'')',
      p_title                  => 'MGD-418',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Non-standard characters exist in the descriptions of imported invoices which can cause errors in invoice cancellation and other invoice workbench actions and warnings in some reports.<br/><strong>Impact Area(s): </strong>Invoice Cancellation, Invoice Data',
      p_solution               => '<strong>Bug Number: </strong>n/a</br><strong>Note: </strong>[2224983/KB769444]</br><strong>Script Name: </strong>None</br></br>Please log a Service Request to obtain a data fix from [2224983/KB769444].

If the issue persists, then follow the instructions as detailed in [960115/KB771922] to check and fix invalid leading/trailing spaces and control characters using afchrchk.sql. <br><br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '15'
      );
   l_info.delete;
debug('end add_signature: 418');



debug('begin add_signature: 420');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Data, PO Matching';
   l_info('bug_number'):= '19848929';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1961120.1';
   l_info('problem'):= 'When creating a retainage release invoice for a PO shipment (with multiple distributions) a unique constraint error (ORA-00001) occurs resulting in the line_selected_for_release_flag remaining as Y on affected lines';
   l_info('solution'):= 'Apply the root cause fix from bug 19848929 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4126',
      p_sig_id                 => '420',
      p_sig_sql                => 'SELECT ail.invoice_id,
          ail.line_number,
          ail.line_selected_for_release_flag,
          ail.retained_amount,
          ail.retained_amount_remaining
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoice_lines_all ail
   WHERE ail.invoice_id = invs.invoice_id
   AND   ail.po_line_location_id is not null
   AND   ail.retained_amount is not null
   AND   ail.line_selected_for_release_flag = ''Y''
   AND   ail.retained_amount_remaining > 0
   AND   nvl(ail.discarded_flag,''N'') <> ''Y''
   AND   (-1) * ail.retained_amount  <> (
           SELECT nvl(sum(ail2.amount),0) FROM ap_invoice_lines_all ail2
           WHERE ail2.retained_invoice_id = ail.invoice_id
           AND   ail2.retained_line_number = ail.line_number)',
      p_title                  => 'MGD-420',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'When creating a retainage release invoice for a PO shipment (with multiple distributions) a unique constraint error (ORA-00001) occurs resulting in the line_selected_for_release_flag remaining as Y on affected lines<br/><strong>Impact Area(s): </strong>Invoice Data, PO Matching',
      p_solution               => '<strong>Bug Number: </strong>19848929</br><strong>Note: </strong>[1961120/KB788143]</br><strong>Script Name: </strong>ap_upd_line_sel_rel_flag_sel.sql</br></br>Apply the root cause fix from bug {19848929} if you have not done so, and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: 420');



