   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Invoice validation fails when trying to delete frozen tax distributions.  Freight distrubutions are reversed, but corresponding tax distributions are not.';
   l_info('solution'):= 'Apply the root cause fixes from bug 12419997 or 14383132.
For datafix please review the steps in Doc ID 2114166.1.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4129',
      p_sig_id                 => '428',
      p_sig_sql                => 'SELECT aid.invoice_id,
          aid.line_type_lookup_code,
          aid.invoice_distribution_id,
          aid.amount
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        financials_system_params_all fsp,
        ap_invoice_distributions_all aid,
        ap_invoice_lines_all ail
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = aid.invoice_id
   AND   aid.invoice_id = ail.invoice_id
   AND   aid.invoice_line_number = ail.line_number
   AND   fsp.org_id = ai.org_id
   AND   aid.line_type_lookup_code IN (''FREIGHT'', ''MISCELLANEOUS'')
   AND   aid.reversal_flag = ''Y''
   AND   aid.parent_reversal_id is null
   AND   nvl(ail.discarded_flag, ''N'') = ''N''
   AND   nvl(ai.historical_flag, ''N'') = ''N''
   AND   EXISTS (
           SELECT 1 FROM zx_rec_nrec_dist zrnd
           WHERE zrnd.trx_id = aid.invoice_id
           AND   zrnd.application_id = 200
           AND   zrnd.entity_code = ''AP_INVOICES''
           AND   zrnd.event_class_code IN (''STANDARD INVOICES'',
                   ''PREPAYMENT INVOICES'', ''EXPENSE REPORTS'')
           AND   zrnd.trx_line_dist_id = aid.invoice_distribution_id
           AND   nvl(zrnd.reverse_flag, ''N'') = ''N'')
   AND   EXISTS (
           SELECT 1 FROM ap_allocation_rule_lines arl
           WHERE arl.invoice_id = ai.invoice_id
           AND   arl.chrg_invoice_line_number = ail.line_number)
   AND   EXISTS (
           SELECT 1 FROM dual
           WHERE ai.force_revalidation_flag = ''Y''
           UNION ALL
           SELECT 1 FROM ap_invoice_distributions_all aidx
           WHERE aidx.invoice_id = ai.invoice_id
           AND   fsp.purch_encumbrance_flag = ''Y''
           AND   aidx.match_status_flag <> ''A''
           UNION ALL
           SELECT 1 FROM ap_invoice_distributions_all aidx
           WHERE aidx.invoice_id = ai.invoice_id
           AND   fsp.purch_encumbrance_flag = ''N''
           AND   aidx.match_status_flag not IN (''T'', ''A'')
           UNION ALL
           SELECT 1 FROM ap_holds_all aha
           WHERE aha.invoice_id = ai.invoice_id
           AND   aha.release_lookup_code is null)',
      p_title                  => 'MGD-428',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice validation fails when trying to delete frozen tax distributions.  Freight distrubutions are reversed, but corresponding tax distributions are not.<br/><strong>Impact Area(s): </strong>Invoice Approval',
      p_solution               => '<strong>Bug Number: </strong>20452983</br><strong>Script Name: </strong>active_tax_on_reversed_chrg_sel.sql</br></br>Apply the root cause fixes from bug {12419997} or {14383132}.
For datafix please review the steps in [2114166/KB188488].',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 428');



