debug('begin add_signature: 438');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure, Accounting Incorrect, Trial Balance';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1359966.1';
   l_info('problem'):= 'User-defined subledger accounting method components have been detected.';
   l_info('solution'):= 'Review your component definitions.  See Doc ID 1359966.1 to determine if there was a bug fix or change implemented for your component, and correct your definitions accordingly. Also verify in a test instance whether using the seeded application accounting definition (AAD) results in the same issue to confirm the cause. Log a service request if needed.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4131',
      p_sig_id                 => '438',
      p_sig_sql                => 'WITH invs AS (
     ##$$MIVIEW$$##
   )
   SELECT ''Product Rule Code'' component_type,
          xah.product_rule_code "Code",
          xah.ledger_id
   FROM invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah
   WHERE ai.invoice_id = invs.invoice_id
   AND   xte.application_id = 200
   AND   xte.ledger_id = ai.set_of_books_id
   AND   nvl( xte.source_id_int_1, - 99 ) = ai.invoice_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.entity_id = xah.entity_id
   AND   xah.application_id = 200
   AND   xah.product_rule_type_code = ''C''
   UNION ALL
   SELECT ''Journal Line Definition'',
          xdl.line_definition_code,
          xah.ledger_id
   FROM invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah,
        xla_distribution_links xdl
   WHERE ai.invoice_id = invs.invoice_id
   AND   xte.application_id = 200
   AND   xte.ledger_id = ai.set_of_books_id
   AND   nvl( xte.source_id_int_1, - 99 ) = ai.invoice_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.entity_id = xah.entity_id
   AND   xah.application_id = 200
   AND   xdl.ae_header_id = xah.ae_header_id
   AND   xdl.line_definition_owner_code = ''C''
   AND   xdl.application_id = 200
   UNION ALL
   SELECT ''Journal Line Type'',
         xdl.accounting_line_code,
         xah.ledger_id
   FROM invs,
        ap_invoices_all ai,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah,
        xla_distribution_links xdl
   WHERE ai.invoice_id = invs.invoice_id
   AND   xte.application_id = 200
   AND   xte.ledger_id = ai.set_of_books_id
   AND   nvl( xte.source_id_int_1, - 99 ) = ai.invoice_id
   AND   xte.entity_code = ''AP_INVOICES''
   AND   xte.entity_id = xah.entity_id
   AND   xah.application_id = 200
   AND   xdl.ae_header_id = xah.ae_header_id
   AND   xdl.accounting_line_type_code = ''C''
   AND   xdl.application_id = 200',
      p_title                  => 'MGD-438',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'User-defined subledger accounting method components have been detected.<br/><strong>Impact Area(s): </strong>Accounting Failure, Accounting Incorrect, Trial Balance',
      p_solution               => '<strong>Note: </strong>[1359966/KB350804]</br><strong>Script Name: </strong>None</br></br>Review your component definitions.  See [1359966/KB350804] to determine if there was a bug fix or change implemented for your component, and correct your definitions accordingly. Also verify in a test instance whether using the seeded application accounting definition (AAD) results in the same issue to confirm the cause. Log a service request if needed.',
