debug('begin add_signature: 440');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'EBTax, Invoice Approval';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1316316.1';
   l_info('problem'):= 'Invoices cannot be validated because (a) the total recovery rate is greater than 100 or (b) the system is trying to delete frozen tax distributions (or frozen self-assessed tax distributions)';
   l_info('solution'):= 'Apply the root cause fix from bug 18910468 if you have not done so, then follow the instructions provided in Doc ID 1316316.1 section #49 and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'TAX';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4567',
      p_sig_id                 => '440',
      p_sig_sql                => 'SELECT rnd.application_id,
          rnd.entity_code,
          rnd.event_class_code,
          rnd.trx_id,
          rnd.reverse_flag,
          rnd.reversed_tax_dist_id,
          rnd.rec_nrec_tax_dist_id
   FROM zx_rec_nrec_dist rnd
   WHERE rnd.application_id = 200
   AND   rnd.entity_code = ''AP_INVOICES''
   AND   rnd.event_class_code IN (''STANDARD INVOICES'',''PREPAYMENT INVOICES'',
           ''EXPENSE REPORTS'')
   AND   nvl(rnd.reverse_flag,''N'') = ''N''
   AND   rnd.reversed_tax_dist_id is not null
   AND   EXISTS (
           SELECT 1
           FROM (
                  ##$$IVIEW$$##
                ) invs,
                ap_invoices_all ai
           WHERE ai.invoice_id = invs.invoice_id
           AND   rnd.trx_id = ai.invoice_id
           AND   ai.creation_date < (
                   SELECT min(pr.end_date)
                   FROM ad_appl_tops at,
                        ad_applied_patches aap,
                        ad_patch_drivers pd,
                        ad_patch_runs pr,
                        ad_patch_run_bugs prb,
                        ad_file_versions afv,
                        ad_patch_run_bug_actions prba,
                        ad_files f
                   WHERE f.app_short_name = ''ZX''
                   AND   f.subdir = ''patch/115/sql''
                   AND   f.filename = ''zxifnewsrvcspubb.pls''
                   AND   f.file_id = prba.file_id
                   AND   prba.executed_flag = ''Y''
                   AND   prba.patch_run_bug_id = prb.patch_run_bug_id
                   AND   pr.appl_top_id = at.appl_top_id
                   AND   prb.patch_run_id = pr.patch_run_id
                   AND   pr.patch_driver_id = pd.patch_driver_id
                   AND   pd.applied_patch_id = aap.applied_patch_id
                   AND   prba.patch_file_version_id = afv.file_version_id
                   AND   to_number(nvl(afv.version_segment4,afv.version_segment2)) >=
                           to_number(decode(afv.version_segment3,
                             12020000,9,
                             12010000,22,
                             12000000,22,
                             afv.version_segment2))))',
      p_title                  => 'MGD-440',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoices cannot be validated because (a) the total recovery rate is greater than 100 or (b) the system is trying to delete frozen tax distributions (or frozen self-assessed tax distributions)<br/><strong>Impact Area(s): </strong>EBTax, Invoice Approval',
      p_solution               => '<strong>Note: </strong>[1316316/KB731274]</br><strong>Script Name: </strong>None</br></br>Apply the root cause fix from bug {18910468} if you have not done so, then follow the instructions provided in [1316316/KB731274] section #49 and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
