debug('begin add_signature: 442');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '20132902';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '2003653.1';
   l_info('problem'):= 'Create Accounting process errors because the accounted amount and entered amount for the subledger journal entry line have different signs';
   l_info('solution'):= 'Apply the Root Cause fix detailed in Doc ID 2003653.1 if you have not already and follow Doc ID 1276043.1 for the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5031',
      p_sig_id                 => '442',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(dist) */
       ai.invoice_num,
       ai.org_id,
       ai.invoice_id,
       dist.application_id,
       dist.entity_code,
       dist.event_class_code,
       dist.rec_nrec_tax_dist_id,
       dist.reverse_flag,
       dist.reversed_tax_dist_id,
       dist.historical_flag,
       dist.creation_date,
       dist.rec_nrec_tax_amt,
       dist.rec_nrec_tax_amt_tax_curr,
       dist.rec_nrec_tax_amt_funcl_curr
FROM (
       ##$$IVIEW$$##
     ) invs,
     ap_invoices_all ai,
     (
       SELECT /*+ materialize */
              nvl((
                SELECT MIN(pr.end_date)
                FROM ad_appl_tops at,
                     ad_applied_patches aap,
                     ad_patch_drivers pd,
                     ad_patch_runs pr,
                     ad_patch_run_bugs prb,
                     ad_file_versions afv,
                     ad_patch_run_bug_actions prba,
                     ad_files f
                WHERE f.app_short_name = ''ZX''
                AND   f.subdir = ''patch/115/sql''
                AND   f.filename = ''zxdiroundtaxpkgb.pls''
                AND   f.file_id = prba.file_id
                AND   prba.executed_flag = ''Y''
                AND   prba.patch_run_bug_id = prb.patch_run_bug_id
                AND   pr.appl_top_id = at.appl_top_id
                AND   prb.patch_run_id = pr.patch_run_id
                AND   pr.patch_driver_id = pd.patch_driver_id
                AND   pd.applied_patch_id = aap.applied_patch_id
                AND   prba.patch_file_version_id = afv.file_version_id
                AND   to_number(nvl(afv.version_segment4, afv.VERSION_SEGMENT2)) > =
                        to_number(
                          decode(afv.version_segment3,
                            12020000, 13,
                            12010000, 32,
                            12000000, 50,
                            afv.version_segment2))),
                sysdate) AS applied_date
       FROM dual
     ) ptch,
  zx_rec_nrec_dist dist
WHERE ai.invoice_id = invs.invoice_id
-- AND   ai.creation_date < ptch.applied_date -- AF Req ID 134786 
AND   dist.trx_id = ai.invoice_id
AND   dist.application_id = 200
AND   dist.entity_code = ''AP_INVOICES''
AND   dist.event_class_code IN (''STANDARD INVOICES'',
        ''PREPAYMENT INVOICES'',''EXPENSE REPORTS'')
AND   sign(dist.rec_nrec_tax_amt) <> sign(dist.rec_nrec_tax_amt_funcl_curr)',
      p_title                  => 'MGD-442',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Create Accounting process errors because the accounted amount and entered amount for the subledger journal entry line have different signs<br/><strong>Impact Area(s): </strong>Accounting Failure',
