debug('begin add_signature: 445');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Automatic Witholding Tax';
   l_info('bug_number'):= '23273289';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'AWT is prorated only on reversed tax distributions causing incorrect AWT calculations and underpayment of suppliers.';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for the affected invoices and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '5387',
      p_sig_id                 => '445',
      p_sig_sql                => 'SELECT ai.invoice_num,
          ail.invoice_id,
          ail.line_number,
          ail.line_type_lookup_code,
          ai.org_id
   FROM (
          ##$$IVIEW$$##
        ) invs,
        ap_invoices_all ai,
        ap_invoice_lines_all ail,
        ap_system_parameters_all asp
   WHERE ai.invoice_id = invs.invoice_id
   AND   ai.invoice_id = ail.invoice_id
   AND   nvl(ai.payment_status_flag,''N'') = ''N''
   AND   ai.cancelled_date is null
   AND   ail.line_type_lookup_code = ''TAX''
   AND   nvl(ail.discarded_flag,''N'') = ''Y''
   AND   ail.org_id = asp.org_id
   AND   ail.set_of_books_id = asp.set_of_books_id
   AND   nvl(asp.allow_awt_flag,''N'') = ''Y''
   AND   asp.create_awt_dists_type = ''APPROVAL''
   AND   nvl(asp.awt_include_tax_amt,''N'') = ''Y''
   AND   ail.awt_group_id is null
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_lines_all ail_awt
           WHERE ail_awt.invoice_id = ail.invoice_id
           AND   ail_awt.line_type_lookup_code = ''AWT''
           AND   nvl(ail_awt.discarded_flag,''N'') = ''N'')
   AND   EXISTS (
            SELECT 1 FROM ap_invoice_distributions_all tax_par
            WHERE tax_par.invoice_id = ail.invoice_id
            AND   tax_par.invoice_line_number = ail.line_number
            AND   tax_par.parent_reversal_id is null
            AND   nvl(tax_par.reversal_flag,''N'') = ''Y''
            AND   tax_par.awt_group_id is null
            AND   EXISTS (
                    SELECT 1 FROM ap_invoice_distributions_all tax_rev
                    WHERE tax_rev.parent_reversal_id = tax_par.invoice_distribution_id
                    AND   tax_rev.awt_group_id is not null
                    AND   EXISTS (
                            SELECT 1 FROM ap_invoice_distributions_all aid_awt
                            WHERE aid_awt.awt_related_id = tax_rev.invoice_distribution_id
                            AND   nvl(aid_awt.reversal_flag,''N'') = ''N'' )))',
      p_title                  => 'MGD-445',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'AWT is prorated only on reversed tax distributions causing incorrect AWT calculations and underpayment of suppliers.<br/><strong>Impact Area(s): </strong>Automatic Witholding Tax',
      p_solution               => '<strong>Bug Number: </strong>23273289</br><strong>Script Name: </strong>ap_active_awt_on_reversed_tax_sel.sql</br></br>Generate the Create Accounting Analyzer ([1665706/KB627726]) output for the affected invoices and log a Service Request to obtain the data fix.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
