debug('begin add_signature: 461');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'PO Matching';
   l_info('bug_number'):= '17534079';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Invoice distributions have incorrect amount_variance and are matched to a fully or over-billed po_distribution having active encumbrance > 1, and there exist no invoice distributions with encumbered_flag as ''N'' for the po_distribution_id.';
   l_info('solution'):= 'Apply the root cause fix from bug 17534079 if you have not done so, and log a Service Req
uest to obtain the data fix.';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8430',
      p_sig_id                 => '461',
      p_sig_sql                => 'SELECT pd.po_distribution_id po_distribution_id,
       nvl(pd.amount_billed,0) amount_billed,
       nvl(pd.amount_ordered,0) amount_ordered,
       nvl(pd.amount_cancelled,0) amount_cancelled,
       sum(nvl(aid.amount,0)) dist_amount,
       sum(nvl(aid.amount,0)) - sum(nvl(amount_variance,0)) total_amount_invoiced,
       (nvl(pd.amount_ordered,0) - nvl(pd.amount_cancelled,0))  po_amount,
       (sum(nvl(aid.amount,0)) - sum(nvl(amount_variance,0)) -
         (nvl(pd.amount_ordered,0) - nvl(pd.amount_cancelled,0))) av_correction
FROM (
       ##$$IVIEW$$##
     ) invs,
     ap_invoice_distributions_all aid,
     po_distributions_all pd,
     po_lines_all pl,
     ap_system_parameters_all asp,
     po_line_locations_all pll
WHERE aid.invoice_id = invs.invoice_id
AND   nvl(pd.accrue_on_receipt_flag, ''N'') = ''N''
AND   aid.po_distribution_id = pd.po_distribution_id
AND   pd.po_line_id = pl.po_line_id
AND   pl.matching_basis = ''AMOUNT''
AND   nvl(asp.org_id,-99) = nvl(aid.org_id,-99)
AND   pd.line_location_id = pll.line_location_id
AND   NOT EXISTS (
        SELECT ''Invoice dist encumbered IN 11.0''
        FROM ap_ae_lines_all aael,
             ap_invoice_distributions_all aid1
        WHERE aael.source_table = ''AP_INVOICE_DISTRIBUTIONS''
        AND   aael.source_id = aid1.invoice_distribution_id
        AND   aid1.po_distribution_id = pd.po_distribution_id
        AND   nvl(aael.description, ''000'') = ''R11.5 Upgrade'')
AND   NOT EXISTS (
        SELECT ''Unreleased non-postable hold on a matched Invoice''
        FROM ap_holds_all ah,
             ap_hold_codes ahc,
             ap_invoice_distributions_all aid1
        WHERE ah.invoice_id = aid1.invoice_id
        AND   aid1.po_distribution_id = pd.po_distribution_id
        AND   ah.hold_lookup_code = ahc.hold_lookup_code
        AND   ah.release_lookup_code is null
        AND   ahc.postable_flag <> ''Y'')
AND   EXISTS (
        SELECT ''Invoice dist with AV'' FROM ap_invoice_distributions_all aid1
        WHERE aid1.po_distribution_id = pd.po_distribution_id
        AND   amount_variance IS NOT NULL
        AND   nvl(amount_variance, 0) <> 0)
AND   EXISTS (
        SELECT ''one dist encumbered IN R12'' FROM ap_invoice_distributions_all aid1
        WHERE aid1.po_distribution_id = pd.po_distribution_id
        AND   aid1.line_type_lookup_code IN (''ITEM'',''NONREC_TAX'')
        AND   aid1.amount <> 0
        AND   aid1.encumbered_flag = ''Y''
        AND   aid1.bc_event_id IS NOT NULL)
GROUP BY pd.po_distribution_id, nvl(pd.amount_billed,0), nvl(pd.amount_ordered,0),
         nvl(pd.amount_cancelled,0)
HAVING   nvl(pd.amount_billed, 0) = sum(nvl(aid.amount, 0)) AND
         (((nvl(pd.amount_billed, 0) >
              nvl(pd.amount_ordered, 0) - nvl(pd.amount_cancelled, 0) ) AND
           (sum(nvl(aid.amount, 0)) - sum(nvl(aid.amount_variance, 0)) -
             (nvl(pd.amount_ordered, 0) - nvl(pd.amount_cancelled, 0))) > 0.1) OR
          ((nvl(pd.amount_billed, 0) <=
              nvl(pd.amount_ordered, 0) - nvl(pd.amount_cancelled, 0)) AND
            abs(sum(nvl(aid.amount_variance,0))) > 0.1))',
      p_title                  => 'MGD-461',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice distributions have incorrect amount_variance and are matched to a fully or over-billed po_distribution having active encumbrance > 1, and there exist no invoice distributions with encumbered_flag as ''N'' for the po_distribution_id.<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Bug Number: </strong>17534079</br><strong>Script Name: </strong>ap_x_av_R12_sel.sql</br></br>Apply the root cause fix from bug {17534079} if you have not done so, and log a Service Req
uest to obtain the data fix.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 461');



debug('begin add_signature: 462');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'PO Matching';
   l_info('bug_number'):= '25421681';
