   l_info('solution'):= 'Log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '8431',
      p_sig_id                 => '462',
      p_sig_sql                => 'WITH invs AS (
  ##$$MIVIEW$$##
)
SELECT aid.invoice_id,
       aid.po_distribution_id,
       aid.invoice_distribution_id,
       ''QV'' var_type
FROM invs,
     ap_invoice_distributions_all aid,
     po_distributions_all pd,
     po_lines_all pl
WHERE aid.invoice_id = invs.invoice_id
AND   pd.po_distribution_id = aid.po_distribution_id
AND   pd.po_line_id = pl.po_line_id
AND   pl.matching_basis = ''QUANTITY''
AND   nvl(pd.accrue_on_receipt_flag, ''N'') = ''N''
AND   nvl(aid.encumbered_flag, ''N'') = ''R''
AND   nvl(aid.historical_flag, ''N'') <> ''Y''
AND   nvl(aid.reversal_flag, ''N'') = ''Y''
AND   aid.quantity_variance is not null
UNION
SELECT aid.invoice_id,
       aid.po_distribution_id,
       aid.invoice_distribution_id,
       ''AV''
FROM invs,
     ap_invoice_distributions_all aid,
     po_distributions_all pd,
     po_lines_all pl
WHERE aid.invoice_id = invs.invoice_id
AND   pd.po_distribution_id = aid.po_distribution_id
AND   pd.po_line_id = pl.po_line_id
AND   pl.matching_basis = ''AMOUNT''
AND   nvl(pd.accrue_on_receipt_flag, ''N'') = ''N''
AND   nvl(aid.encumbered_flag, ''N'') = ''R''
AND   nvl(aid.historical_flag, ''N'') <> ''Y''
AND   nvl(aid.reversal_flag, ''N'') = ''Y''
AND   aid.amount_variance is not null',
      p_title                  => 'MGD-462',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice distributions have incorrect quantity or amount variances on non-encumbered distributions (encumbered flag = ''R'')<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Bug Number: </strong>25421681</br><strong>Script Name: </strong>ap_x_qv_av_on_r_sel.sql</br></br>Log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: 462');



debug('begin add_signature: 463');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'PO Matching';
   l_info('bug_number'):= '17534079';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '2393099.1';
   l_info('problem'):= 'Invoice distributions have incorrect quantity variance and are matched to a fully or over-billed po_distribution having active encumbrance > 1, and there is no invoice distribution with encumbered_flag as ''N'' for that po_distribution_id';
   l_info('solution'):= 'Please apply the code fix patch as detailed in Doc ID 2393099.1 and then log an SR to request the data fix.';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '8432',
      p_sig_id                 => '463',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(aid, pd, pl, pll) */
       pd.po_distribution_id ,
       nvl(pd.quantity_billed, 0),
       nvl(pd.quantity_ordered, 0),
       nvl(pd.quantity_cancelled, 0),
       sum(nvl(quantity_invoiced, 0)),
       nvl(pll.price_override, 0),
       sum(nvl(quantity_invoiced, 0)) -
         (sum(nvl(quantity_variance, 0))/pll.price_override) tot_qty_inv,
       nvl(pd.quantity_ordered, 0) - nvl(pd.quantity_cancelled, 0) po_qty,
       sum(nvl(quantity_invoiced, 0)) -
         (sum(nvl(quantity_variance, 0))/pll.price_override) -
         (nvl(pd.quantity_ordered, 0) - nvl(pd.quantity_cancelled, 0)) diff,
       (sum(nvl(quantity_invoiced, 0)) -
         (sum(nvl(quantity_variance, 0))/pll.price_override) -
         (nvl(pd.quantity_ordered, 0) - nvl(pd.quantity_cancelled, 0))) *
          nvl(pll.price_override, 0) qv_correction
FROM (
       ##$$IVIEW$$##
     ) invs,
     ap_invoice_distributions_all aid,
     po_distributions_all pd,
     po_lines_all pl,
     ap_system_parameters_all asp,
     po_line_locations_all pll
WHERE aid.invoice_id = invs.invoice_id
AND   aid.po_distribution_id = pd.po_distribution_id
AND   pd.po_line_id = pl.po_line_id
AND   pl.matching_basis = ''QUANTITY''
AND   aid.matched_uom_lookup_code =
         nvl(pll.unit_meas_lookup_code, pl.unit_meas_lookup_code)
AND   nvl(asp.org_id,-99) = nvl(aid.org_id,-99)
AND   nvl(pd.accrue_on_receipt_flag,''N'') = ''N''
AND   pd.line_location_id = pll.line_location_id
AND   NOT EXISTS (
        SELECT /*+ no_unnest */ ''Unencumbered invoice dist'' FROM ap_invoice_distributions_all aid2
        WHERE nvl(aid2.encumbered_flag, ''N'') = ''N''
        AND   aid2.po_distribution_id = pd.po_distribution_id
        AND   nvl(aid2.match_status_flag, ''A'') <> ''A''
        AND   aid2.amount <> 0
        AND   aid2.line_type_lookup_code IN (''ITEM'',''NONREC_TAX''))
AND   NOT EXISTS (
        SELECT /*+ no_unnest */ ''Invoice dist encumbered IN 11.0''
        FROM ap_ae_lines_all aael ,
             ap_invoice_distributions_all aid3
        WHERE aael.source_table = ''AP_INVOICE_DISTRIBUTIONS''
        AND   aael.source_id = aid3.invoice_distribution_id
        AND   aid3.po_distribution_id = pd.po_distribution_id
        AND   nvl(aael.description, ''000'') = ''R11.5 Upgrade'')
AND   NOT EXISTS (
        SELECT /*+ no_unnest */ ''Unreleased non-postable hold on a matched Invoice''
        FROM ap_holds_all ah,
             ap_hold_codes ahc,
             ap_invoice_distributions_all aid1
        WHERE ah.invoice_id = aid1.invoice_id
        AND   aid1.po_distribution_id = pd.po_distribution_id
        AND   ah.hold_lookup_code = ahc.hold_lookup_code
        AND   ah.release_lookup_code is null
        AND   ahc.postable_flag <> ''Y'')
AND   EXISTS (
        SELECT /*+ no_unnest */ ''one dist encumbered IN R12''
        FROM ap_invoice_distributions_all aid1
        WHERE aid1.po_distribution_id = pd.po_distribution_id
        AND   aid1.line_type_lookup_code IN (''ITEM'',''NONREC_TAX'')
        AND   aid1.amount <> 0
        AND   aid1.encumbered_flag = ''Y''
        AND   aid1.bc_event_id IS NOT NULL)
GROUP BY pd.po_distribution_id, nvl(pd.quantity_billed, 0),
         nvl(pd.quantity_billed, 0), nvl(pd.quantity_ordered, 0),
         nvl(pd.quantity_cancelled, 0), pll.price_override
HAVING sum(quantity_invoiced) - (sum(nvl(quantity_variance, 0)) /
         nvl(pll.price_override, 0)) <>
         (nvl(pd.quantity_ordered, 0) - nvl(pd.quantity_cancelled, 0)) AND
       nvl(pd.quantity_billed, 0) = sum(nvl(aid.quantity_invoiced, 0))',
      p_title                  => 'MGD-463',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Invoice distributions have incorrect quantity variance and are matched to a fully or over-billed po_distribution having active encumbrance > 1, and there is no invoice distribution with encumbered_flag as ''N'' for that po_distribution_id<br/><strong>Impact Area(s): </strong>PO Matching',
      p_solution               => '<strong>Bug Number: </strong>17534079</br><strong>Note: </strong>[2393099/KB786397]</br><strong>Script Name: </strong>ap_x_qv_av_on_r_sel.sql</br></br>Please apply the code fix patch as detailed in [2393099/KB786397] and then log an SR to request the data fix.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 463');



