debug('begin add_signature: 468');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Invoice Data';
   l_info('category'):= 'INVOICE';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '2247553.1';
   l_info('problem'):= 'Invoices which are assigned to a supplier site in a different operating unit. Because of this these invoices are not viewable in the invoice workbench.';
