debug('begin add_signature: 46');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '22873624';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2115968.1';
   l_info('problem'):= 'Checks with check_id out of sync between ap_checks_all and ap_invoice_payments_all';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2115968.1';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3782',
      p_sig_id                 => '46',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(aip, ai) */
          aip.check_id             correct_check_id,
          aip.org_id               org_id,
          aip.accounting_event_id  inv_pmt_acctg_event_id,
          aip.posted_flag          inv_pmt_posted_flag,
          ac.vendor_id            chk_vendor_id,
          ai.vendor_id             inv_vendor_id,
          ac.vendor_site_code      vendor_site_code,
          ai.vendor_site_id        vendor_site_id,
          ac.check_id              wrong_check_id,
          ac.check_number          wrong_check_number,
          ac.amount                wrong_chk_amount,
          ac.payment_id            wrong_chk_payment_id,
          ac.status_lookup_code    wrong_chk_status,
          ac.currency_code         wrong_chk_currency,
          aph.transaction_type    wrong_pmt_hist_trx_type,
          aph.posted_flag         wrong_pmt_hist_posted_flag,
          aph.accounting_event_id wrong_ph_acctg_event_id
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_invoice_payments_all aip,
        ap_invoices_all ai,
        all_sequences seq,
        ap_checks_all ac,
        ap_payment_history_all aph
   WHERE aip.check_id = chks.check_id
   AND   ai.invoice_id = aip.invoice_id
   AND   ai.org_id = aip.org_id
   AND   nvl(aip.reversal_flag,''N'') <> ''Y''
   AND   NOT EXISTS (
           SELECT 1 FROM ap_checks_all ac1
           WHERE ac1.check_id = aip.check_id)
   AND   ac.check_id = aph.check_id(+)
   AND   ac.status_lookup_code NOT IN (''OVERFLOW'',''SET UP'',''SPOILED'')
   AND   nvl(aph.historical_flag,''N'') <> ''Y''
   AND   ac.check_id BETWEEN (aip.check_id - (seq.cache_size + 1)) AND
                             (aip.check_id + (seq.cache_size + 1))
   AND   ac.org_id = aip.org_id
   AND   ac.vendor_id = ai.vendor_id
   AND   ac.vendor_site_id = ai.vendor_site_id
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1 FROM ap_invoice_payments_all aip1
           WHERE ac.check_id = aip1.check_id)
   AND   ac.creation_date > (
           SELECT MIN(creation_date) FROM ad_bugs
           WHERE aru_release_name = ''R12'')
   AND   seq.sequence_name = ''AP_CHECKS_S''
   AND   seq.sequence_owner = ''AP''',
      p_title                  => 'MGD-46',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Checks with check_id out of sync between ap_checks_all and ap_invoice_payments_all<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>22873624</br><strong>Note: </strong>[2115968/KB778253]</br><strong>Script Name: </strong>ap_incorrect_checks_sel.sql Case 2 - AIP</br></br>Apply the GDF patch following the instructions provided in [2115968/KB778253]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '13'
      );
   l_info.delete;
debug('end add_signature: 46');



