debug('begin add_signature: 48');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '18491045';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1125533.1';
   l_info('problem'):= 'Foreign currency checks that are missing exchange rates, maturity exchange rates, or clearing exchange rates.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1125533.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3810',
      p_sig_id                 => '48',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.vendor_id,
          ac.check_date,
          ac.amount,
          ac.org_id
   FROM ap_checks_all ac,
        ap_system_parameters_all asp,
        ap_payment_history_all ph,
        (
          ##$$CVIEW$$##
        ) chks
   WHERE ac.org_id = asp.org_id
   AND   ac.currency_code <> asp.base_currency_code
   AND   ph.check_id = ac.check_id
   AND   nvl(ph.historical_flag, ''N'') <> ''Y''
   AND   /* pmt created exchange rate */
         ((ph.transaction_type in (''PAYMENT CREATED'', ''REFUND RECORDED'',
                 ''MANUAL PAYMENT ADJUSTED'',
                 ''PAYMENT ADJUSTED'', ''REFUND ADJUSTED'',
                 ''PAYMENT CANCELLED'', ''REFUND CANCELLED'') AND
           ph.pmt_to_base_xrate is null AND
           ((nvl(ph.posted_flag,''N'') <> ''Y'' AND
             (decode(ph.pmt_to_base_xrate_type,
                ''User'', null,
                ph.pmt_to_base_xrate_type) is null OR
             ph.pmt_to_base_xrate_date is null OR
             EXISTS (
               /*autorate will not pick it up if aip rate and base are populated */
               SELECT 1 FROM ap_invoice_payments_all aip
               WHERE aip.check_id = ph.check_id
               AND   aip.posted_flag = ''N''
               AND   aip.accounting_event_id = ph.accounting_event_id
               AND   aip.invoice_base_amount is not null
               AND   aip.exchange_rate is not null))) OR
            (ph.posted_flag = ''Y'' AND
             (ac.exchange_rate is null OR
              ph.trx_base_amount is null OR
              ap_utilities_pkg.ap_round_currency(
                ph.trx_pmt_amount * ac.exchange_rate,
                ph.pmt_currency_code) <> ph.trx_base_amount)))) OR
          /* pmt maturity exchange rate */
          (ph.transaction_type in (''PAYMENT MATURITY'',
              ''PAYMENT MATURITY ADJUSTED'', ''PAYMENT MATURITY REVERSAL'') AND
           ph.pmt_to_base_xrate is null AND
           (nvl(ph.posted_flag,''N'') <> ''Y'' AND
            (decode(ph.pmt_to_base_xrate_type,
               ''User'', null,
               ph.pmt_to_base_xrate_type) is null OR
             ph.pmt_to_base_xrate_date is null) OR
            (ph.posted_flag = ''Y'' AND
             (ac.maturity_exchange_rate is null OR
              ph.trx_base_amount is null OR
              ap_utilities_pkg.ap_round_currency(
                ph.trx_pmt_amount * ac.maturity_exchange_rate,
                ph.pmt_currency_code) <> ph.trx_base_amount)))) OR
          /* pmt clearing exchange rate */
          (ph.transaction_type in (''PAYMENT CLEARING'',
             ''PAYMENT CLEARING ADJUSTED'', ''PAYMENT UNCLEARING'') AND
           (ph.pmt_to_base_xrate is null AND
            (nvl(ph.posted_flag,''N'') <> ''Y'' OR
             (ph.posted_flag = ''Y'' AND
              (ac.cleared_exchange_rate is null OR
               ph.trx_base_amount is null OR
               ap_utilities_pkg.ap_round_currency(
                 ph.trx_pmt_amount * ac.cleared_exchange_rate,
                 ph.pmt_currency_code) <> ph.trx_base_amount)))) OR
               (ph.bank_to_base_xrate is null AND
                ph.bank_currency_code <> asp.base_currency_code)))
   AND   ac.check_id = chks.check_id',
      p_title                  => 'MGD-48',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Foreign currency checks that are missing exchange rates, maturity exchange rates, or clearing exchange rates.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>18491045</br><strong>Note: </strong>[1125533/KB627007]</br><strong>Script Name: </strong>ap_rate_miss_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1125533/KB627007]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '9'
      );
   l_info.delete;
debug('end add_signature: 48');



debug('begin add_signature: 49');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Payment Selection';
   l_info('bug_number'):= '17918701';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1154813.1';
   l_info('problem'):= 'Incorrect check statuses when Payables accounting option ''Account for Payment When Payment Clears'' is disabled. Payments are accounted but appear as unreconciled';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1154813.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3760',
      p_sig_id                 => '49',
      p_sig_sql                => 'SELECT /*+ leading(chks) */
          ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.check_date,
          ac.payment_method_lookup_code,
          ac.checkrun_name,
          ac.vendor_id,
          ac.vendor_site_id,
          ac.amount,
          ac.currency_code,
          ac.payment_type_flag,
          ac.cleared_amount,
          ac.status_lookup_code
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac
   WHERE ac.check_id = chks.check_id
   AND   ac.status_lookup_code IN (
           ''CLEARED BUT UNACCOUNTED'',''RECONCILED UNACCOUNTED'')
   AND   NOT EXISTS (
           SELECT ''Check has no clearing event or accounted clearing ''||
                  ''event but check status is wrong''
           FROM ap_payment_history_all aph
           WHERE transaction_type   IN (
                  ''PAYMENT CLEARING'', ''PAYMENT UNCLEARING'',
                  ''PAYMENT CLEARING ADJUSTED'', ''PAYMENT UNCLEARING ADJUSTED'')
           AND   aph.check_id = ac.check_id
           AND   nvl(aph.posted_flag,''N'') ! = ''Y'')',
      p_title                  => 'MGD-49',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incorrect check statuses when Payables accounting option ''Account for Payment When Payment Clears'' is disabled. Payments are accounted but appear as unreconciled<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>17918701</br><strong>Note: </strong>[1154813/KB716355]</br><strong>Script Name: </strong>ap_wrgchksts_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1154813/KB716355]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '8'
      );
   l_info.delete;
debug('end add_signature: 49');



