      p_solution               => '<strong>Solution GDF: </strong>25984141</br><strong>Note: </strong>[1206075/KB361783]</br><strong>Script Name: </strong>ap_negotiable_iby_void_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1206075/KB361783]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
