debug('begin add_signature: 51');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Payment Selection';
   l_info('bug_number'):= '20422292';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1264221.1';
   l_info('problem'):= 'Checks in functional currency with exchange rate information populated in ap_checks_all or  ap_payment_history_all';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1264221.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3757',
      p_sig_id                 => '51',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.currency_code,
          aph.payment_history_id,
          aph.transaction_type,
          aph.trx_base_amount,
          aph.accounting_event_id,
          aph.pmt_to_base_xrate_type,
          aph.pmt_to_base_xrate_date,
          aph.pmt_to_base_xrate
   FROM ap_checks_all ac,
        ap_payment_history_all aph,
        ap_system_parameters_all asp,
        (
          ##$$CVIEW$$##
        ) chks
   WHERE ac.check_id = aph.check_id
   AND   asp.org_id = ac.org_id
   AND   asp.base_currency_code = ac.currency_code
   AND   (aph.pmt_to_base_xrate is not null OR
          ac.exchange_rate is not null OR
