debug('begin add_signature: 54');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Payment Selection';
   l_info('bug_number'):= '17855319';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1315138.1';
   l_info('problem'):= 'Checks which have been reconciled but which have a status of NEGOTIABLE in ap_checks_all';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1315138.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3831',
      p_sig_id                 => '54',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.check_date,
          ac.amount,
          ac.vendor_id,
          ac.status_lookup_code,
          ac.org_id,
          ac.cleared_amount,
          ac.cleared_date
   FROM ap_checks_all ac,
        ap_system_parameters_all asp,
        (
          ##$$CVIEW$$##
        ) chks
   WHERE ac.org_id = asp.org_id
   AND   asp.recon_accounting_flag = ''Y''
   AND   ac.status_lookup_code = ''NEGOTIABLE''
   AND   ac.check_id IN (
           SELECT aph.check_id FROM ap_payment_history_all aph
           WHERE aph.check_id = ac.check_id
           AND   aph.transaction_type = ''PAYMENT CLEARING''
           AND   aph.payment_history_id = (
                   SELECT max(aph2.payment_history_id) FROM ap_payment_history_all aph2
                   WHERE aph2.transaction_type in
                           (''PAYMENT CLEARING'',''PAYMENT UNCLEARING'')
                   AND   ac.check_id = aph2.check_id))
   AND   NOT EXISTS (
           SELECT ''1'' FROM ap_payment_history_all aph1
           WHERE ac.check_id = aph1.check_id
           AND   aph1.transaction_type = ''PAYMENT CANCELLED'')
   AND   ac.check_id = chks.check_id',
      p_title                  => 'MGD-54',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Checks which have been reconciled but which have a status of NEGOTIABLE in ap_checks_all<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>17855319</br><strong>Note: </strong>[1315138/KB750731]</br><strong>Script Name: </strong>ap_check_stat_incorrect_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1315138/KB750731]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '8'
      );
