   l_info('problem'):= 'Remit to columns are incorrect in ap_checks_all and ap_recurring_payments all after supplier merge';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 982802.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3835',
      p_sig_id                 => '56',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.vendor_id,
          ac.vendor_site_id,
          ac.remit_to_supplier_id,
          ac.remit_to_supplier_site_id,
          ac.relationship_id
   FROM ap_checks_all ac,
        (
