debug('begin add_signature: 121');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '17511602';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1089119.1';
   l_info('problem'):= 'Payment accounting is wrong when there is a discount';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1089119.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3869',
      p_sig_id                 => '121',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.check_date,
          ac.vendor_id,
          ac.amount check_amount,
          aip.invoice_payment_id,
          aip.amount,
          aip.discount_taken,
          aip.invoice_id,
          aph.transaction_type,
          aph.accounting_event_id,
          aph.accounting_date,
          aph.posted_flag,
          aph.historical_flag
   FROM ap_checks_all ac,
        ap_invoice_payments_all aip,
        ap_payment_history_all aph,
        (
          ##$$CVIEW$$##
        ) chks
   WHERE aip.check_id = ac.check_id
   AND   ac.void_date is null
   AND   aph.check_id = aip.check_id
   AND   aph.accounting_event_id = aip.accounting_event_id
   AND   aip.discount_taken <> 0
   AND   aip.posted_flag = ''Y''
   AND   aip.reversal_inv_pmt_id is null
   AND   aip.amount - nvl(aip.discount_taken, 0) = (
           SELECT sum(aphd.amount) FROM ap_payment_hist_dists aphd
