debug('begin add_signature: 122');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '17638041';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1140253.1';
   l_info('problem'):= 'Payment cancellation did not revert unclearing, incorrect accounting';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1140253.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3864',
      p_sig_id                 => '122',
      p_sig_sql                => 'SELECT pt.check_id,
          pt.check_number,
          pt.org_id,
          pt.check_date,
          pt.amount check_amount,
          aph.payment_history_id,
          aph.transaction_type,
          aph.accounting_event_id event_id,
          aph.posted_flag,
          pt.acctd_cash
   FROM (
          SELECT /*+ ordered use_nl(ac, aph, asp, xe) */
                 ac.org_id,
                 ac.check_number,
                 ac.check_id,
                 ac.check_date,
                 ac.amount,
                 xah.ledger_id,
                 sum(nvl(entered_cr,0) - nvl(entered_dr,0)) acctd_cash
          FROM (
                 ##$$CVIEW$$##
               ) chks,
               ap_checks_all ac,
               ap_payment_history_all aph,
               ap_system_parameters_all asp,
               xla_events xe,
               xla_ae_headers xah,
               xla_ae_lines xal
          WHERE ac.check_id = aph.check_id
          AND   aph.accounting_event_id = xe.event_id
          AND   xe.event_id = xah.event_id
          AND   xal.ae_header_id = xah.ae_header_id
          AND   accounting_class_code like ''CASH%CLEAR%''
          AND   asp.org_id = ac.org_id
          AND   asp.set_of_books_id = xah.ledger_id
          AND   ac.void_date       is not null
          AND   ac.check_date       > (
                  SELECT MIN(TRUNC(creation_date)) FROM ad_applied_patches
                  WHERE patch_type = ''MAINTENANCE-PACK''
                  AND   maint_pack_level LIKE ''12.0%'')
          AND   NOT EXISTS (
                  SELECT /*+ no_unnest */ 1 FROM ap_payment_history_all aph1
                  WHERE aph1.check_id = ac.check_id
                  AND   posted_flag <> ''Y'')
          AND   EXISTS (
                  SELECT /*+ no_unnest */ 1
                  FROM ap_payment_history_all aph2,
                       xla_events xe2
                  WHERE aph2.check_id = ac.check_id
                  AND   aph2.accounting_event_id = xe2.event_id
                  AND   aph2.posted_flag = ''Y''
                  AND   xe2.event_status_code = ''P''
                  AND   xe2.process_status_code = ''P''
                  AND   aph2.transaction_type = ''PAYMENT UNCLEARING'')
          AND   ac.check_id = chks.check_id
          GROUP BY ac.org_id, ac.check_number, ac.check_id, ac.amount,
                   ac.check_date, xah.ledger_id
          HAVING   0 <> sum(nvl(entered_cr,0) - nvl(entered_dr,0))
        ) pt,
        ap_payment_history_all aph,
        xla_ae_headers xah
   WHERE aph.check_id = pt.check_id
   AND   aph.accounting_event_id = xah.event_id
   AND   xah.application_id = 200
   AND   xah.ledger_id = pt.ledger_id
   AND   aph.transaction_type IN (''PAYMENT CANCELLED'',
           ''REFUND CANCELLED'')
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_payment_history_all aph2,
                xla_distribution_links xdl1
           WHERE aph2.transaction_type = ''PAYMENT CLEARING''
           AND   aph2.check_id = aph.check_id
           AND   xdl1.ref_event_id = aph2.accounting_event_id
           AND   xdl1.ae_header_id = xah.ae_header_id
           AND   xdl1.application_id = 200)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_payment_history_all aph3,
                xla_distribution_links xdl2
           WHERE aph3.transaction_type = ''PAYMENT UNCLEARING''
           AND   aph3.check_id = aph.check_id
           AND   xdl2.ref_event_id = aph3.accounting_event_id
           AND   xdl2.ae_header_id = xah.ae_header_id
           AND   xdl2.application_id = 200)',
      p_title                  => 'MGD-122',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment cancellation did not revert unclearing, incorrect accounting<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>17638041</br><strong>Note: </strong>[1140253/KB282259]</br><strong>Script Name: </strong>ap_CancPmtUnclrdNotRev_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1140253/KB282259]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '10'
      );
   l_info.delete;
