debug('begin add_signature: 131');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '19367686';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1118703.1';
   l_info('problem'):= 'Checks accounted with incorrect amounts due to bugs 8975671 and 9257606.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1118703.1.<br>
<br>
You should also ensure the code fix is applied as detailed in Doc ID 1059577.1.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3867',
      p_sig_id                 => '131',
      p_sig_sql                => 'WITH ctrl AS (
     SELECT DISTINCT
            aip.check_id
     FROM (
            ##$$CVIEW$$##
          ) chks,
          ap_invoice_payments_all aip,
          ap_invoice_payments_all aip2,
          ap_checks_all ac1
     WHERE ac1.void_date is not null
     AND   ac1.status_lookup_code = ''VOIDED''
     AND   ac1.check_id = aip2.check_id
     AND   aip.check_id != aip2.check_id
     AND   aip2.invoice_id = aip.invoice_id
     AND   aip.check_id = chks.check_id
   )
   SELECT /*+ ordered use_nl(ac, aph, xe, xh, xl) */
          ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.check_date,
          xe.event_id,
          xe.event_type_code,
          sum(nvl(entered_cr,   0)) - sum(nvl(entered_dr,   0)) acctd_amt,
          ac.amount,
          ''Case 1'' case
   FROM ctrl,
        ap_checks_all ac,
        ap_payment_history_all aph,
        xla_events xe,
        xla_ae_headers xh,
        xla_ae_lines xl,
        ap_system_parameters_all asp
   WHERE xl.application_id = 200
   AND   aph.check_id = ac.check_id
   AND   ac.check_id = ctrl.check_id
   AND   ac.void_date is null
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_payments_all aip
           WHERE aip.check_id = ac.check_id
           GROUP BY aip.check_id
           HAVING   sum(aip.amount) = ac.amount)
   AND   aph.accounting_event_id = xe.event_id
   AND   aph.posted_flag = ''Y''
   AND   xe.event_id = xh.event_id
   AND   xh.upg_batch_id is null
   AND   xe.event_type_code IN(''PAYMENT CREATED'', ''REFUND RECORDED'',
           ''PAYMENT CLEARED'')
   AND   xe.event_status_code = ''P''
   AND   xe.application_id = 200
   AND   xh.application_id = 200
   AND   xh.ledger_id = asp.set_of_books_id
   AND   xh.ae_header_id = xl.ae_header_id
   AND   asp.org_id = ac.org_id
   AND   xl.accounting_class_code IN(''CASH_CLEARING'', ''CASH'',
           ''FUTURE_DATED_PMT'')
   AND   decode(xe.event_type_code,
           ''PAYMENT CLEARED'',xl.accounting_class_code,
           ''YES'') != ''CASH''
   GROUP BY ac.org_id, ac.check_id, ac.check_date, ac.check_number,
            ac.amount, xe.event_id, xe.event_type_code
   HAVING   abs(abs(sum(nvl(entered_cr,0)) -
            sum(nvl(entered_dr,0)) ) - abs(ac.amount)) > 1
   UNION ALL
   SELECT /*+ ordered use_nl(ac, aph, aphd, xh) */
          ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.check_date,
          aph.accounting_event_id,
          aph.transaction_type,
          0 acctd_amt,
          ac.amount,
          ''Case 2''
   FROM ctrl,
        ap_checks_all ac,
        ap_payment_history_all aph,
        ap_payment_hist_dists aphd,
        xla_ae_headers xh,
        ap_system_parameters_all asp
   WHERE ac.amount <> 0
   AND aph.check_id = ac.check_id
   AND ac.check_id = ctrl.check_id
   AND ac.void_date is null
   AND asp.org_id = ac.org_id
   AND aphd.accounting_event_id = aph.accounting_event_id
   AND aphd.accounting_event_id = xh.event_id
   AND xh.application_id = 200
   AND xh.upg_batch_id is null
   AND aphd.pay_dist_lookup_code IN( ''CASH'', ''FINAL PAYMENT ROUNDING'')
   AND aph.transaction_type IN (''PAYMENT CREATED'',''REFUND RECORDED'')
   AND aph.posted_flag = ''Y''
   GROUP BY ac.org_id, ac.check_id, ac.check_date,
            ac.check_number, ac.amount, aph.accounting_event_id,
            aph.transaction_type
   HAVING SUM(aphd.invoice_dist_base_amount) = 0',
      p_title                  => 'MGD-131',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Checks accounted with incorrect amounts due to bugs 8975671 and 9257606.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>19367686</br><strong>Note: </strong>[1118703/KB690643]</br><strong>Script Name: </strong>ap_reissue_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1118703/KB690643].<br>
<br>
You should also ensure the code fix is applied as detailed in [1059577/KB345068].</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '14'
      );
   l_info.delete;
debug('end add_signature: 131');



