   l_info('problem'):= 'EC12 error in journal import - wrong payment clearing accounting due to incorrect Bank_Curr_Amount in the table AP_Payment_Hist_Dists';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1193313.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3907',
      p_sig_id                 => '134',
      p_sig_sql                => 'SELECT DISTINCT
          ''DIRECT'' affected_checks,
          ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.amount,
          ac.check_date,
          ac.cleared_date,
          aph.payment_history_id,
          aph.transaction_type,
          aph.accounting_event_id event_id,
          aph.bank_currency_code,
          aph.pmt_currency_code
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        ap_payment_hist_dists aphd
   WHERE aph.payment_history_id = aphd.payment_history_id
   AND   ac.check_id = aph.check_id
   AND   aph.transaction_type like ''PAYMENT CLEARING%''
   AND   aph.posted_flag = ''Y''
   AND   aphd.pay_dist_lookup_code = ''CASH''
   AND   aph.bank_currency_code = aph.pmt_currency_code
