   l_info('note_number'):= '1264147.1';
   l_info('problem'):= 'Accounting_event_id is out of sync between AP_Invoice_Payments_all and AP_Payment_History_All tables';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1264147.1';
