   l_info('problem'):= 'Orphan checks not paying any invoice and where another check exists with the same check number and vendor information or payment document id. These orphans cause the accounting program to fail';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2115968.1';
   l_info('sub_category'):= 'ACCOUNTING';
