debug('begin add_signature: 139');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Period Close';
   l_info('bug_number'):= '26255537';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '874904.1';
   l_info('problem'):= 'Out of sync accounting date between payment transaction tables and xla_events table';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 874904.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3824',
      p_sig_id                 => '139',
      p_sig_sql                => 'WITH chks AS (
     ##$$MCVIEW$$##
   )
   SELECT ''Invoice Payment'' record_type,
          ac.check_id,
          ac.check_number,
          ac.org_id,
          aip.accounting_date,
          xe.event_date,
          xe.event_id,
          aip.invoice_payment_id,
          aip.posted_flag
   FROM chks,
        ap_checks_all ac,
        ap_invoice_payments_all aip,
        xla_events xe
   WHERE aip.accounting_event_id = xe.event_id
   AND   xe.application_id = 200
   AND   ac.check_id = aip.check_id
   AND   aip.accounting_DATE <> xe.event_date
   AND   ac.check_id = chks.check_id
   UNION ALL
   SELECT ''Payment History'',
          ac.check_id,
          ac.check_number,
          ac.org_id,
          aph.accounting_date,
          xe.event_date,
          xe.event_id,
          aph.payment_history_id,
          aph.posted_flag
   FROM chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        xla_events xe
   WHERE aph.accounting_event_id = xe.event_id
   AND   ac.check_id = aph.check_id
   AND   xe.application_id = 200
   AND   aph.accounting_date <> xe.event_date
   AND   ac.check_id = chks.check_id',
      p_title                  => 'MGD-139',
