debug('begin add_signature: 141');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Period Close, Trial Balance';
   l_info('bug_number'):= '24692565';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
