      p_sig_sql                => 'WITH chks AS (
     ##$$MCVIEW$$##
   )
   SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          ''AP_INVOICE_PAYMENTS_ALL'' trx_table,
