   FROM chks,
        ap_checks_all ac,
        ap_invoice_payments_all aip,
        xla_events xe,
        xla_transaction_entities_upg xte,
        gl_ledgers gl
   WHERE (aip.posted_flag = ''N'' OR
          (aip.accrual_posted_flag = ''N'' AND
           nvl(gl.sla_ledger_cash_basis_flag, ''N'') <> ''Y''))
   AND   aip.set_of_books_id = gl.ledger_id
   AND   xe.process_status_code = ''P''
   AND   xe.event_status_code IN (''N'',''P'')
   AND   ac.check_id = aip.check_id
   AND   xe.event_id = aip.accounting_event_id
   AND   xte.security_id_int_1 = ac.org_id
   AND   xe.entity_id = xte.entity_id
   AND   xe.application_id = xte.application_id
   AND   xe.application_id = 200
   AND   ac.check_id = chks.check_id
   UNION ALL
   SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          ''AP_PAYMENT_HISTORY_ALL'' trx_table,
          aph.payment_history_id trx_id,
          aph.posted_flag,
          null,
          null,
          xe.event_id,
          xte.ledger_id ledger_id
   FROM chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        xla_events xe,
        xla_transaction_entities_upg xte
   WHERE aph.posted_flag <> ''Y''
   AND   xe.process_status_code = ''P''
   AND   xe.event_status_code IN (''N'',''P'')
   AND   xte.security_id_int_1 = aph.org_id
   AND   xe.event_id = aph.accounting_event_id
   AND   ac.check_id = aph.check_id
   AND   xe.entity_id = xte.entity_id
   AND   xe.application_id = 200
   AND   xte.application_id = 200
   AND   ac.check_id = chks.check_id',
      p_title                  => 'MGD-143',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Out of Sync Posting status between the Accounting events in the Events tables and the transaction tables.<br/><strong>Impact Area(s): </strong>Accounting Failure, Period Close, Sweep',
      p_solution               => '<strong>Solution GDF: </strong>18997220</br><strong>Note: </strong>[1071876/KB207473]</br><strong>Script Name: </strong>ap_incorrect_posted_flag_sel.sql Payments</br></br>Apply the GDF patch following the instructions provided in [1071876/KB207473]',
