      p_sig_id                 => '144',
      p_sig_sql                => 'WITH chks AS (
     ##$$MCVIEW$$##
   )
   SELECT ''AP_INVOICE_PAYMENTS_ALL'' transaction_table,
          ac.check_id,
          ac.check_number,
          ac.org_id,
          invoice_payment_id transaction_id,
          posted_flag,
          event_id,
          event_status_code,
          decode(event_status_code, ''P'',''Y'',''N'') events_posted_flag,
          aip.invoice_id,
          invoice_num
   FROM chks,
        ap_checks_all ac,
        ap_invoice_payments_all aip,
        xla_events xe,
        ap_invoices_all ai
   WHERE aip.posted_flag = ''S''
   AND   xe.application_id = 200
   AND   xe.event_id = aip.accounting_event_id
   AND   ac.check_id = aip.check_id
   AND   ai.invoice_id = aip.invoice_id
   AND   ac.check_id = chks.check_id
   UNION ALL
   SELECT ''AP_PAYMENT_HISTORY_ALL'',
          ac.check_id,
          ac.check_number,
          ac.org_id,
          payment_history_id,
          posted_flag,
          event_id ,
          event_status_code,
          decode(event_status_code, ''P'',''Y'',''N'') events_posted_flag,
          null,
          null
   FROM chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        xla_events xe
   WHERE aph.posted_flag = ''S''
   AND   xe.application_id = 200
   AND   xe.event_id = aph.accounting_event_id
   AND   ac.check_id = aph.check_id
   AND   ac.check_id = chks.check_id',
      p_title                  => 'MGD-144',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Posted Flag stuck in status ''S'' on transaction tables<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>17956236</br><strong>Note: </strong>[1088872/KB633498]</br><strong>Script Name: </strong>ap_posted_flag_out_sync_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1088872/KB633498]. Note: if the event is in N/P status this GDF will not work.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
