debug('begin add_signature: 145');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '17533422';
   l_info('category'):= 'PAYMENT';
