   l_info('note_number'):= '1316588.1';
   l_info('problem'):= 'Incorrect technical rounding on the column Invoice_Dist_Base_Amount in the table AP_PAYMENT_HIST_DISTS causing Incorrect Payment Accounting ';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1316588.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3942',
      p_sig_id                 => '145',
      p_sig_sql                => 'SELECT aip.check_id,
          aip.org_id,
          aip.invoice_id
   FROM ap_invoice_payments_all aip,
        ap_payment_history_all aph,
        ap_payment_hist_dists aphd,
        ap_system_parameters_all asp,
        (
          ##$$CVIEW$$##
        ) chks
   WHERE aip.check_id = aph.check_id
   AND   aphd.invoice_payment_id = aip.invoice_payment_id
   AND   aphd.pay_dist_lookup_code = ''CASH''
   AND   aip.accounting_event_id = aphd.accounting_event_id
   AND   aip.accounting_event_id = aph.accounting_event_id
   AND   aph.payment_history_id = aphd.payment_history_id
   AND   aph.historical_flag is null
   AND   aph.pmt_currency_code <> asp.base_currency_code
   AND   aph.org_id = asp.org_id
   AND   aph.transaction_type IN (''PAYMENT CREATED'' , ''REFUND RECORDED'')
   AND   aph.posted_flag = ''Y''
   AND   aip.check_id = chks.check_id
   GROUP BY aip.check_id, aip.org_id, aip.invoice_id, aip.invoice_payment_id,
            aip.invoice_base_amount, aip.accounting_event_id, aip.amount
   HAVING   sum(nvl(aphd.invoice_dist_base_amount, invoice_dist_amount)) !=
              nvl(aip.invoice_base_amount,aip.amount)',
      p_title                  => 'MGD-145',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incorrect technical rounding on the column Invoice_Dist_Base_Amount in the table AP_PAYMENT_HIST_DISTS causing Incorrect Payment Accounting <br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>17533422</br><strong>Note: </strong>[1316588/KB771769]</br><strong>Script Name: </strong>ap_pay_cr_has_x_idba_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1316588/KB771769]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
