   l_info('problem'):= 'Payment history distributions having zero values due to incorrect proration of invoice distributions when the invoice amount is zero';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1505485.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4164',
      p_sig_id                 => '265',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(aph, aip, ai) */
          aip.check_id,
          aip.org_id,
          ai.invoice_id,
          ai.invoice_num,
          aph.accounting_event_id,
          aip.invoice_payment_id
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_payment_history_all aph,
        ap_invoice_payments_all aip,
        ap_invoices_all ai
   WHERE aph.check_id = chks.check_id
   AND   aip.invoice_id = ai.invoice_id
   AND   aip.posted_flag = ''Y''
   AND   aip.org_id = ai.org_id
   AND   aip.amount = 0
   AND   ai.invoice_amount = 0
   AND   ai.payment_status_flag = ''Y''
   AND   aph.check_id = aip.check_id
   AND   aph.transaction_type in (''PAYMENT CREATED'',
           ''REFUND RECORDED'', ''PAYMENT CLEARING'')
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.amount    <> 0)
   AND   EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_payment_hist_dists aphd
           WHERE aphd.accounting_event_id = aph.accounting_event_id
           AND   aphd.invoice_payment_id  = aip.invoice_payment_id
           AND   aphd.pay_dist_lookup_code = ''CASH''
           AND   aphd.amount             = 0)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM ap_payment_hist_dists aphd
           WHERE aphd.accounting_event_id = aph.accounting_event_id
           AND   aphd.invoice_payment_id  = aip.invoice_payment_id
           AND   aphd.pay_dist_lookup_code = ''CASH''
           AND   aphd.amount             <> 0)
   AND   NOT EXISTS (
           SELECT /*+ no_unnest */ 1
           FROM xla_ae_headers xah
           WHERE xah.event_id = aph.accounting_event_id
           AND   xah.upg_batch_id IS NOT NULL
           AND   xah.application_id = 200
           AND   xah.ledger_id = aip.set_of_books_id)',
