      p_problem_descr          => 'The value for GL_SL_LINK is missing on upgraded accounting lines which are transferred to GL.<br/><strong>Impact Area(s): </strong>Drilldown',
      p_solution               => '<strong>Solution GDF: </strong>13783741</br><strong>Note: </strong>[1445563/KB464222]</br><strong>Script Name: </strong>xla_transR12_xdl_miss_sel.sql Payment</br></br>Apply the GDF patch following the instructions provided in [1445563/KB464222]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
