debug('end add_signature: 275');



debug('begin add_signature: 283');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '18799665';
   l_info('category'):= 'PAYMENT';
