   l_info('problem'):= 'Upgraded checks adjusted in R12 did not have a Payment Adjusted event created causing Payment Clearing events not to be accounted with the message "This line cannot be accounted until the accounting event that it references has been fully accounted."';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1920251.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4018',
      p_sig_id                 => '283',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          ac.vendor_id,
          aph.transaction_type,
          aph.posted_flag,
          aph.payment_history_id,
          xe.event_id
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        xla_events xe,
        ap_payment_history_all aph_clr,
        ap_payment_hist_dists aphd,
        ap_invoice_distributions_all aid
   WHERE ac.check_id = chks.check_id
   AND   aph.transaction_type in (''PAYMENT CREATED'',''REFUND RECORDED'')
   AND   nvl(aph.historical_flag,''N'') = ''Y''
   AND   aph.posted_flag = ''Y''
   AND   xe.event_id = aph.accounting_event_id
   AND   nvl(xe.upg_batch_id, -9999) <> -9999
   AND   aph_clr.check_id = aph.check_id
   AND   aph_clr.transaction_type in (''PAYMENT CLEARING'', ''PAYMENT MATURITY'')
   AND   aph_clr.posted_flag <> ''Y''
   AND   aph_clr.historical_flag is null
   AND   aphd.payment_history_id = aph_clr.payment_history_id
   AND   aid.invoice_distribution_id = aphd.invoice_distribution_id
   AND   aid.historical_flag is null
   AND   aid.posted_flag = ''Y''
   AND   aph.check_id = ac.check_id
   AND   NOT EXISTS (
           SELECT 1 FROM ap_payment_hist_dists aphd2
           WHERE aphd2.payment_history_id = aph.payment_history_id
           AND   aphd2.invoice_distribution_id = aphd.invoice_distribution_id)
   AND   EXISTS (
           SELECT 1 FROM ap_payment_hist_dists aphd3
           WHERE aphd3.payment_history_id = aph.payment_history_id)',
      p_title                  => 'MGD-283',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Upgraded checks adjusted in R12 did not have a Payment Adjusted event created causing Payment Clearing events not to be accounted with the message "This line cannot be accounted until the accounting event that it references has been fully accounted."<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Solution GDF: </strong>18799665</br><strong>Note: </strong>[1920251/KB675365]</br><strong>Script Name: </strong>ap_11i_chk_missg_adj_event_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1920251/KB675365]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
