debug('begin add_signature: 360');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Trial Balance';
   l_info('bug_number'):= '17571683';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1377248.1';
   l_info('problem'):= 'Accounting transactions which have not been merged to the destination supplier after Supplier/Site merge';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1377248.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4083',
      p_sig_id                 => '360',
      p_sig_sql                => 'WITH chks AS (
     ##$$MCVIEW$$##
   ),
  ap_ledger_options AS (
     SELECT aip.set_of_books_id,
            nvl(xlo.merge_acct_option_code,''NONE'') merge_acct_option_code,
            adv.org_id,
            adv.vendor_id to_vendor_id,
            adv.vendor_site_id to_vendor_site_id,
            adv.duplicate_vendor_id from_vendor_id,
            adv.duplicate_vendor_site_id from_vendor_site_id,
            adv.process,
            adv.paid_invoices_flag
      FROM chks,
           xla_ledger_options xlo,
           ap_invoice_payments_all aip,
           ap_checks_all ac,
           ap_duplicate_vendors_all adv
      WHERE ac.check_id = chks.check_id
      AND   aip.set_of_books_id = xlo.ledger_id
      AND   xlo.application_id = 200
     -- AND   xlo.merge_acct_option_code IN (''CHANGE'',''TRANSFER'')   -- REQ 210113 - Removing this line
         AND xlo.merge_acct_option_code IN (''CHANGE'',''TRANSFER'', ''NONE'')   -- REQ 210113 - Adding this line
AND   aip.check_id = ac.check_id
      AND   ac.vendor_id = adv.vendor_id
      AND   nvl(adv.vendor_site_id,ac.vendor_site_id) = ac.vendor_site_id
      AND   adv.process_flag = ''Y''
      AND   adv.process <> ''P'')
   SELECT alo.to_vendor_id,
          nvl(alo.to_vendor_site_id,ac.vendor_site_id) to_vendor_site_id,
          alo.org_id,
          ac.check_id source_id_int_1,
          alo.from_vendor_id,
          alo.from_vendor_site_id,
          to_char(ac.check_number) source_number,
          ''AP_PAYMENTS'' entity_code,
          aip.set_of_books_id ledger_id
   FROM chks,
        ap_checks_all ac,
        ap_invoice_payments_all aip,
        ap_ledger_options alo
   WHERE ac.check_id = chks.check_id
   AND   aip.set_of_books_id = alo.set_of_books_id
   AND   aip.check_id = ac.check_id
   AND   ac.vendor_id = alo.to_vendor_id
   AND   ac.vendor_site_id = nvl(alo.to_vendor_site_id,ac.vendor_site_id)
   AND   alo.merge_acct_option_code = ''TRANSFER''
   AND   alo.paid_invoices_flag = ''Y''
   AND   NOT EXISTS (
           SELECT ''No Merge Entry in xla for this vendor site''
           FROM xla_transaction_entities_upg xte,
                xla_events xe
           WHERE xte.application_id = 200
           AND   xte.ledger_id = alo.set_of_books_id
           AND   xte.entity_code = ''THIRD_PARTY_MERGE''
           AND   xe.entity_id = xte.entity_id
           AND   xe.application_id = 200
           AND   xe.event_type_code  IN (''FULL_MERGE'',''PARTIAL_MERGE'')
           AND   xe.reference_num_1 = alo.from_vendor_id
           AND   xe.reference_num_2 = alo.from_vendor_site_id
           AND   xe.reference_num_3 = alo.to_vendor_id
           AND   xe.reference_num_4 = nvl(alo.to_vendor_site_id,xe.reference_num_4))
   AND   EXISTS (
           SELECT ''Need to merger invoice''
           FROM xla_ae_lines xel,
                xla_ae_headers xeh,
                xla_transaction_entities_upg xte
           WHERE xte.application_id = 200
           AND   xel.application_id = xeh.application_id
           AND   xeh.accounting_entry_status_code = ''F''
           AND   xte.application_id = xeh.application_id
           AND   xel.ae_header_id = xeh.ae_header_id
           AND   xte.entity_code = ''AP_PAYMENTS''
           AND   xte.ledger_id = aip.set_of_books_id
           AND   nvl(xte.source_id_int_1,(-99)) = ac.check_id
           AND   xte.entity_id = xeh.entity_id
           AND   xel.party_id = alo.from_vendor_id
           AND   xel.party_site_id = alo.from_vendor_site_id)
   UNION ALL
   SELECT alo.to_vendor_id,
          nvl(alo.to_vendor_site_id,ac.vendor_site_id ) to_vendor_site_id,
          alo.org_id,
          ac.check_id source_id_int_1,
          alo.from_vendor_id,
          alo.from_vendor_site_id,
          to_char(ac.check_number) source_number,
          ''AP_PAYMENTS'' entity_code,
          aip.set_of_books_id ledger_id
   FROM chks,
        ap_checks_all ac,
        ap_invoice_payments_all aip,
        ap_ledger_options alo
   WHERE ac.check_id = chks.check_id
   AND   aip.set_of_books_id = alo.set_of_books_id
   AND   aip.check_id = ac.check_id
   AND   ac.vendor_id = alo.to_vendor_id
   AND   ac.vendor_site_id = nvl(alo.to_vendor_site_id,ac.vendor_site_id )
   AND   alo.merge_acct_option_code = ''CHANGE''
   AND   alo.paid_invoices_flag = ''Y''
   AND   EXISTS (
           SELECT ''Need to merger invoice''
           FROM xla_ae_lines xel,
                xla_ae_headers xeh,
                xla_transaction_entities_upg xte
           WHERE xte.application_id = 200
           AND   xel.application_id = xeh.application_id
           AND   xeh.accounting_entry_status_code = ''F''
           AND   xte.application_id = xeh.application_id
           AND   xel.ae_header_id = xeh.ae_header_id
           AND   xte.entity_code = ''AP_PAYMENTS''
           AND   xte.ledger_id = aip.set_of_books_id
           AND   nvl(xte.source_id_int_1,(-99)) = ac.check_id
           AND   xte.entity_id = xeh.entity_id
           AND   xel.party_id = alo.from_vendor_id
           AND   xel.party_site_id = alo.from_vendor_site_id)',
      p_title                  => 'MGD-360',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Accounting transactions which have not been merged to the destination supplier after Supplier/Site merge<br/><strong>Impact Area(s): </strong>Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>17571683</br><strong>Note: </strong>[1377248/KB300876]</br><strong>Script Name: </strong>ap_xla_supmg_sel.sql Payment</br></br>Apply the GDF patch following the instructions provided in [1377248/KB300876]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: 360');



debug('begin add_signature: 361');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect, Automatic Witholding Tax, Trial Balance';
   l_info('bug_number'):= '18818008';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1920640.1';
   l_info('problem'):= 'Payment accounting does not fully relieve the liability for foreign currency invoices with withholding.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1920640.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4119',
      p_sig_id                 => '361',
      p_sig_sql                => 'SELECT aip.check_id,
          aip.invoice_id,
          ai.invoice_num,
          ai.set_of_books_id,
          ai.payment_status_flag,
          ai.invoice_currency_code,
          aid.invoice_line_number,
          aid.invoice_distribution_id,
          aid.amount,
          aid.base_amount
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_invoice_payments_all aip,
        ap_invoice_distributions_all aid,
        ap_invoices_all ai,
        po_vendors pov,
        gl_ledgers gl,
        fnd_currencies fc_b,
        fnd_currencies fc_i
   WHERE ac.check_id = chks.check_id
   AND   aid.invoice_id = ai.invoice_id
   AND   ai.invoice_id = aip.invoice_id
   AND   ai.set_of_books_id = gl.ledger_id
   AND   aip.check_id = ac.check_id
   AND   pov.vendor_id = ac.vendor_id
   AND   pov.vendor_id = ai.vendor_id
   AND   trunc(ai.creation_date)  >= (
           SELECT min(trunc(creation_date)) FROM ad_applied_patches
           WHERE patch_type=''MAINTENANCE-PACK''
           AND   maint_pack_level LIKE ''12.%'' )
   AND   ai.payment_status_flag = ''Y''
   AND   nvl(ai.historical_flag, ''N'') = ''N''
   AND   gl.currency_code = fc_b.currency_code
   AND   fc_i.currency_code = ai.invoice_currency_code
   AND   aid.line_type_lookup_code = ''AWT''
   AND   aid.base_amount <> round( aid.amount * ai.exchange_rate, fc_b.precision )
   AND   NOT EXISTS (
           SELECT 1 FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = ai.invoice_id
           AND   aid.prepay_distribution_id is not null)
   AND   aid.base_amount <> (
           SELECT sum(aphd.invoice_dist_base_amount)
           FROM ap_invoice_payments_all aip,
                ap_payment_hist_dists aphd
           WHERE aphd.accounting_event_id = aip.accounting_event_id
           AND   aip.amount > 0
           AND   aip.invoice_id = aid.invoice_id
           AND   aphd.invoice_payment_id = aip.invoice_payment_id
           AND   aphd.invoice_distribution_id = aid.invoice_distribution_id
           AND   aphd.pay_dist_lookup_code = ''AWT'')',
      p_title                  => 'MGD-361',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment accounting does not fully relieve the liability for foreign currency invoices with withholding.<br/><strong>Impact Area(s): </strong>Accounting Incorrect, Automatic Witholding Tax, Trial Balance',
      p_solution               => '<strong>Solution GDF: </strong>18818008</br><strong>Note: </strong>[1920640/KB291807]</br><strong>Script Name: </strong>ap_x_prorate_due_to_awt_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1920640/KB291807]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '6'
      );
   l_info.delete;
debug('end add_signature: 361');



debug('begin add_signature: 368');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '17811729';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1573926.1';
   l_info('problem'):= 'Incorrect manual payment adjustment events resulting from reversing invoices in a payment to do a manual payment adjustment but not adding in invoices to balance the payment amount.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1573926.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4100',
      p_sig_id                 => '368',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.check_date,
          ac.amount,
          ac.vendor_id,
          ac.status_lookup_code,
          ac.org_id,
          ac.cleared_amount,
          ac.cleared_date,
          pay_v.accounting_event_id,
          CASE ac.status_lookup_code
            WHEN ''VOIDED''
              THEN ''No manual action required''
            WHEN ''RECONCILED''
              THEN ''UNCLEAR Check, VOID Check''
            WHEN ''RECONCILED UNACCOUNTED''
              THEN ''UNCLEAR Check, VOID Check''
            WHEN ''CLEARED BUT UNACCOUNTED''
              THEN ''UNCLEAR Check, VOID Check''
            WHEN ''CLEARED''
              THEN ''UNCLEAR Check, VOID Check''
            WHEN ''NEGOTIABLE''
              THEN ''VOID Check''
          END "Pre-Fix Actions"
   FROM ap_checks_all ac,
        (
          SELECT /*+ leading(chks) */
                 aph.check_id,
                 aph.accounting_event_id
          FROM (
                 ##$$CVIEW$$##
               ) chks,
               ap_payment_history_all aph,
               ap_invoice_payments_all aip
          WHERE aph.check_id = chks.check_id
          AND   aph.check_id = aip.check_id
          AND   aph.accounting_event_id = aip.accounting_event_id
          AND   aph.transaction_type IN (''MANUAL PAYMENT ADJUSTED'',
                  ''REFUND ADJUSTED'')
          AND   NOT EXISTS (
                  SELECT 1 FROM ap_invoice_payments_all aip2
                  WHERE aip2.accounting_event_id = aph.accounting_event_id
                  AND   aip2.check_id = aph.check_id
                  AND   (aip2.reversal_flag <> ''Y'' OR
                         aip2.reversal_inv_pmt_id is null))
         GROUP BY aph.check_id, aph.accounting_event_id
         HAVING SUM(aip.amount) <> 0
        ) pay_v
   WHERE ac.check_id = pay_v.check_id',
      p_title                  => 'MGD-368',
      p_fail_condition         => 'RS',
