debug('begin add_signature: 399');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '13652773';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2004116.1';
   l_info('problem'):= 'Payment clearing events with large Final Cash rounding lines causing incorrect accounting.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2004116.1';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4181',
      p_sig_id                 => '399',
      p_sig_sql                => 'SELECT DISTINCT
          ac.check_id,
          aph.accounting_event_id,
          ac.base_amount,
          ac.cleared_base_amount,
          ac.cleared_charges_base_amount,
          aphd.cleared_base_amount dist_cleared_base_amt
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        ap_payment_hist_dists aphd,
        ap_system_parameters_all asp,
        xla_ae_headers h
   WHERE ac.check_id = chks.check_id
   AND   ac.check_id = aph.check_id
   AND   aph.transaction_type LIKE ''PAYMENT CLEARING%''
   AND   aph.posted_flag = ''Y''
   AND   aph.bank_currency_code != aph.pmt_currency_code
   AND   aph.org_id = asp.org_id
   AND   aph.bank_currency_code = asp.base_currency_code
   AND   aph.accounting_event_id = h.event_id
   AND   h.application_id = 200
   AND   h.upg_batch_id is null
   AND   h.ledger_id = asp.set_of_books_id
   AND   aphd.payment_history_id = aph.payment_history_id
   AND   aphd.accounting_event_id = aph.accounting_event_id
   AND   aphd.pay_dist_lookup_code = ''FINAL CASH ROUNDING''
   AND   ac.cleared_base_amount is not null
   AND   ac.void_date is null
   AND   ((0.05 > abs(abs(aphd.cleared_base_amount)
             - abs(ac.base_amount - ac.cleared_base_amount
             + nvl(ac.cleared_charges_base_amount, 0)))) OR
          (ac.cleared_charges_base_amount > 0 AND
           (0.05 > (abs(aphd.cleared_base_amount)
              - ac.cleared_charges_base_amount))))',
      p_title                  => 'MGD-399',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment clearing events with large Final Cash rounding lines causing incorrect accounting.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>13652773</br><strong>Note: </strong>[2004116/KB828328]</br><strong>Script Name: </strong>ap_pay_clear_x_fcr_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2004116/KB828328]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
