debug('begin add_signature: 451');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'GL Transfer';
   l_info('bug_number'):= '9481239';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2225571.1';
   l_info('problem'):= 'Journals marked as transferred in SLA are not in the General Ledger.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2225571.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '5848',
      p_sig_id                 => '451',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ac, xte, h, l) */
          ac.check_id,
          ac.check_number,
          ac.org_id,
          h.event_id,
          h.ledger_id,
          h.application_id,
          h.ae_header_id,
          h.accounting_date,
          h.period_name,
          h.entity_id,
          h.gl_transfer_status_code,
          h.group_id,
          l.gl_sl_link_id,
          l.gl_sl_link_table
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_system_parameters_all sp,
        xla_transaction_entities_upg xte,
        xla_ae_headers h,
        xla_ae_lines l
   WHERE ac.check_id = chks.check_id
   AND   sp.org_id = ac.org_id
   AND   nvl(xte.source_id_int_1,-99) = ac.check_id
   AND   xte.ledger_id = sp.set_of_books_id
   AND   xte.entity_code = ''AP_PAYMENTS''
   AND   xte.application_id = 200
   AND   h.application_id = xte.application_id
   AND   h.entity_id = xte.entity_id
   AND   h.gl_transfer_status_code=''Y''
   AND   h.accounting_entry_status_code=''F''
   AND   (h.upg_batch_id is null OR h.upg_batch_id = -9999)
   AND   h.ledger_id IN (
           SELECT gled.ledger_id
           FROM gl_ledger_relationships glr,
                gl_ledgers gled
           WHERE glr.primary_ledger_id = sp.set_of_books_id
           AND   glr.application_id = 101
           AND   ((glr.target_ledger_category_code IN (''SECONDARY'',''ALC'') AND
                   glr.relationship_type_code = ''SUBLEDGER'') OR
                  (glr.target_ledger_category_code IN (''PRIMARY'') AND
                   glr.relationship_type_code = ''NONE''))
           AND   glr.target_ledger_id = gled.ledger_id
           AND   nvl(gled.complete_flag,''Y'') = ''Y''
           GROUP BY gled.ledger_id)
   AND   l.application_id = h.application_id
   AND   l.ae_header_id = h.ae_header_id
   AND   l.gl_sl_link_id is not null
   AND   NOT EXISTS  (
           SELECT /*+ no_unnest */ 1
           FROM gl_import_references ir,
                gl_je_headers gh
           WHERE ir.gl_sl_link_id = l.gl_sl_link_id
           AND   ir.gl_sl_link_table = l.gl_sl_link_table
           AND   ir.je_header_id = gh.je_header_id
           AND   ir.je_batch_id = gh.je_batch_id
           AND   gh.ledger_id = h.ledger_id)',
      p_title                  => 'MGD-451',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Journals marked as transferred in SLA are not in the General Ledger.<br/><strong>Impact Area(s): </strong>GL Transfer',
      p_solution               => '<strong>Solution GDF: </strong>9481239</br><strong>Note: </strong>[2225571/KB410909]</br><strong>Script Name: </strong>xla_insla_notingl_sel.sql Payment</br></br>Apply the GDF patch following the instructions provided in [2225571/KB410909]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '4'
      );
   l_info.delete;
debug('end add_signature: 451');



debug('begin add_signature: 453');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'GL Transfer';
   l_info('bug_number'):= '13699255';
   l_info('category'):= 'PAYMENT';
