   l_info('note_number'):= '2225570.1';
   l_info('problem'):= 'EC12 Errors in Journal Import due to unnecessary Gain/Loss lines.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2225570.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '5851',
      p_sig_id                 => '453',
      p_sig_sql                => 'SELECT /*+ ordered use_nl(ac, xte, xah, xal, gll) */
          ac.check_id,
          ac.check_number,
          ac.org_id,
          xal.ae_header_id,
          sum(nvl(xal.accounted_dr,0)) sum_accounted_dr,
          sum(nvl(xal.accounted_cr,0)) sum_accounted_cr,
          sum(nvl(xal.entered_dr,0)) sum_entered_dr,
          sum(nvl(xal.entered_cr,0)) sum_entered_cr
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_system_parameters_all sp,
        xla_transaction_entities_upg xte,
        xla_ae_headers xah,
        xla_ae_Lines xal,
        gl_ledgers gll
   WHERE ac.check_id = chks.check_id
   AND   sp.org_id = ac.org_id
   AND   nvl(xte.source_id_int_1,-99) = ac.check_id
   AND   xte.ledger_id = sp.set_of_books_id
   AND   xte.entity_code = ''AP_PAYMENTS''
   AND   xte.application_id = 200
   AND   xah.application_id = xte.application_id
   AND   xah.entity_id = xte.entity_id
   AND   xah.ledger_id = xte.ledger_id
   AND   xah.gl_transfer_status_code = ''N''
   AND   xah.accounting_entry_status_code = ''F''
   AND   xal.application_id = xah.application_id
   AND   xal.ae_header_id = xah.ae_header_id
   AND   xal.gain_or_loss_flag = ''Y''
   AND   gll.ledger_id = xal.ledger_id
   AND   gll.currency_code = xal.currency_code
   GROUP BY ac.check_id, ac.check_number, ac.org_id, xal.ae_header_id
   HAVING   sum(nvl(xal.accounted_dr,0)) = sum(nvl(xal.accounted_cr,0))
   AND      sum(nvl(xal.entered_dr,0)) = sum(nvl(xal.entered_cr,0))',
      p_title                  => 'MGD-453',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'EC12 Errors in Journal Import due to unnecessary Gain/Loss lines.<br/><strong>Impact Area(s): </strong>GL Transfer',
      p_solution               => '<strong>Solution GDF: </strong>13699255</br><strong>Note: </strong>[2225570/KB301413]</br><strong>Script Name: </strong>xla_incorrect_gainloss_sel.sql Payment</br></br>Apply the GDF patch following the instructions provided in [2225570/KB301413]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
