debug('begin add_signature: 195');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Checks with missing or invalid business class on the accounting lines';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for affected checks and log a Service Request';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3982',
      p_sig_id                 => '195',
      p_sig_sql                => 'SELECT aph.check_id,
          aph.org_id,
          aph.accounting_event_id,
          h.ae_header_id,
          l.ae_line_num,
          l.accounting_class_code,
          l.business_class_code,
          h.upg_batch_id
   FROM xla_ae_lines l,
        xla_ae_headers h,
        ap_payment_history_all aph,
        (
          ##$$CVIEW$$##
        ) chks
   WHERE aph.accounting_event_id = h.event_id
   AND   h.application_id = 200
   AND   h.ae_header_id = l.ae_header_id
   AND   l.application_id = 200
   AND   aph.posted_flag = ''Y''
   AND   aph.transaction_type IN(''MANUAL PAYMENT ADJUSTED'', ''PAYMENT CREATED'')
   AND   l.accounting_class_code IN (''CASH_CLEARING'', ''FUTURE_DATED_PMT'')
   AND   (l.business_class_code is null OR
          (l.business_class_code like ''%AP_FUTURE_DTD_PMT%'' AND
