debug('begin add_signature: 199');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('bug_number'):= '9784405';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Unable to account Payment/Refund Cancelled or Payment Unclearing events when the Payment/Refund Cancelled event_id is less than the Payment Created event_id or the Payment Unclearing event_id is less than the Payment Clearing event_id causing the events to be processed in the wrong order.';
   l_info('solution'):= 'Apply the root cause fix from bug 9784405 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3984',
      p_sig_id                 => '199',
      p_sig_sql                => 'SELECT
          aph.check_id,
          aph.org_id,
          aph.transaction_type,
          aph.accounting_event_id,
          aph.related_event_id,
          xe.entity_id
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_payment_history_all aph,
        xla_events xe
   WHERE aph.check_id = chks.check_id
   AND   aph.accounting_event_id < aph.related_event_id
   AND   aph.posted_flag <> ''Y''
   AND   aph.accounting_event_id = xe.event_id
   AND   xe.application_id = 200
   AND   ((aph.transaction_type in (''PAYMENT CANCELLED'', ''REFUND CANCELLED'') AND
           NOT EXISTS (
             SELECT 1 FROM xla_events xe2
             WHERE xe2.entity_id = xe.entity_id
             AND   xe2.process_status_code = ''P''
             AND   xe2.application_id = 200)) OR
          (aph.transaction_type IN (''PAYMENT UNCLEARING'') AND
           NOT EXISTS (
             SELECT 1 FROM xla_events xe2
             WHERE xe2.event_id = aph.related_event_id
             AND   xe2.process_status_code = ''P''
             AND   xe2.application_id = 200)))',
      p_title                  => 'MGD-199',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Unable to account Payment/Refund Cancelled or Payment Unclearing events when the Payment/Refund Cancelled event_id is less than the Payment Created event_id or the Payment Unclearing event_id is less than the Payment Clearing event_id causing the events to be processed in the wrong order.<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Bug Number: </strong>9784405</br><strong>Script Name: </strong>ap_event_x_seq_sel.sql</br></br>Apply the root cause fix from bug {9784405} if you have not done so, and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '13'
      );
