debug('begin add_signature: 287');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect, Trial Balance';
   l_info('bug_number'):= '13043111';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1453591.1';
   l_info('problem'):= 'Payment accounting is incorrect due to incorrect final pay rounding when there exsists an exchange rate variance (ERV) for an invoice price variance (IPV). This can cause fully paid invoices to appear on the trial balance';
   l_info('solution'):= 'Apply the root cause fix from bug 13043111 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '3990',
      p_sig_id                 => '287',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          aip.accounting_event_id,
          aip.accounting_date,
          aip.amount,
          aip.invoice_id
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_invoice_payments_all aip,
        ap_payment_hist_dists aphd,
        ap_invoice_distributions_all aid_item,
        ap_invoice_distributions_all aid_erv,
        xla_ae_headers xah
   WHERE ac.check_id = chks.check_id
   AND   aip.check_id = ac.check_id
   AND   aip.invoice_base_amount <> 0
   AND   aip.accounting_event_id = aphd.accounting_event_id
   AND   xah.event_id = aphd.accounting_event_id
   AND   xah.upg_batch_id is null
   AND   aphd.invoice_payment_id  = aip.invoice_payment_id
   AND   aphd.accounting_event_id = aip.accounting_event_id
   AND   aphd.pay_dist_lookup_code = ''FINAL PAYMENT ROUNDING''
   AND   aphd.invoice_distribution_id = aid_item.invoice_distribution_id
   AND   aid_item.invoice_id = aid_erv.invoice_id
