debug('begin add_signature: 291');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Failure';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Payment created events with event_status_code/process_status_code of N/P (No Action/Processed) cause successive events to fail accounting. This can occur if payment accounting setup has been changed from "Clearing Only" to "Always"';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for the affected invoices and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4021',
      p_sig_id                 => '291',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          aph.accounting_event_id
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_system_parameters_all asp,
        ap_payment_history_all aph,
        xla_events xe
   WHERE ac.check_id = chks.check_id
   AND   ac.void_date is null
   AND   asp.org_id = ac.org_id
   AND   aph.check_id = ac.check_id
   AND   nvl(asp.when_to_account_pmt, ''X'') != ''CLEARING ONLY''
   AND   aph.transaction_type = ''PAYMENT CREATED''
   AND   aph.posted_flag = ''Y''
   AND   xe.event_id = aph.accounting_event_id
   AND   xe.event_status_code = ''N''
   AND   EXISTS (
           SELECT 1
           FROM ap_payment_history_all aph1,
                xla_events xe1
           WHERE aph1.check_id = ac.check_id
           AND   xe1.event_id = aph1.accounting_event_id
           AND   aph1.transaction_type = ''PAYMENT CLEARING''
           AND   aph1.posted_flag = ''N''
           AND   xe1.event_id = aph1.accounting_event_id
           AND   xe1.event_status_code = ''U'')
   UNION  -- Setup was changed after accounting of pay created.
   SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          aph.accounting_event_id
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_system_parameters_all asp,
        ap_payment_history_all aph,
        xla_events xe
   WHERE ac.check_id = chks.check_id
   AND   ac.void_date is not null
   AND   asp.org_id = ac.org_id
   AND   aph.check_id = ac.check_id
   AND   nvl(asp.when_to_account_pmt, ''X'') = ''CLEARING ONLY''
   AND   aph.transaction_type IN (''PAYMENT CANCELLED'' ,
           ''REFUND CANCELLED'')
   AND   aph.posted_flag = ''Y''
   AND   xe.event_id = aph.accounting_event_id
   AND   xe.event_status_code = ''N''
   AND   EXISTS (
           SELECT 1
           FROM ap_payment_history_all aph1,
                xla_events xe1
           WHERE aph1.check_id = ac.check_id
           AND   xe1.event_id = aph1.accounting_event_id
           AND   aph1.transaction_type IN (''PAYMENT CREATED'',
                   ''REFUND RECORDED'')
           AND   aph1.posted_flag = ''Y''
           AND   aph.related_event_id = aph1.accounting_event_id
           AND   xe1.event_status_code = ''P''
           AND   xe1.application_id = 200)',
      p_title                  => 'MGD-291',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment created events with event_status_code/process_status_code of N/P (No Action/Processed) cause successive events to fail accounting. This can occur if payment accounting setup has been changed from "Clearing Only" to "Always"<br/><strong>Impact Area(s): </strong>Accounting Failure',
