          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ad_parallel_update_units u,
        xla_upgrade_dates upg,
        ap_system_parameters_all asp
   WHERE ac.check_id = chks.check_id
   AND   ac.rowid BETWEEN
           dbms_rowid.rowid_create(
             1, u.data_object_id, u.relative_fno, u.start_block, 0) AND
           dbms_rowid.rowid_create(
             1, u.data_object_id, u.relative_fno, u.end_block, 9999)
   AND   asp.org_id = ac.org_id
   AND   upg.ledger_id = asp.set_of_books_id
   AND   trunc(ac.check_date) BETWEEN upg.start_date AND upg.end_date
   AND   u.update_id IN (
           SELECT ad_par.update_id FROM ad_parallel_updates ad_par
           WHERE ad_par.table_name = ''AP_CHECKS_ALL''
           AND ad_par.script_name LIKE ''apxlapay.sql%'')
   AND u.status != ''P''',
      p_title                  => 'MGD-391',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'The SLA hotpatch is failing on apxlapay.sql with either "ORA-00001: unique constraint (XLA.XLA_DISTRIBUTION_LINKS_U1) violated" OR "cannot insert NULL into AP.AP_APYMENT_HIST_DISTS.INVOICE_DISTRIBUTION_ID" OR cannnot insert NULL into AP.AP_PAYMENT_HIST_DISTS.AMOUNT"<br/><strong>Impact Area(s): </strong>Accounting Failure',
      p_solution               => '<strong>Script Name: </strong>sla_hotpatch_err_diag_pay.sql</br></br>Generate the Create Accounting Analyzer ([1665706/KB627726]) output for the affected invoices and log a Service Request to obtain the data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
