debug('begin add_signature: 395');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Payment Data, Payment Selection';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '2042389.1';
   l_info('problem'):= 'Checks with incorrect status which are out of sync with data in the Cash Management (CE) tables.';
   l_info('solution'):= 'As detailed in Doc ID 2042389.1 please log an SR for a data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3929',
      p_sig_id                 => '395',
      p_sig_sql                => 'WITH chks AS (
     ##$$MCVIEW$$##
   )
   SELECT ac.check_id,
          ac.check_number,
          ac.check_date,
          ac.amount,
          ac.status_lookup_code,
          ac.org_id,
          ac.cleared_amount,
          ac.cleared_date,
          CASE aph.posted_flag
            WHEN ''Y'' THEN
              CASE aph.matched_flag
                WHEN ''Y'' THEN ''RECONCILED''
                WHEN ''N'' THEN ''CLEARED''
              END
            WHEN ''N'' THEN
              CASE aph.matched_flag
                WHEN ''Y'' THEN ''RECONCILED UNACCOUNTED''
                WHEN ''N'' THEN ''CLEARED BUT UNACCOUNTED''
              END
          END correct_status
   FROM chks,
        ap_checks_all ac,
        ap_system_parameters_all asp,
        ap_payment_history_all aph
   WHERE ac.check_id = chks.check_id
   AND   ac.org_id = asp.org_id
   AND   asp.recon_accounting_flag = ''Y''
   AND   ac.status_lookup_code = ''NEGOTIABLE''
   AND   ac.check_id = aph.check_id
   AND   aph.transaction_type = ''PAYMENT CLEARING''
   AND   aph.payment_history_id = (
           SELECT max(aph2.payment_history_id)
           FROM ap_payment_history_all aph2
           WHERE aph2.transaction_type IN (''PAYMENT CLEARING'',''PAYMENT UNCLEARING'')
           AND   ac.check_id = aph2.check_id)
   AND   NOT EXISTS (
           SELECT 1 FROM ap_payment_history_all aph1
           WHERE ac.check_id = aph1.check_id
           AND   aph1.transaction_type = ''PAYMENT CANCELLED'')
   AND   EXISTS (
           SELECT 1
           FROM ce_statement_reconcils_all csr,
                ce_statement_lines csl
           WHERE csr.statement_line_id = csl.statement_line_id
           AND   csl.status = ''RECONCILED''
           AND   csr.reference_type = ''PAYMENT''
           AND   csr.reference_id = ac.check_id
           AND   csr.status_flag = ''M''
           AND   csr.current_record_flag = ''Y'')
   UNION
   SELECT ac.check_id,
          ac.check_number,
          ac.check_date,
          ac.amount,
          ac.status_lookup_code,
          ac.org_id,
          ac.cleared_amount,
          ac.cleared_date,
          ''NEGOTIABLE''
   FROM chks,
        ap_checks_all ac,
        ap_system_parameters_all asp
   WHERE ac.check_id = chks.check_id
   AND   ac.org_id = asp.org_id
   AND   asp.recon_accounting_flag = ''Y''
   AND   ac.status_lookup_code IN (''RECONCILED'',''RECONCILED UNACCOUNTED'')
   AND   ac.check_id NOT IN (
           SELECT aph.check_id FROM ap_payment_history_all aph
           WHERE aph.check_id = ac.check_id
           AND   aph.transaction_type = ''PAYMENT CLEARING''
           AND   aph.payment_history_id = (
                   SELECT max(aph2.payment_history_id)
                   FROM ap_payment_history_all aph2
                   WHERE aph2.transaction_type IN (''PAYMENT CLEARING'',
                           ''PAYMENT UNCLEARING'')
                   AND   ac.check_id = aph2.check_id))
   AND   NOT EXISTS (
           SELECT 1 FROM ap_payment_history_all aph1
            WHERE ac.check_id = aph1.check_id
            AND   aph1.transaction_type IN (''PAYMENT CANCELLED'',
                    ''REFUND CANCELLED'' ))
   AND   NOT EXISTS (
           SELECT 1
           FROM ce_statement_reconcils_all csr,
                ce_statement_lines csl
           WHERE csr.statement_line_id = csl.statement_line_id
           AND   csl.status = ''RECONCILED''
           AND   csr.reference_type = ''PAYMENT''
           AND   csr.reference_id = ac.check_id
           AND   csr.status_flag = ''M''
           AND   csr.current_record_flag = ''Y'')
   UNION
   SELECT ac.check_id,
          ac.check_number,
          ac.check_date,
          ac.amount,
          ac.status_lookup_code,
          ac.org_id,
          ac.cleared_amount,
          ac.cleared_date,
          ''CLEARED''
   FROM chks,
        ap_checks_all ac,
        ap_system_parameters_all asp
   WHERE ac.check_id = chks.check_id
   AND   ac.org_id = asp.org_id
   AND   asp.recon_accounting_flag = ''Y''
   AND   ac.status_lookup_code NOT IN (''CLEARED'')
   AND   ac.check_id IN (
           SELECT aph.check_id FROM ap_payment_history_all aph
           WHERE aph.check_id = ac.check_id
           AND   aph.transaction_type = ''PAYMENT CLEARING''
           AND   aph.payment_history_id = (
                   SELECT max(aph2.payment_history_id)
                   FROM ap_payment_history_all aph2
                   WHERE aph2.transaction_type IN (''PAYMENT CLEARING'',
                           ''PAYMENT UNCLEARING'')
                    AND   ac.check_id = aph2.check_id))
   AND   NOT EXISTS (
           SELECT 1 FROM ap_payment_history_all aph1
           WHERE ac.check_id = aph1.check_id
           AND   aph1.transaction_type IN (''PAYMENT CANCELLED'',
                   ''REFUND CANCELLED'' ))
   AND   NOT EXISTS (
           SELECT 1
           FROM ce_statement_reconcils_all csr,
                ce_statement_lines csl
           WHERE csr.statement_line_id = csl.statement_line_id
           AND   csl.status = ''RECONCILED''
           AND   csr.reference_type = ''PAYMENT''
           AND   csr.reference_id = ac.check_id
           AND   csr.status_flag = ''M''
           AND   csr.current_record_flag = ''Y'')',
      p_title                  => 'MGD-395',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Checks with incorrect status which are out of sync with data in the Cash Management (CE) tables.<br/><strong>Impact Area(s): </strong>Payment Data, Payment Selection',
      p_solution               => '<strong>Note: </strong>[2042389/KB188115]</br><strong>Script Name: </strong>ap_ce_check_status_mismatch_sel.sql</br></br>As detailed in [2042389/KB188115] please log an SR for a data fix.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '7'
      );
   l_info.delete;
debug('end add_signature: 395');



debug('begin add_signature: 397');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '21621811';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2632111.1';
   l_info('problem'):= 'When there are multiple invoices payments may be accounted with incorrect amounts causing small rounding amount differences in CASH or CASH CLEARING.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2632111.1.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4166',
      p_sig_id                 => '397',
      p_sig_sql                => 'SELECT aph.check_id,
          ac.check_number,
          ac.amount,
          aip.invoice_id,
          aip.invoice_payment_id,
          aip.invoice_base_amount,
          aip.accounting_event_id,
          aip.amount,
          sum(nvl(aphd.invoice_dist_base_amount, aphd.invoice_dist_amount)) -
            nvl(aip.invoice_base_amount, aip.amount) difference
   FROM (
          ##$$CVIEW$$##
        ) chks,
         ap_checks_all ac,
         ap_invoice_payments_all aip,
         ap_payment_history_all aph,
         ap_payment_hist_dists aphd
   WHERE ac.check_id = chks.check_id
   AND   aip.check_id = ac.check_id
   AND   aip.check_id = aph.check_id
   AND   aphd.invoice_payment_id = aip.invoice_payment_id
   AND   aphd.pay_dist_lookup_code = ''CASH''
   AND   aip.accounting_event_id = aphd.accounting_event_id
   AND   aip.accounting_event_id = aph.accounting_event_id
   AND   aph.payment_history_id = aphd.payment_history_id
   AND   aph.historical_flag is null
   AND   aph.transaction_type IN (''PAYMENT CREATED'', ''REFUND RECORDED'')
   AND   aph.posted_flag = ''Y''
   GROUP BY aph.check_id, aip.invoice_id, ac.check_number, ac.amount,
            aip.invoice_payment_id, aip.invoice_base_amount,
            aip.accounting_event_id, aip.amount
   HAVING sum(nvl(aphd.invoice_dist_base_amount, aphd.invoice_dist_amount)) !=
            nvl(aip.invoice_base_amount, aip.amount)',
      p_title                  => 'MGD-397',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'When there are multiple invoices payments may be accounted with incorrect amounts causing small rounding amount differences in CASH or CASH CLEARING.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>21621811</br><strong>Note: </strong>[2632111/KB163144]</br><strong>Script Name: </strong>ap_pay_cr_has_x_ida_sel.sql</br></br>Apply the GDF patch following the instructions provided in [2632111/KB163144].</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 397');



debug('begin add_signature: 398');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect, Trial Balance';
   l_info('bug_number'):= '16723807';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1559565.1';
   l_info('problem'):= 'Payment adjustment events are accounted with incorrect amounts when there is a discount, resulting in trial balance issues due to small rounding differences.';
   l_info('solution'):= 'Apply the root cause fix from bug 19941321 or 16723807 if you have not done so, and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4180',
      p_sig_id                 => '398',
      p_sig_sql                => 'SELECT aph.check_id,
          l.accounting_class_code,
          sum(nvl(entered_dr, 0) - nvl(entered_cr, 0)) acct_amt
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_payment_history_all aph,
        xla_ae_headers h,
        xla_ae_lines l,
        ap_system_parameters_all asp
   WHERE aph.check_id = chks.check_id
   AND   h.event_id = aph.accounting_event_id
   AND   h.application_id = 200
   AND   aph.transaction_type like ''%ADJUSTED''
   AND   aph.transaction_type not like ''MAN%''
   AND   l.accounting_class_code IN (''CASH'', ''LIABILITY'', ''CASH_CLEARING'')
   AND   nvl(aph.historical_flag, ''N'') != ''Y''
   AND   h.ae_header_id = l.ae_header_id
   AND   l.application_id = 200
   AND   aph.org_id = asp.org_id
   AND   asp.set_of_books_id = h.ledger_id
   AND   aph.posted_flag = ''Y''
   AND   NOT EXISTS (
           SELECT 1 FROM ap_payment_history_all h2
           WHERE h2.check_id = aph.check_id
           AND   h2.transaction_type like ''%ADJUSTED''
           AND   h2.related_event_id = aph.related_event_id
           AND   h2.transaction_type not like ''MAN%''
           AND   h2.posted_flag != ''Y'')
   AND   EXISTS (
           SELECT 1 FROM ap_invoice_payments_all p1
           WHERE p1.check_id = aph.check_id
           AND   p1.discount_Taken != 0)
   GROUP BY aph.check_id, l.accounting_class_code
   HAVING sum(nvl(entered_dr, 0) - nvl(entered_cr, 0)) != 0',
      p_title                  => 'MGD-398',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment adjustment events are accounted with incorrect amounts when there is a discount, resulting in trial balance issues due to small rounding differences.<br/><strong>Impact Area(s): </strong>Accounting Incorrect, Trial Balance',
      p_solution               => '<strong>Bug Number: </strong>16723807</br><strong>Note: </strong>[1559565/KB731908]</br><strong>Script Name: </strong>ap_pay_adj_x_discount.sql</br></br>Apply the root cause fix from bug {19941321} or {16723807} if you have not done so, and log a Service Request to obtain the data fix.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: 398');



debug('begin add_signature: 401');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect, Trial Balance';
   l_info('bug_number'):= '20514802';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2632103.1';
   l_info('problem'):= 'Payment adjustment events are accounted with incorrect amounts resulting in issues with the trial balance.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2632103.1.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4124',
      p_sig_id                 => '401',
      p_sig_sql                => 'SELECT /*+ leading(chks) */ DISTINCT
          aph.check_id,
          aip.org_id,
          aph.accounting_date,
          aph.related_event_id,
          aip.invoice_id,
          aip.invoice_payment_id,
          aphd.all_inv_dist_base_sum,
          aip.invoice_base_amount,
          aip.amount,
          nvl( aip.invoice_base_amount, aip.amount ) -
            aphd.all_inv_dist_base_sum trx_amt_different,
          aph.posted_flag
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        ap_invoice_payments_all aip,
        (
          SELECT sum(nvl(aphd1.invoice_dist_base_amount,
                   aphd1.invoice_dist_amount)) all_inv_dist_base_sum,
                 sum(decode(aph1.accounting_event_id,
                       aph1.related_event_id, nvl(aphd1.invoice_dist_base_amount,
                         aphd1.invoice_dist_amount ),
                       0)) pay_cr_inv_dist_sum,
                 aph1.check_id,
                 aph1.related_event_id,
                 aphd1.invoice_payment_id
          FROM ap_payment_hist_dists aphd1,
               ap_payment_history_all aph1
          WHERE aph1.accounting_event_id = aphd1.accounting_event_id
          AND   aphd1.payment_history_id = aph1.payment_history_id
          AND   aph1.transaction_type NOT IN (''MANUAL PAYMENT ADJUSTED'',
                    ''MANUAL REFUND ADJUSTED'')
          AND   aphd1.pay_dist_lookup_code IN (''CASH'')
          GROUP BY aph1.check_id, aph1.related_event_id, aphd1.invoice_payment_id
        ) aphd
   WHERE ac.check_id = chks.check_id
   AND   ac.check_id = aph.check_id
   AND   aph.check_id = aip.check_id
   AND   ac.void_date is null
   AND   aph.transaction_type IN (''PAYMENT ADJUSTED'', ''REFUND ADJUSTED'')
   AND   nvl(aph.historical_flag, ''N'') <> ''Y''
   AND   aph.posted_flag = ''Y''
   AND   aip.posted_flag = ''Y''
   AND   aph.check_id = aphd.check_id
   AND   aph.related_event_id = aphd.related_event_id
   AND   aip.invoice_payment_id = aphd.invoice_payment_id
   AND   aphd.all_inv_dist_base_sum <> nvl(aip.invoice_base_amount, aip.amount)
   AND   aphd.pay_cr_inv_dist_sum = nvl(aip.invoice_base_amount, aip.amount)
   AND   NOT EXISTS (
           SELECT ''unacct pay adj event'' FROM ap_payment_history_all aph2
           WHERE aph2.related_event_id = aph.related_event_id
           AND   aph2.check_id = aph.check_id
           AND   (aph2.posted_flag = ''N'' OR
                  nvl(aph2.historical_flag, ''x'') = ''Y''))
   AND   NOT EXISTS (
           SELECT ''unaccounted dist'' FROM ap_invoice_distributions_all aid
           WHERE aid.invoice_id = aip.invoice_id
           AND   nvl(aid.posted_flag, ''N'') = ''N'')
   AND   NOT EXISTS (
           SELECT ''payment voided'' FROM ap_checks_all ac1
