debug('begin add_signature: 402');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '22724558';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '2632110.1';
   l_info('problem'):= 'Payment clearing events are accounted with incorrect amounts, causing differences between the cleared base amount and the accounted cash amount.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 2632110.1.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4133',
      p_sig_id                 => '402',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.cleared_base_amount,
          aphd.clr_base_amt
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks_all ac,
        ap_payment_history_all aph,
        (
          SELECT sum(aphd.cleared_base_amount) clr_base_amt,
                 aph.check_id
          FROM ap_payment_hist_dists aphd,
               ap_payment_history_all aph
          WHERE aphd.accounting_event_id = aph.accounting_event_id
          AND   aphd.payment_history_id = aph.payment_history_id
          AND   aph.transaction_type IN (''PAYMENT CLEARING'',
                  ''PAYMENT CLEARING ADJUSTED'')
          AND   NOT EXISTS (
                  SELECT ''unaccounted payment''
                  FROM ap_payment_history_all aph1
                  WHERE aph1.check_id = aph.check_id
                  AND aph1.related_event_id = aph.related_event_id
                  AND aph1.transaction_type = ''PAYMENT UNCLEARING'')
          AND   aphd.pay_dist_lookup_code IN (''CASH'', ''FINAL CASH ROUNDING'',
                  ''BANK CHARGE'', ''BANK ERROR'')
          GROUP BY aph.check_id
        ) aphd
   WHERE ac.check_id = chks.check_id
   AND   ac.void_date is null
   AND   ac.check_id = aph.check_id
   AND   ac.cleared_base_amount is not null
   AND   NOT EXISTS (
           SELECT ''unaccounted payment'' FROM ap_payment_history_all aph1
           WHERE aph1.check_id = ac.check_id
           AND  (nvl( aph1.historical_flag, ''N'') = ''Y'' OR
                 aph1.posted_flag = ''N''))
   AND   ac.cleared_base_amount <> aphd.clr_base_amt
   AND   ac.check_id = aphd.check_id',
      p_title                  => 'MGD-402',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment clearing events are accounted with incorrect amounts, causing differences between the cleared base amount and the accounted cash amount.<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Solution GDF: </strong>22724558</br><strong>Note: </strong>[2632110/KB781623]</br><strong>Script Name: </strong>ap_x_cash_pay_clr_sel.sq</br></br>Apply the GDF patch following the instructions provided in [2632110/KB781623].</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
