debug('begin add_signature: 415');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('bug_number'):= '19775384';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Incorrect accounted amount calculated for discount lines results in incorrect accounting entries';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for the affected invoices and log a Service Request to obtain the data fix.';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '4116',
      p_sig_id                 => '415',
      p_sig_sql                => 'SELECT ac.check_id,
          ac.check_number,
          ac.org_id,
          aphd.check_id,
          ai.invoice_id,
          ai.invoice_num,
          aphd.sum_disc_amt - nvl(aip.discount_taken, 0) disc_amt_diff,
          abs(aphd.sum_disc_base_amt -
            (aip.discount_taken * ai.exchange_rate)) disc_base_amt_diff
   FROM (
          ##$$CVIEW$$##
        ) chks,
        ap_checks ac,
        ap_invoice_payments_all aip,
        (
          SELECT sum(nvl(aphd1.amount, 0)) sum_disc_amt,
                 sum(nvl(aphd1.invoice_dist_base_amount, 0)) sum_disc_base_amt,
                 aph1.check_id,
                 aphd1.invoice_payment_id,
                 aphd1.accounting_event_id
          FROM ap_payment_hist_dists aphd1,
               ap_payment_history_all aph1
          WHERE (aph1.transaction_type IN (''PAYMENT CREATED'', ''REFUND RECORDED'') OR
                 (aph1.transaction_type LIKE ''%ADJUSTED'' AND
                  aph1.transaction_type NOT LIKE ''MAN%''))
          AND   aphd1.payment_history_id = aph1.payment_history_id
          AND   aphd1.accounting_event_id = aph1.accounting_event_id
          AND   aphd1.pay_dist_lookup_code = ''DISCOUNT''
          GROUP BY aph1.check_id, aphd1.invoice_payment_id, aphd1.accounting_event_id
        ) aphd,
        xla_ae_headers xah,
        ap_invoices_all ai
   WHERE ac.check_id = chks.check_id
   AND   aphd.check_id = ac.check_id
   AND   aip.posted_flag = ''Y''
   AND   aip.check_id = aphd.check_id
   AND   aip.invoice_payment_id = aphd.invoice_payment_id
   AND   aip.accounting_event_id = aphd.accounting_event_id
   AND   aip.discount_taken is not null
   AND   aip.exchange_rate is not null
   AND   xah.ledger_id = aip.set_of_books_id
   AND   xah.event_id = aip.accounting_event_id
   AND   xah.upg_batch_id is null
   AND   aphd.sum_disc_amt = aip.discount_taken
   AND   ai.invoice_id = aip.invoice_id
   AND   abs(aphd.sum_disc_base_amt - (aip.discount_taken * ai.exchange_rate)) > 5',
      p_title                  => 'MGD-415',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Incorrect accounted amount calculated for discount lines results in incorrect accounting entries<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Bug Number: </strong>19775384</br><strong>Script Name: </strong>ap_x_disc_pay_acctg_all.txt</br></br>Generate the Create Accounting Analyzer ([1665706/KB627726]) output for the affected invoices and log a Service Request to obtain the data fix.</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
