   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'N';
   l_info('problem'):= 'Foreign currency checks for which there is a sign difference between the check base amount and the sum(payment_base_amount) in AP_INVOICE_PAYMENTS_ALL.';
   l_info('solution'):= 'Generate the Create Accounting Analyzer output for the affected payments/invoices and log a Service Request to obtain the data fix.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '5286',
      p_sig_id                 => '443',
      p_sig_sql                => 'SELECT chk.check_id,
          chk.amount,
          chk.base_amount,
          chk.exchange_rate,
          sum(aip.payment_base_amount),
          max(aip.invoice_payment_id)
   FROM (
          SELECT ac.check_id,
                 ac.amount,
                 ac.base_amount,
                 ac.exchange_rate,
                 aph.accounting_event_id
          FROM (
                 ##$$CVIEW$$##
               ) chks,
               ap_checks_all ac,
               ap_system_parameters_all asp,
               ap_payment_history_all aph
          WHERE ac.check_id = chks.check_id
          AND   ac.currency_code <> asp.base_currency_code
          AND   ac.org_id = asp.org_id
          AND   ac.exchange_rate is not null
          AND   ac.check_id = aph.check_id
          AND   nvl(aph.posted_flag, ''N'') <> ''Y''
          AND   aph.transaction_type = ''PAYMENT CREATED''
        ) chk,
        ap_invoice_payments_all aip
   WHERE chk.check_id = aip.check_id
   AND   aip.accounting_event_id = chk.accounting_event_id
   GROUP BY chk.check_id, chk.amount, chk.base_amount, chk.exchange_rate
   HAVING   sign(sum(aip.payment_base_amount)) <> sign(chk.base_amount)',
      p_title                  => 'MGD-443',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Foreign currency checks for which there is a sign difference between the check base amount and the sum(payment_base_amount) in AP_INVOICE_PAYMENTS_ALL.<br/><strong>Impact Area(s): </strong>Payment Data',
