debug('begin add_signature: 471');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Accounting Incorrect';
   l_info('category'):= 'PAYMENT';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '2665666.1';
   l_info('problem'):= 'Payment accounting is incorrect due to invalid data in the prepayment application distributions table: AP_PREPAY_APP_DISTS';
   l_info('solution'):= 'Apply the root cause fix for the issue following the instructions in Doc ID 1394302.1 if you have not done so, and log a service request to obtain the data fix as described in Doc ID 2665666.1';
   l_info('sub_category'):= 'ACCOUNTING';
   l_info('undo_flag'):= 'Y';
  add_signature(
      p_sig_repo_id            => '14757',
      p_sig_id                 => '471',
      p_sig_sql                => 'SELECT aip.check_id,
       aip.invoice_id,
       aip.invoice_payment_id,
       sum(aip.amount) paid_amt,
       sum(aph.amount) acctounted_amt
FROM (
       ##$$CVIEW$$##
     ) chks,
     ap_invoice_payments_all aip,
     ap_payment_hist_dists aph
WHERE aip.check_id = chks.check_id
AND   aip.invoice_payment_id = aph.invoice_payment_id
AND   aip.posted_flag = ''Y''
AND   aph.pay_dist_lookup_code = ''CASH''
AND   EXISTS (
        SELECT 1 FROM ap_prepay_app_dists apad
        WHERE apad.prepay_dist_lookup_code = ''PREPAY APPL''
        AND   apad.invoice_distribution_id = aph.invoice_distribution_id)
GROUP BY aip.check_id,aip.invoice_id,aip.invoice_payment_id
HAVING sum(aip.amount) <> sum(aph.amount)',
      p_title                  => 'MGD-471',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Payment accounting is incorrect due to invalid data in the prepayment application distributions table: AP_PREPAY_APP_DISTS<br/><strong>Impact Area(s): </strong>Accounting Incorrect',
      p_solution               => '<strong>Note: </strong>[2665666/KB782861]</br><strong>Script Name: </strong>None</br></br>Apply the root cause fix for the issue following the instructions in [1394302/KB340888] if you have not done so, and log a service request to obtain the data fix as described in [2665666/KB782861]</br></br><strong>IMPORTANT:</strong> This fix will undo accounting.<br/><br/>'||mask_text(g_apply_undo, nvl( upper(''), 'NO_MASK') )||'<strong>NOTE:</strong>For transactions posted in <strong>closed periods</strong> the reversing and corrected events will be accounted <strong>in the current open period.</strong><br/>For a deeper understanding of the undo accounting process please refer to [753695/KB218158]</br>',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
