debug('begin add_signature: 60');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Payment Selection';
   l_info('bug_number'):= '10144798';
   l_info('category'):= 'SUPPLIER';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1265353.1';
   l_info('problem'):= 'Duplicate bank accounts.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1265353.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3837',
      p_sig_id                 => '60',
      p_sig_sql                => 'SELECT ext_bank_account_id, 
currency_code, 
country_code, 
bank_account_type, 
account_suffix, rank() OVER ( 
PARTITION BY bank_account_num, bank_id, branch_id, 
currency_code, country_code, bank_account_num_hash1, bank_account_num_hash2, bank_account_type 
ORDER BY end_date desc, creation_date, start_date, ext_bank_account_id ) num, 
(select rtrim (xmlagg (xmlelement (e, ACCOUNT_OWNER_PARTY_ID || '','')).extract (''//text()''), '','') enames from iby_account_owners iao where iao.EXT_BANK_ACCOUNT_ID = ieba.EXT_BANK_ACCOUNT_ID) "Owner Party_Ids" 
FROM iby_ext_bank_accounts ieba 
WHERE (bank_account_num, nvl(bank_id,-99), 
nvl(branch_id,-99), 
nvl(currency_code,''XX''), 
country_code, 
nvl(bank_account_num_hash1,-1), 
nvl(bank_account_num_hash2,-1)) IN ( 
SELECT bank_account_num, 
nvl(bank_id,-99), 
nvl(branch_id,-99), 
nvl(currency_code,''XX''), 
country_code, 
nvl(bank_account_num_hash1,-1), 
nvl(bank_account_num_hash2,-1) 
FROM iby_ext_bank_accounts 
WHERE country_code <> ''JP'' 
AND country_code <> ''NZ'' 
GROUP BY bank_account_num, bank_id, branch_id, currency_code, 
country_code, bank_account_num_hash1, bank_account_num_hash2 
HAVING count(*) > 1) 
UNION ALL 
SELECT ext_bank_account_id, 
currency_code, 
country_code, 
bank_account_type, 
account_suffix, rank() OVER ( 
PARTITION BY bank_account_num, bank_id, branch_id, currency_code, 
country_code, bank_account_num_hash1, bank_account_num_hash2 
ORDER BY end_date desc, creation_date, start_date, ext_bank_account_id ) num,
(select rtrim (xmlagg (xmlelement (e, ACCOUNT_OWNER_PARTY_ID || '','')).extract (''//text()''), '','') enames from iby_account_owners iao where iao.EXT_BANK_ACCOUNT_ID = ieba.EXT_BANK_ACCOUNT_ID) "Owner Party_Ids" 
FROM iby_ext_bank_accounts ieba
WHERE (bank_account_num, 
nvl(bank_id,-99), 
nvl(branch_id,-99), 
nvl(currency_code,''XX''), 
country_code, 
nvl(bank_account_num_hash1,-1), 
nvl(bank_account_num_hash2,-1), 
nvl(bank_account_type,''XX'')) IN ( 
SELECT bank_account_num, 
nvl(bank_id,-99), 
nvl(branch_id,-99), 
nvl(currency_code,''XX''), 
country_code, 
nvl(bank_account_num_hash1,-1), 
nvl(bank_account_num_hash2,-1), 
nvl(bank_account_type,''XX'') 
FROM iby_ext_bank_accounts 
WHERE country_code = ''JP'' 
GROUP BY bank_account_num, 
bank_id, branch_id, 
currency_code, 
country_code, 
bank_account_num_hash1, 
bank_account_num_hash2, 
bank_account_type 
HAVING count(*) > 1) 
UNION ALL 
SELECT ext_bank_account_id, currency_code, country_code, bank_account_type, account_suffix, 
rank() OVER ( 
PARTITION BY bank_account_num, bank_id,branch_id, currency_code, country_code, bank_account_num_hash1, bank_account_num_hash2, account_suffix 
ORDER BY end_date desc, creation_date, start_date, 
ext_bank_account_id ) num ,
(select rtrim (xmlagg (xmlelement (e, ACCOUNT_OWNER_PARTY_ID || '','')).extract (''//text()''), '','') enames from iby_account_owners iao where iao.EXT_BANK_ACCOUNT_ID = ieba.EXT_BANK_ACCOUNT_ID) "Owner Party_Ids" 
FROM iby_ext_bank_accounts ieba
WHERE (bank_account_num, nvl(bank_id,-99), nvl(branch_id,-99), nvl(currency_code,''XX''), country_code, nvl(bank_account_num_hash1,-1), nvl(bank_account_num_hash2,-1), nvl(ACCOUNT_SUFFIX,''XX'')) 
IN ( 
SELECT bank_account_num, 
nvl(bank_id,-99), 
nvl(branch_id,-99), 
nvl(currency_code,''XX''), 
country_code, 
nvl(bank_account_num_hash1,-1), 
nvl(bank_account_num_hash2,-1), 
nvl(ACCOUNT_SUFFIX,''XX'') 
FROM iby_ext_bank_accounts 
WHERE country_code = ''NZ'' 
GROUP BY bank_account_num, bank_id, branch_id, currency_code, 
country_code, bank_account_num_hash1, bank_account_num_hash2, 
account_suffix 
HAVING count(*) > 1)',
      p_title                  => 'MGD-60',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Duplicate bank accounts.<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>10144798</br><strong>Note: </strong>[1265353/KB627120]</br><strong>Script Name: </strong>iby_dup_bnkAcct_Sel.sql</br></br>Apply the GDF patch following the instructions provided in [1265353/KB627120]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('Y','RS'),
      p_limit_rows             => nvl('Y','Y'),
