            PARTITION BY per_party_id, org_party_site_id
          ) new_vendor_contact_id,
          ss.vendor_site_id,
          ss.vendor_site_code,
          (
            SELECT hps.party_site_name
            FROM hz_party_sites hps
            WHERE party_site_id = ss.party_site_id
