   l_info('problem'):= 'Inactive vendor site causes double amounts on 1099 payment report';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1489862.1.  <br><br>
<b>NOTE:</b> Ensure when running ap_one_off_scripts_sel.sql that you provide <b>TAX</b> when prompted to enter the <b>Component Value</b> parameter.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '3783',
      p_sig_id                 => '248',
      p_sig_sql                => 'SELECT /*+ parallel(inactive,6) */
          ''TAX2'' corruption_type,
          inactive.vendor_id,
          inactive.vendor_site_id,
          inactive.inactive_date
   FROM ap_supplier_sites_all inactive
   WHERE tax_reporting_site_flag = ''Y''
   AND   inactive_date is not null
   AND   EXISTS (
           SELECT 1 FROM ap_supplier_sites_all active
           WHERE active.org_id = inactive.org_id
           AND   active.vendor_id = inactive.vendor_id
           AND   active.vendor_site_id <> inactive.vendor_site_id
           AND   active.tax_reporting_site_flag = ''Y'')
   AND   inactive.vendor_id =nvl(##$$VND$$##, inactive.vendor_id)',
      p_title                  => 'MGD-248',
