debug('begin add_signature: 434');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Payment Selection';
   l_info('bug_number'):= '21983844';
   l_info('category'):= 'SUPPLIER';
   l_info('gdf_flag'):= 'Y';
   l_info('note_number'):= '1370214.1';
   l_info('problem'):= 'Orphan bank accounts which are not upgraded and have no owners or assignments.';
   l_info('solution'):= 'Apply the GDF patch following the instructions provided in Doc ID 1370214.1';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4001',
      p_sig_id                 => '434',
      p_sig_sql                => 'SELECT ''IBY'' acct_source,
          eba.ext_bank_account_id,
          eba.currency_code,
          eba.country_code,
          eba.bank_account_type,
          eba.account_suffix,
          null ext_payee_id,
          null payee_party_id,
          null account_owner_party_id,
          null payment_function
   FROM iby_ext_bank_accounts eba
   WHERE NOT EXISTS(
           SELECT ''OWNER'' FROM iby_account_owners ao
           WHERE ao.account_owner_party_id <> -99
           AND   ao.ext_bank_account_id = eba.ext_bank_account_id)
   AND   NOT EXISTS(
           SELECT ''ASSIGNMENT'' FROM iby_pmt_instr_uses_all iu
           WHERE iu.instrument_type = ''BANKACCOUNT''
           AND   iu.instrument_id = eba.ext_bank_account_id)
   AND   NOT EXISTS (
           SELECT ''UPGRADE_ASSIGNMENT'' FROM iby_upg_instruments ui
           WHERE ui.instrument_type = ''BANKACCOUNT''
           AND   ui.instrument_id = eba.ext_bank_account_id)
   UNION
   SELECT ''AR'',
          ao.ext_bank_account_id,
          null, null, null, null,
          ep.ext_payee_id,
          ep.payee_party_id,
          ao.account_owner_party_id,
          ep.payment_function
   FROM iby_account_owners ao,
        iby_external_payees_all ep
   WHERE ao.account_owner_party_id = ep.payee_party_id
   AND   ep.payment_function = ''AR_CUSTOMER_REFUNDS''
   AND   NOT EXISTS (
           SELECT 1 FROM iby_pmt_instr_uses_all piu
           WHERE piu.ext_pmt_party_id = ep.ext_payee_id
           AND   piu.instrument_id = ao.ext_bank_account_id)
   UNION
   SELECT ''CE'',
          ao.ext_bank_account_id,
          null, null, null, null,
          ep.ext_payee_id,
          ep.payee_party_id,
          ao.account_owner_party_id,
          ep.payment_function
   FROM iby_account_owners ao,
        iby_external_payees_all ep
   WHERE ao.account_owner_party_id = ep.payee_party_id
   AND   ep.org_type = ''LEGAL_ENTITY''
   AND   NOT EXISTS (
           SELECT 1 FROM iby_pmt_instr_uses_all piu
           WHERE piu.ext_pmt_party_id = ep.ext_payee_id
           AND   piu.instrument_id = ao.ext_bank_account_id)
   ORDER BY 10, 1',
      p_title                  => 'MGD-434',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Orphan bank accounts which are not upgraded and have no owners or assignments.<br/><strong>Impact Area(s): </strong>Payment Selection',
      p_solution               => '<strong>Solution GDF: </strong>21983844</br><strong>Note: </strong>[1370214/KB689127]</br><strong>Script Name: </strong>iby_orphan_acct_sel.sql</br></br>Apply the GDF patch following the instructions provided in [1370214/KB689127]',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '5'
      );
   l_info.delete;
debug('end add_signature: 434');



