   l_info('problem'):= 'Purchase orders for suppliers with contacts that were merged without selecting the PO option leaving the PO''s unmerged and not queriable.';
   l_info('solution'):= 'Apply the code fix as detailed in Doc ID 1442312.1.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '4092',
      p_sig_id                 => '351',
      p_sig_sql                => 'SELECT DISTINCT
       poh.po_header_id,
       poh.segment1,
       poh.org_id,
       poh.start_date_active,
       poh.vendor_site_id,
       poh.vendor_contact_id
   FROM ap_duplicate_vendors_all adv1,
        po_headers_all poh
   WHERE adv1.duplicate_vendor_id = nvl(##$$VND$$##, adv1.duplicate_vendor_id)
   AND   adv1.process_flag = ''Y''
   AND   adv1.process <>  ''P''
   AND   poh.vendor_contact_id is not null
   AND   poh.vendor_id = adv1.duplicate_vendor_id
   AND   poh.vendor_site_id = adv1.duplicate_vendor_site_id
   AND   poh.org_id = adv1.org_id
   AND   EXISTS (
           SELECT 1 FROM po_vendor_contacts cont
           WHERE cont.vendor_contact_id = poh.vendor_contact_id)
   AND   NOT EXISTS (
           SELECT 1 FROM po_vendor_contacts cont
           WHERE cont.vendor_contact_id = poh.vendor_contact_id
           AND   cont.vendor_site_id = poh.vendor_site_id)',
      p_title                  => 'MGD-351',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Purchase orders for suppliers with contacts that were merged without selecting the PO option leaving the PO''s unmerged and not queriable.<br/><strong>Impact Area(s): </strong>PO Matching',
