debug('begin add_signature: 469');
   l_info('##SHOW_SQL##'):= 'Y';
   l_info('#IMPACT_AREAS#'):= 'Supplier';
   l_info('category'):= 'SUPPLIER';
   l_info('gdf_flag'):= 'N';
   l_info('note_number'):= '1070071.1';
   l_info('problem'):= 'Upgraded contacts are not displayed in the Contacts page of the Suppliers form because there is no primary EMAIL record.';
   l_info('solution'):= 'Verify the issue following the instructions in Doc ID 1070071.1 and log a service request to obtain the datafix as needed.';
   l_info('undo_flag'):= 'N';
  add_signature(
      p_sig_repo_id            => '12430',
      p_sig_id                 => '469',
      p_sig_sql                => 'SELECT cp.contact_point_type,
       cp.owner_table_name,
       r.relationship_id,
       r.subject_id,
       r.subject_table_name,
       r.object_id,
       r.object_table_name,
       r.relationship_type
FROM hz_contact_points cp,
     hz_relationships r
WHERE cp.owner_table_name (+) = ''HZ_PARTIES''
AND   cp.owner_table_id (+) = r.party_id
AND   cp.contact_point_type (+) = ''EMAIL''
AND   cp.status = ''A''
AND   cp.primary_flag = ''N''
AND   r.subject_type = ''ORGANIZATION''
AND   r.subject_table_name = ''HZ_PARTIES''
AND   r.object_table_name = ''HZ_PARTIES''
AND   r.object_type = ''PERSON''
AND   r.relationship_code = ''CONTACT''
AND   r.directional_flag = ''B''
AND   r.relationship_type = ''CONTACT''
AND   NOT EXISTS ( /*no record with primary flag Y for the table_owner_id*/
        SELECT 1 FROM hz_contact_points cp2
        WHERE cp2.owner_table_name = ''HZ_PARTIES''
        AND   cp2.owner_table_id = cp.owner_table_id
        AND   cp2.contact_point_type = ''EMAIL''
        AND   cp2.status = ''A''
        AND   nvl(cp2.primary_flag,''N'') = ''Y'')
AND   r.subject_id IN (
        SELECT party_id FROM ap_suppliers
        WHERE vendor_id = nvl(##$$VND$$##,vendor_id))',
      p_title                  => 'MGD-469',
      p_fail_condition         => 'RS',
      p_problem_descr          => 'Upgraded contacts are not displayed in the Contacts page of the Suppliers form because there is no primary EMAIL record.<br/><strong>Impact Area(s): </strong>Supplier',
      p_solution               => '<strong>Note: </strong>[1070071/KB180552]</br><strong>Script Name: </strong>None</br></br>Verify the issue following the instructions in [1070071/KB180552] and log a service request to obtain the datafix as needed.',
      p_success_msg            => '',
      p_print_condition        => nvl('FAILURE','ALWAYS'),
      p_fail_type              => nvl('E','W'),
      p_print_sql_output       => nvl('RS','RS'),
      p_limit_rows             => nvl('Y','Y'),
      p_extra_info             => l_info,
      p_child_sigs             => VARCHAR_TBL(),
      p_include_in_dx_summary  => nvl('Y','N'),
      p_version                => '3'
      );
   l_info.delete;
debug('end add_signature: 469');



