-- MAIN ENTRY POINT
---------------------------------
PROCEDURE main(
            p_analysis_mode                IN VARCHAR2    DEFAULT NULL
           ,p_invoice_id                   IN NUMBER      DEFAULT NULL
           ,p_check_id                     IN NUMBER      DEFAULT NULL
           ,p_vendor_id                    IN NUMBER      DEFAULT NULL
           ,p_trx_type                     IN VARCHAR2    DEFAULT 'ALL'
           ,p_start_date                   IN DATE        DEFAULT NULL
           ,p_end_date                     IN DATE        DEFAULT NULL
           ,p_org_ids                      IN NUMBER      DEFAULT NULL
           ,p_org_ids_sql                  IN NUMBER      DEFAULT NULL
           ,p_validations                  IN VARCHAR2    DEFAULT 'ALL'
           ,p_skip_general                 IN VARCHAR2    DEFAULT 'N'
           ,p_max_output_rows              IN NUMBER      DEFAULT 20
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y')

 IS

  l_sql_result VARCHAR2(1);
  l_step       VARCHAR2(5);
  --l_analyzer_end_time   TIMESTAMP;

BEGIN

  l_step := '1';
  initialize_globals;

  -- Workaround for handling debugging before file init
  g_debug_mode := nvl(p_debug_mode, 'Y');
  g_params_string := '';



  l_step := '10';
  initialize_files;

  analyzer_title := 'Master GDF Diagnostic Analyzer';
  analyzer_title := regexp_replace('EBS ' || analyzer_title, '(\S+\s)\1', '\1', 1, 0, 'i');  -- EBSAF-243

  l_step := '15';
   validate_parameters(
     p_analysis_mode                => p_analysis_mode
    ,p_invoice_id                   => p_invoice_id
    ,p_check_id                     => p_check_id
    ,p_vendor_id                    => p_vendor_id
    ,p_trx_type                     => p_trx_type
    ,p_start_date                   => p_start_date
    ,p_end_date                     => p_end_date
    ,p_org_ids                      => p_org_ids
    ,p_org_ids_sql                  => p_org_ids_sql
    ,p_validations                  => p_validations
    ,p_skip_general                 => p_skip_general
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  l_step := '20';
  set_cloud_flag;

  l_step := '23';
  set_snap_days;

  l_step := '25';
  print_page_header;

  l_step := '30';
  print_rep_header(analyzer_title);
  --print_execdetails;
  print_feedback;
  print_parameters;
  print_whatsnew;

  l_step := '40';
  load_signatures;

  l_step := '45';
  create_hyperlink_table;

  l_step := '50';
  initialize_hidden_xml;

  -- Start of Sections and signatures
  l_step := '60';
  debug('begin section: Main Section');
  -- Print the menu of the section screen
  start_main_section;

debug('begin section: PROACTIVE_RECOMMENDATIONS');
start_section('Proactive Recommendations', 'PROACTIVE_RECOMMENDATIONS');
   IF (substr(g_rep_info('Apps Version'),1,4) = '12.1') THEN
      set_item_result(check_rec_patches_1); /* Signature AP_RPC_PATCHES */
   END IF;
   IF (substr(g_rep_info('Apps Version'),1,4) = '12.1' OR
substr(g_rep_info('Apps Version'),1,4) = '12.2') THEN
      set_item_result(check_rec_patches_2); /* Signature APTB_CHECK_REC_PATCHES */
      set_item_result(check_rec_patches_3); /* Signature check_rec_patches */
   END IF;
   set_item_result(run_stored_sig('MGD_STALE_STATISTICS'));
   set_item_result(run_stored_sig('EBS_FIN_AP_INV_SEQUENCES'));
end_section;
debug('end section: PROACTIVE_RECOMMENDATIONS');

debug('begin section: GENERAL_GDF_SIGNATURES');
IF g_validations in ('ALL','GDF') AND
nvl(g_skip_general,'N') != 'Y' THEN
   start_section('General (Non-Trx Specific) GDF Data Validation', 'GENERAL_GDF_SIGNATURES');
      set_item_result(run_stored_sig('74'));
      set_item_result(run_stored_sig('229'));
      set_item_result(run_stored_sig('245'));
   end_section;
END IF;
debug('end section: GENERAL_GDF_SIGNATURES');

debug('begin section: GENERAL_NON_GDF_SIGNATURES');
IF g_validations in ('ALL','NON-GDF') AND
nvl(g_skip_general, 'N') != 'Y' THEN
   start_section('General (Non-Trx Specific) Non GDF Data Validation', 'GENERAL_NON_GDF_SIGNATURES');
      set_item_result(run_stored_sig('280'));
   end_section;
END IF;
debug('end section: GENERAL_NON_GDF_SIGNATURES');

debug('begin section: INVOICE_GDF_SIGNATURES');
IF g_validations IN ('ALL','GDF') AND
(g_mode = 'DATERANGE' AND
  g_trx_type in ('INVOICE','ALL')) THEN
   start_section('Invoice GDF Data Validation', 'INVOICE_GDF_SIGNATURES');
      set_item_result(run_stored_sig('1'));
