  --print_execution_time (l_analyzer_end_time);
  print_execdetails;

  print_mainpage;

  print_footer;

  print_hidden_xml;

  print_sig_exceptions;

  close_files;

EXCEPTION WHEN others THEN
  g_retcode := 2;
  g_errbuf := 'Error in main at step '||l_step||': '||sqlerrm;
  print_log(g_errbuf);

END main;


PROCEDURE main_cp(
            errbuf                         OUT VARCHAR2
           ,retcode                        OUT VARCHAR2
           ,p_analysis_mode                IN VARCHAR2    DEFAULT NULL
           ,p_invoice_id                   IN NUMBER      DEFAULT NULL
           ,p_check_id                     IN NUMBER      DEFAULT NULL
           ,p_vendor_id                    IN NUMBER      DEFAULT NULL
           ,p_trx_type                     IN VARCHAR2    DEFAULT 'ALL'
           ,p_start_date                   IN VARCHAR2    DEFAULT NULL
           ,p_end_date                     IN VARCHAR2    DEFAULT NULL
           ,p_org_ids                      IN NUMBER      DEFAULT NULL
           ,p_validations                  IN VARCHAR2    DEFAULT 'ALL'
           ,p_skip_general                 IN VARCHAR2    DEFAULT 'N'
           ,p_max_output_rows              IN NUMBER      DEFAULT 20
           ,p_debug_mode                   IN VARCHAR2    DEFAULT 'Y'
)
 IS

BEGIN
  g_retcode := 0;
  g_errbuf := null;

   main(
     p_analysis_mode                => p_analysis_mode
    ,p_invoice_id                   => p_invoice_id
    ,p_check_id                     => p_check_id
    ,p_vendor_id                    => p_vendor_id
    ,p_trx_type                     => p_trx_type
    ,p_start_date                   => FND_DATE.canonical_to_date(p_start_date)
    ,p_end_date                     => FND_DATE.canonical_to_date(p_end_date)
    ,p_org_ids                      => p_org_ids
    ,p_validations                  => p_validations
    ,p_skip_general                 => p_skip_general
    ,p_max_output_rows              => p_max_output_rows
    ,p_debug_mode                   => p_debug_mode
  );


  retcode := g_retcode;
  errbuf  := g_errbuf;
EXCEPTION WHEN OTHERS THEN
  retcode := '2';
  errbuf := 'Error in main_cp: '||sqlerrm||' : '||g_errbuf;
END main_cp;


END ap_gdf_detect_analyzer_pkg;
/
show errors
